// --- boundaries.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Boundary {
    pub word: String,
    pub described: bool,
    pub moved: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Reported {
    pub level: String,
    pub message: String,
    pub label: Option<String>,
    pub notes: Vec<String>,
}

pub fn restated(reported: &Reported, on_the_line: Option<&str>, source: &str, boundaries: &[Boundary]) -> Option<Reported> {
    if reported.level != "error" { return None; }
    let label = written_or_nothing((reported.label).as_deref());
    let joined = reported.notes.join(" ");
    let all_of_it = format!("{} {} {}", reported.message, label, joined);
    let the_shape = all_of_it.contains("is not a future") || all_of_it.contains("can only be applied to values that implement `Try`") || all_of_it.contains("`Result<") || all_of_it.contains("enum `Result`");
    if !the_shape { return None; }
    let at = the_boundary(on_the_line, source, boundaries);
    if at < 0 { return None; }
    let boundary = (*nikaia_std::index::get(&boundaries, nikaia_std::index::at(at))).clone();
    let word = boundary.word.to_owned();
    let below = if !label.is_empty() { format!("{} - {}", reported.message, label) } else { reported.message.to_owned() };
    let mut notes: Vec<String> = vec![format!("The Rust compiler said: {}", below)];
    if !boundary.moved.is_empty() {
        let moved = boundary.moved.join(", ");
        notes.push(format!("`{}`'s {} changed since it was described.", word, moved));
    }
    let message = if boundary.described { format!("The description of `{}` doesn't match the crate.", word) } else { format!("The ledger of `{}` doesn't match its sources.", word) };
    if boundary.described { notes.push(format!("help: Run `nikaia describe {}` again, and review what changed in `contracts/{}.contracts`.", word, word)); } else { notes.push(format!("help: Build `{}` again: `nikaia build` without `--locked` rebuilds its ledger from its sources.", word)); }
    for note in reported.notes.iter() { notes.push(note.to_owned()); }
    Some(Reported { level: reported.level.to_owned(), message, label: match reported.label.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, notes })
}

fn written_or_nothing(text: Option<&str>) -> String {
    let written = match text { Some(__nikaia_value) => __nikaia_value, None => return String::from("") };
    written.to_owned()
}

fn the_boundary(on_the_line: Option<&str>, source: &str, boundaries: &[Boundary]) -> i64 {
    let line = written_or_nothing(on_the_line);
    let mut in_the_file: Vec<i64> = vec![];
    for at in 0..boundaries.len() as i64 {
        let called = format!("{}::", nikaia_std::index::get(&boundaries, nikaia_std::index::at(at)).word);
        if on_the_line.is_some() && line.contains(&called) { return at; }
        if source.contains(&called) { in_the_file.push(at); }
    }
    for at in in_the_file.iter() {
        let at = nikaia_std::num::value(at);
        if !nikaia_std::index::get(&boundaries, nikaia_std::index::at(at)).moved.is_empty() { return at; }
    }
    if in_the_file.len() == 1 { return *nikaia_std::index::get(&in_the_file, 0); }
    -1
}


// --- bounds_basic.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
struct CountedLoop {
    binding: String,
    list: String,
}

pub fn basic_indices(body: &Block, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64) -> collections::BTreeSet<i64> {
    let mut out: collections::BTreeSet<i64> = collections::BTreeSet::new();
    counted_block(body, &mut vec![], words, node_of, &mut out);
    out
}

fn counted_block(block: &Block, over: &mut Vec<CountedLoop>, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, out: &mut collections::BTreeSet<i64>) { for stmt in block.stmts.iter() { counted_statement(&stmt.node, over, words, node_of, out); } }

fn without(over: &[CountedLoop], name: &str) -> Vec<CountedLoop> {
    let mut kept: Vec<CountedLoop> = vec![];
    for o in over.iter() { if o.binding != name && o.list != name { kept.push(CountedLoop { binding: o.binding.to_owned(), list: o.list.to_owned() }); } }
    kept
}

fn copied(over: &[CountedLoop]) -> Vec<CountedLoop> {
    let mut kept: Vec<CountedLoop> = vec![];
    for o in over.iter() { kept.push(CountedLoop { binding: o.binding.to_owned(), list: o.list.to_owned() }); }
    kept
}

fn counted_statement(stmt: &Stmt, over: &mut Vec<CountedLoop>, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, out: &mut collections::BTreeSet<i64>) {
    match stmt {
        Stmt::For { bindings, iter, body } => {
            counted_expr(iter, &over, words, node_of, out);
            let mut inner = copied(&over);
            for b in bindings.iter() { inner = without(&inner, words.resolve(*b)); }
            if bindings.len() == 1 {
                let found = loop_over_length(*nikaia_std::index::get(&bindings, 0), iter, body, &over, words);
                if found.is_some() { inner.push(nikaia_std::index::or(found, || CountedLoop { binding: String::from(""), list: String::from("") })); }
            }
            counted_block(body, &mut inner, words, node_of, out);
        },
        Stmt::Let { names, value, .. } => {
            counted_expr(value, &over, words, node_of, out);
            for name in names.iter() {
                let kept = without(&over, words.resolve(*name));
                over.clear();
                over.extend(kept);
            }
        },
        Stmt::Comptime { name, value, .. } => {
            let name = *name;
            counted_expr(value, &over, words, node_of, out);
            let kept = without(&over, words.resolve(name));
            over.clear();
            over.extend(kept);
        },
        Stmt::Assign { target, value, .. } => {
            counted_expr(target, &over, words, node_of, out);
            counted_expr(value, &over, words, node_of, out);
        },
        Stmt::While { cond, body } => {
            counted_expr(cond, &over, words, node_of, out);
            counted_block(body, &mut copied(&over), words, node_of, out);
        },
        Stmt::Return(value) => { counted_maybe((value).as_ref(), &over, words, node_of, out); },
        Stmt::Expr(value) => counted_expr(value, &over, words, node_of, out),
        Stmt::Break => { },
        Stmt::Continue => { },
    }
}

fn loop_over_length(binding: winnow_grammar::Symbol, iter: &Expr, body: &Block, over: &[CountedLoop], words: &winnow_grammar::InternerContext) -> Option<CountedLoop> {
    let (start, end) = match iter {
        Expr::Range { start, end, inclusive } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end); let inclusive = *inclusive;
            if inclusive { return None; }
            (start, end)
        },
        _ => return None,
    };
    let list = match end {
        Expr::MethodCall { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            if !args.is_empty() || words.resolve(method) != "len" { return None; }
            match receiver {
                Expr::Variable(list) => { let list = *list; words.resolve(list).to_owned() },
                _ => return None,
            }
        },
        _ => return None,
    };
    let counter = words.resolve(binding).to_owned();
    if !starts_not_negative(start, over, words) || !length_stays(body, &list, words) || rebinds(body, &counter, words) { return None; }
    Some(CountedLoop { binding: counter, list })
}

fn starts_not_negative(start: &Expr, over: &[CountedLoop], words: &winnow_grammar::InternerContext) -> bool {
    match start {
        Expr::LitInt { negative, .. } => { let negative = *negative; !negative },
        Expr::Variable(name) => { let name = *name; counts(over, words.resolve(name)) },
        _ => false,
    }
}

fn counts(over: &[CountedLoop], binding: &str) -> bool {
    for o in over.iter() { if o.binding == binding { return true; } }
    false
}

fn indexes_its_loop(over: &[CountedLoop], list: &str, at: &str) -> bool {
    for o in over.iter() { if o.list == list && o.binding == at { return true; } }
    false
}

fn counted_expr(expr: &Expr, over: &[CountedLoop], words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, out: &mut collections::BTreeSet<i64>) {
    match expr {
        Expr::Index { base, index } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            match base {
                Expr::Variable(list) => { let list = *list; match index {
                    Expr::Variable(at) => {
                        let at = *at;
                        if indexes_its_loop(over, words.resolve(list), words.resolve(at)) { out.insert(node_of(base)); }
                    },
                    _ => { },
                } },
                _ => { },
            }
        },
        _ => { },
    }
    match expr {
        Expr::Closure { .. } => { },
        Expr::Spawn { .. } => { },
        _ => {
            counted_children(expr, over, words, node_of, out);
            counted_blocks(expr, over, words, node_of, out);
        },
    }
}

fn counted_all(exprs: &[Expr], over: &[CountedLoop], words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, out: &mut collections::BTreeSet<i64>) { for e in exprs.iter() { counted_expr(e, over, words, node_of, out); } }

fn counted_maybe(expr: Option<&Expr>, over: &[CountedLoop], words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, out: &mut collections::BTreeSet<i64>) { counted_expr(match expr { Some(__nikaia_value) => __nikaia_value, None => return }, over, words, node_of, out); }

fn counted_maybe_block(block: Option<&Block>, over: &[CountedLoop], words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, out: &mut collections::BTreeSet<i64>) { counted_block(match block { Some(__nikaia_value) => __nikaia_value, None => return }, &mut copied(over), words, node_of, out); }

fn counted_children(expr: &Expr, over: &[CountedLoop], words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, out: &mut collections::BTreeSet<i64>) {
    match expr {
        Expr::Match { value, arms } => {
            let value = nikaia_std::boxed::open(value);
            counted_expr(value, over, words, node_of, out);
            for arm in arms.iter() {
                counted_maybe((arm.guard).as_ref(), over, words, node_of, out);
                counted_expr(&arm.body, over, words, node_of, out);
            }
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            counted_expr(start, over, words, node_of, out);
            counted_expr(end, over, words, node_of, out);
        },
        Expr::Tuple(items) => counted_all(items, over, words, node_of, out),
        Expr::ListLit { items, .. } => counted_all(items, over, words, node_of, out),
        Expr::LitInterpolated { parts } => {
            for part in parts.iter() {
                match part {
                    FPart::Hole { expr, .. } => counted_expr(expr, over, words, node_of, out),
                    _ => { },
                }
            }
        },
        Expr::If { cond, .. } => { let cond = nikaia_std::boxed::open(cond); counted_expr(cond, over, words, node_of, out) },
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            counted_expr(func, over, words, node_of, out);
            counted_all(args, over, words, node_of, out);
            for c in config.iter() { counted_expr(&c.value, over, words, node_of, out); }
        },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            counted_expr(receiver, over, words, node_of, out);
            counted_all(args, over, words, node_of, out);
            for c in config.iter() { counted_expr(&c.value, over, words, node_of, out); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            counted_expr(receiver, over, words, node_of, out);
            counted_all(args, over, words, node_of, out);
            for c in config.iter() { counted_expr(&c.value, over, words, node_of, out); }
        },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); counted_expr(base, over, words, node_of, out) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); counted_expr(base, over, words, node_of, out) },
        Expr::StructLit { fields, .. } => { for field in fields.iter() { counted_maybe((field.value).as_ref(), over, words, node_of, out); } },
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            counted_expr(base, over, words, node_of, out);
            for field in fields.iter() { counted_maybe((field.value).as_ref(), over, words, node_of, out); }
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); counted_expr(expr, over, words, node_of, out) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); counted_expr(inner, over, words, node_of, out) },
        Expr::Throw(inner) => { let inner = nikaia_std::boxed::open(inner); counted_expr(inner, over, words, node_of, out) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); counted_expr(expr, over, words, node_of, out) },
        Expr::TryCatch { expr, .. } => { let expr = nikaia_std::boxed::open(expr); counted_expr(expr, over, words, node_of, out) },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            counted_expr(lhs, over, words, node_of, out);
            counted_expr(rhs, over, words, node_of, out);
        },
        Expr::Return(value) => {
            let value = nikaia_std::boxed::open(value);
            counted_maybe((value).as_ref(), over, words, node_of, out);
        },
        Expr::Index { base, index } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            counted_expr(base, over, words, node_of, out);
            counted_expr(index, over, words, node_of, out);
        },
        Expr::Coalesce { value, fallback } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            counted_expr(value, over, words, node_of, out);
            counted_expr(fallback, over, words, node_of, out);
        },
        Expr::Select(arms) => { for arm in arms.iter() { counted_expr(&arm.value, over, words, node_of, out); } },
        _ => { },
    }
}

fn counted_blocks(expr: &Expr, over: &[CountedLoop], words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, out: &mut collections::BTreeSet<i64>) {
    match expr {
        Expr::Block(b) => counted_block(b, &mut copied(over), words, node_of, out),
        Expr::Overlap(b) => counted_block(b, &mut copied(over), words, node_of, out),
        Expr::Unsafe(b) => counted_block(b, &mut copied(over), words, node_of, out),
        Expr::If { then_branch, else_branch, .. } => {
            counted_block(then_branch, &mut copied(over), words, node_of, out);
            counted_maybe_block((else_branch).as_ref(), over, words, node_of, out);
        },
        Expr::TryCatch { handler, .. } => counted_block(handler, &mut copied(over), words, node_of, out),
        Expr::Select(arms) => { for arm in arms.iter() { counted_block(&arm.body, &mut copied(over), words, node_of, out); } },
        _ => { },
    }
}

pub fn keeps_length(method: &str) -> bool { matches!(method, "len" | "is_empty" | "contains" | "iter" | "first" | "last" | "get" | "clone" | "to_vec" | "index_of" | "starts_with" | "ends_with" | "join" | "sum" | "min" | "max" | "sort" | "sort_by" | "sort_by_key" | "reverse" | "swap" | "fill" | "map" | "filter" | "any" | "all" | "count" | "find" | "position" | "enumerate" | "zip" | "windows" | "chunks" | "rev" | "fold" | "binary_search" | "to_string" | "chars" | "bytes") }

#[derive(Debug, Clone, PartialEq, Eq)]
enum Seek {
    LengthChanged(String),
    Rebound(String),
    Mentioned(String),
}

pub fn length_stays(body: &Block, list: &str, words: &winnow_grammar::InternerContext) -> bool { !seek_block(body, &Seek::LengthChanged(list.to_owned()), words) }

pub fn rebinds(body: &Block, name: &str, words: &winnow_grammar::InternerContext) -> bool { seek_block(body, &Seek::Rebound(name.to_owned()), words) }

fn is_variable(expr: &Expr, name: &str, words: &winnow_grammar::InternerContext) -> bool {
    match expr {
        Expr::Variable(n) => { let n = *n; words.resolve(n) == name },
        _ => false,
    }
}

fn any_is_variable(exprs: &[Expr], name: &str, words: &winnow_grammar::InternerContext) -> bool {
    for e in exprs.iter() { if is_variable(e, name, words) { return true; } }
    false
}

fn any_symbol(symbols: &[winnow_grammar::Symbol], name: &str, words: &winnow_grammar::InternerContext) -> bool {
    for s in symbols.iter() { if words.resolve(*s) == name { return true; } }
    false
}

fn statement_says(stmt: &Stmt, seek: &Seek, words: &winnow_grammar::InternerContext) -> bool {
    match seek {
        Seek::LengthChanged(list) => match stmt {
            Stmt::Assign { target, .. } => is_variable(target, list, words),
            Stmt::Let { names, .. } => any_symbol(names, list, words),
            Stmt::For { bindings, .. } => any_symbol(bindings, list, words),
            _ => false,
        },
        Seek::Rebound(wanted) => match stmt {
            Stmt::Let { names, .. } => any_symbol(names, wanted, words),
            Stmt::Comptime { name, .. } => { let name = *name; words.resolve(name) == wanted },
            Stmt::For { bindings, .. } => any_symbol(bindings, wanted, words),
            Stmt::Assign { target, .. } => is_variable(target, wanted, words),
            _ => false,
        },
        Seek::Mentioned(name) => match stmt {
            Stmt::Assign { target, .. } => is_variable(target, name, words),
            _ => false,
        },
    }
}

fn expression_says(expr: &Expr, seek: &Seek, words: &winnow_grammar::InternerContext) -> bool {
    match seek {
        Seek::LengthChanged(list) => match expr {
            Expr::MethodCall { receiver, method, args, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; is_variable(receiver, list, words) && !keeps_length(words.resolve(method)) || any_is_variable(args, list, words) },
            Expr::SafeMethod { receiver, method, args, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; is_variable(receiver, list, words) && !keeps_length(words.resolve(method)) || any_is_variable(args, list, words) },
            Expr::Call { args, .. } => any_is_variable(args, list, words),
            Expr::Closure { body, .. } => seek_block(body, &Seek::Mentioned(list.to_owned()), words),
            Expr::Spawn { body, .. } => { let body = nikaia_std::boxed::open(body); seek_expr(body, &Seek::Mentioned(list.to_owned()), words) },
            _ => false,
        },
        Seek::Rebound(name) => match expr {
            Expr::Closure { params, .. } => any_symbol(params, name, words),
            _ => false,
        },
        Seek::Mentioned(name) => is_variable(expr, name, words),
    }
}

fn seek_block(block: &Block, seek: &Seek, words: &winnow_grammar::InternerContext) -> bool {
    for stmt in block.stmts.iter() { if seek_statement(&stmt.node, seek, words) { return true; } }
    false
}

fn seek_statement(stmt: &Stmt, seek: &Seek, words: &winnow_grammar::InternerContext) -> bool {
    if statement_says(stmt, seek, words) { return true; }
    match stmt {
        Stmt::For { iter, body, .. } => seek_expr(iter, seek, words) || seek_block(body, seek, words),
        Stmt::While { cond, body } => seek_expr(cond, seek, words) || seek_block(body, seek, words),
        Stmt::Let { value, .. } => seek_expr(value, seek, words),
        Stmt::Comptime { value, .. } => seek_expr(value, seek, words),
        Stmt::Expr(value) => seek_expr(value, seek, words),
        Stmt::Assign { target, value, .. } => seek_expr(target, seek, words) || seek_expr(value, seek, words),
        Stmt::Return(value) => seek_maybe((value).as_ref(), seek, words),
        _ => false,
    }
}

fn seek_all(exprs: &[Expr], seek: &Seek, words: &winnow_grammar::InternerContext) -> bool {
    for e in exprs.iter() { if seek_expr(e, seek, words) { return true; } }
    false
}

fn seek_config(config: &[ConfigArg], seek: &Seek, words: &winnow_grammar::InternerContext) -> bool {
    for c in config.iter() { if seek_expr(&c.value, seek, words) { return true; } }
    false
}

fn seek_fields(fields: &[FieldInit], seek: &Seek, words: &winnow_grammar::InternerContext) -> bool {
    for field in fields.iter() { if seek_maybe((field.value).as_ref(), seek, words) { return true; } }
    false
}

fn seek_maybe_block(block: Option<&Block>, seek: &Seek, words: &winnow_grammar::InternerContext) -> bool { seek_block(match block { Some(__nikaia_value) => __nikaia_value, None => return false }, seek, words) }

fn seek_maybe(expr: Option<&Expr>, seek: &Seek, words: &winnow_grammar::InternerContext) -> bool { seek_expr(match expr { Some(__nikaia_value) => __nikaia_value, None => return false }, seek, words) }

fn seek_expr(expr: &Expr, seek: &Seek, words: &winnow_grammar::InternerContext) -> bool {
    if expression_says(expr, seek, words) { return true; }
    match expr {
        Expr::Match { value, arms } => { let value = nikaia_std::boxed::open(value); seek_expr(value, seek, words) || seek_arms(arms, seek, words) },
        Expr::Range { start, end, .. } => { let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end); seek_expr(start, seek, words) || seek_expr(end, seek, words) },
        Expr::Tuple(items) => seek_all(items, seek, words),
        Expr::ListLit { items, .. } => seek_all(items, seek, words),
        Expr::LitInterpolated { parts } => seek_holes(parts, seek, words),
        Expr::If { cond, then_branch, else_branch } => { let cond = nikaia_std::boxed::open(cond); seek_expr(cond, seek, words) || seek_block(then_branch, seek, words) || seek_maybe_block((else_branch).as_ref(), seek, words) },
        Expr::Call { func, args, config } => { let func = nikaia_std::boxed::open(func); seek_expr(func, seek, words) || seek_all(args, seek, words) || seek_config(config, seek, words) },
        Expr::Spawn { body, .. } => { let body = nikaia_std::boxed::open(body); seek_expr(body, seek, words) },
        Expr::MethodCall { receiver, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); seek_expr(receiver, seek, words) || seek_all(args, seek, words) || seek_config(config, seek, words) },
        Expr::SafeMethod { receiver, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); seek_expr(receiver, seek, words) || seek_all(args, seek, words) || seek_config(config, seek, words) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); seek_expr(base, seek, words) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); seek_expr(base, seek, words) },
        Expr::StructLit { fields, .. } => seek_fields(fields, seek, words),
        Expr::With { base, fields, .. } => { let base = nikaia_std::boxed::open(base); seek_expr(base, seek, words) || seek_fields(fields, seek, words) },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); seek_expr(expr, seek, words) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); seek_expr(inner, seek, words) },
        Expr::Throw(inner) => { let inner = nikaia_std::boxed::open(inner); seek_expr(inner, seek, words) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); seek_expr(expr, seek, words) },
        Expr::TryCatch { expr, handler } => { let expr = nikaia_std::boxed::open(expr); seek_expr(expr, seek, words) || seek_block(handler, seek, words) },
        Expr::Binary { lhs, rhs, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); seek_expr(lhs, seek, words) || seek_expr(rhs, seek, words) },
        Expr::Return(value) => { let value = nikaia_std::boxed::open(value); seek_maybe((value).as_ref(), seek, words) },
        Expr::Index { base, index } => { let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index); seek_expr(base, seek, words) || seek_expr(index, seek, words) },
        Expr::Coalesce { value, fallback } => { let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback); seek_expr(value, seek, words) || seek_expr(fallback, seek, words) },
        Expr::Select(arms) => seek_select(arms, seek, words),
        Expr::Block(b) => seek_block(b, seek, words),
        Expr::Overlap(b) => seek_block(b, seek, words),
        Expr::Unsafe(b) => seek_block(b, seek, words),
        Expr::Closure { body, .. } => seek_block(body, seek, words),
        _ => false,
    }
}

fn seek_arms(arms: &[MatchArm], seek: &Seek, words: &winnow_grammar::InternerContext) -> bool {
    for arm in arms.iter() {
        if seek_maybe((arm.guard).as_ref(), seek, words) { return true; }
        if seek_expr(&arm.body, seek, words) { return true; }
    }
    false
}

fn seek_holes(parts: &[FPart], seek: &Seek, words: &winnow_grammar::InternerContext) -> bool {
    for part in parts.iter() {
        match part {
            FPart::Hole { expr, .. } if seek_expr(expr, seek, words) => return true,
            _ => { },
        }
    }
    false
}

fn seek_select(arms: &[SelectArm], seek: &Seek, words: &winnow_grammar::InternerContext) -> bool {
    for arm in arms.iter() { if seek_expr(&arm.value, seek, words) || seek_block(&arm.body, seek, words) { return true; } }
    false
}


// --- bounds_body.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
enum Ask {
    Leaves,
    Breaks,
    Changes(String),
    Pinned,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Tally {
    found: bool,
    count: i64,
    names: collections::BTreeSet<String>,
}

fn tally() -> Tally { Tally { found: false, count: 0, names: collections::BTreeSet::new() } }

pub fn breaks(body: &Block, words: &winnow_grammar::InternerContext) -> bool {
    let mut found = tally();
    tally_block(body, &Ask::Breaks, false, words, &mut found);
    found.found
}

pub fn pinned_in(body: &Block, words: &winnow_grammar::InternerContext) -> collections::BTreeSet<String> {
    let mut found = tally();
    tally_block(body, &Ask::Pinned, false, words, &mut found);
    found.names
}

pub fn filled_once(body: &Block, pinned: &collections::BTreeSet<String>, words: &winnow_grammar::InternerContext) -> Vec<String> {
    let mut leaving = tally();
    tally_block(body, &Ask::Leaves, false, words, &mut leaving);
    if leaving.found { return vec![]; }
    let mut pushed: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    for stmt in body.stmts.iter() {
        let list = match pushed_onto(&stmt.node, words) { Some(__nikaia_value) => __nikaia_value, None => continue };
        let before = nikaia_std::index::or(pushed.get(&list), || 0);
        pushed.insert(list, before + 1);
    }
    let mut once: Vec<String> = vec![];
    for (list, count) in pushed.iter() {
        let count = nikaia_std::num::value(count);
        if count != 1 || pinned.contains(list) { continue; }
        let mut changes = tally();
        tally_block(body, &Ask::Changes(list.to_owned()), false, words, &mut changes);
        if changes.count == 1 && !rebinds(body, list, words) { once.push(list.to_owned()); }
    }
    once
}

fn pushed_onto(stmt: &Stmt, words: &winnow_grammar::InternerContext) -> Option<String> {
    let value = match stmt {
        Stmt::Expr(value) => value,
        _ => return None,
    };
    match value {
        Expr::MethodCall { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            if words.resolve(method) != "push" || args.len() != 1 { return None; }
            variable_text(receiver, words)
        },
        _ => None,
    }
}

fn variable_text(expr: &Expr, words: &winnow_grammar::InternerContext) -> Option<String> {
    match expr {
        Expr::Variable(name) => { let name = *name; Some(words.resolve(name).to_owned()) },
        _ => None,
    }
}

fn assigned_root(target: &Expr, words: &winnow_grammar::InternerContext) -> Option<String> {
    match target {
        Expr::Index { base, .. } => { let base = nikaia_std::boxed::open(base); assigned_root(base, words) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); assigned_root(base, words) },
        Expr::Variable(name) => { let name = *name; Some(words.resolve(name).to_owned()) },
        _ => None,
    }
}

fn add_variables(exprs: &[Expr], words: &winnow_grammar::InternerContext, names: &mut collections::BTreeSet<String>) {
    for e in exprs.iter() {
        let name = match variable_text(e, words) { Some(__nikaia_value) => __nikaia_value, None => continue };
        names.insert(name);
    }
}

fn add_variable(expr: &Expr, words: &winnow_grammar::InternerContext, names: &mut collections::BTreeSet<String>) {
    let name = match variable_text(expr, words) { Some(__nikaia_value) => __nikaia_value, None => return };
    names.insert(name);
}

fn names_the(exprs: &[Expr], list: &str, words: &winnow_grammar::InternerContext) -> bool {
    for e in exprs.iter() { if nikaia_std::index::or(variable_text(e, words), || "".into()) == list { return true; } }
    false
}

fn tally_block(block: &Block, ask: &Ask, deferred: bool, words: &winnow_grammar::InternerContext, tally: &mut Tally) { for stmt in block.stmts.iter() { tally_statement(&stmt.node, ask, deferred, words, tally); } }

fn tally_statement(stmt: &Stmt, ask: &Ask, deferred: bool, words: &winnow_grammar::InternerContext, tally: &mut Tally) {
    match ask {
        Ask::Leaves => match stmt {
            Stmt::Break => { tally.found = true; },
            Stmt::Continue => { tally.found = true; },
            Stmt::Return(_) => { tally.found = true; },
            _ => { },
        },
        Ask::Breaks => match stmt {
            Stmt::Break => { tally.found = true; },
            Stmt::For { .. } => return,
            Stmt::While { .. } => return,
            _ => { },
        },
        Ask::Pinned => {
            if deferred {
                match stmt {
                    Stmt::Assign { target, .. } => {
                        let root = assigned_root(target, words);
                        if root.is_some() { tally.names.insert(nikaia_std::index::or(root, || "".into())); }
                    },
                    _ => { },
                }
            }
        },
        Ask::Changes(_) => { },
    }
    match stmt {
        Stmt::For { iter, body, .. } => {
            tally_expr(iter, ask, deferred, words, tally);
            tally_block(body, ask, deferred, words, tally);
        },
        Stmt::While { cond, body } => {
            tally_expr(cond, ask, deferred, words, tally);
            tally_block(body, ask, deferred, words, tally);
        },
        Stmt::Let { value, .. } => tally_expr(value, ask, deferred, words, tally),
        Stmt::Comptime { value, .. } => tally_expr(value, ask, deferred, words, tally),
        Stmt::Expr(value) => tally_expr(value, ask, deferred, words, tally),
        Stmt::Assign { target, value, .. } => {
            tally_expr(target, ask, deferred, words, tally);
            tally_expr(value, ask, deferred, words, tally);
        },
        Stmt::Return(value) => tally_maybe((value).as_ref(), ask, deferred, words, tally),
        _ => { },
    }
}

fn tally_maybe(expr: Option<&Expr>, ask: &Ask, deferred: bool, words: &winnow_grammar::InternerContext, tally: &mut Tally) { tally_expr(match expr { Some(__nikaia_value) => __nikaia_value, None => return }, ask, deferred, words, tally); }

fn tally_maybe_block(block: Option<&Block>, ask: &Ask, deferred: bool, words: &winnow_grammar::InternerContext, tally: &mut Tally) { tally_block(match block { Some(__nikaia_value) => __nikaia_value, None => return }, ask, deferred, words, tally); }

fn tally_all(exprs: &[Expr], ask: &Ask, deferred: bool, words: &winnow_grammar::InternerContext, tally: &mut Tally) { for e in exprs.iter() { tally_expr(e, ask, deferred, words, tally); } }

fn tally_config(config: &[ConfigArg], ask: &Ask, deferred: bool, words: &winnow_grammar::InternerContext, tally: &mut Tally) { for c in config.iter() { tally_expr(&c.value, ask, deferred, words, tally); } }

fn tally_fields(fields: &[FieldInit], ask: &Ask, deferred: bool, words: &winnow_grammar::InternerContext, tally: &mut Tally) { for field in fields.iter() { tally_maybe((field.value).as_ref(), ask, deferred, words, tally); } }

fn tally_here(expr: &Expr, ask: &Ask, deferred: bool, words: &winnow_grammar::InternerContext, tally: &mut Tally) {
    match ask {
        Ask::Leaves => match expr {
            Expr::Break => { tally.found = true; },
            Expr::Continue => { tally.found = true; },
            Expr::Return(_) => { tally.found = true; },
            Expr::Throw(_) => { tally.found = true; },
            Expr::Try(_) => { tally.found = true; },
            _ => { },
        },
        Ask::Breaks => match expr {
            Expr::Break => { tally.found = true; },
            _ => { },
        },
        Ask::Changes(list) => match expr {
            Expr::MethodCall { receiver, method, args, .. } => {
                let receiver = nikaia_std::boxed::open(receiver); let method = *method;
                if nikaia_std::index::or(variable_text(receiver, words), || "".into()) == *list && !keeps_length(words.resolve(method)) { tally.count += 1; } else if names_the(args, list, words) { tally.count += 2; }
            },
            Expr::SafeMethod { receiver, method, args, .. } => {
                let receiver = nikaia_std::boxed::open(receiver); let method = *method;
                if nikaia_std::index::or(variable_text(receiver, words), || "".into()) == *list && !keeps_length(words.resolve(method)) { tally.count += 1; } else if names_the(args, list, words) { tally.count += 2; }
            },
            Expr::Call { args, .. } if names_the(args, list, words) => { tally.count += 2; },
            _ => { },
        },
        Ask::Pinned => {
            if deferred {
                match expr {
                    Expr::MethodCall { receiver, args, .. } => {
                        let receiver = nikaia_std::boxed::open(receiver);
                        add_variable(receiver, words, &mut tally.names);
                        add_variables(args, words, &mut tally.names);
                    },
                    Expr::SafeMethod { receiver, args, .. } => {
                        let receiver = nikaia_std::boxed::open(receiver);
                        add_variable(receiver, words, &mut tally.names);
                        add_variables(args, words, &mut tally.names);
                    },
                    Expr::Call { args, .. } => add_variables(args, words, &mut tally.names),
                    _ => { },
                }
            }
        },
    }
}

fn tally_expr(expr: &Expr, ask: &Ask, deferred: bool, words: &winnow_grammar::InternerContext, tally: &mut Tally) {
    tally_here(expr, ask, deferred, words, tally);
    let mut stops = false;
    match ask {
        Ask::Breaks => match expr {
            Expr::Closure { .. } => { stops = true; },
            Expr::Spawn { .. } => { stops = true; },
            _ => { },
        },
        _ => { },
    }
    if stops { return; }
    match expr {
        Expr::Match { value, arms } => {
            let value = nikaia_std::boxed::open(value);
            tally_expr(value, ask, deferred, words, tally);
            for arm in arms.iter() {
                tally_maybe((arm.guard).as_ref(), ask, deferred, words, tally);
                tally_expr(&arm.body, ask, deferred, words, tally);
            }
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            tally_expr(start, ask, deferred, words, tally);
            tally_expr(end, ask, deferred, words, tally);
        },
        Expr::Tuple(items) => tally_all(items, ask, deferred, words, tally),
        Expr::ListLit { items, .. } => tally_all(items, ask, deferred, words, tally),
        Expr::LitInterpolated { parts } => {
            for part in parts.iter() {
                match part {
                    FPart::Hole { expr, .. } => tally_expr(expr, ask, deferred, words, tally),
                    _ => { },
                }
            }
        },
        Expr::If { cond, then_branch, else_branch } => {
            let cond = nikaia_std::boxed::open(cond);
            tally_expr(cond, ask, deferred, words, tally);
            tally_block(then_branch, ask, deferred, words, tally);
            tally_maybe_block((else_branch).as_ref(), ask, deferred, words, tally);
        },
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            tally_expr(func, ask, deferred, words, tally);
            tally_all(args, ask, deferred, words, tally);
            tally_config(config, ask, deferred, words, tally);
        },
        Expr::Spawn { body, .. } => { let body = nikaia_std::boxed::open(body); tally_expr(body, ask, true, words, tally) },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            tally_expr(receiver, ask, deferred, words, tally);
            tally_all(args, ask, deferred, words, tally);
            tally_config(config, ask, deferred, words, tally);
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            tally_expr(receiver, ask, deferred, words, tally);
            tally_all(args, ask, deferred, words, tally);
            tally_config(config, ask, deferred, words, tally);
        },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); tally_expr(base, ask, deferred, words, tally) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); tally_expr(base, ask, deferred, words, tally) },
        Expr::StructLit { fields, .. } => tally_fields(fields, ask, deferred, words, tally),
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            tally_expr(base, ask, deferred, words, tally);
            tally_fields(fields, ask, deferred, words, tally);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); tally_expr(expr, ask, deferred, words, tally) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); tally_expr(inner, ask, deferred, words, tally) },
        Expr::Throw(inner) => { let inner = nikaia_std::boxed::open(inner); tally_expr(inner, ask, deferred, words, tally) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); tally_expr(expr, ask, deferred, words, tally) },
        Expr::TryCatch { expr, handler } => {
            let expr = nikaia_std::boxed::open(expr);
            tally_expr(expr, ask, deferred, words, tally);
            tally_block(handler, ask, deferred, words, tally);
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            tally_expr(lhs, ask, deferred, words, tally);
            tally_expr(rhs, ask, deferred, words, tally);
        },
        Expr::Return(value) => { let value = nikaia_std::boxed::open(value); tally_maybe((value).as_ref(), ask, deferred, words, tally) },
        Expr::Index { base, index } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            tally_expr(base, ask, deferred, words, tally);
            tally_expr(index, ask, deferred, words, tally);
        },
        Expr::Coalesce { value, fallback } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            tally_expr(value, ask, deferred, words, tally);
            tally_expr(fallback, ask, deferred, words, tally);
        },
        Expr::Select(arms) => {
            for arm in arms.iter() {
                tally_expr(&arm.value, ask, deferred, words, tally);
                tally_block(&arm.body, ask, true, words, tally);
            }
        },
        Expr::Block(b) => tally_block(b, ask, deferred, words, tally),
        Expr::Overlap(b) => tally_block(b, ask, true, words, tally),
        Expr::Unsafe(b) => tally_block(b, ask, deferred, words, tally),
        Expr::Closure { body, .. } => tally_block(body, ask, true, words, tally),
        _ => { },
    }
}


// --- bounds_interval.nika ---

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Range {
    pub lo: Option<i64>,
    pub hi: Option<i64>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Form {
    vars: collections::BTreeMap<String, i64>,
    k: i64,
}

impl Range {
    pub fn open() -> Range { Range { lo: None, hi: None } }
    pub fn exactly(n: i64) -> Range { Range { lo: Some(n), hi: Some(n) } }
    pub fn of_type(ty: &str) -> Option<Range> {
        match ty {
            "i8" => Some(Range { lo: Some(-128), hi: Some(127) }),
            "i16" => Some(Range { lo: Some(-32768), hi: Some(32767) }),
            "i32" => Some(Range { lo: Some(-2147483648), hi: Some(2147483647) }),
            "i64" => Some(Range { lo: Some(-9223372036854775808i64), hi: Some(9223372036854775807i64) }),
            "isize" => Some(Range { lo: Some(-9223372036854775808i64), hi: Some(9223372036854775807i64) }),
            "u8" => Some(Range { lo: Some(0), hi: Some(255) }),
            "u16" => Some(Range { lo: Some(0), hi: Some(65535) }),
            "u32" => Some(Range { lo: Some(0), hi: Some(4294967295i64) }),
            "u64" => Some(Range { lo: Some(0), hi: Some(9223372036854775807i64) }),
            "usize" => Some(Range { lo: Some(0), hi: Some(9223372036854775807i64) }),
            _ => None,
        }
    }
    pub fn holds(&self, other: &Range) -> bool {
        let mut lo = self.lo.is_none();
        if other.lo.is_some() { lo = self.lo.is_none() || nikaia_std::index::or(self.lo, || 0) <= nikaia_std::index::or(other.lo, || 0); }
        let mut hi = self.hi.is_none();
        if other.hi.is_some() { hi = self.hi.is_none() || nikaia_std::index::or(self.hi, || 0) >= nikaia_std::index::or(other.hi, || 0); }
        lo && hi
    }
    pub fn join(&self, other: &Range) -> Range {
        let mut out = Range::open();
        if self.lo.is_some() && other.lo.is_some() { out.lo = Some(nikaia_std::index::or(self.lo, || 0).min(nikaia_std::index::or(other.lo, || 0))); }
        if self.hi.is_some() && other.hi.is_some() { out.hi = Some(nikaia_std::index::or(self.hi, || 0).max(nikaia_std::index::or(other.hi, || 0))); }
        out
    }
    pub fn meet(&self, other: &Range) -> Range {
        let mut out = Range { lo: self.lo, hi: self.hi };
        if other.lo.is_some() {
            out.lo = other.lo;
            if self.lo.is_some() { out.lo = Some(nikaia_std::index::or(self.lo, || 0).max(nikaia_std::index::or(other.lo, || 0))); }
        }
        if other.hi.is_some() {
            out.hi = other.hi;
            if self.hi.is_some() { out.hi = Some(nikaia_std::index::or(self.hi, || 0).min(nikaia_std::index::or(other.hi, || 0))); }
        }
        out
    }
    pub fn is_bounded(&self) -> bool { self.lo.is_some() || self.hi.is_some() }
    pub fn add(&self, other: &Range) -> Range {
        let mut out = Range::open();
        if self.lo.is_some() && other.lo.is_some() { out.lo = nikaia_std::index::or(self.lo, || 0).checked_add(nikaia_std::index::or(other.lo, || 0)); }
        if self.hi.is_some() && other.hi.is_some() { out.hi = nikaia_std::index::or(self.hi, || 0).checked_add(nikaia_std::index::or(other.hi, || 0)); }
        out
    }
    pub fn neg(&self) -> Range {
        let mut out = Range::open();
        if self.hi.is_some() { out.lo = nikaia_std::index::or(self.hi, || 0).checked_neg(); }
        if self.lo.is_some() { out.hi = nikaia_std::index::or(self.lo, || 0).checked_neg(); }
        out
    }
    pub fn mul(&self, other: &Range) -> Range {
        if self.lo.is_none() || self.hi.is_none() || other.lo.is_none() || other.hi.is_none() { return Range::open(); }
        let (a, b, c, d) = (nikaia_std::index::or(self.lo, || 0), nikaia_std::index::or(self.hi, || 0), nikaia_std::index::or(other.lo, || 0), nikaia_std::index::or(other.hi, || 0));
        let ac = match a.checked_mul(c) { Some(__nikaia_value) => __nikaia_value, None => return Range::open() };
        let ad = match a.checked_mul(d) { Some(__nikaia_value) => __nikaia_value, None => return Range::open() };
        let bc = match b.checked_mul(c) { Some(__nikaia_value) => __nikaia_value, None => return Range::open() };
        let bd = match b.checked_mul(d) { Some(__nikaia_value) => __nikaia_value, None => return Range::open() };
        Range { lo: Some(ac.min(ad).min(bc.min(bd))), hi: Some(ac.max(ad).max(bc.max(bd))) }
    }
}

pub fn candidate(term: i64, facts: &[i64], term_of: &impl Fn(i64) -> SolverTerm) -> Range {
    let form = match linear_form(term, term_of) { Some(__nikaia_value) => __nikaia_value, None => return Range::open() };
    let known = propagate(facts, term_of);
    evaluate(&form, &known)
}

fn linear_form(term: i64, term_of: &impl Fn(i64) -> SolverTerm) -> Option<Form> {
    match term_of(term) {
        SolverTerm::Int(n) => Some(Form { vars: collections::BTreeMap::new(), k: n }),
        SolverTerm::Var(ref name) => {
            let mut vars: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
            vars.insert(name.to_owned(), 1);
            Some(Form { vars, k: 0 })
        },
        SolverTerm::Add(a, b) => {
            let left = match linear_form(a, term_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let right = match linear_form(b, term_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
            sum(&left, &right, 1)
        },
        SolverTerm::Sub(a, b) => {
            let left = match linear_form(a, term_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let right = match linear_form(b, term_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
            sum(&left, &right, -1)
        },
        SolverTerm::Neg(a) => {
            let inner = match linear_form(a, term_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
            scaled(&inner, -1)
        },
        SolverTerm::Mul(a, b) => {
            let left = match linear_form(a, term_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let right = match linear_form(b, term_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
            if left.vars.is_empty() { return scaled(&right, left.k); }
            if right.vars.is_empty() { return scaled(&left, right.k); }
            None
        },
        _ => None,
    }
}

fn sum(left: &Form, right: &Form, sign: i64) -> Option<Form> {
    let mut vars = left.vars.to_owned();
    for (name, c) in right.vars.iter() {
        let c = nikaia_std::num::value(c);
        let before = nikaia_std::index::or(vars.get(name), || 0);
        let by = match c.checked_mul(sign) { Some(__nikaia_value) => __nikaia_value, None => return None };
        let after = match before.checked_add(by) { Some(__nikaia_value) => __nikaia_value, None => return None };
        vars.insert(name.to_owned(), after);
    }
    let by = match right.k.checked_mul(sign) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let k = match left.k.checked_add(by) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(Form { vars, k })
}

fn scaled(form: &Form, by: i64) -> Option<Form> {
    let mut vars: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    for (name, c) in form.vars.iter() {
        let c = nikaia_std::num::value(c);
        let times = match c.checked_mul(by) { Some(__nikaia_value) => __nikaia_value, None => return None };
        vars.insert(name.to_owned(), times);
    }
    let k = match form.k.checked_mul(by) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(Form { vars, k })
}

fn shifted(form: &Form, n: i64) -> Option<Form> {
    let k = match form.k.checked_add(n) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(Form { vars: form.vars.to_owned(), k })
}

fn atoms(fact: i64, term_of: &impl Fn(i64) -> SolverTerm, out: &mut Vec<Form>) {
    match term_of(fact) {
        SolverTerm::And(ref parts) => {
            for part in parts.iter() {
                let part = nikaia_std::num::value(part);
                atoms(part, term_of, out);
            }
        },
        SolverTerm::Le(a, b) => {
            let d = match difference(a, b, term_of) { Some(__nikaia_value) => __nikaia_value, None => return };
            out.push(d);
        },
        SolverTerm::Lt(a, b) => {
            let d = match difference(a, b, term_of) { Some(__nikaia_value) => __nikaia_value, None => return };
            let strict = match shifted(&d, 1) { Some(__nikaia_value) => __nikaia_value, None => return };
            out.push(strict);
        },
        SolverTerm::Ge(a, b) => {
            let d = match difference(a, b, term_of) { Some(__nikaia_value) => __nikaia_value, None => return };
            let turned = match scaled(&d, -1) { Some(__nikaia_value) => __nikaia_value, None => return };
            out.push(turned);
        },
        SolverTerm::Gt(a, b) => {
            let d = match difference(a, b, term_of) { Some(__nikaia_value) => __nikaia_value, None => return };
            let turned = match scaled(&d, -1) { Some(__nikaia_value) => __nikaia_value, None => return };
            let strict = match shifted(&turned, 1) { Some(__nikaia_value) => __nikaia_value, None => return };
            out.push(strict);
        },
        SolverTerm::Eq(a, b) => {
            let d = match difference(a, b, term_of) { Some(__nikaia_value) => __nikaia_value, None => return };
            let turned = match scaled(&d, -1) { Some(__nikaia_value) => __nikaia_value, None => return };
            out.push(turned);
            out.push(d);
        },
        _ => { },
    }
}

fn difference(a: i64, b: i64, term_of: &impl Fn(i64) -> SolverTerm) -> Option<Form> {
    let left = match linear_form(a, term_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let right = match linear_form(b, term_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
    sum(&left, &right, -1)
}

fn propagate(facts: &[i64], term_of: &impl Fn(i64) -> SolverTerm) -> collections::BTreeMap<String, Range> {
    let mut all: Vec<Form> = vec![];
    for fact in facts.iter() {
        let fact = nikaia_std::num::value(fact);
        atoms(fact, term_of, &mut all);
    }
    let mut known: collections::BTreeMap<String, Range> = collections::BTreeMap::new();
    for _ in 0..4 {
        let mut changed = false;
        for atom in all.iter() {
            for (x, cx) in atom.vars.iter() {
                let cx = nikaia_std::num::value(cx);
                if cx == 0 { continue; }
                let rest = match least_of_the_rest(atom, x, &known) { Some(__nikaia_value) => __nikaia_value, None => continue };
                let before = nikaia_std::index::or(known.get(x), || Range::open());
                let mut entry = Range { lo: before.lo, hi: before.hi };
                let negated = match rest.checked_neg() { Some(__nikaia_value) => __nikaia_value, None => continue };
                if cx > 0 {
                    let bound = negated.div_euclid(cx);
                    if entry.hi.is_none() || bound < nikaia_std::index::or(entry.hi, || 0) {
                        entry.hi = Some(bound);
                        changed = true;
                    }
                } else {
                    let by = match cx.checked_neg() { Some(__nikaia_value) => __nikaia_value, None => continue };
                    let down = negated.div_euclid(by);
                    let bound = match down.checked_neg() { Some(__nikaia_value) => __nikaia_value, None => continue };
                    if entry.lo.is_none() || bound > nikaia_std::index::or(entry.lo, || 0) {
                        entry.lo = Some(bound);
                        changed = true;
                    }
                }
                known.insert(x.to_owned(), entry);
            }
        }
        if !changed { break; }
    }
    known
}

fn least_of_the_rest(atom: &Form, x: &str, known: &collections::BTreeMap<String, Range>) -> Option<i64> {
    let mut rest = atom.k;
    for (y, cy) in atom.vars.iter() {
        let cy = nikaia_std::num::value(cy);
        if y == x { continue; }
        let bounds = match known.get(y) { Some(__nikaia_value) => __nikaia_value, None => return None };
        let side = if cy > 0 { bounds.lo } else { bounds.hi };
        let value = match side { Some(__nikaia_value) => __nikaia_value, None => return None };
        let least = match cy.checked_mul(value) { Some(__nikaia_value) => __nikaia_value, None => return None };
        rest = match rest.checked_add(least) { Some(__nikaia_value) => __nikaia_value, None => return None };
    }
    Some(rest)
}

fn plus_times(sum: Option<i64>, c: i64, side: Option<i64>) -> Option<i64> {
    let start = match sum { Some(__nikaia_value) => __nikaia_value, None => return None };
    let value = match side { Some(__nikaia_value) => __nikaia_value, None => return None };
    let part = match c.checked_mul(value) { Some(__nikaia_value) => __nikaia_value, None => return None };
    start.checked_add(part)
}

fn evaluate(form: &Form, known: &collections::BTreeMap<String, Range>) -> Range {
    let mut lo: Option<i64> = Some(form.k);
    let mut hi: Option<i64> = Some(form.k);
    for (x, c) in form.vars.iter() {
        let c = nikaia_std::num::value(c);
        let bounds = nikaia_std::index::or(known.get(x), || Range::open());
        let least_side = if c >= 0 { bounds.lo } else { bounds.hi };
        let most_side = if c >= 0 { bounds.hi } else { bounds.lo };
        lo = plus_times(lo, c, least_side);
        hi = plus_times(hi, c, most_side);
    }
    Range { lo, hi }
}


// --- bounds_reasons.nika ---

pub fn blocked_index(base: &Expr, index: &Expr) -> String {
    match base {
        Expr::Index { .. } => list_of_lists(),
        _ => site_shape(base, index),
    }
}

pub fn blocked_operation(op: &BinaryOp, lhs: &Expr, rhs: &Expr) -> String {
    let shape = site_shape(lhs, rhs);
    if shape == unbounded() && *op == BinaryOp::Mul && !is_int_literal(lhs) && !is_int_literal(rhs) { return String::from("a product of two unknowns (#386)"); }
    shape
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct SiteReads {
    field: bool,
    call: bool,
    nested: bool,
}

fn site_shape(a: &Expr, b: &Expr) -> String {
    let mut read = SiteReads { field: false, call: false, nested: false };
    site_reads(a, &mut read);
    site_reads(b, &mut read);
    if read.field { return String::from("it reads a field, of which the walk keeps no facts (#384)"); }
    if read.nested { return list_of_lists(); }
    if read.call { return String::from("a call's result, which the walk knows nothing of (#382)"); }
    unbounded()
}

fn site_reads(expr: &Expr, read: &mut SiteReads) {
    match expr {
        Expr::Field { base, .. } => {
            let base = nikaia_std::boxed::open(base);
            read.field = true;
            site_reads(base, read);
        },
        Expr::Call { args, .. } => {
            read.call = true;
            for arg in args.iter() { site_reads(arg, read); }
        },
        Expr::MethodCall { receiver, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            if !args.is_empty() { read.call = true; }
            site_reads(receiver, read);
            for arg in args.iter() { site_reads(arg, read); }
        },
        Expr::SafeMethod { receiver, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            read.call = true;
            site_reads(receiver, read);
            for arg in args.iter() { site_reads(arg, read); }
        },
        Expr::Index { base, index } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            match base {
                Expr::Index { .. } => { read.nested = true; },
                _ => { },
            }
            site_reads(base, read);
            site_reads(index, read);
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            site_reads(lhs, read);
            site_reads(rhs, read);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); site_reads(expr, read) },
        _ => { },
    }
}

fn is_int_literal(expr: &Expr) -> bool { matches!(expr, Expr::LitInt { .. }) }

fn list_of_lists() -> String { String::from("a list of lists, whose inner lengths the walk does not know (#385)") }

fn unbounded() -> String { String::from("no fact bounds what it reads - a counter, a loop, a length, or one list as long as another (#432, #383, #388)") }


// --- bounds_shape.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BodyShape {
    pub constants: collections::BTreeMap<String, i64>,
    pub unsigned: collections::BTreeSet<String>,
    pub roots: collections::BTreeSet<String>,
    pub aliases: collections::BTreeMap<String, String>,
    pub bound: collections::BTreeSet<String>,
    pub twice: collections::BTreeSet<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Around {
    pub functions: collections::BTreeMap<String, Vec<bool>>,
    pub changing_methods: collections::BTreeSet<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Look {
    Bound,
    Lets,
    Aliases,
    Lost,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ShapeSeen {
    bound: collections::BTreeMap<String, i64>,
    shape: BodyShape,
    lost: collections::BTreeSet<String>,
}

pub fn shape_of(args: &[FnArg], body: &Block, pinned: &collections::BTreeSet<String>, around: &Around, words: &winnow_grammar::InternerContext) -> BodyShape {
    let mut seen = ShapeSeen { bound: collections::BTreeMap::new(), shape: BodyShape { constants: collections::BTreeMap::new(), unsigned: collections::BTreeSet::new(), roots: collections::BTreeSet::new(), aliases: collections::BTreeMap::new(), bound: collections::BTreeSet::new(), twice: collections::BTreeSet::new() }, lost: collections::BTreeSet::new() };
    for arg in args.iter() { bind_name(words.resolve(arg.name), &mut seen); }
    look_block(body, &Look::Bound, false, around, words, &mut seen);
    for (name, times) in seen.bound.iter() {
        let times = nikaia_std::num::value(times);
        seen.shape.bound.insert(name.to_owned());
        if times > 1 { seen.shape.twice.insert(name.to_owned()); }
    }
    for arg in args.iter() {
        let name = words.resolve(arg.name).to_owned();
        if once(&name, &seen) && is_unsigned(&plain_name(&arg.ty, words)) { seen.shape.unsigned.insert(name); }
    }
    look_block(body, &Look::Lets, false, around, words, &mut seen);
    look_block(body, &Look::Aliases, false, around, words, &mut seen);
    look_block(body, &Look::Aliases, false, around, words, &mut seen);
    for name in pinned.iter() { seen.lost.insert(name.to_owned()); }
    look_block(body, &Look::Lost, false, around, words, &mut seen);
    let mut through: Vec<String> = vec![];
    for name in seen.lost.iter() {
        let key = match seen.shape.aliases.get(name) { Some(__nikaia_value) => __nikaia_value, None => continue };
        through.push(key_root(&key));
    }
    for root in through.iter() { seen.lost.insert(root.to_owned()); }
    let mut kept: collections::BTreeSet<String> = collections::BTreeSet::new();
    for root in seen.shape.roots.iter() { if !seen.lost.contains(root) { kept.insert(root.to_owned()); } }
    seen.shape.roots = kept;
    seen.shape
}

pub fn elements_key(shape: &BodyShape, expr: &Expr, words: &winnow_grammar::InternerContext) -> Option<String> {
    match expr {
        Expr::Variable(n) => {
            let n = *n;
            let name = words.resolve(n);
            if shape.roots.contains(name) { return Some(name.to_owned()); }
            let key = match shape.aliases.get(name) { Some(__nikaia_value) => __nikaia_value, None => return None };
            return Some(key.to_owned());
        },
        Expr::Index { base, .. } => {
            let base = nikaia_std::boxed::open(base);
            let key = match elements_key(shape, base, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
            Some(format!("{}[]", key))
        },
        _ => None,
    }
}

pub fn tracks(shape: &BodyShape, key: &str) -> bool { shape.roots.contains(&key_root(key)) }

pub fn writes_a_value(method: &str, args: i64) -> Option<i64> {
    match method {
        "push" => if args == 1 { Some(0) } else { None },
        "fill" => if args == 1 { Some(0) } else { None },
        "insert" => if args == 2 { Some(1) } else { None },
        "resize" => if args == 2 { Some(1) } else { None },
        _ => None,
    }
}

pub fn only_removes(method: &str) -> bool { matches!(method, "pop" | "remove" | "swap_remove" | "clear" | "truncate" | "retain" | "dedup") }

pub fn key_root(key: &str) -> String {
    let parts: Vec<&str> = key.split("[").collect::<Vec<_>>();
    (*nikaia_std::index::get(&parts, 0)).to_owned()
}

pub fn root_name(expr: &Expr, words: &winnow_grammar::InternerContext) -> Option<String> {
    match expr {
        Expr::Variable(n) => { let n = *n; Some(words.resolve(n).to_owned()) },
        Expr::Index { base, .. } => { let base = nikaia_std::boxed::open(base); root_name(base, words) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); root_name(base, words) },
        _ => None,
    }
}

pub fn is_unsigned(ty: &str) -> bool { matches!(ty, "u8" | "u16" | "u32" | "u64" | "usize") }

pub fn is_whole_number(ty: &str) -> bool {
    match ty {
        "i8" => true,
        "i16" => true,
        "i32" => true,
        "i64" => true,
        "isize" => true,
        _ => is_unsigned(ty),
    }
}

fn plain_name(ty: &Type, words: &winnow_grammar::InternerContext) -> String {
    if !ty.generics.is_empty() { return String::from(""); }
    words.resolve(ty.name).to_owned()
}

fn bind_name(name: &str, seen: &mut ShapeSeen) {
    let before = nikaia_std::index::or(seen.bound.get(name), || 0);
    seen.bound.insert(name.to_owned(), before + 1);
}

fn bind_all(names: &[winnow_grammar::Symbol], words: &winnow_grammar::InternerContext, seen: &mut ShapeSeen) { for n in names.iter() { bind_name(words.resolve(*n), seen); } }

fn once(name: &str, seen: &ShapeSeen) -> bool { nikaia_std::index::or(seen.bound.get(name), || 0) == 1 }

fn bind_pattern(pattern: &MatchPattern, words: &winnow_grammar::InternerContext, seen: &mut ShapeSeen) {
    match pattern {
        MatchPattern::Path(segments) => bind_all(segments, words, seen),
        MatchPattern::Tuple { parts, .. } => { for p in parts.iter() { bind_pattern(p, words, seen); } },
        MatchPattern::Named { bindings, .. } => bind_all(bindings, words, seen),
        MatchPattern::Or(alternatives) => { for p in alternatives.iter() { bind_pattern(p, words, seen); } },
        _ => { },
    }
}

fn literal_count(expr: &Expr) -> Option<i64> {
    match expr {
        Expr::LitInt { value, negative } => { let negative = *negative; let value = *value; integer_as_count(&integer(value, negative)) },
        _ => None,
    }
}

fn is_list_literal(expr: &Expr) -> bool { matches!(expr, Expr::ListLit { .. }) }

fn is_index(expr: &Expr) -> bool { matches!(expr, Expr::Index { .. }) }

fn declared_name(ty: Option<&Type>, words: &winnow_grammar::InternerContext) -> Option<String> {
    let t = match ty { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(plain_name(t, words))
}

fn read_let(name: &str, mutable: bool, ty: Option<&Type>, value: &Expr, words: &winnow_grammar::InternerContext, seen: &mut ShapeSeen) {
    if !once(name, &seen) { return; }
    let declared = declared_name(ty, words);
    let whole = declared.is_none() || is_whole_number(nikaia_std::index::or(declared.as_deref(), || ""));
    if is_unsigned(nikaia_std::index::or(declared.as_deref(), || "")) { seen.shape.unsigned.insert(name.to_owned()); }
    if !mutable && whole {
        let n = literal_count(value);
        if n.is_some() { seen.shape.constants.insert(name.to_owned(), nikaia_std::index::or(n, || 0)); }
    }
    if is_list_literal(value) { seen.shape.roots.insert(name.to_owned()); }
}

fn read_alias(name: &str, value: &Expr, words: &winnow_grammar::InternerContext, seen: &mut ShapeSeen) {
    if !once(name, &seen) || seen.shape.roots.contains(name) { return; }
    let key = match elements_key(&seen.shape, value, words) { Some(__nikaia_value) => __nikaia_value, None => return };
    seen.shape.aliases.insert(name.to_owned(), key);
}

fn lose(expr: &Expr, words: &winnow_grammar::InternerContext, seen: &mut ShapeSeen) {
    let root = match root_name(expr, words) { Some(__nikaia_value) => __nikaia_value, None => return };
    seen.lost.insert(root);
}

fn lose_by_method(receiver: &Expr, method: &str, args: &[Expr], around: &Around, words: &winnow_grammar::InternerContext, seen: &mut ShapeSeen) {
    let writes = writes_a_value(method, args.len() as i64).is_some();
    if !writes && !only_removes(method) && !keeps_length(method) { lose(receiver, words, seen); }
    if !writes && (around.changing_methods.contains(method) || !keeps_length(method)) { for arg in args.iter() { lose(arg, words, seen); } }
}

fn lose_by_call(func: &Expr, args: &[Expr], around: &Around, words: &winnow_grammar::InternerContext, seen: &mut ShapeSeen) {
    let params = callee_params(func, around, words);
    let mut at: i64 = 0;
    for arg in args.iter() {
        if hands_on((params).as_ref(), at) { lose(arg, words, seen); }
        at += 1;
    }
}

fn callee_params(func: &Expr, around: &Around, words: &winnow_grammar::InternerContext) -> Option<Vec<bool>> {
    match func {
        Expr::Variable(name) => {
            let name = *name;
            let params = match around.functions.get(words.resolve(name)) { Some(__nikaia_value) => __nikaia_value, None => return None };
            Some(params.to_owned())
        },
        _ => None,
    }
}

fn hands_on(params: Option<&Vec<bool>>, at: i64) -> bool {
    let given = match params { Some(__nikaia_value) => __nikaia_value, None => return true };
    if at < given.len() as i64 { return *nikaia_std::index::get(&given, nikaia_std::index::at(at)); }
    true
}

fn look_statement_here(stmt: &Stmt, look: &Look, words: &winnow_grammar::InternerContext, seen: &mut ShapeSeen) {
    match look {
        Look::Bound => match stmt {
            Stmt::Let { names, .. } => bind_all(names, words, seen),
            Stmt::Comptime { name, .. } => { let name = *name; bind_name(words.resolve(name), seen) },
            Stmt::For { bindings, .. } => bind_all(bindings, words, seen),
            _ => { },
        },
        Look::Lets => match stmt {
            Stmt::Let { names, mutable, ty, value } => {
                let mutable = *mutable;
                if names.len() == 1 { read_let(words.resolve(*nikaia_std::index::get(&names, 0)), mutable, (ty).as_ref(), value, words, seen); }
            },
            _ => { },
        },
        Look::Aliases => match stmt {
            Stmt::Let { names, mutable, value, .. } => {
                let mutable = *mutable;
                if names.len() == 1 && !mutable { read_alias(words.resolve(*nikaia_std::index::get(&names, 0)), value, words, seen); }
            },
            _ => { },
        },
        Look::Lost => match stmt {
            Stmt::Assign { target, op, .. } => { if op.is_some() || !is_index(target) { lose(target, words, seen); } },
            Stmt::Let { mutable, value, .. } => {
                let mutable = *mutable;
                if mutable { lose(value, words, seen); }
            },
            _ => { },
        },
    }
}

fn look_expr_here(expr: &Expr, look: &Look, deferred: bool, around: &Around, words: &winnow_grammar::InternerContext, seen: &mut ShapeSeen) {
    match look {
        Look::Bound => match expr {
            Expr::Closure { params, .. } => bind_all(params, words, seen),
            Expr::Match { arms, .. } => { for arm in arms.iter() { bind_pattern(&arm.pattern, words, seen); } },
            Expr::Select(arms) => {
                for arm in arms.iter() {
                    let n = match arm.binding { Some(__nikaia_value) => __nikaia_value, None => continue };
                    bind_name(words.resolve(n), seen);
                }
            },
            Expr::TryCatch { .. } => bind_name("error", seen),
            _ => { },
        },
        Look::Lost => {
            if deferred {
                match expr {
                    Expr::Variable(n) => {
                        let n = *n;
                        seen.lost.insert(words.resolve(n).to_owned());
                    },
                    _ => { },
                }
            }
            match expr {
                Expr::MethodCall { receiver, method, args, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; lose_by_method(receiver, words.resolve(method), args, around, words, seen) },
                Expr::SafeMethod { receiver, method, args, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; lose_by_method(receiver, words.resolve(method), args, around, words, seen) },
                Expr::Call { func, args, .. } => { let func = nikaia_std::boxed::open(func); lose_by_call(func, args, around, words, seen) },
                _ => { },
            }
        },
        _ => { },
    }
}

fn look_block(block: &Block, look: &Look, deferred: bool, around: &Around, words: &winnow_grammar::InternerContext, seen: &mut ShapeSeen) { for stmt in block.stmts.iter() { look_statement(&stmt.node, look, deferred, around, words, seen); } }

fn look_statement(stmt: &Stmt, look: &Look, deferred: bool, around: &Around, words: &winnow_grammar::InternerContext, seen: &mut ShapeSeen) {
    look_statement_here(stmt, look, words, seen);
    match stmt {
        Stmt::For { iter, body, .. } => {
            look_expr(iter, look, deferred, around, words, seen);
            look_block(body, look, deferred, around, words, seen);
        },
        Stmt::While { cond, body } => {
            look_expr(cond, look, deferred, around, words, seen);
            look_block(body, look, deferred, around, words, seen);
        },
        Stmt::Let { value, .. } => look_expr(value, look, deferred, around, words, seen),
        Stmt::Comptime { value, .. } => look_expr(value, look, deferred, around, words, seen),
        Stmt::Expr(value) => look_expr(value, look, deferred, around, words, seen),
        Stmt::Assign { target, value, .. } => {
            look_expr(target, look, deferred, around, words, seen);
            look_expr(value, look, deferred, around, words, seen);
        },
        Stmt::Return(value) => look_maybe((value).as_ref(), look, deferred, around, words, seen),
        _ => { },
    }
}

fn look_maybe(expr: Option<&Expr>, look: &Look, deferred: bool, around: &Around, words: &winnow_grammar::InternerContext, seen: &mut ShapeSeen) { look_expr(match expr { Some(__nikaia_value) => __nikaia_value, None => return }, look, deferred, around, words, seen); }

fn look_all(exprs: &[Expr], look: &Look, deferred: bool, around: &Around, words: &winnow_grammar::InternerContext, seen: &mut ShapeSeen) { for e in exprs.iter() { look_expr(e, look, deferred, around, words, seen); } }

fn look_config(config: &[ConfigArg], look: &Look, deferred: bool, around: &Around, words: &winnow_grammar::InternerContext, seen: &mut ShapeSeen) { for c in config.iter() { look_expr(&c.value, look, deferred, around, words, seen); } }

fn look_fields(fields: &[FieldInit], look: &Look, deferred: bool, around: &Around, words: &winnow_grammar::InternerContext, seen: &mut ShapeSeen) { for field in fields.iter() { look_maybe((field.value).as_ref(), look, deferred, around, words, seen); } }

fn look_expr(expr: &Expr, look: &Look, deferred: bool, around: &Around, words: &winnow_grammar::InternerContext, seen: &mut ShapeSeen) {
    look_expr_here(expr, look, deferred, around, words, seen);
    match expr {
        Expr::Match { value, arms } => {
            let value = nikaia_std::boxed::open(value);
            look_expr(value, look, deferred, around, words, seen);
            for arm in arms.iter() {
                look_maybe((arm.guard).as_ref(), look, deferred, around, words, seen);
                look_expr(&arm.body, look, deferred, around, words, seen);
            }
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            look_expr(start, look, deferred, around, words, seen);
            look_expr(end, look, deferred, around, words, seen);
        },
        Expr::Tuple(items) => look_all(items, look, deferred, around, words, seen),
        Expr::ListLit { items, .. } => look_all(items, look, deferred, around, words, seen),
        Expr::LitInterpolated { parts } => {
            for part in parts.iter() {
                match part {
                    FPart::Hole { expr, .. } => look_expr(expr, look, deferred, around, words, seen),
                    _ => { },
                }
            }
        },
        Expr::If { cond, then_branch, else_branch } => {
            let cond = nikaia_std::boxed::open(cond);
            look_expr(cond, look, deferred, around, words, seen);
            look_block(then_branch, look, deferred, around, words, seen);
            let other = match else_branch { Some(__nikaia_value) => __nikaia_value, None => return };
            look_block(other, look, deferred, around, words, seen);
        },
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            look_expr(func, look, deferred, around, words, seen);
            look_all(args, look, deferred, around, words, seen);
            look_config(config, look, deferred, around, words, seen);
        },
        Expr::Spawn { body, .. } => { let body = nikaia_std::boxed::open(body); look_expr(body, look, true, around, words, seen) },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            look_expr(receiver, look, deferred, around, words, seen);
            look_all(args, look, deferred, around, words, seen);
            look_config(config, look, deferred, around, words, seen);
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            look_expr(receiver, look, deferred, around, words, seen);
            look_all(args, look, deferred, around, words, seen);
            look_config(config, look, deferred, around, words, seen);
        },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); look_expr(base, look, deferred, around, words, seen) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); look_expr(base, look, deferred, around, words, seen) },
        Expr::StructLit { fields, .. } => look_fields(fields, look, deferred, around, words, seen),
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            look_expr(base, look, deferred, around, words, seen);
            look_fields(fields, look, deferred, around, words, seen);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); look_expr(expr, look, deferred, around, words, seen) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); look_expr(inner, look, deferred, around, words, seen) },
        Expr::Throw(inner) => { let inner = nikaia_std::boxed::open(inner); look_expr(inner, look, deferred, around, words, seen) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); look_expr(expr, look, deferred, around, words, seen) },
        Expr::TryCatch { expr, handler } => {
            let expr = nikaia_std::boxed::open(expr);
            look_expr(expr, look, deferred, around, words, seen);
            look_block(handler, look, deferred, around, words, seen);
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            look_expr(lhs, look, deferred, around, words, seen);
            look_expr(rhs, look, deferred, around, words, seen);
        },
        Expr::Return(value) => { let value = nikaia_std::boxed::open(value); look_maybe((value).as_ref(), look, deferred, around, words, seen) },
        Expr::Index { base, index } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            look_expr(base, look, deferred, around, words, seen);
            look_expr(index, look, deferred, around, words, seen);
        },
        Expr::Coalesce { value, fallback } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            look_expr(value, look, deferred, around, words, seen);
            look_expr(fallback, look, deferred, around, words, seen);
        },
        Expr::Select(arms) => {
            for arm in arms.iter() { look_expr(&arm.value, look, deferred, around, words, seen); }
            for arm in arms.iter() { look_block(&arm.body, look, true, around, words, seen); }
        },
        Expr::Block(b) => look_block(b, look, deferred, around, words, seen),
        Expr::Overlap(b) => look_block(b, look, true, around, words, seen),
        Expr::Unsafe(b) => look_block(b, look, deferred, around, words, seen),
        Expr::Closure { body, .. } => look_block(body, look, true, around, words, seen),
        _ => { },
    }
}


// --- bounds_walk.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BoundsContext {
    pub lengths: collections::BTreeSet<i64>,
    pub sized: collections::BTreeSet<i64>,
    pub arithmetic: collections::BTreeMap<i64, String>,
    pub nonnegative: collections::BTreeSet<i64>,
    pub char_codes: collections::BTreeSet<i64>,
    pub ensured: collections::BTreeMap<String, Ensured>,
    pub given: collections::BTreeMap<String, Range>,
    pub negations: collections::BTreeMap<i64, String>,
    pub classes: collections::BTreeMap<String, Range>,
    pub text_lengths: collections::BTreeMap<String, Range>,
    pub text_classes: collections::BTreeMap<String, Range>,
    pub around: Around,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Ensured {
    pub params: Vec<String>,
    pub chars: Vec<bool>,
    pub conditions: Vec<Vec<SolverTerm>>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BoundsProven {
    pub indices: collections::BTreeSet<i64>,
    pub arithmetic: collections::BTreeSet<i64>,
    pub nonnegative: collections::BTreeSet<i64>,
    pub negations: collections::BTreeSet<i64>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct BoundsFacts {
    ints: collections::BTreeSet<String>,
    facts: Vec<i64>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct BoundsChanged {
    values: collections::BTreeSet<String>,
    lengths: collections::BTreeSet<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct BoundsWalk {
    arena: TermArena,
    proven: BoundsProven,
    axioms: collections::BTreeMap<String, Vec<i64>>,
    unsized_names: collections::BTreeSet<String>,
    floors: collections::BTreeMap<String, i64>,
    pinned: collections::BTreeSet<String>,
    nonnegative: collections::BTreeSet<String>,
    codes: i64,
    loop_classes: collections::BTreeMap<String, Range>,
    shape: BodyShape,
    assumed: collections::BTreeMap<String, Range>,
    written: collections::BTreeMap<String, Range>,
    poisoned: collections::BTreeSet<String>,
    collecting: bool,
    at: i64,
}

fn length_below() -> i64 { 1152921504606846976i64 }

fn solvable() -> i64 { 4611686018427387904i64 }

fn most_facts() -> i64 { 48 }

fn call_depth() -> i64 { 4 }

fn no_proofs() -> BoundsProven { BoundsProven { indices: collections::BTreeSet::new(), arithmetic: collections::BTreeSet::new(), nonnegative: collections::BTreeSet::new(), negations: collections::BTreeSet::new() } }

fn nothing_changed() -> BoundsChanged { BoundsChanged { values: collections::BTreeSet::new(), lengths: collections::BTreeSet::new() } }

#[allow(clippy::too_many_arguments)]
pub fn bounds_aggressive(args: &[FnArg], body: &Block, nonnegative: collections::BTreeSet<String>, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) -> BoundsProven {
    let pinned = pinned_in(body, words);
    let shape = shape_of(args, body, &pinned, &context.around, words);
    let mut walk = BoundsWalk { arena: TermArena::empty(), proven: no_proofs(), axioms: collections::BTreeMap::new(), unsized_names: collections::BTreeSet::new(), floors: collections::BTreeMap::new(), pinned, nonnegative, codes: 0, loop_classes: collections::BTreeMap::new(), shape, assumed: collections::BTreeMap::new(), written: collections::BTreeMap::new(), poisoned: collections::BTreeSet::new(), collecting: false, at: 0 };
    let mut settled = false;
    if !walk.shape.roots.is_empty() {
        walk.collecting = true;
        for _round in 0..2 {
            bounding_pass(&mut walk, args, body, context, program, words, node_of, ask);
            walk.assumed = bounding_found(&walk);
        }
        walk.collecting = false;
        for _round in 0..4 {
            walk.proven = no_proofs();
            bounding_pass(&mut walk, args, body, context, program, words, node_of, ask);
            let found = bounding_found(&walk);
            let before = walk.assumed.len() as i64;
            let mut kept: collections::BTreeMap<String, Range> = collections::BTreeMap::new();
            for (key, bound) in walk.assumed.iter() {
                let seen = match found.get(key) { Some(__nikaia_value) => __nikaia_value, None => continue };
                if bound.holds(&seen) { kept.insert(key.to_owned(), bound.clone()); }
            }
            walk.assumed = kept;
            if (walk.assumed.len() as i64) == before {
                settled = true;
                break;
            }
        }
    }
    if !settled {
        if !walk.shape.roots.is_empty() { walk.assumed = collections::BTreeMap::new(); }
        walk.proven = no_proofs();
        bounding_pass(&mut walk, args, body, context, program, words, node_of, ask);
    }
    walk.proven
}

#[allow(clippy::too_many_arguments)]
fn bounding_pass(walk: &mut BoundsWalk, args: &[FnArg], body: &Block, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) {
    walk.written = collections::BTreeMap::new();
    walk.poisoned = collections::BTreeSet::new();
    let mut facts = BoundsFacts { ints: collections::BTreeSet::new(), facts: vec![] };
    for arg in args.iter() {
        let name = words.resolve(arg.name).to_owned();
        let ty = words.resolve(arg.ty.name).to_owned();
        if arg.ty.generics.is_empty() && is_whole_number(&ty) {
            facts.ints.insert(name.to_owned());
            if ty.starts_with("u") { bounding_at_least_zero(walk, &mut facts, &name); }
        }
        if ty == "Vec" || ty == "List" || ty == "Array" { bounding_at_least_zero(walk, &mut facts, &length_of(&name)); }
    }
    for (name, range) in context.given.iter() {
        if !walk.shape.bound.contains(name) {
            facts.ints.insert(name.to_owned());
            bounding_bounded(walk, &mut facts, name, range);
        }
    }
    for (name, range) in context.text_lengths.iter() { if !walk.shape.bound.contains(name) { bounding_bounded(walk, &mut facts, &length_of(name), range); } }
    bounding_block(walk, body, &mut facts, context, program, words, node_of, ask);
}

fn bounding_found(walk: &BoundsWalk) -> collections::BTreeMap<String, Range> {
    let mut out: collections::BTreeMap<String, Range> = collections::BTreeMap::new();
    for (key, bound) in walk.written.iter() { if bound.is_bounded() && !bounding_poisoned(walk, key) { out.insert(key.to_owned(), bound.clone()); } }
    out
}

fn bounding_poisoned(walk: &BoundsWalk, key: &str) -> bool {
    let mut at = key_root(key);
    let parts: Vec<&str> = key.split("[").collect::<Vec<_>>();
    for _part in 0..parts.len() as i64 {
        if walk.poisoned.contains(&at) { return true; }
        at.push_str("[]");
    }
    false
}

fn bounding_assumed(walk: &BoundsWalk, key: &str) -> Option<Range> {
    let bound = match walk.assumed.get(key) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(bound.clone())
}

#[allow(clippy::too_many_arguments)]
fn bounding_write(walk: &mut BoundsWalk, key: &str, value: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) {
    if !tracks(&walk.shape, key) { return; }
    let inner = format!("{}[]", key);
    match value {
        Expr::ListLit { items, .. } => {
            for item in items.iter() { bounding_write(walk, &inner, item, facts, context, program, words, node_of, ask); }
            return;
        },
        _ => { },
    }
    let range = bounding_range(walk, value, facts, context, program, words, node_of, ask);
    if range.is_some() {
        bounding_join(walk, key, nikaia_std::index::or(range, || Range::open()));
        return;
    }
    let elements = elements_key(&walk.shape, value, words);
    if elements.is_some() {
        let bound = bounding_assumed(&walk, nikaia_std::index::or(elements.as_deref(), || ""));
        if bound.is_some() { bounding_join(walk, &inner, nikaia_std::index::or(bound, || Range::open())); } else { walk.poisoned.insert(inner); }
        return;
    }
    walk.poisoned.insert(key.to_owned());
}

fn bounding_join(walk: &mut BoundsWalk, key: &str, range: Range) {
    if !range.is_bounded() {
        walk.poisoned.insert(key.to_owned());
        return;
    }
    let mut joined = range;
    let was = walk.written.get(key);
    if was.is_some() { joined = nikaia_std::index::or(was, || Range::open()).join(&range); }
    walk.written.insert(key.to_owned(), joined);
}

fn bounding_proves(walk: &BoundsWalk, facts: &BoundsFacts, goal: i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) -> bool {
    let mut all = facts.facts.to_owned();
    for (name, axiom) in walk.axioms.iter() {
        if !walk.unsized_names.contains(name) {
            for fact in axiom.iter() {
                let fact = nikaia_std::num::value(fact);
                all.push(fact);
            }
        }
    }
    for (name, floor) in walk.floors.iter() {
        let floor = nikaia_std::num::value(floor);
        if walk.unsized_names.contains(name) { all.push(floor); }
    }
    ask(&walk.arena, &all, goal)
}

fn bounding_term(walk: &mut BoundsWalk, term: i64, facts: &BoundsFacts, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) -> Range {
    let known = walk.arena.constant(term);
    if known.is_some() { return Range::exactly(nikaia_std::index::or(known, || 0)); }
    let guess = candidate(term, &facts.facts, &|at| { walk.arena.at(at) });
    let mut confirmed = Range::open();
    if guess.hi.is_some() {
        let hi = nikaia_std::index::or(guess.hi, || 0);
        let k = walk.arena.int(hi);
        let goal = walk.arena.le(term, k);
        if bounding_proves(&walk, facts, goal, ask) { confirmed.hi = Some(hi); }
    }
    if guess.lo.is_some() {
        let lo = nikaia_std::index::or(guess.lo, || 0);
        let k = walk.arena.int(lo);
        let goal = walk.arena.ge(term, k);
        if bounding_proves(&walk, facts, goal, ask) { confirmed.lo = Some(lo); }
    }
    confirmed
}

#[allow(clippy::too_many_arguments)]
fn bounding_range(walk: &mut BoundsWalk, expr: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) -> Option<Range> {
    let term = bounding_lin(walk, expr, facts, context, program, words, node_of);
    if term.is_some() { return Some(bounding_term(walk, nikaia_std::index::or(term, || 0), facts, ask)); }
    match expr {
        Expr::Binary { op, lhs, rhs, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); return bounding_range_of(walk, op, lhs, rhs, facts, context, program, words, node_of, ask) },
        Expr::Unary { op, expr } => {
            let expr = nikaia_std::boxed::open(expr);
            match op {
                UnaryOp::Neg => {
                    let inner = match bounding_range(walk, expr, facts, context, program, words, node_of, ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
                    return Some(inner.neg());
                },
                _ => { },
            }
        },
        Expr::Cast { expr, ty } => {
            let expr = nikaia_std::boxed::open(expr);
            if ty.generics.is_empty() {
                let into = match Range::of_type(words.resolve(ty.name)) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let got = match bounding_range(walk, expr, facts, context, program, words, node_of, ask) { Some(__nikaia_value) => __nikaia_value, None => return Some(into) };
                return Some(got.meet(&into));
            }
        },
        Expr::MethodCall { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            if args.is_empty() {
                let name = words.resolve(method);
                if name == "len" { return Some(Range { lo: Some(0), hi: None }); }
                if !name.starts_with("truncating_") { return None; }
                let into = match Range::of_type(&bounding_dropped(name, 11)) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let got = match bounding_range(walk, receiver, facts, context, program, words, node_of, ask) { Some(__nikaia_value) => __nikaia_value, None => return Some(into) };
                if into.holds(&got) { return Some(got); }
                return Some(into);
            }
        },
        Expr::Index { base, .. } => {
            let base = nikaia_std::boxed::open(base);
            let key = match elements_key(&walk.shape, base, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
            return bounding_assumed(&walk, &key);
        },
        _ => { },
    }
    None
}

fn bounding_dropped(text: &str, count: i64) -> String {
    let c: Vec<char> = nikaia_std::list::chars(text.chars());
    let mut out: String = String::from("");
    for k in count..c.len() as i64 { out.push(*nikaia_std::index::get(&c, nikaia_std::index::at(k))); }
    out
}

#[allow(clippy::too_many_arguments)]
fn bounding_range_of(walk: &mut BoundsWalk, op: &BinaryOp, lhs: &Expr, rhs: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) -> Option<Range> {
    match op {
        BinaryOp::Add => {
            let a = match bounding_range(walk, lhs, facts, context, program, words, node_of, ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let b = match bounding_range(walk, rhs, facts, context, program, words, node_of, ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
            return Some(a.add(&b));
        },
        BinaryOp::Sub => {
            let a = match bounding_range(walk, lhs, facts, context, program, words, node_of, ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let b = match bounding_range(walk, rhs, facts, context, program, words, node_of, ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
            return Some(a.add(&b.neg()));
        },
        BinaryOp::Mul => {
            let a = match bounding_range(walk, lhs, facts, context, program, words, node_of, ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let b = match bounding_range(walk, rhs, facts, context, program, words, node_of, ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
            return Some(a.mul(&b));
        },
        BinaryOp::Rem => {
            let n = match bounding_range(walk, rhs, facts, context, program, words, node_of, ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let low = match n.lo { Some(__nikaia_value) => __nikaia_value, None => return None };
            let high = match n.hi { Some(__nikaia_value) => __nikaia_value, None => return None };
            if low < 1 { return None; }
            let x = bounding_range(walk, lhs, facts, context, program, words, node_of, ask);
            return Some(bounding_remainder((x).as_ref(), high));
        },
        BinaryOp::Shr => {
            let by = match bounding_range(walk, rhs, facts, context, program, words, node_of, ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let k = match by.lo { Some(__nikaia_value) => __nikaia_value, None => return None };
            let same = match by.hi { Some(__nikaia_value) => __nikaia_value, None => return None };
            if k != same || k < 0 || k >= 64 { return None; }
            let x = match bounding_range(walk, lhs, facts, context, program, words, node_of, ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let lo = match x.lo { Some(__nikaia_value) => __nikaia_value, None => return None };
            if lo < 0 { return None; }
            let mut shifted = Range { lo: Some(lo >> k), hi: None };
            if x.hi.is_some() { shifted.hi = Some(nikaia_std::index::or(x.hi, || 0) >> k); }
            return Some(shifted);
        },
        BinaryOp::BitAnd => {
            let mut mask: Option<i64> = None;
            let first = bounding_mask(walk, lhs, facts, context, program, words, node_of);
            if first.is_some() { mask = first; }
            let second = bounding_mask(walk, rhs, facts, context, program, words, node_of);
            if second.is_some() { mask = second; }
            let most = match mask { Some(__nikaia_value) => __nikaia_value, None => return None };
            return Some(Range { lo: Some(0), hi: Some(most) });
        },
        _ => { },
    }
    None
}

fn bounding_remainder(x: Option<&Range>, high: i64) -> Range {
    let either = Range { lo: Some(1 - high), hi: Some(high - 1) };
    let known = match x { Some(__nikaia_value) => __nikaia_value, None => return either };
    let lo = match known.lo { Some(__nikaia_value) => __nikaia_value, None => return either };
    if lo < 0 { return either; }
    let hi = match known.hi { Some(__nikaia_value) => __nikaia_value, None => return Range { lo: Some(0), hi: Some(high - 1) } };
    Range { lo: Some(0), hi: Some(hi.min(high - 1)) }
}

fn bounding_mask(walk: &mut BoundsWalk, side: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64) -> Option<i64> {
    let term = match bounding_lin(walk, side, facts, context, program, words, node_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let c = match walk.arena.constant(term) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if c >= 0 { return Some(c); }
    None
}

#[allow(clippy::too_many_arguments)]
fn bounding_fits(walk: &mut BoundsWalk, op: &BinaryOp, lhs: &Expr, rhs: &Expr, ty: &str, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) -> bool {
    let bounds = match Range::of_type(ty) { Some(__nikaia_value) => __nikaia_value, None => return false };
    let widest_lo = match bounds.lo { Some(__nikaia_value) => __nikaia_value, None => return false };
    let widest_hi = match bounds.hi { Some(__nikaia_value) => __nikaia_value, None => return false };
    let lo = widest_lo.max(0 - solvable());
    let hi = widest_hi.min(solvable());
    let term = bounding_lin_of(walk, op, lhs, rhs, facts, context, program, words, node_of);
    if term.is_some() {
        let t = nikaia_std::index::or(term, || 0);
        let low = walk.arena.int(lo);
        let high = walk.arena.int(hi);
        let above = walk.arena.ge(t, low);
        let below = walk.arena.le(t, high);
        let goal = walk.arena.and(vec![above, below]);
        return bounding_proves(&walk, facts, goal, ask);
    }
    let range = match bounding_range_of(walk, op, lhs, rhs, facts, context, program, words, node_of, ask) { Some(__nikaia_value) => __nikaia_value, None => return false };
    bounds.holds(&range)
}

fn bounding_bounded(walk: &mut BoundsWalk, facts: &mut BoundsFacts, name: &str, range: &Range) {
    let n = walk.arena.var(name);
    if range.lo.is_some() {
        let lo = walk.arena.int(nikaia_std::index::or(range.lo, || 0));
        let fact = walk.arena.ge(n, lo);
        bounding_push(&walk, facts, fact);
    }
    if range.hi.is_some() {
        let hi = walk.arena.int(nikaia_std::index::or(range.hi, || 0));
        let fact = walk.arena.le(n, hi);
        bounding_push(&walk, facts, fact);
    }
}

fn bounding_push(walk: &BoundsWalk, facts: &mut BoundsFacts, fact: i64) {
    let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
    walk.arena.variables(fact, &mut read);
    for name in read.iter() { if walk.pinned.contains(&bounding_base_of(name)) { return; } }
    facts.facts.push(fact);
    if (facts.facts.len() as i64) > most_facts() { facts.facts.remove(0); }
}

fn bounding_base_of(name: &str) -> String {
    if !name.ends_with(".len()") { return name.to_owned(); }
    let c: Vec<char> = nikaia_std::list::chars(name.chars());
    let mut out: String = String::from("");
    for k in 0..c.len() as i64 - 6 { out.push(*nikaia_std::index::get(&c, (k) as usize)); }
    out
}

fn bounding_at_least_zero(walk: &mut BoundsWalk, facts: &mut BoundsFacts, name: &str) {
    let n = walk.arena.var(name);
    let zero = walk.arena.int(0);
    let fact = walk.arena.ge(n, zero);
    bounding_push(&walk, facts, fact);
}

fn bounding_forget(walk: &BoundsWalk, facts: &mut BoundsFacts, name: &str) {
    let length = length_of(name);
    let mut kept: Vec<i64> = vec![];
    for fact in facts.facts.iter() {
        let fact = nikaia_std::num::value(fact);
        if !walk.arena.mentions(fact, name) && !walk.arena.mentions(fact, &length) { kept.push(fact); }
    }
    facts.facts = kept;
}

fn bounding_forget_length(walk: &BoundsWalk, facts: &mut BoundsFacts, name: &str) {
    let length = length_of(name);
    let mut kept: Vec<i64> = vec![];
    for fact in facts.facts.iter() {
        let fact = nikaia_std::num::value(fact);
        if !walk.arena.mentions(fact, &length) { kept.push(fact); }
    }
    facts.facts = kept;
}

fn bounding_shift(walk: &mut BoundsWalk, facts: &mut BoundsFacts, name: &str, by: i64) {
    let now = walk.arena.var(name);
    let old = walk.arena.sub(now, by);
    let mut given: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    given.insert(name.to_owned(), old);
    for k in 0..facts.facts.len() as i64 {
        let fact = *nikaia_std::index::get(&facts.facts, (k) as usize);
        if walk.arena.mentions(fact, name) { { let __nikaia_stored = walk.arena.substitute(fact, &given); nikaia_std::index::set(&mut facts.facts, (k) as usize, __nikaia_stored); } }
    }
}

fn bounding_after_change(walk: &mut BoundsWalk, facts: &mut BoundsFacts, changed: &BoundsChanged) {
    for name in changed.values.iter() {
        bounding_forget(&walk, facts, name);
        if (walk.nonnegative.contains(name) || walk.shape.unsigned.contains(name)) && facts.ints.contains(name) { bounding_at_least_zero(walk, facts, name); }
    }
    for name in changed.lengths.iter() { bounding_forget_length(&walk, facts, name); }
}

fn bounding_lin(walk: &mut BoundsWalk, expr: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64) -> Option<i64> {
    match expr {
        Expr::LitInt { value, negative } => {
            let negative = *negative; let value = *value;
            let n = match integer_as_count(&integer(value, negative)) { Some(__nikaia_value) => __nikaia_value, None => return None };
            return Some(walk.arena.int(n));
        },
        Expr::Variable(name) => {
            let name = *name;
            let text = words.resolve(name);
            if walk.shape.constants.contains_key(text) {
                let n = nikaia_std::index::or(*nikaia_std::index::get(&walk.shape.constants, text), || 0);
                return Some(walk.arena.int(n));
            }
            if facts.ints.contains(text) { return Some(walk.arena.var(text)); }
        },
        Expr::MethodCall { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            if args.is_empty() && words.resolve(method) == "len" {
                match receiver {
                    Expr::Variable(name) => { let name = *name; return bounding_length(walk, receiver, words.resolve(name), context, node_of) },
                    _ => { },
                }
            }
        },
        Expr::Unary { op, expr } => {
            let expr = nikaia_std::boxed::open(expr);
            match op {
                UnaryOp::Neg => {
                    let a = match bounding_lin(walk, expr, facts, context, program, words, node_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
                    return Some(walk.arena.neg(a));
                },
                _ => { },
            }
        },
        Expr::Cast { expr, ty } => {
            let expr = nikaia_std::boxed::open(expr);
            if ty.generics.is_empty() && is_whole_number(words.resolve(ty.name)) {
                if context.char_codes.contains(&node_of(expr)) { return Some(bounding_code_of(walk, expr, context, words)); }
                return bounding_lin(walk, expr, facts, context, program, words, node_of);
            }
        },
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            if config.is_empty() {
                let callee = match bounding_callee(func, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let mut given: Vec<i64> = vec![];
                let mut every = true;
                for arg in args.iter() {
                    let term = bounding_lin(walk, arg, facts, context, program, words, node_of);
                    if term.is_none() { every = false; } else { given.push(nikaia_std::index::or(term, || 0)); }
                }
                if every {
                    let inlined = bounding_called(walk, &callee, &given, 0, program, words);
                    if inlined.is_some() { return inlined; }
                }
                let ensured = match *nikaia_std::index::get(&context.ensured, &callee) { Some(__nikaia_value) => __nikaia_value, None => return None };
                return bounding_ensured(walk, ensured, args, facts, context, program, words, node_of);
            }
        },
        Expr::Binary { op, lhs, rhs, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); return bounding_lin_of(walk, op, lhs, rhs, facts, context, program, words, node_of) },
        _ => { },
    }
    None
}

fn bounding_code(walk: &mut BoundsWalk) -> i64 {
    let name = format!("code#{}", walk.codes);
    walk.codes += 1;
    let v = walk.arena.var(&name);
    let zero = walk.arena.int(0);
    let most = walk.arena.int(1114111);
    let low = walk.arena.ge(v, zero);
    let high = walk.arena.le(v, most);
    walk.axioms.insert(name, vec![low, high]);
    v
}

fn bounding_code_of(walk: &mut BoundsWalk, expr: &Expr, context: &BoundsContext, words: &winnow_grammar::InternerContext) -> i64 {
    let v = bounding_code(walk);
    let name = match bounding_variable(expr, words) { Some(__nikaia_value) => __nikaia_value, None => return v };
    let class = match bounding_class_of(&walk, &name, context) { Some(__nikaia_value) => __nikaia_value, None => return v };
    let key = format!("code#{}", walk.codes - 1);
    let mut held: Vec<i64> = vec![];
    if class.lo.is_some() {
        let lo = walk.arena.int(nikaia_std::index::or(class.lo, || 0));
        held.push(walk.arena.ge(v, lo));
    }
    if class.hi.is_some() {
        let hi = walk.arena.int(nikaia_std::index::or(class.hi, || 0));
        held.push(walk.arena.le(v, hi));
    }
    walk.axioms.insert(key, held);
    v
}

#[allow(clippy::too_many_arguments)]
fn bounding_negation(walk: &mut BoundsWalk, expr: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) {
    if walk.collecting || context.negations.is_empty() { return; }
    let node = node_of(expr);
    let ty = match *nikaia_std::index::get(&context.negations, &node) { Some(__nikaia_value) => __nikaia_value, None => return };
    let operand = match expr {
        Expr::Unary { op, expr } => { let expr = nikaia_std::boxed::open(expr); match op {
            UnaryOp::Neg => expr,
            _ => return,
        } },
        _ => return,
    };
    let least = match Range::of_type(ty) { Some(__nikaia_value) => __nikaia_value, None => return };
    let lo = match least.lo { Some(__nikaia_value) => __nikaia_value, None => return };
    let above = (lo + 1).max(0 - solvable());
    let term = match bounding_lin(walk, operand, facts, context, program, words, node_of) { Some(__nikaia_value) => __nikaia_value, None => return };
    let k = walk.arena.int(above);
    let goal = walk.arena.ge(term, k);
    if bounding_proves(&walk, facts, goal, ask) { walk.proven.negations.insert(node); }
}

fn bounding_class_of(walk: &BoundsWalk, name: &str, context: &BoundsContext) -> Option<Range> {
    if walk.loop_classes.contains_key(name) && !walk.shape.twice.contains(name) { return (*nikaia_std::index::get(&walk.loop_classes, name)).copied(); }
    if walk.shape.bound.contains(name) { return None; }
    (*nikaia_std::index::get(&context.classes, name)).copied()
}

fn bounding_chars_of(iter: &Expr, words: &winnow_grammar::InternerContext) -> Option<String> {
    match iter {
        Expr::MethodCall { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            if !args.is_empty() || words.resolve(method) != "chars" { return None; }
            bounding_variable(receiver, words)
        },
        _ => None,
    }
}

fn bounding_callee(func: &Expr, words: &winnow_grammar::InternerContext) -> Option<String> {
    match func {
        Expr::Variable(name) => { let name = *name; Some(words.resolve(name).to_owned()) },
        Expr::Path(parts) => {
            let mut out: String = String::from("");
            for part in parts.iter() {
                if !out.is_empty() { out.push_str("::"); }
                out.push_str(words.resolve(*part));
            }
            Some(out)
        },
        _ => None,
    }
}

#[allow(clippy::too_many_arguments)]
fn bounding_ensured(walk: &mut BoundsWalk, ensured: &Ensured, args: &[Expr], facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64) -> Option<i64> {
    if (args.len() as i64) != ensured.params.len() as i64 || ensured.conditions.is_empty() { return None; }
    let mut given: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    for k in 0..args.len() as i64 {
        if *nikaia_std::index::get(&ensured.chars, (k) as usize) { given.insert((*nikaia_std::index::get(&ensured.params, (k) as usize)).to_owned(), bounding_code_of(walk, nikaia_std::index::get(&args, (k) as usize), context, words)); } else {
            let term = match bounding_lin(walk, nikaia_std::index::get(&args, (k) as usize), facts, context, program, words, node_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
            given.insert((*nikaia_std::index::get(&ensured.params, (k) as usize)).to_owned(), term);
        }
    }
    let name = format!("result#{}", walk.codes);
    walk.codes += 1;
    let result = walk.arena.var(&name);
    given.insert(String::from("result"), result);
    let mut holds: Vec<i64> = vec![];
    for nodes in ensured.conditions.iter() {
        let read = walk.arena.adopt(nodes);
        holds.push(walk.arena.substitute(read, &given));
    }
    walk.axioms.insert(name, holds);
    Some(result)
}

fn bounding_variable(expr: &Expr, words: &winnow_grammar::InternerContext) -> Option<String> {
    match expr {
        Expr::Variable(name) => { let name = *name; Some(words.resolve(name).to_owned()) },
        _ => None,
    }
}

fn bounding_length(walk: &mut BoundsWalk, receiver: &Expr, name: &str, context: &BoundsContext, node_of: &impl Fn(&Expr) -> i64) -> Option<i64> {
    if !context.lengths.contains(&node_of(receiver)) { return None; }
    let length = length_of(name);
    let n = walk.arena.var(&length);
    if context.sized.contains(&node_of(receiver)) {
        if !walk.axioms.contains_key(&length) {
            let zero = walk.arena.int(0);
            let most = walk.arena.int(length_below());
            let low = walk.arena.ge(n, zero);
            let high = walk.arena.le(n, most);
            walk.axioms.insert(length, vec![low, high]);
        }
    } else {
        walk.unsized_names.insert(length.to_owned());
        if !walk.floors.contains_key(&length) {
            let zero = walk.arena.int(0);
            let low = walk.arena.ge(n, zero);
            walk.floors.insert(length, low);
        }
    }
    Some(n)
}

#[allow(clippy::too_many_arguments)]
fn bounding_lin_of(walk: &mut BoundsWalk, op: &BinaryOp, lhs: &Expr, rhs: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64) -> Option<i64> {
    let l = match bounding_lin(walk, lhs, facts, context, program, words, node_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let r = match bounding_lin(walk, rhs, facts, context, program, words, node_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
    bounding_combined(walk, op, l, r)
}

fn bounding_combined(walk: &mut BoundsWalk, op: &BinaryOp, l: i64, r: i64) -> Option<i64> {
    match op {
        BinaryOp::Add => return Some(walk.arena.add(l, r)),
        BinaryOp::Sub => return Some(walk.arena.sub(l, r)),
        BinaryOp::Mul => return bounding_product(walk, l, r),
        _ => { },
    }
    None
}

fn bounding_product(walk: &mut BoundsWalk, l: i64, r: i64) -> Option<i64> {
    if walk.arena.constant(l).is_none() && walk.arena.constant(r).is_none() { return None; }
    Some(walk.arena.mul(l, r))
}

fn bounding_called(walk: &mut BoundsWalk, wanted: &str, given: &[i64], depth: i64, program: &Program, words: &winnow_grammar::InternerContext) -> Option<i64> {
    if depth >= call_depth() { return None; }
    for item in program.items.iter() {
        match &item.node {
            Item::Fn { name, receiver, args, config, ret_type, body, .. } => {
                let name = *name;
                if receiver.is_some() || !config.is_empty() { continue; }
                let declared = match name { Some(__nikaia_value) => __nikaia_value, None => continue };
                if words.resolve(declared) != wanted { continue; }
                let ret = match ret_type { Some(__nikaia_value) => __nikaia_value, None => continue };
                if !ret.generics.is_empty() || !is_whole_number(words.resolve(ret.name)) || body.stmts.len() != 1 { continue; }
                for only in body.stmts.iter() {
                    match &only.node {
                        Stmt::Return(returned) => {
                            let value = match returned { Some(__nikaia_value) => __nikaia_value, None => continue };
                            if (args.len() as i64) != given.len() as i64 { return None; }
                            let mut env: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
                            for k in 0..args.len() as i64 { env.insert(words.resolve(nikaia_std::index::get(&args, (k) as usize).name).to_owned(), *nikaia_std::index::get(&given, (k) as usize)); }
                            return bounding_inline(walk, value, &env, depth, program, words);
                        },
                        _ => { },
                    }
                }
            },
            _ => { },
        }
    }
    None
}

fn bounding_inline(walk: &mut BoundsWalk, expr: &Expr, env: &collections::BTreeMap<String, i64>, depth: i64, program: &Program, words: &winnow_grammar::InternerContext) -> Option<i64> {
    match expr {
        Expr::LitInt { value, negative } => {
            let negative = *negative; let value = *value;
            let n = match integer_as_count(&integer(value, negative)) { Some(__nikaia_value) => __nikaia_value, None => return None };
            return Some(walk.arena.int(n));
        },
        Expr::Variable(name) => {
            let name = *name;
            let term = match *nikaia_std::index::get(&env, words.resolve(name)) { Some(__nikaia_value) => nikaia_std::num::value(__nikaia_value), None => return None };
            return Some(term);
        },
        Expr::Unary { op, expr } => {
            let expr = nikaia_std::boxed::open(expr);
            match op {
                UnaryOp::Neg => {
                    let a = match bounding_inline(walk, expr, env, depth, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
                    return Some(walk.arena.neg(a));
                },
                _ => { },
            }
        },
        Expr::Cast { expr, ty } => {
            let expr = nikaia_std::boxed::open(expr);
            if ty.generics.is_empty() && is_whole_number(words.resolve(ty.name)) { return bounding_inline(walk, expr, env, depth, program, words); }
        },
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            if config.is_empty() {
                let callee = match bounding_variable(func, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let mut given: Vec<i64> = vec![];
                for arg in args.iter() {
                    let term = match bounding_inline(walk, arg, env, depth, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
                    given.push(term);
                }
                return bounding_called(walk, &callee, &given, depth + 1, program, words);
            }
        },
        Expr::Binary { op, lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            let l = match bounding_inline(walk, lhs, env, depth, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let r = match bounding_inline(walk, rhs, env, depth, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
            return bounding_combined(walk, op, l, r);
        },
        _ => { },
    }
    None
}

fn bounding_claim(walk: &mut BoundsWalk, expr: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64) -> Option<i64> {
    match expr {
        Expr::LitBool(b) => { let b = *b; return Some(walk.arena.boolean(b)) },
        Expr::Unary { op, expr } => {
            let expr = nikaia_std::boxed::open(expr);
            match op {
                UnaryOp::Not => return bounding_denial(walk, expr, facts, context, program, words, node_of),
                _ => { },
            }
        },
        Expr::Binary { op, lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            match op {
                BinaryOp::And => {
                    let l = bounding_claim(walk, lhs, facts, context, program, words, node_of);
                    let r = bounding_claim(walk, rhs, facts, context, program, words, node_of);
                    if l.is_some() && r.is_some() { return Some(walk.arena.and(vec![nikaia_std::index::or(l, || 0), nikaia_std::index::or(r, || 0)])); }
                    if l.is_some() { return l; }
                    return r;
                },
                BinaryOp::Or => {
                    let l = match bounding_claim(walk, lhs, facts, context, program, words, node_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
                    let r = match bounding_claim(walk, rhs, facts, context, program, words, node_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
                    return Some(walk.arena.or(vec![l, r]));
                },
                _ => { },
            }
        },
        _ => { },
    }
    bounding_comparison(walk, expr, facts, context, program, words, node_of)
}

fn bounding_denial(walk: &mut BoundsWalk, expr: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64) -> Option<i64> {
    match expr {
        Expr::LitBool(b) => { let b = *b; return Some(walk.arena.boolean(!b)) },
        Expr::Unary { op, expr } => {
            let expr = nikaia_std::boxed::open(expr);
            match op {
                UnaryOp::Not => return bounding_claim(walk, expr, facts, context, program, words, node_of),
                _ => { },
            }
        },
        Expr::Binary { op, lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            match op {
                BinaryOp::Or => {
                    let l = bounding_denial(walk, lhs, facts, context, program, words, node_of);
                    let r = bounding_denial(walk, rhs, facts, context, program, words, node_of);
                    if l.is_some() && r.is_some() { return Some(walk.arena.and(vec![nikaia_std::index::or(l, || 0), nikaia_std::index::or(r, || 0)])); }
                    if l.is_some() { return l; }
                    return r;
                },
                BinaryOp::And => {
                    let l = match bounding_denial(walk, lhs, facts, context, program, words, node_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
                    let r = match bounding_denial(walk, rhs, facts, context, program, words, node_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
                    return Some(walk.arena.or(vec![l, r]));
                },
                _ => { },
            }
        },
        _ => { },
    }
    let atom = match bounding_comparison(walk, expr, facts, context, program, words, node_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(walk.arena.not(atom))
}

fn bounding_comparison(walk: &mut BoundsWalk, expr: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64) -> Option<i64> {
    match expr {
        Expr::Binary { op, lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            let compares = matches!(op, BinaryOp::Lt | BinaryOp::Le | BinaryOp::Gt | BinaryOp::Ge | BinaryOp::Eq | BinaryOp::Ne);
            if !compares { return None; }
            let a = match bounding_lin(walk, lhs, facts, context, program, words, node_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let b = match bounding_lin(walk, rhs, facts, context, program, words, node_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
            match op {
                BinaryOp::Lt => return Some(walk.arena.lt(a, b)),
                BinaryOp::Le => return Some(walk.arena.le(a, b)),
                BinaryOp::Gt => return Some(walk.arena.gt(a, b)),
                BinaryOp::Ge => return Some(walk.arena.ge(a, b)),
                BinaryOp::Eq => return Some(walk.arena.equal(a, b)),
                _ => return Some(walk.arena.unequal(a, b)),
            }
        },
        _ => { },
    }
    None
}

fn bounding_assume(walk: &mut BoundsWalk, facts: &mut BoundsFacts, cond: &Expr, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64) {
    let holds = match bounding_claim(walk, cond, &facts, context, program, words, node_of) { Some(__nikaia_value) => __nikaia_value, None => return };
    bounding_push(&walk, facts, holds);
}

fn bounding_assume_not(walk: &mut BoundsWalk, facts: &mut BoundsFacts, cond: &Expr, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64) {
    let holds = match bounding_denial(walk, cond, &facts, context, program, words, node_of) { Some(__nikaia_value) => __nikaia_value, None => return };
    bounding_push(&walk, facts, holds);
}

#[allow(clippy::too_many_arguments)]
fn bounding_inside(walk: &mut BoundsWalk, list: &str, index: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) -> bool {
    if walk.collecting || walk.pinned.contains(list) { return false; }
    let length = length_of(list);
    let len = walk.arena.var(&length);
    let at = bounding_lin(walk, index, facts, context, program, words, node_of);
    if at.is_none() {
        let range = match bounding_range(walk, index, facts, context, program, words, node_of, ask) { Some(__nikaia_value) => __nikaia_value, None => return false };
        let lo = match range.lo { Some(__nikaia_value) => __nikaia_value, None => return false };
        let hi = match range.hi { Some(__nikaia_value) => __nikaia_value, None => return false };
        if lo < 0 { return false; }
        let most = walk.arena.int(hi);
        let goal = walk.arena.lt(most, len);
        return bounding_proves(&walk, facts, goal, ask);
    }
    let position = nikaia_std::index::or(at, || 0);
    let zero = walk.arena.int(0);
    let low = walk.arena.ge(position, zero);
    let high = walk.arena.lt(position, len);
    let goal = walk.arena.and(vec![low, high]);
    bounding_proves(&walk, facts, goal, ask)
}

#[allow(clippy::too_many_arguments)]
fn bounding_index(walk: &mut BoundsWalk, base: &Expr, index: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) {
    match base {
        Expr::Variable(list) => {
            let list = *list;
            if bounding_inside(walk, words.resolve(list), index, facts, context, program, words, node_of, ask) { walk.proven.indices.insert(node_of(base)); }
        },
        _ => { },
    }
}

#[allow(clippy::too_many_arguments)]
fn bounding_block(walk: &mut BoundsWalk, block: &Block, facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) -> bool {
    let before = facts.ints.to_owned();
    let mut bound: Vec<String> = vec![];
    let mut leaves = false;
    for stmt in block.stmts.iter() {
        match &stmt.node {
            Stmt::Let { names, .. } => { for name in names.iter() { bound.push(words.resolve(*name).to_owned()); } },
            Stmt::Comptime { name, .. } => { let name = *name; bound.push(words.resolve(name).to_owned()) },
            _ => { },
        }
        walk.at = stmt.span.start as i64;
        if bounding_stmt(walk, &stmt.node, facts, context, program, words, node_of, ask) {
            leaves = true;
            break;
        }
    }
    for name in bound.iter() {
        bounding_forget(&walk, facts, name);
        facts.ints.remove(name);
        if before.contains(name) { facts.ints.insert(name.to_owned()); }
    }
    leaves
}

#[allow(clippy::too_many_arguments)]
fn bounding_maybe_block(walk: &mut BoundsWalk, block: Option<&Block>, facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) -> bool {
    let present = match block { Some(__nikaia_value) => __nikaia_value, None => return false };
    bounding_block(walk, present, facts, context, program, words, node_of, ask)
}

#[allow(clippy::too_many_arguments)]
fn bounding_stmt(walk: &mut BoundsWalk, stmt: &Stmt, facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) -> bool {
    match stmt {
        Stmt::Let { names, ty, value, .. } => {
            bounding_let(walk, names, (ty).as_ref(), value, facts, context, program, words, node_of, ask);
            return false;
        },
        Stmt::Comptime { name, value, .. } => {
            let name = *name;
            bounding_expr(walk, value, facts, context, program, words, node_of, ask);
            let text = words.resolve(name);
            bounding_forget(&walk, facts, text);
            facts.ints.remove(text);
            return false;
        },
        Stmt::Assign { target, op, value } => {
            let at = walk.at;
            bounding_expr(walk, value, facts, context, program, words, node_of, ask);
            bounding_place(walk, target, facts, context, program, words, node_of, ask);
            bounding_compound(walk, (op).as_ref(), target, value, at, &facts, context, program, words, node_of, ask);
            if op.is_none() {
                match target {
                    Expr::Index { base, .. } => {
                        let base = nikaia_std::boxed::open(base);
                        let key = elements_key(&walk.shape, base, words);
                        if key.is_some() { bounding_write(walk, nikaia_std::index::or(key.as_deref(), || ""), value, &facts, context, program, words, node_of, ask); }
                    },
                    _ => { },
                }
            }
            match target {
                Expr::Variable(name) => { let name = *name; bounding_assign(walk, facts, words.resolve(name), (op).as_ref(), value, context, program, words, node_of, ask) },
                _ => { },
            }
            return false;
        },
        Stmt::For { bindings, iter, body } => {
            bounding_for(walk, bindings, iter, body, facts, context, program, words, node_of, ask);
            return false;
        },
        Stmt::While { cond, body } => {
            let mut changed = bounding_changed(body, context, words);
            bounding_extend(&mut changed, &bounding_changed_in_expr(cond, context, words));
            bounding_after_change(walk, facts, &changed);
            bounding_expr(walk, cond, facts, context, program, words, node_of, ask);
            let mut inner = facts.clone();
            bounding_assume(walk, &mut inner, cond, context, program, words, node_of);
            bounding_block(walk, body, &mut inner, context, program, words, node_of, ask);
            if !breaks(body, words) { bounding_assume_not(walk, facts, cond, context, program, words, node_of); }
            return false;
        },
        Stmt::Return(value) => {
            let returned = match value { Some(__nikaia_value) => __nikaia_value, None => return true };
            bounding_expr(walk, returned, facts, context, program, words, node_of, ask);
            return true;
        },
        Stmt::Break => return true,
        Stmt::Continue => return true,
        Stmt::Expr(expr) => return bounding_expr_leaves(walk, expr, facts, context, program, words, node_of, ask),
    }
}

#[allow(clippy::too_many_arguments)]
fn bounding_let(walk: &mut BoundsWalk, names: &[winnow_grammar::Symbol], ty: Option<&Type>, value: &Expr, facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) {
    bounding_expr(walk, value, facts, context, program, words, node_of, ask);
    let value_lin = bounding_lin(walk, value, &facts, context, program, words, node_of);
    let mut value_range: Option<Range> = None;
    if value_lin.is_none() {
        let range = nikaia_std::index::or(bounding_range(walk, value, &facts, context, program, words, node_of, ask), || Range::open());
        if range.is_bounded() { value_range = Some(range); }
    }
    let whole = nikaia_std::index::or(bounding_declared_whole(ty, words), || value_lin.is_some() || value_range.is_some().into());
    for symbol in names.iter() {
        let name = words.resolve(*symbol);
        bounding_forget(&walk, facts, name);
        facts.ints.remove(name);
    }
    if names.len() != 1 { return; }
    let name = words.resolve(*nikaia_std::index::get(&names, 0)).to_owned();
    if whole {
        facts.ints.insert(name.to_owned());
        if value_lin.is_some() {
            let v = nikaia_std::index::or(value_lin, || 0);
            if !walk.arena.mentions(v, &name) {
                let n = walk.arena.var(&name);
                let fact = walk.arena.equal(n, v);
                bounding_push(&walk, facts, fact);
            }
        }
        if bounding_declared_unsigned(ty, words) { bounding_at_least_zero(walk, facts, &name); }
        if value_range.is_some() { bounding_bounded(walk, facts, &name, &nikaia_std::index::or(value_range, || Range::open())); }
    }
    bounding_built(walk, facts, &name, value);
    if walk.shape.roots.contains(&name) {
        match value {
            Expr::ListLit { items, .. } => { for item in items.iter() { bounding_write(walk, &name, item, &facts, context, program, words, node_of, ask); } },
            _ => { },
        }
    }
}

fn bounding_declared_whole(ty: Option<&Type>, words: &winnow_grammar::InternerContext) -> Option<bool> {
    let t = match ty { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(t.generics.is_empty() && is_whole_number(words.resolve(t.name)))
}

fn bounding_declared_unsigned(ty: Option<&Type>, words: &winnow_grammar::InternerContext) -> bool {
    let t = match ty { Some(__nikaia_value) => __nikaia_value, None => return false };
    words.resolve(t.name).starts_with("u")
}

#[allow(clippy::too_many_arguments)]
fn bounding_compound(walk: &mut BoundsWalk, op: Option<&BinaryOp>, target: &Expr, value: &Expr, at: i64, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) {
    let operation = match op { Some(__nikaia_value) => __nikaia_value, None => return };
    let arithmetic = matches!(operation, BinaryOp::Add | BinaryOp::Sub | BinaryOp::Mul);
    if !arithmetic || walk.collecting { return; }
    match target {
        Expr::Variable(_) => { },
        _ => return,
    }
    let ty = match *nikaia_std::index::get(&context.arithmetic, &at) { Some(__nikaia_value) => __nikaia_value, None => return };
    if bounding_fits(walk, operation, target, value, ty, facts, context, program, words, node_of, ask) { walk.proven.arithmetic.insert(at); }
}

#[allow(clippy::too_many_arguments)]
fn bounding_for(walk: &mut BoundsWalk, bindings: &[winnow_grammar::Symbol], iter: &Expr, body: &Block, facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) {
    bounding_expr(walk, iter, facts, context, program, words, node_of, ask);
    let changed = bounding_changed(body, context, words);
    let mut counted = false;
    let mut name: String = String::from("");
    let mut low: Option<i64> = None;
    let mut high: Option<i64> = None;
    let mut closed = false;
    if bindings.len() == 1 {
        match iter {
            Expr::Range { start, end, inclusive } => {
                let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end); let inclusive = *inclusive;
                low = bounding_lin(walk, start, &facts, context, program, words, node_of);
                high = bounding_lin(walk, end, &facts, context, program, words, node_of);
                counted = true;
                name = words.resolve(*nikaia_std::index::get(&bindings, 0)).to_owned();
                closed = inclusive;
            },
            _ => { },
        }
    }
    let mut inner = facts.clone();
    bounding_after_change(walk, &mut inner, &changed);
    for binding in bindings.iter() {
        let bound = words.resolve(*binding);
        bounding_forget(&walk, &mut inner, bound);
        inner.ints.remove(bound);
    }
    let mut classed: Option<String> = None;
    if bindings.len() == 1 && !counted {
        let over = bounding_chars_of(iter, words);
        if over.is_some() {
            let text = nikaia_std::index::or(over, || "".into());
            let class = *nikaia_std::index::get(&context.text_classes, &text);
            if class.is_some() && !walk.shape.bound.contains(&text) {
                let only = words.resolve(*nikaia_std::index::get(&bindings, 0)).to_owned();
                walk.loop_classes.insert(only.to_owned(), nikaia_std::index::or(class, || Range::open()));
                classed = Some(only);
            }
        }
    }
    if bindings.len() == 1 && !counted {
        let key = elements_key(&walk.shape, iter, words);
        if key.is_some() {
            let bound = bounding_assumed(&walk, nikaia_std::index::or(key.as_deref(), || ""));
            if bound.is_some() {
                let only = words.resolve(*nikaia_std::index::get(&bindings, 0)).to_owned();
                inner.ints.insert(only.to_owned());
                bounding_bounded(walk, &mut inner, &only, &nikaia_std::index::or(bound, || Range::open()));
            }
        }
    }
    if counted {
        inner.ints.insert(name.to_owned());
        let n = walk.arena.var(&name);
        if low.is_some() {
            let l = nikaia_std::index::or(low, || 0);
            if bounding_stable(&walk, l, &changed, &name) {
                let fact = walk.arena.le(l, n);
                bounding_push(&walk, &mut inner, fact);
            }
        }
        if high.is_some() {
            let h = nikaia_std::index::or(high, || 0);
            if bounding_stable(&walk, h, &changed, &name) {
                let fact = bounding_below(walk, n, h, closed);
                bounding_push(&walk, &mut inner, fact);
            }
        }
    }
    bounding_block(walk, body, &mut inner, context, program, words, node_of, ask);
    if classed.is_some() { walk.loop_classes.remove(&nikaia_std::index::or(classed, || "".into())); }
    let mut filled: Vec<String> = vec![];
    let mut count: i64 = 0;
    if counted && low.is_some() && high.is_some() {
        let l = nikaia_std::index::or(low, || 0);
        let h = nikaia_std::index::or(high, || 0);
        let mut stable = true;
        for c in changed.values.iter() { if bounding_reads(&walk, l, h, c) { stable = false; } }
        for c in changed.lengths.iter() { if bounding_reads(&walk, l, h, c) { stable = false; } }
        let mut lists: Vec<String> = vec![];
        if stable { lists = filled_once(body, &walk.pinned, words); }
        let not_empty = walk.arena.le(l, h);
        if !lists.is_empty() && bounding_proves(&walk, &facts, not_empty, ask) {
            let mut taken: i64 = 0;
            if closed { taken = 1; }
            let one = walk.arena.int(taken);
            let span = walk.arena.sub(h, l);
            count = walk.arena.add(span, one);
            filled = lists;
        }
    }
    let mut outer = BoundsChanged { values: changed.values.to_owned(), lengths: changed.lengths.to_owned() };
    for list in filled.iter() { outer.lengths.remove(list); }
    bounding_after_change(walk, facts, &outer);
    for list in filled.iter() { bounding_shift(walk, facts, &length_of(list), count); }
}

fn bounding_below(walk: &mut BoundsWalk, n: i64, h: i64, closed: bool) -> i64 {
    if closed { return walk.arena.le(n, h); }
    walk.arena.lt(n, h)
}

fn bounding_stable(walk: &BoundsWalk, t: i64, changed: &BoundsChanged, name: &str) -> bool {
    for c in changed.values.iter() { if walk.arena.mentions(t, c) { return false; } }
    for c in changed.lengths.iter() { if walk.arena.mentions(t, &length_of(c)) { return false; } }
    !walk.arena.mentions(t, name)
}

fn bounding_reads(walk: &BoundsWalk, l: i64, h: i64, c: &str) -> bool {
    let length = length_of(c);
    walk.arena.mentions(l, c) || walk.arena.mentions(h, c) || walk.arena.mentions(l, &length) || walk.arena.mentions(h, &length)
}

#[allow(clippy::too_many_arguments)]
fn bounding_assign(walk: &mut BoundsWalk, facts: &mut BoundsFacts, name: &str, op: Option<&BinaryOp>, value: &Expr, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) {
    if !facts.ints.contains(name) {
        bounding_forget(&walk, facts, name);
        bounding_built(walk, facts, name, value);
        return;
    }
    let value_lin = bounding_lin(walk, value, &facts, context, program, words, node_of);
    let now = walk.arena.var(name);
    let mut by: Option<i64> = None;
    if value_lin.is_some() {
        let v = nikaia_std::index::or(value_lin, || 0);
        if bounding_is_op(op, &BinaryOp::Add) && !walk.arena.mentions(v, name) { by = Some(v); } else if bounding_is_op(op, &BinaryOp::Sub) && !walk.arena.mentions(v, name) { by = Some(walk.arena.neg(v)); } else if op.is_none() && walk.arena.mentions(v, name) {
            let d = walk.arena.sub(v, now);
            let mut at_zero: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
            at_zero.insert(name.to_owned(), walk.arena.int(0));
            let d0 = walk.arena.substitute(d, &at_zero);
            let mut at_one: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
            at_one.insert(name.to_owned(), walk.arena.int(1));
            let d1 = walk.arena.substitute(d, &at_one);
            let same = walk.arena.equal(d0, d1);
            let none: Vec<i64> = vec![];
            if ask(&walk.arena, &none, same) { by = Some(d0); }
        }
    }
    if by.is_some() {
        bounding_shift(walk, facts, name, nikaia_std::index::or(by, || 0));
        return;
    }
    if op.is_none() && value_lin.is_some() {
        bounding_forget(&walk, facts, name);
        let n = walk.arena.var(name);
        let fact = walk.arena.equal(n, nikaia_std::index::or(value_lin, || 0));
        bounding_push(&walk, facts, fact);
        return;
    }
    let mut range: Option<Range> = None;
    if op.is_none() && value_lin.is_none() { range = bounding_range(walk, value, &facts, context, program, words, node_of, ask); }
    bounding_forget(&walk, facts, name);
    if walk.nonnegative.contains(name) || walk.shape.unsigned.contains(name) { bounding_at_least_zero(walk, facts, name); }
    if range.is_some() { bounding_bounded(walk, facts, name, &nikaia_std::index::or(range, || Range::open())); }
}

fn bounding_is_op(op: Option<&BinaryOp>, wanted: &BinaryOp) -> bool {
    let given = match op { Some(__nikaia_value) => __nikaia_value, None => return false };
    given == wanted
}

fn bounding_built(walk: &mut BoundsWalk, facts: &mut BoundsFacts, name: &str, value: &Expr) {
    match value {
        Expr::ListLit { items, .. } => {
            let length = length_of(name);
            let len = walk.arena.var(&length);
            let n = walk.arena.int(items.len() as i64);
            let fact = walk.arena.equal(len, n);
            bounding_push(&walk, facts, fact);
        },
        _ => { },
    }
}

#[allow(clippy::too_many_arguments)]
fn bounding_place(walk: &mut BoundsWalk, target: &Expr, facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) {
    match target {
        Expr::Index { base, index } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            bounding_place(walk, base, facts, context, program, words, node_of, ask);
            bounding_expr(walk, index, facts, context, program, words, node_of, ask);
            bounding_index(walk, base, index, &facts, context, program, words, node_of, ask);
        },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); bounding_place(walk, base, facts, context, program, words, node_of, ask) },
        _ => { },
    }
}

#[allow(clippy::too_many_arguments)]
fn bounding_expr_leaves(walk: &mut BoundsWalk, expr: &Expr, facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) -> bool {
    match expr {
        Expr::If { cond, then_branch, else_branch } => { let cond = nikaia_std::boxed::open(cond); return bounding_if_leaves(walk, cond, then_branch, (else_branch).as_ref(), facts, context, program, words, node_of, ask) },
        Expr::Return(value) => {
            let value = nikaia_std::boxed::open(value);
            let returned = match value { Some(__nikaia_value) => __nikaia_value, None => return true };
            bounding_expr(walk, returned, facts, context, program, words, node_of, ask);
            return true;
        },
        Expr::Break => return true,
        Expr::Continue => return true,
        Expr::Throw(value) => {
            let value = nikaia_std::boxed::open(value);
            bounding_expr(walk, value, facts, context, program, words, node_of, ask);
            return true;
        },
        Expr::Call { func, args, .. } => {
            let func = nikaia_std::boxed::open(func);
            let callee = nikaia_std::index::or(bounding_variable(func, words), || "".into());
            if callee == "panic" {
                for arg in args.iter() { bounding_expr(walk, arg, facts, context, program, words, node_of, ask); }
                return true;
            }
        },
        _ => { },
    }
    bounding_expr(walk, expr, facts, context, program, words, node_of, ask);
    false
}

#[allow(clippy::too_many_arguments)]
fn bounding_if_leaves(walk: &mut BoundsWalk, cond: &Expr, then_branch: &Block, else_branch: Option<&Block>, facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) -> bool {
    bounding_expr(walk, cond, facts, context, program, words, node_of, ask);
    let mut then_facts = facts.clone();
    bounding_assume(walk, &mut then_facts, cond, context, program, words, node_of);
    let then_leaves = bounding_block(walk, then_branch, &mut then_facts, context, program, words, node_of, ask);
    let mut else_facts = facts.clone();
    bounding_assume_not(walk, &mut else_facts, cond, context, program, words, node_of);
    let else_leaves = bounding_maybe_block(walk, else_branch, &mut else_facts, context, program, words, node_of, ask);
    if then_leaves && else_leaves { return true; }
    if then_leaves {
        facts.ints = else_facts.ints;
        facts.facts = else_facts.facts;
    } else if else_leaves {
        facts.ints = then_facts.ints;
        facts.facts = then_facts.facts;
    } else {
        let mut changed = bounding_changed(then_branch, context, words);
        bounding_extend_maybe(&mut changed, else_branch, context, words);
        bounding_after_change(walk, facts, &changed);
    }
    false
}

#[allow(clippy::too_many_arguments)]
fn bounding_expr(walk: &mut BoundsWalk, expr: &Expr, facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) {
    bounding_nonnegative(walk, expr, &facts, context, program, words, node_of, ask);
    bounding_negation(walk, expr, &facts, context, program, words, node_of, ask);
    match expr {
        Expr::Index { base, index } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            bounding_expr(walk, base, facts, context, program, words, node_of, ask);
            bounding_expr(walk, index, facts, context, program, words, node_of, ask);
            bounding_index(walk, base, index, &facts, context, program, words, node_of, ask);
        },
        Expr::Binary { op, lhs, rhs, span, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); bounding_binary(walk, op, lhs, rhs, span.start as i64, facts, context, program, words, node_of, ask) },
        Expr::If { cond, then_branch, else_branch } => {
            let cond = nikaia_std::boxed::open(cond);
            bounding_expr(walk, cond, facts, context, program, words, node_of, ask);
            let mut then_facts = facts.clone();
            bounding_assume(walk, &mut then_facts, cond, context, program, words, node_of);
            bounding_block(walk, then_branch, &mut then_facts, context, program, words, node_of, ask);
            let mut changed = bounding_changed(then_branch, context, words);
            bounding_else(walk, (else_branch).as_ref(), cond, &facts, &mut changed, context, program, words, node_of, ask);
            bounding_after_change(walk, facts, &changed);
        },
        Expr::Block(block) => bounding_inner_block(walk, block, facts, context, program, words, node_of, ask),
        Expr::Unsafe(block) => bounding_inner_block(walk, block, facts, context, program, words, node_of, ask),
        Expr::Match { value, arms } => {
            let value = nikaia_std::boxed::open(value);
            bounding_expr(walk, value, facts, context, program, words, node_of, ask);
            let mut changed = nothing_changed();
            for arm in arms.iter() {
                let mut inner = BoundsFacts { ints: collections::BTreeSet::new(), facts: vec![] };
                bounding_maybe_expr(walk, (arm.guard).as_ref(), &mut inner, context, program, words, node_of, ask);
                bounding_expr(walk, &arm.body, &mut inner, context, program, words, node_of, ask);
                bounding_extend(&mut changed, &bounding_changed_in_expr(&arm.body, context, words));
            }
            bounding_after_change(walk, facts, &changed);
        },
        Expr::Closure { .. } => { },
        Expr::Spawn { .. } => { },
        Expr::Overlap(_) => { },
        Expr::Select(_) => { },
        Expr::MethodCall { receiver, method, args, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; bounding_method_call(walk, receiver, words.resolve(method), args, facts, context, program, words, node_of, ask) },
        Expr::SafeMethod { receiver, method, args, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; bounding_method_call(walk, receiver, words.resolve(method), args, facts, context, program, words, node_of, ask) },
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            bounding_expr(walk, func, facts, context, program, words, node_of, ask);
            for arg in args.iter() { bounding_expr(walk, arg, facts, context, program, words, node_of, ask); }
            for c in config.iter() { bounding_expr(walk, &c.value, facts, context, program, words, node_of, ask); }
            if args.len() == 1 && nikaia_std::index::or(bounding_variable(func, words), || "".into()) == "assert" { bounding_assume(walk, facts, nikaia_std::index::get(&args, 0), context, program, words, node_of); }
            let callee = callee_params(func, &context.around, words);
            for at in 0..args.len() as i64 {
                match nikaia_std::index::get(&args, nikaia_std::index::at(at)) {
                    Expr::Variable(name) => {
                        let name = *name;
                        if hands_on((callee).as_ref(), at) { bounding_forget(&walk, facts, words.resolve(name)); }
                    },
                    _ => { },
                }
            }
        },
        _ => bounding_children(walk, expr, facts, context, program, words, node_of, ask),
    }
}

#[allow(clippy::too_many_arguments)]
fn bounding_nonnegative(walk: &mut BoundsWalk, expr: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) {
    if walk.collecting || context.nonnegative.is_empty() { return; }
    let node = node_of(expr);
    if !context.nonnegative.contains(&node) { return; }
    let term = match bounding_lin(walk, expr, facts, context, program, words, node_of) { Some(__nikaia_value) => __nikaia_value, None => return };
    let zero = walk.arena.int(0);
    let goal = walk.arena.ge(term, zero);
    if bounding_proves(&walk, facts, goal, ask) { walk.proven.nonnegative.insert(node); }
}

#[allow(clippy::too_many_arguments)]
fn bounding_maybe_expr(walk: &mut BoundsWalk, expr: Option<&Expr>, facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) {
    let present = match expr { Some(__nikaia_value) => __nikaia_value, None => return };
    bounding_expr(walk, present, facts, context, program, words, node_of, ask);
}

#[allow(clippy::too_many_arguments)]
fn bounding_else(walk: &mut BoundsWalk, else_branch: Option<&Block>, cond: &Expr, facts: &BoundsFacts, changed: &mut BoundsChanged, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) {
    let block = match else_branch { Some(__nikaia_value) => __nikaia_value, None => return };
    let mut else_facts = facts.clone();
    bounding_assume_not(walk, &mut else_facts, cond, context, program, words, node_of);
    bounding_block(walk, block, &mut else_facts, context, program, words, node_of, ask);
    bounding_extend(changed, &bounding_changed(block, context, words));
}

#[allow(clippy::too_many_arguments)]
fn bounding_inner_block(walk: &mut BoundsWalk, block: &Block, facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) {
    let mut inner = facts.clone();
    bounding_block(walk, block, &mut inner, context, program, words, node_of, ask);
    let changed = bounding_changed(block, context, words);
    bounding_after_change(walk, facts, &changed);
}

#[allow(clippy::too_many_arguments)]
fn bounding_binary(walk: &mut BoundsWalk, op: &BinaryOp, lhs: &Expr, rhs: &Expr, at: i64, facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) {
    match op {
        BinaryOp::And => {
            bounding_expr(walk, lhs, facts, context, program, words, node_of, ask);
            let mut right = facts.clone();
            bounding_assume(walk, &mut right, lhs, context, program, words, node_of);
            bounding_expr(walk, rhs, &mut right, context, program, words, node_of, ask);
            let changed = bounding_changed_in_expr(rhs, context, words);
            bounding_after_change(walk, facts, &changed);
            return;
        },
        BinaryOp::Or => {
            bounding_expr(walk, lhs, facts, context, program, words, node_of, ask);
            let mut right = facts.clone();
            bounding_assume_not(walk, &mut right, lhs, context, program, words, node_of);
            bounding_expr(walk, rhs, &mut right, context, program, words, node_of, ask);
            let changed = bounding_changed_in_expr(rhs, context, words);
            bounding_after_change(walk, facts, &changed);
            return;
        },
        _ => { },
    }
    bounding_expr(walk, lhs, facts, context, program, words, node_of, ask);
    bounding_expr(walk, rhs, facts, context, program, words, node_of, ask);
    let arithmetic = matches!(op, BinaryOp::Add | BinaryOp::Sub | BinaryOp::Mul);
    if !arithmetic || walk.collecting { return; }
    let ty = match *nikaia_std::index::get(&context.arithmetic, &at) { Some(__nikaia_value) => __nikaia_value, None => return };
    if bounding_fits(walk, op, lhs, rhs, ty, &facts, context, program, words, node_of, ask) { walk.proven.arithmetic.insert(at); }
}

#[allow(clippy::too_many_arguments)]
fn bounding_method_call(walk: &mut BoundsWalk, receiver: &Expr, method: &str, args: &[Expr], facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) {
    bounding_expr(walk, receiver, facts, context, program, words, node_of, ask);
    for arg in args.iter() { bounding_expr(walk, arg, facts, context, program, words, node_of, ask); }
    let written = writes_a_value(method, args.len() as i64);
    if written.is_some() {
        let key = elements_key(&walk.shape, receiver, words);
        if key.is_some() { bounding_write(walk, nikaia_std::index::or(key.as_deref(), || ""), nikaia_std::index::get(&args, nikaia_std::index::at(nikaia_std::index::or(written, || 0))), &facts, context, program, words, node_of, ask); }
    }
    match receiver {
        Expr::Variable(name) => { let name = *name; bounding_method(walk, facts, words.resolve(name), method, args, context, program, words, node_of, ask) },
        _ => { },
    }
    let changes_its_arguments = context.around.changing_methods.contains(method);
    for arg in args.iter() {
        match arg {
            Expr::Variable(name) => {
                let name = *name;
                let text = words.resolve(name);
                if changes_its_arguments { bounding_forget(&walk, facts, text); } else if !facts.ints.contains(text) { bounding_forget_length(&walk, facts, text); }
            },
            _ => { },
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn bounding_method(walk: &mut BoundsWalk, facts: &mut BoundsFacts, name: &str, method: &str, args: &[Expr], context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) {
    if keeps_length(method) || facts.ints.contains(name) { return; }
    let length = length_of(name);
    let count = args.len() as i64;
    if method == "push" && count == 1 || method == "insert" && count == 2 {
        let one = walk.arena.int(1);
        bounding_shift(walk, facts, &length, one);
        return;
    }
    if (method == "remove" || method == "swap_remove") && count == 1 {
        let one = walk.arena.int(-1);
        bounding_shift(walk, facts, &length, one);
        return;
    }
    if method == "clear" && count == 0 {
        bounding_forget_length(&walk, facts, name);
        let len = walk.arena.var(&length);
        let zero = walk.arena.int(0);
        let fact = walk.arena.equal(len, zero);
        bounding_push(&walk, facts, fact);
        return;
    }
    if method == "resize" && count == 2 {
        let to = bounding_lin(walk, nikaia_std::index::get(&args, 0), &facts, context, program, words, node_of);
        bounding_forget_length(&walk, facts, name);
        if to.is_some() {
            let len = walk.arena.var(&length);
            let fact = walk.arena.equal(len, nikaia_std::index::or(to, || 0));
            bounding_push(&walk, facts, fact);
        }
        return;
    }
    if method == "extend" && count == 1 {
        let other = nikaia_std::index::or(bounding_variable(nikaia_std::index::get(&args, 0), words), || "".into());
        if !other.is_empty() && other != name {
            let mine = walk.arena.var(&length);
            let theirs = walk.arena.var(&length_of(&other));
            let mine_known = bounding_term(walk, mine, &facts, ask);
            let theirs_known = bounding_term(walk, theirs, &facts, ask);
            bounding_forget_length(&walk, facts, name);
            let len = walk.arena.var(&length);
            if mine_known.lo.is_some() && theirs_known.lo.is_some() {
                let lo = nikaia_std::index::or(mine_known.lo, || 0).checked_add(nikaia_std::index::or(theirs_known.lo, || 0));
                if lo.is_some() {
                    let k = walk.arena.int(nikaia_std::index::or(lo, || 0));
                    let fact = walk.arena.ge(len, k);
                    bounding_push(&walk, facts, fact);
                }
            }
            if mine_known.hi.is_some() && theirs_known.hi.is_some() {
                let hi = nikaia_std::index::or(mine_known.hi, || 0).checked_add(nikaia_std::index::or(theirs_known.hi, || 0));
                if hi.is_some() {
                    let k = walk.arena.int(nikaia_std::index::or(hi, || 0));
                    let fact = walk.arena.le(len, k);
                    bounding_push(&walk, facts, fact);
                }
            }
            return;
        }
    }
    bounding_forget_length(&walk, facts, name);
}

#[allow(clippy::too_many_arguments)]
fn bounding_children(walk: &mut BoundsWalk, expr: &Expr, facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, node_of: &impl Fn(&Expr) -> i64, ask: &impl Fn(&TermArena, &[i64], i64) -> bool) {
    match expr {
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            bounding_expr(walk, start, facts, context, program, words, node_of, ask);
            bounding_expr(walk, end, facts, context, program, words, node_of, ask);
        },
        Expr::Tuple(items) => { for item in items.iter() { bounding_expr(walk, item, facts, context, program, words, node_of, ask); } },
        Expr::ListLit { items, .. } => { for item in items.iter() { bounding_expr(walk, item, facts, context, program, words, node_of, ask); } },
        Expr::LitInterpolated { parts } => {
            for part in parts.iter() {
                match part {
                    FPart::Hole { expr, .. } => bounding_expr(walk, expr, facts, context, program, words, node_of, ask),
                    _ => { },
                }
            }
        },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); bounding_expr(walk, base, facts, context, program, words, node_of, ask) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); bounding_expr(walk, base, facts, context, program, words, node_of, ask) },
        Expr::StructLit { fields, .. } => { for field in fields.iter() { bounding_maybe_expr(walk, (field.value).as_ref(), facts, context, program, words, node_of, ask); } },
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            bounding_expr(walk, base, facts, context, program, words, node_of, ask);
            for field in fields.iter() { bounding_maybe_expr(walk, (field.value).as_ref(), facts, context, program, words, node_of, ask); }
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); bounding_expr(walk, expr, facts, context, program, words, node_of, ask) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); bounding_expr(walk, inner, facts, context, program, words, node_of, ask) },
        Expr::Throw(inner) => { let inner = nikaia_std::boxed::open(inner); bounding_expr(walk, inner, facts, context, program, words, node_of, ask) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); bounding_expr(walk, expr, facts, context, program, words, node_of, ask) },
        Expr::TryCatch { expr, handler } => {
            let expr = nikaia_std::boxed::open(expr);
            bounding_expr(walk, expr, facts, context, program, words, node_of, ask);
            bounding_inner_block(walk, handler, facts, context, program, words, node_of, ask);
        },
        Expr::Return(value) => { let value = nikaia_std::boxed::open(value); bounding_maybe_expr(walk, (value).as_ref(), facts, context, program, words, node_of, ask) },
        Expr::Coalesce { value, fallback } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            bounding_expr(walk, value, facts, context, program, words, node_of, ask);
            bounding_expr(walk, fallback, facts, context, program, words, node_of, ask);
        },
        _ => { },
    }
}

fn bounding_extend(changed: &mut BoundsChanged, other: &BoundsChanged) {
    for name in other.values.iter() { changed.values.insert(name.to_owned()); }
    for name in other.lengths.iter() { changed.lengths.insert(name.to_owned()); }
}

fn bounding_extend_maybe(changed: &mut BoundsChanged, block: Option<&Block>, context: &BoundsContext, words: &winnow_grammar::InternerContext) {
    let present = match block { Some(__nikaia_value) => __nikaia_value, None => return };
    bounding_extend(changed, &bounding_changed(present, context, words));
}

fn bounding_changed(block: &Block, context: &BoundsContext, words: &winnow_grammar::InternerContext) -> BoundsChanged {
    let mut out = nothing_changed();
    changed_in_block(block, context, words, &mut out);
    out
}

fn bounding_changed_in_expr(expr: &Expr, context: &BoundsContext, words: &winnow_grammar::InternerContext) -> BoundsChanged {
    let mut out = nothing_changed();
    changed_in_expr(expr, context, words, &mut out);
    out
}

fn changed_in_block(block: &Block, context: &BoundsContext, words: &winnow_grammar::InternerContext, out: &mut BoundsChanged) {
    for stmt in block.stmts.iter() {
        match &stmt.node {
            Stmt::Assign { target, value, .. } => {
                match target {
                    Expr::Variable(name) => {
                        let name = *name;
                        out.lengths.insert(words.resolve(name).to_owned());
                        out.values.insert(words.resolve(name).to_owned());
                    },
                    _ => { },
                }
                changed_in_expr(target, context, words, out);
                changed_in_expr(value, context, words, out);
            },
            Stmt::For { iter, body, .. } => {
                changed_in_expr(iter, context, words, out);
                changed_in_block(body, context, words, out);
            },
            Stmt::While { cond, body } => {
                changed_in_expr(cond, context, words, out);
                changed_in_block(body, context, words, out);
            },
            Stmt::Let { value, .. } => changed_in_expr(value, context, words, out),
            Stmt::Comptime { value, .. } => changed_in_expr(value, context, words, out),
            Stmt::Expr(value) => changed_in_expr(value, context, words, out),
            Stmt::Return(value) => changed_in_maybe((value).as_ref(), context, words, out),
            _ => { },
        }
    }
}

fn changed_in_maybe(expr: Option<&Expr>, context: &BoundsContext, words: &winnow_grammar::InternerContext, out: &mut BoundsChanged) {
    let present = match expr { Some(__nikaia_value) => __nikaia_value, None => return };
    changed_in_expr(present, context, words, out);
}

fn changed_in_all(exprs: &[Expr], context: &BoundsContext, words: &winnow_grammar::InternerContext, out: &mut BoundsChanged) { for e in exprs.iter() { changed_in_expr(e, context, words, out); } }

fn changed_in_expr(expr: &Expr, context: &BoundsContext, words: &winnow_grammar::InternerContext, out: &mut BoundsChanged) {
    changed_by(expr, context, words, out);
    match expr {
        Expr::Match { value, arms } => {
            let value = nikaia_std::boxed::open(value);
            changed_in_expr(value, context, words, out);
            for arm in arms.iter() {
                changed_in_maybe((arm.guard).as_ref(), context, words, out);
                changed_in_expr(&arm.body, context, words, out);
            }
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            changed_in_expr(start, context, words, out);
            changed_in_expr(end, context, words, out);
        },
        Expr::Tuple(items) => changed_in_all(items, context, words, out),
        Expr::ListLit { items, .. } => changed_in_all(items, context, words, out),
        Expr::LitInterpolated { parts } => {
            for part in parts.iter() {
                match part {
                    FPart::Hole { expr, .. } => changed_in_expr(expr, context, words, out),
                    _ => { },
                }
            }
        },
        Expr::If { cond, then_branch, else_branch } => {
            let cond = nikaia_std::boxed::open(cond);
            changed_in_expr(cond, context, words, out);
            changed_in_block(then_branch, context, words, out);
            changed_in_maybe_block((else_branch).as_ref(), context, words, out);
        },
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            changed_in_expr(func, context, words, out);
            changed_in_all(args, context, words, out);
            for c in config.iter() { changed_in_expr(&c.value, context, words, out); }
        },
        Expr::Spawn { body, .. } => { let body = nikaia_std::boxed::open(body); changed_in_expr(body, context, words, out) },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            changed_in_expr(receiver, context, words, out);
            changed_in_all(args, context, words, out);
            for c in config.iter() { changed_in_expr(&c.value, context, words, out); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            changed_in_expr(receiver, context, words, out);
            changed_in_all(args, context, words, out);
            for c in config.iter() { changed_in_expr(&c.value, context, words, out); }
        },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); changed_in_expr(base, context, words, out) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); changed_in_expr(base, context, words, out) },
        Expr::StructLit { fields, .. } => { for field in fields.iter() { changed_in_maybe((field.value).as_ref(), context, words, out); } },
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            changed_in_expr(base, context, words, out);
            for field in fields.iter() { changed_in_maybe((field.value).as_ref(), context, words, out); }
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); changed_in_expr(expr, context, words, out) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); changed_in_expr(inner, context, words, out) },
        Expr::Throw(inner) => { let inner = nikaia_std::boxed::open(inner); changed_in_expr(inner, context, words, out) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); changed_in_expr(expr, context, words, out) },
        Expr::TryCatch { expr, handler } => {
            let expr = nikaia_std::boxed::open(expr);
            changed_in_expr(expr, context, words, out);
            changed_in_block(handler, context, words, out);
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            changed_in_expr(lhs, context, words, out);
            changed_in_expr(rhs, context, words, out);
        },
        Expr::Return(value) => { let value = nikaia_std::boxed::open(value); changed_in_maybe((value).as_ref(), context, words, out) },
        Expr::Index { base, index } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            changed_in_expr(base, context, words, out);
            changed_in_expr(index, context, words, out);
        },
        Expr::Coalesce { value, fallback } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            changed_in_expr(value, context, words, out);
            changed_in_expr(fallback, context, words, out);
        },
        Expr::Select(arms) => {
            for arm in arms.iter() {
                changed_in_expr(&arm.value, context, words, out);
                changed_in_block(&arm.body, context, words, out);
            }
        },
        Expr::Block(b) => changed_in_block(b, context, words, out),
        Expr::Overlap(b) => changed_in_block(b, context, words, out),
        Expr::Unsafe(b) => changed_in_block(b, context, words, out),
        Expr::Closure { body, .. } => changed_in_block(body, context, words, out),
        _ => { },
    }
}

fn changed_in_maybe_block(block: Option<&Block>, context: &BoundsContext, words: &winnow_grammar::InternerContext, out: &mut BoundsChanged) {
    let present = match block { Some(__nikaia_value) => __nikaia_value, None => return };
    changed_in_block(present, context, words, out);
}

fn changed_by(expr: &Expr, context: &BoundsContext, words: &winnow_grammar::InternerContext, out: &mut BoundsChanged) {
    match expr {
        Expr::MethodCall { receiver, method, args, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; changed_by_method(receiver, words.resolve(method), args, context, words, out) },
        Expr::SafeMethod { receiver, method, args, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; changed_by_method(receiver, words.resolve(method), args, context, words, out) },
        Expr::Call { func, args, .. } => {
            let func = nikaia_std::boxed::open(func);
            let callee = callee_params(func, &context.around, words);
            for at in 0..args.len() as i64 {
                match nikaia_std::index::get(&args, nikaia_std::index::at(at)) {
                    Expr::Variable(name) => {
                        let name = *name;
                        if hands_on((callee).as_ref(), at) {
                            out.lengths.insert(words.resolve(name).to_owned());
                            out.values.insert(words.resolve(name).to_owned());
                        }
                    },
                    _ => { },
                }
            }
        },
        _ => { },
    }
}

fn changed_by_method(receiver: &Expr, method: &str, args: &[Expr], context: &BoundsContext, words: &winnow_grammar::InternerContext, out: &mut BoundsChanged) {
    match receiver {
        Expr::Variable(name) => {
            let name = *name;
            if !keeps_length(method) { out.lengths.insert(words.resolve(name).to_owned()); }
        },
        _ => { },
    }
    let changes_its_arguments = context.around.changing_methods.contains(method);
    for arg in args.iter() {
        match arg {
            Expr::Variable(name) => {
                let name = *name;
                if changes_its_arguments { out.values.insert(words.resolve(name).to_owned()); }
                out.lengths.insert(words.resolve(name).to_owned());
            },
            _ => { },
        }
    }
}


// --- buffers.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Escape {
    Returned,
    Param(String),
    Outer(String),
    Task,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Source {
    Buffer { at: i64, name: String, ty: String, span: Span },
    Call { at: i64, callee: String, span: Span },
    Argument { at: i64, callee: String, index: i64, span: Span },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum KeepAt {
    Param,
    Frame,
    Local(i64),
    Task,
    Element(i64),
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BufferPlan {
    pub key: String,
    pub first: i64,
    pub takes_keep: bool,
    pub frame_keep: bool,
    pub task_keep: bool,
    pub local_keeps: collections::BTreeSet<i64>,
    pub puts: collections::BTreeMap<i64, KeepAt>,
    pub calls: collections::BTreeMap<(i64, String), KeepAt>,
    pub tethered: collections::BTreeMap<String, i64>,
    pub element_keepers: collections::BTreeSet<String>,
    pub struct_keepers: collections::BTreeSet<String>,
    pub widths: collections::BTreeMap<String, i64>,
    pub keeper_structs: collections::BTreeMap<String, String>,
    pub held_locals: collections::BTreeSet<String>,
    pub holds: collections::BTreeMap<(i64, String), collections::BTreeMap<i64, collections::BTreeSet<i64>>>,
    pub escapes: Vec<(Source, Escape)>,
    pub refusals: Vec<Finding>,
    pub reputs: collections::BTreeMap<i64, KeepAt>,
}

#[derive(Debug, Clone)]
pub struct BufferAsk<'a> {
    pub names: &'a winnow_grammar::InternerContext,
    pub own: &'a Ledger,
    pub library: &'a Ledger,
    pub items: &'a Vec<Spanned<Item>>,
    pub context: &'a KeepContext,
}

#[derive(Debug, Clone, PartialEq)]
struct Local {
    at: i64,
    path: Vec<(i64, bool)>,
    origins: collections::BTreeSet<(i64, String)>,
    ty: Option<Type>,
    parameter: bool,
    keeps: bool,
    buffer: bool,
    text: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Sourced {
    source: Source,
    path: Vec<(i64, bool)>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct PutsAt {
    by_arg: collections::BTreeMap<i64, collections::BTreeSet<(i64, String)>>,
}

#[derive(Debug, Clone, PartialEq)]
struct BufferWalk {
    target: Option<String>,
    locals: collections::BTreeMap<String, Vec<Local>>,
    frames: Vec<Vec<String>>,
    path: Vec<(i64, bool)>,
    sources: collections::BTreeMap<(i64, String), Sourced>,
    escapes: Vec<((i64, String), Escape)>,
    sheds: collections::BTreeMap<String, Vec<Vec<(i64, bool)>>>,
    puts_into: collections::BTreeMap<(i64, String), PutsAt>,
    struct_puts: collections::BTreeMap<String, String>,
    taken: collections::BTreeMap<String, String>,
    reassigned: collections::BTreeMap<i64, i64>,
    captured: collections::BTreeMap<String, (i64, collections::BTreeSet<(i64, String)>)>,
    statement: i64,
    result_carries: bool,
    last_seen: collections::BTreeMap<String, Local>,
}

fn open_scope(walk: &mut BufferWalk) { walk.frames.push(vec![]); }

fn close_scope(walk: &mut BufferWalk) {
    if walk.frames.is_empty() { return; }
    let names = (*nikaia_std::index::get(&walk.frames, nikaia_std::index::at(walk.frames.len() as i64 - 1))).to_owned();
    for name in names.iter() {
        let mut stack = match match *nikaia_std::index::get(&walk.locals, name) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => continue };
        if !stack.is_empty() { stack.pop(); }
        walk.locals.insert(name.to_owned(), stack);
    }
    walk.frames.pop();
}

fn local_of(name: &str, walk: &BufferWalk) -> Option<Local> {
    let stack = match *nikaia_std::index::get(&walk.locals, name) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if stack.is_empty() { return None; }
    Some((*nikaia_std::index::get(&stack, nikaia_std::index::at(stack.len() as i64 - 1))).clone())
}

fn set_local(name: &str, local: Local, walk: &mut BufferWalk) {
    let mut stack = match match *nikaia_std::index::get(&walk.locals, name) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return };
    if stack.is_empty() { return; }
    let last = stack.len() as i64 - 1;
    { let __nikaia_stored = local; nikaia_std::index::set(&mut stack, nikaia_std::index::at(last), __nikaia_stored); }
    walk.locals.insert(name.to_owned(), stack);
}

fn bind_local(name: String, local: Local, walk: &mut BufferWalk) {
    walk.last_seen.insert(name.to_owned(), local.clone());
    let mut stack: Vec<Local> = nikaia_std::index::or(match *nikaia_std::index::get(&walk.locals, &name) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || vec![].into());
    stack.push(local);
    walk.locals.insert(name.to_owned(), stack);
    if !walk.frames.is_empty() {
        let last = walk.frames.len() as i64 - 1;
        walk.frames[nikaia_std::index::at(last)].push(name);
    }
}

fn a_local(at: i64, path: &[(i64, bool)], origins: collections::BTreeSet<(i64, String)>, ty: Option<Type>, buffer: bool, text: bool) -> Local { Local { at, path: path.to_owned(), origins, ty, parameter: false, keeps: false, buffer, text } }

pub fn buffer_plans(program: &Program, ask: &BufferAsk<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String) -> Vec<BufferPlan> {
    let mut out: Vec<BufferPlan> = vec![];
    for item in program.items.iter() {
        match &item.node {
            Item::Fn { .. } => { out.push(match plan_of(&item.node, None, ask, holes_of, unaliased) { Some(__nikaia_value) => __nikaia_value, None => continue }); },
            Item::Impl { target, methods, .. } => {
                let owner = ask.names.resolve(target.name).to_owned();
                for method in methods.iter() { out.push(match plan_of(&method.node, Some(owner.to_owned()), ask, holes_of, unaliased) { Some(__nikaia_value) => __nikaia_value, None => continue }); }
            },
            _ => { },
        }
    }
    out
}

fn plan_of(item: &Item, target: Option<String>, ask: &BufferAsk<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String) -> Option<BufferPlan> {
    let (name, receiver, args, body) = match item {
        Item::Fn { name, receiver, args, body, .. } => { let name = *name; (name, receiver, args, body) },
        _ => return None,
    };
    let key = key_of_function((name).as_ref(), &nikaia_std::index::or(match target.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || "".into()), ask.names);
    let carries = match item {
        Item::Fn { ret_type, .. } => carries_maybe((ret_type).as_ref(), ask),
        _ => false,
    };
    let mut walk = BufferWalk { target, locals: collections::BTreeMap::new(), frames: vec![], path: vec![], sources: collections::BTreeMap::new(), escapes: vec![], sheds: collections::BTreeMap::new(), puts_into: collections::BTreeMap::new(), struct_puts: collections::BTreeMap::new(), taken: collections::BTreeMap::new(), reassigned: collections::BTreeMap::new(), captured: collections::BTreeMap::new(), statement: 0, result_carries: carries, last_seen: collections::BTreeMap::new() };
    open_scope(&mut walk);
    for arg in args.iter() {
        let parameter = Local { at: 0, path: vec![], origins: collections::BTreeSet::new(), ty: Some(arg.ty.clone()), parameter: true, keeps: arg.mutable && ask.context.carries(ask.names, &arg.ty), buffer: false, text: false };
        bind_local(ask.names.resolve(arg.name).to_owned(), parameter, &mut walk);
    }
    if receiver.is_some() {
        let subject = match receiver { Some(__nikaia_value) => __nikaia_value, None => return None };
        let keeps = subject.is_mut && walk.target.is_some() && ask.context.borrowing.contains(&nikaia_std::index::or(match walk.target.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || "".into()));
        bind_local(String::from("self"), Local { at: 0, path: vec![], origins: collections::BTreeSet::new(), ty: None, parameter: true, keeps, buffer: false, text: false }, &mut walk);
    }
    for _ in 0..2 {
        while walk.frames.len() > 1 { close_scope(&mut walk); }
        walk.path = vec![];
        open_scope(&mut walk);
        for stmt in body.stmts.iter() {
            walk.statement = stmt.span.start as i64;
            buffer_statement(&stmt.node, &stmt.span, ask, holes_of, unaliased, &mut walk);
        }
        if walk.result_carries && !body.stmts.is_empty() {
            let last = nikaia_std::index::get(&body.stmts, nikaia_std::index::at(body.stmts.len() as i64 - 1));
            match last.node {
                Stmt::Expr(ref value) => {
                    walk.statement = last.span.start as i64;
                    let origins = origins_of(value, ask, holes_of, unaliased, &mut walk);
                    if !is_the_buffer(value, ask, &walk) { escape_all(&origins, &Escape::Returned, &mut walk); }
                },
                _ => { },
            }
        }
        close_scope(&mut walk);
    }
    Some(decide(key, body, &walk, ask))
}

fn carries_maybe(ty: Option<&Type>, ask: &BufferAsk<'_>) -> bool {
    let written = match ty { Some(__nikaia_value) => __nikaia_value, None => return false };
    ask.context.carries(ask.names, written)
}

fn buffer_block(block: &Block, ask: &BufferAsk<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, walk: &mut BufferWalk) {
    open_scope(walk);
    for stmt in block.stmts.iter() {
        walk.statement = stmt.span.start as i64;
        buffer_statement(&stmt.node, &stmt.span, ask, holes_of, unaliased, walk);
    }
    close_scope(walk);
}

fn nested(at: i64, looping: bool, block: &Block, ask: &BufferAsk<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, walk: &mut BufferWalk) {
    walk.path.push((at, looping));
    buffer_block(block, ask, holes_of, unaliased, walk);
    walk.path.pop();
}

fn buffer_statement(stmt: &Stmt, span: &Span, ask: &BufferAsk<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, walk: &mut BufferWalk) {
    let at = span.start as i64;
    match stmt {
        Stmt::Let { value, .. } => {
            spawns_in(value, ask, holes_of, walk);
            nested_blocks(value, at, ask, holes_of, unaliased, walk);
            let_statement(stmt, span, ask, holes_of, unaliased, walk);
        },
        Stmt::Assign { target, op, value } => {
            spawns_in(value, ask, holes_of, walk);
            nested_blocks(value, at, ask, holes_of, unaliased, walk);
            let origins = origins_of(value, ask, holes_of, unaliased, walk);
            let root = match root_of(ask.names, target) { Some(__nikaia_value) => __nikaia_value, None => return };
            let whole = op.is_none() && matches!(target, Expr::Variable(_));
            if whole {
                let bound = local_of(&root, &walk);
                if bound.is_some() && nikaia_std::index::or(bound.as_ref().map(|__nikaia_it| __nikaia_it.buffer), || false) { walk.reassigned.insert(at, nikaia_std::index::or(bound.as_ref().map(|__nikaia_it| __nikaia_it.at), || 0)); }
                shed(&root, walk);
            }
            if whole && is_the_buffer(value, ask, &walk) {
                let mut local = match local_of(&root, &walk) { Some(__nikaia_value) => __nikaia_value, None => return };
                local.buffer = true;
                for origin in origins.iter() { local.origins.insert(origin.clone()); }
                set_local(&root, local, walk);
            } else { flow_into(&root, &origins, walk); }
        },
        Stmt::For { bindings, iter, body } => {
            let origins = origins_of(iter, ask, holes_of, unaliased, walk);
            walk.path.push((at, true));
            open_scope(walk);
            for name in bindings.iter() { bind_local(ask.names.resolve(*name).to_owned(), a_local(at, &walk.path, origins.to_owned(), None, false, false), walk); }
            for inner in body.stmts.iter() {
                walk.statement = inner.span.start as i64;
                buffer_statement(&inner.node, &inner.span, ask, holes_of, unaliased, walk);
            }
            close_scope(walk);
            walk.path.pop();
        },
        Stmt::While { cond, body } => {
            origins_of(cond, ask, holes_of, unaliased, walk);
            nested(at, true, body, ask, holes_of, unaliased, walk);
        },
        Stmt::Return(value) => {
            let returned = match value { Some(__nikaia_value) => __nikaia_value, None => return };
            spawns_in(returned, ask, holes_of, walk);
            nested_blocks(returned, at, ask, holes_of, unaliased, walk);
            let origins = origins_of(returned, ask, holes_of, unaliased, walk);
            if walk.result_carries && !is_the_buffer(returned, ask, &walk) { escape_all(&origins, &Escape::Returned, walk); }
        },
        Stmt::Expr(expr) => {
            spawns_in(expr, ask, holes_of, walk);
            nested_blocks(expr, at, ask, holes_of, unaliased, walk);
            effects(expr, ask, holes_of, unaliased, walk);
        },
        _ => { },
    }
}

fn shed(root: &str, walk: &mut BufferWalk) {
    let mut paths: Vec<Vec<(i64, bool)>> = nikaia_std::index::or(match *nikaia_std::index::get(&walk.sheds, root) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || vec![].into());
    paths.push(walk.path.to_owned());
    walk.sheds.insert(root.to_owned(), paths);
}

fn let_statement(stmt: &Stmt, span: &Span, ask: &BufferAsk<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, walk: &mut BufferWalk) {
    let (names, value, ty, made) = match stmt {
        Stmt::Let { names, value, ty, .. } => (names, value, ty, made_here(names, value, (ty).as_ref(), ask, unaliased, &walk)),
        _ => return,
    };
    let at = span.start as i64;
    if names.len() == 1 {
        let from = taken_from(ask.names, value);
        if from.is_some() { walk.taken.insert(ask.names.resolve(*nikaia_std::index::get(&names, 0)).to_owned(), nikaia_std::index::or(from, || "".into())); }
    }
    let text = names.len() == 1 && ty.is_none() && copies_text(value, ask, &walk);
    let is_buffer = a_named_buffer(&made) || is_the_buffer(value, ask, &walk);
    let mut origins: collections::BTreeSet<(i64, String)> = collections::BTreeSet::new();
    match made {
        Buffer::Named(ref buffer) => {
            let no_callee: String = String::from("");
            let id = (at, no_callee.to_owned());
            if !walk.sources.contains_key(&id) {
                let source = Source::Buffer { at, name: ask.names.resolve(*nikaia_std::index::get(&names, 0)).to_owned(), ty: buffer.to_owned(), span: span.clone() };
                walk.sources.insert(id, Sourced { source, path: walk.path.to_owned() });
            }
            origins.insert((at, no_callee));
        },
        _ => { origins = origins_of(value, ask, holes_of, unaliased, walk); },
    }
    for bound in names.iter() {
        bind_local(ask.names.resolve(*bound).to_owned(), a_local(at, &walk.path, origins.to_owned(), match ty {
            Some(__nikaia_it) => Some(__nikaia_it.to_owned()),
            None => None,
        }, is_buffer, text), walk);
    }
}

fn a_named_buffer(made: &Buffer) -> bool { matches!(made, Buffer::Named(_)) }

fn made_here(names: &[winnow_grammar::Symbol], value: &Expr, ty: Option<&Type>, ask: &BufferAsk<'_>, unaliased: &impl Fn(&str) -> String, walk: &BufferWalk) -> Buffer {
    if names.len() != 1 { return Buffer::None; }
    match value {
        Expr::MethodCall { receiver, method, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            let called = ask.names.resolve(method);
            if called == "clone" && copies_text(receiver, ask, walk) { return Buffer::Named(String::from("String")); }
            if called == "to_string" && formats(receiver, ask, walk) { return Buffer::Named(String::from("String")); }
        },
        _ => { },
    }
    let found = makes_a_buffer(value, &Asked { names: ask.names, own: ask.own, library: ask.library }, unaliased);
    if a_named_buffer(&found) { return found; }
    if !is_the_buffer(value, ask, walk) && declares_text(ask.names, ty) { return Buffer::Named(String::from("String")); }
    found
}

fn copies_text(receiver: &Expr, ask: &BufferAsk<'_>, walk: &BufferWalk) -> bool {
    match receiver {
        Expr::LitStr { .. } => true,
        Expr::LitInterpolated { .. } => true,
        Expr::Variable(name) => { let name = *name; text_local(ask.names.resolve(name), ask, walk) },
        Expr::MethodCall { receiver, method, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; match ask.names.resolve(method) == "trim" || ask.names.resolve(method) == "trim_start" || ask.names.resolve(method) == "trim_end" || ask.names.resolve(method) == "clone" {
            true => copies_text(receiver, ask, walk),
            false => false,
        } },
        _ => false,
    }
}

fn text_local(name: &str, ask: &BufferAsk<'_>, walk: &BufferWalk) -> bool {
    let local = match local_of(name, walk) { Some(__nikaia_value) => __nikaia_value, None => return false };
    if local.text { return true; }
    let ty = match local.ty { Some(__nikaia_value) => __nikaia_value, None => return false };
    let written = ask.names.resolve(ty.name);
    (written == "String" || written == "str") && ty.generics.is_empty()
}

fn formats(receiver: &Expr, ask: &BufferAsk<'_>, walk: &BufferWalk) -> bool {
    match receiver {
        Expr::Variable(name) => { let name = *name; formats_local(ask.names.resolve(name), ask, walk) },
        _ => false,
    }
}

fn formats_local(name: &str, ask: &BufferAsk<'_>, walk: &BufferWalk) -> bool {
    let local = match local_of(name, walk) { Some(__nikaia_value) => __nikaia_value, None => return false };
    let ty = match local.ty { Some(__nikaia_value) => __nikaia_value, None => return false };
    let written = ask.names.resolve(ty.name);
    written != "String" && written != "str"
}

fn is_the_buffer(expr: &Expr, ask: &BufferAsk<'_>, walk: &BufferWalk) -> bool {
    match expr {
        Expr::Variable(name) => { let name = *name; a_buffer_local(ask.names.resolve(name), walk) },
        Expr::MethodCall { receiver, method, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; match ask.names.resolve(method) == "clone" || ask.names.resolve(method) == "to_owned" || ask.names.resolve(method) == "to_string" {
            true => is_the_buffer(receiver, ask, walk),
            false => false,
        } },
        _ => false,
    }
}

fn struct_of(expr: &Expr, ask: &BufferAsk<'_>, walk: &BufferWalk) -> Option<String> {
    let name = match expr {
        Expr::StructLit { name, .. } => { let name = *name; ask.names.resolve(name).to_owned() },
        Expr::Variable(name) => { let name = *name; match written_type_of(ask.names.resolve(name), ask, walk) { Some(__nikaia_value) => __nikaia_value, None => return None } },
        _ => return None,
    };
    if ask.context.borrowing.contains(&name) { return Some(name); }
    None
}

fn written_type_of(name: &str, ask: &BufferAsk<'_>, walk: &BufferWalk) -> Option<String> {
    let local = match local_of(name, walk) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let ty = match local.ty { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(ask.names.resolve(ty.name).to_owned())
}

fn a_variant(callee: &str, ask: &BufferAsk<'_>) -> bool {
    let segments: Vec<&str> = callee.split("::").collect::<Vec<_>>();
    if segments.len() < 2 { return false; }
    let variant = *nikaia_std::index::get(&segments, nikaia_std::index::at(segments.len() as i64 - 1));
    let mut owner: String = String::from("");
    let mut k: i64 = 0;
    for segment in segments.iter() {
        let segment = *segment;
        if k == segments.len() as i64 - 1 { break; }
        if k > 0 { owner.push_str("::"); }
        owner.push_str(segment);
        k += 1;
    }
    for item in ask.items.iter() {
        match &item.node {
            Item::Enum { name, variants, .. } => {
                let name = *name;
                if ask.names.resolve(name) == owner { for one in variants.iter() { if ask.names.resolve(one.name) == variant { return true; } } }
            },
            _ => { },
        }
    }
    false
}

fn flow_into(root: &str, origins: &collections::BTreeSet<(i64, String)>, walk: &mut BufferWalk) {
    if origins.is_empty() { return; }
    let mut local = match local_of(root, &walk) { Some(__nikaia_value) => __nikaia_value, None => return };
    if local.parameter {
        if local.keeps { escape_all(&origins, &Escape::Param(root.to_owned()), walk); }
        return;
    }
    for origin in origins.iter() {
        let found = match *nikaia_std::index::get(&walk.sources, origin) { Some(__nikaia_value) => __nikaia_value, None => continue };
        let path = found.path.to_owned();
        let around = (local.path.len() as i64) <= path.len() as i64 && a_prefix(&local.path, &path);
        if around && local.at < origin.0 { escape(origin.clone(), Escape::Outer(root.to_owned()), walk); }
    }
    for origin in origins.iter() { local.origins.insert(origin.clone()); }
    set_local(root, local, walk);
}

fn a_prefix(short: &[(i64, bool)], long: &[(i64, bool)]) -> bool {
    for k in 0..short.len() as i64 { if nikaia_std::index::get(&short, (k) as usize).0 != nikaia_std::index::get(&long, (k) as usize).0 || nikaia_std::index::get(&short, (k) as usize).1 != nikaia_std::index::get(&long, (k) as usize).1 { return false; } }
    true
}

fn escape_all(origins: &collections::BTreeSet<(i64, String)>, escaping: &Escape, walk: &mut BufferWalk) { for origin in origins.iter() { if walk.sources.contains_key(origin) { escape(origin.clone(), escaping.clone(), walk); } } }

fn escape(origin: (i64, String), escaping: Escape, walk: &mut BufferWalk) {
    for (known, way) in walk.escapes.iter() { if known.0 == origin.0 && known.1 == origin.1 && same_escape(way, &escaping) { return; } }
    walk.escapes.push((origin, escaping));
}

fn same_escape(a: &Escape, b: &Escape) -> bool { escape_word(a) == escape_word(b) }

fn escape_word(escaping: &Escape) -> String {
    match escaping {
        Escape::Returned => String::from("0"),
        Escape::Param(name) => format!("1{}", name),
        Escape::Outer(name) => format!("2{}", name),
        Escape::Task => String::from("3"),
    }
}

fn nested_blocks(expr: &Expr, at: i64, ask: &BufferAsk<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, walk: &mut BufferWalk) {
    match expr {
        Expr::Block(block) => nested_keeping_statement(at, block, ask, holes_of, unaliased, walk),
        Expr::Unsafe(block) => nested_keeping_statement(at, block, ask, holes_of, unaliased, walk),
        Expr::Overlap(block) => nested_keeping_statement(at, block, ask, holes_of, unaliased, walk),
        Expr::Closure { body, .. } => nested_keeping_statement(at, body, ask, holes_of, unaliased, walk),
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            nested_blocks(func, at, ask, holes_of, unaliased, walk);
            for arg in args.iter() { nested_blocks(arg, at, ask, holes_of, unaliased, walk); }
            for setting in config.iter() { nested_blocks(&setting.value, at, ask, holes_of, unaliased, walk); }
        },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            nested_blocks(receiver, at, ask, holes_of, unaliased, walk);
            for arg in args.iter() { nested_blocks(arg, at, ask, holes_of, unaliased, walk); }
            for setting in config.iter() { nested_blocks(&setting.value, at, ask, holes_of, unaliased, walk); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            nested_blocks(receiver, at, ask, holes_of, unaliased, walk);
            for arg in args.iter() { nested_blocks(arg, at, ask, holes_of, unaliased, walk); }
            for setting in config.iter() { nested_blocks(&setting.value, at, ask, holes_of, unaliased, walk); }
        },
        Expr::If { then_branch, else_branch, .. } => {
            nested_keeping_statement(at, then_branch, ask, holes_of, unaliased, walk);
            nested_keeping_statement(at, match else_branch { Some(__nikaia_value) => __nikaia_value, None => return }, ask, holes_of, unaliased, walk);
        },
        Expr::TryCatch { expr, handler } => {
            let expr = nikaia_std::boxed::open(expr);
            nested_blocks(expr, at, ask, holes_of, unaliased, walk);
            nested_keeping_statement(at, handler, ask, holes_of, unaliased, walk);
        },
        Expr::Match { arms, .. } => { for arm in arms.iter() { nested_blocks(&arm.body, at, ask, holes_of, unaliased, walk); } },
        Expr::Select(arms) => { for arm in arms.iter() { nested_keeping_statement(at, &arm.body, ask, holes_of, unaliased, walk); } },
        _ => { },
    }
}

fn nested_keeping_statement(at: i64, block: &Block, ask: &BufferAsk<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, walk: &mut BufferWalk) {
    let statement = walk.statement;
    nested(at, false, block, ask, holes_of, unaliased, walk);
    walk.statement = statement;
}

fn spawns_in(expr: &Expr, ask: &BufferAsk<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, walk: &mut BufferWalk) {
    let mut bodies: Vec<Expr> = vec![];
    spawn_bodies(expr, holes_of, &mut bodies);
    for body in bodies.iter() {
        for name in task_names(body, ask, holes_of) {
            let local = match local_of(&name, &walk) { Some(__nikaia_value) => __nikaia_value, None => continue };
            if local.origins.is_empty() || local.buffer { continue; }
            escape_all(&local.origins, &Escape::Task, walk);
            capture(&name, &local, walk);
        }
    }
}

fn capture(name: &str, local: &Local, walk: &mut BufferWalk) {
    let mut held: (i64, collections::BTreeSet<(i64, String)>) = nikaia_std::index::or(match *nikaia_std::index::get(&walk.captured, name) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || (local.at, collections::BTreeSet::new()).into());
    for origin in local.origins.iter() { held.1.insert(origin.clone()); }
    walk.captured.insert(name.to_owned(), held);
}

fn task_names(body: &Expr, ask: &BufferAsk<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>) -> collections::BTreeSet<String> {
    let mut out: collections::BTreeSet<String> = collections::BTreeSet::new();
    for one in seen_in_expression(body, ask.names, &name_as_it_is, holes_of, &no_root, true) {
        match one {
            Seen::Name(ref name) => { out.insert(name.to_owned()); },
            _ => { },
        }
    }
    match body {
        Expr::Spawn { body, .. } => {
            let body = nikaia_std::boxed::open(body);
            for name in task_names(body, ask, holes_of) { out.insert(name); }
        },
        _ => { },
    }
    out
}

fn spawn_bodies(expr: &Expr, holes_of: &impl Fn(&Expr) -> Vec<Expr>, out: &mut Vec<Expr>) {
    match expr {
        Expr::Spawn { body, .. } => { let body = nikaia_std::boxed::open(body); out.push(body.clone()) },
        _ => { },
    }
    for hole in holes_of(expr) { spawn_bodies(&hole, holes_of, out); }
    match expr {
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            spawn_bodies(func, holes_of, out);
            for arg in args.iter() { spawn_bodies(arg, holes_of, out); }
            for setting in config.iter() { spawn_bodies(&setting.value, holes_of, out); }
        },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            spawn_bodies(receiver, holes_of, out);
            for arg in args.iter() { spawn_bodies(arg, holes_of, out); }
            for setting in config.iter() { spawn_bodies(&setting.value, holes_of, out); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            spawn_bodies(receiver, holes_of, out);
            for arg in args.iter() { spawn_bodies(arg, holes_of, out); }
            for setting in config.iter() { spawn_bodies(&setting.value, holes_of, out); }
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            spawn_bodies(lhs, holes_of, out);
            spawn_bodies(rhs, holes_of, out);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); spawn_bodies(expr, holes_of, out) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); spawn_bodies(inner, holes_of, out) },
        Expr::Throw(inner) => { let inner = nikaia_std::boxed::open(inner); spawn_bodies(inner, holes_of, out) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); spawn_bodies(expr, holes_of, out) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); spawn_bodies(base, holes_of, out) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); spawn_bodies(base, holes_of, out) },
        Expr::Index { base, index } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            spawn_bodies(base, holes_of, out);
            spawn_bodies(index, holes_of, out);
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            spawn_bodies(start, holes_of, out);
            spawn_bodies(end, holes_of, out);
        },
        Expr::Tuple(parts) => { for part in parts.iter() { spawn_bodies(part, holes_of, out); } },
        Expr::Coalesce { value, fallback } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            spawn_bodies(value, holes_of, out);
            spawn_bodies(fallback, holes_of, out);
        },
        Expr::TryCatch { expr, .. } => { let expr = nikaia_std::boxed::open(expr); spawn_bodies(expr, holes_of, out) },
        Expr::If { cond, .. } => { let cond = nikaia_std::boxed::open(cond); spawn_bodies(cond, holes_of, out) },
        Expr::Match { value, arms } => {
            let value = nikaia_std::boxed::open(value);
            spawn_bodies(value, holes_of, out);
            for arm in arms.iter() {
                if arm.guard.is_some() { spawn_bodies(match arm.guard.as_ref() { Some(__nikaia_value) => __nikaia_value, None => continue }, holes_of, out); }
                spawn_bodies(&arm.body, holes_of, out);
            }
        },
        Expr::StructLit { fields, .. } => { for field in fields.iter() { spawn_bodies(match field.value.as_ref() { Some(__nikaia_value) => __nikaia_value, None => continue }, holes_of, out); } },
        Expr::ListLit { items, .. } => { for item in items.iter() { spawn_bodies(item, holes_of, out); } },
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            spawn_bodies(base, holes_of, out);
            for field in fields.iter() { spawn_bodies(match field.value.as_ref() { Some(__nikaia_value) => __nikaia_value, None => continue }, holes_of, out); }
        },
        Expr::Return(value) => { let value = nikaia_std::boxed::open(value); spawn_bodies(match value { Some(__nikaia_value) => __nikaia_value, None => return }, holes_of, out) },
        Expr::Select(arms) => { for arm in arms.iter() { spawn_bodies(&arm.value, holes_of, out); } },
        _ => { },
    }
}

fn effects(expr: &Expr, ask: &BufferAsk<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, walk: &mut BufferWalk) {
    match expr {
        Expr::MethodCall { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            let root = root_of(ask.names, receiver);
            if root.is_some() { put_by_method(nikaia_std::index::or(root.as_deref(), || ""), ask.names.resolve(method), args, ask, holes_of, unaliased, walk); }
            origins_of(expr, ask, holes_of, unaliased, walk);
        },
        Expr::TryCatch { expr, .. } => { let expr = nikaia_std::boxed::open(expr); effects(expr, ask, holes_of, unaliased, walk) },
        Expr::Try(expr) => { let expr = nikaia_std::boxed::open(expr); effects(expr, ask, holes_of, unaliased, walk) },
        _ => { origins_of(expr, ask, holes_of, unaliased, walk); },
    }
}

fn put_by_method(root: &str, method: &str, args: &[Expr], ask: &BufferAsk<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, walk: &mut BufferWalk) {
    if drops_entries(method) { shed(root, walk); }
    if !keeps_what_it_is_given(method) { return; }
    let mut all: collections::BTreeSet<(i64, String)> = collections::BTreeSet::new();
    for k in 0..args.len() as i64 {
        let mut of: collections::BTreeSet<(i64, String)> = collections::BTreeSet::new();
        if !is_the_buffer(nikaia_std::index::get(&args, nikaia_std::index::at(k)), ask, &walk) { of = origins_of(nikaia_std::index::get(&args, nikaia_std::index::at(k)), ask, holes_of, unaliased, walk); }
        put_into(root, k, &of, walk);
        let named = struct_of(nikaia_std::index::get(&args, nikaia_std::index::at(k)), ask, &walk);
        if named.is_some() { walk.struct_puts.insert(root.to_owned(), nikaia_std::index::or(named, || "".into())); }
        for origin in of.iter() { all.insert(origin.clone()); }
    }
    flow_into(root, &all, walk);
}

fn by_arg_of(puts: Option<&PutsAt>) -> collections::BTreeMap<i64, collections::BTreeSet<(i64, String)>> {
    let found = match puts { Some(__nikaia_value) => __nikaia_value, None => return collections::BTreeMap::new() };
    found.by_arg.to_owned()
}

fn put_into(root: &str, at: i64, of: &collections::BTreeSet<(i64, String)>, walk: &mut BufferWalk) {
    let key = (walk.statement, root.to_owned());
    let mut by_arg: collections::BTreeMap<i64, collections::BTreeSet<(i64, String)>> = by_arg_of(*nikaia_std::index::get(&walk.puts_into, &key));
    let mut here: collections::BTreeSet<(i64, String)> = nikaia_std::index::or(match *nikaia_std::index::get(&by_arg, &at) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || collections::BTreeSet::new().into());
    for origin in of.iter() { here.insert(origin.clone()); }
    by_arg.insert(at, here);
    walk.puts_into.insert(key, PutsAt { by_arg });
}

fn origins_of(expr: &Expr, ask: &BufferAsk<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, walk: &mut BufferWalk) -> collections::BTreeSet<(i64, String)> {
    let none: collections::BTreeSet<(i64, String)> = collections::BTreeSet::new();
    match expr {
        Expr::Variable(name) => { let name = *name; origins_of_local(ask.names.resolve(name), &walk) },
        Expr::MethodCall { .. } => method_origins(expr, ask, holes_of, unaliased, walk),
        Expr::SafeMethod { .. } => method_origins(expr, ask, holes_of, unaliased, walk),
        Expr::Call { func, args, .. } => { let func = nikaia_std::boxed::open(func); call_origins(func, args, ask, holes_of, unaliased, walk) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); origins_of(base, ask, holes_of, unaliased, walk) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); origins_of(base, ask, holes_of, unaliased, walk) },
        Expr::Index { base, index } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            origins_of(index, ask, holes_of, unaliased, walk);
            origins_of(base, ask, holes_of, unaliased, walk)
        },
        Expr::StructLit { fields, .. } => {
            let mut out: collections::BTreeSet<(i64, String)> = collections::BTreeSet::new();
            for field in fields.iter() {
                if field.value.is_none() {
                    let local = match local_of(ask.names.resolve(field.name), &walk) { Some(__nikaia_value) => __nikaia_value, None => continue };
                    if !local.buffer { add_all(&local.origins, &mut out); }
                    continue;
                }
                let value = match field.value.as_ref() { Some(__nikaia_value) => __nikaia_value, None => continue };
                let of = origins_of(value, ask, holes_of, unaliased, walk);
                if !is_the_buffer(value, ask, &walk) { add_all(&of, &mut out); }
            }
            out
        },
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            let mut out = origins_of(base, ask, holes_of, unaliased, walk);
            for field in fields.iter() { add_all(&origins_of(match field.value.as_ref() { Some(__nikaia_value) => __nikaia_value, None => continue }, ask, holes_of, unaliased, walk), &mut out); }
            out
        },
        Expr::ListLit { items, .. } => items_origins(items, ask, holes_of, unaliased, walk),
        Expr::Tuple(items) => items_origins(items, ask, holes_of, unaliased, walk),
        Expr::If { cond, then_branch, else_branch } => {
            let cond = nikaia_std::boxed::open(cond);
            origins_of(cond, ask, holes_of, unaliased, walk);
            let mut out = tail_origins(then_branch, ask, holes_of, unaliased, walk);
            if else_branch.is_some() { add_all(&tail_origins(match else_branch { Some(__nikaia_value) => __nikaia_value, None => return out }, ask, holes_of, unaliased, walk), &mut out); }
            out
        },
        Expr::Match { value, arms } => {
            let value = nikaia_std::boxed::open(value);
            origins_of(value, ask, holes_of, unaliased, walk);
            let mut out: collections::BTreeSet<(i64, String)> = collections::BTreeSet::new();
            for arm in arms.iter() { add_all(&origins_of(&arm.body, ask, holes_of, unaliased, walk), &mut out); }
            out
        },
        Expr::Block(block) => tail_origins(block, ask, holes_of, unaliased, walk),
        Expr::Unsafe(block) => tail_origins(block, ask, holes_of, unaliased, walk),
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); origins_of(expr, ask, holes_of, unaliased, walk) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); origins_of(inner, ask, holes_of, unaliased, walk) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); origins_of(expr, ask, holes_of, unaliased, walk) },
        Expr::TryCatch { expr, handler } => {
            let expr = nikaia_std::boxed::open(expr);
            let mut out = origins_of(expr, ask, holes_of, unaliased, walk);
            add_all(&tail_origins(handler, ask, holes_of, unaliased, walk), &mut out);
            out
        },
        Expr::Coalesce { value, fallback } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            let mut out = origins_of(value, ask, holes_of, unaliased, walk);
            add_all(&origins_of(fallback, ask, holes_of, unaliased, walk), &mut out);
            out
        },
        Expr::LitInterpolated { .. } => {
            for hole in holes_of(expr) { origins_of(&hole, ask, holes_of, unaliased, walk); }
            none
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            origins_of(lhs, ask, holes_of, unaliased, walk);
            origins_of(rhs, ask, holes_of, unaliased, walk);
            none
        },
        _ => none,
    }
}

fn origins_of_local(name: &str, walk: &BufferWalk) -> collections::BTreeSet<(i64, String)> {
    let local = match local_of(name, walk) { Some(__nikaia_value) => __nikaia_value, None => return collections::BTreeSet::new() };
    local.origins.to_owned()
}

fn a_buffer_local(name: &str, walk: &BufferWalk) -> bool {
    let local = match local_of(name, walk) { Some(__nikaia_value) => __nikaia_value, None => return false };
    local.buffer
}

fn add_all(from: &collections::BTreeSet<(i64, String)>, into: &mut collections::BTreeSet<(i64, String)>) { for one in from.iter() { into.insert(one.clone()); } }

fn items_origins(items: &[Expr], ask: &BufferAsk<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, walk: &mut BufferWalk) -> collections::BTreeSet<(i64, String)> {
    let mut out: collections::BTreeSet<(i64, String)> = collections::BTreeSet::new();
    for item in items.iter() {
        let of = origins_of(item, ask, holes_of, unaliased, walk);
        if !is_the_buffer(item, ask, &walk) { add_all(&of, &mut out); }
    }
    out
}

fn method_origins(call: &Expr, ask: &BufferAsk<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, walk: &mut BufferWalk) -> collections::BTreeSet<(i64, String)> {
    let (receiver, method, args) = match call {
        Expr::MethodCall { receiver, method, args, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; (receiver, ask.names.resolve(method).to_owned(), args) },
        Expr::SafeMethod { receiver, method, args, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; (receiver, ask.names.resolve(method).to_owned(), args) },
        _ => return collections::BTreeSet::new(),
    };
    if drops_entries(&method) {
        let root = root_of(ask.names, receiver);
        if root.is_some() { shed(nikaia_std::index::or(root.as_deref(), || ""), walk); }
    }
    let mut out: collections::BTreeSet<(i64, String)> = collections::BTreeSet::new();
    let on_self = match receiver {
        Expr::Variable(name) => { let name = *name; ask.names.resolve(name) == "self" },
        _ => false,
    };
    let keeping = keeping_method_key(ask.own, (walk.target).as_deref(), on_self, &method);
    if keeping.is_some() { add_all(&call_source(nikaia_std::index::or(keeping.as_deref(), || ""), walk), &mut out); }
    if hands_back_its_own(&method) || method == "clone" && copies_text(receiver, ask, &walk) || keeping.is_none() && owned_by_every_method(ask.own, &method) {
        for arg in args.iter() { origins_of(arg, ask, holes_of, unaliased, walk); }
        origins_of(receiver, ask, holes_of, unaliased, walk);
        return out;
    }
    add_all(&origins_of(receiver, ask, holes_of, unaliased, walk), &mut out);
    for arg in args.iter() { add_all(&origins_of(arg, ask, holes_of, unaliased, walk), &mut out); }
    out
}

fn owned_by_every_method(ledger: &Ledger, method: &str) -> bool {
    let suffix = format!("::{}", method);
    let mut any = false;
    for (key, contract) in ledger.functions.iter() {
        if key.ends_with(&suffix) {
            let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return false };
            any = true;
            let result = match signature.result.as_ref() { Some(__nikaia_value) => __nikaia_value, None => continue };
            if a_ledger_type_with_a_view(result) { return false; }
        }
    }
    any
}

fn call_origins(func: &Expr, args: &[Expr], ask: &BufferAsk<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, walk: &mut BufferWalk) -> collections::BTreeSet<(i64, String)> {
    let callee = written_callee(ask.names, func, unaliased);
    let named = nikaia_std::index::or(match callee.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || "".into());
    let variant = callee.is_some() && a_variant(&named, ask);
    let mut out: collections::BTreeSet<(i64, String)> = collections::BTreeSet::new();
    let mut by_args: collections::BTreeSet<(i64, String)> = collections::BTreeSet::new();
    for arg in args.iter() {
        let of = origins_of(arg, ask, holes_of, unaliased, walk);
        if !(variant && is_the_buffer(arg, ask, &walk)) { add_all(&of, &mut by_args); }
    }
    if callee.is_some() {
        let mut owned = false;
        if ask.own.functions.contains_key(&named) {
            let contract = match *nikaia_std::index::get(&ask.own.functions, &named) { Some(__nikaia_value) => __nikaia_value, None => return by_args };
            owned = answered_by(contract, &named, args, ask, &mut out, walk);
            made_arguments(contract, &named, args, ask, &mut out, walk);
        } else if ask.library.functions.contains_key(&named) {
            let contract = match *nikaia_std::index::get(&ask.library.functions, &named) { Some(__nikaia_value) => __nikaia_value, None => return by_args };
            owned = answered_by(contract, &named, args, ask, &mut out, walk);
            made_arguments(contract, &named, args, ask, &mut out, walk);
        }
        if owned { return out; }
    }
    add_all(&by_args, &mut out);
    out
}

fn answered_by(contract: &FnContract, named: &str, args: &[Expr], ask: &BufferAsk<'_>, out: &mut collections::BTreeSet<(i64, String)>, walk: &mut BufferWalk) -> bool {
    if takes_a_keep(contract) {
        let source = call_source(named, walk);
        for held in contract.views.iter() {
            if held.state != State::Tethered || held.position == RESULT_POSITION { continue; }
            let at = parameter_index(contract, &held.position);
            if at < 0 || at >= args.len() as i64 { continue; }
            let root = match root_of(ask.names, nikaia_std::index::get(&args, nikaia_std::index::at(at))) { Some(__nikaia_value) => __nikaia_value, None => continue };
            flow_into(&root, &source.to_owned(), walk);
        }
        for held in contract.views.iter() {
            if held.position == RESULT_POSITION && held.state == State::Tethered {
                add_all(&source, out);
                break;
            }
        }
    }
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return false };
    let result = match signature.result.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return false };
    !a_ledger_type_with_a_view(result)
}

fn made_arguments(contract: &FnContract, named: &str, args: &[Expr], ask: &BufferAsk<'_>, out: &mut collections::BTreeSet<(i64, String)>, walk: &mut BufferWalk) {
    if takes_a_keep(contract) { return; }
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return };
    let result = match signature.result.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return };
    if !result.is_a_view() { return; }
    let copying: Vec<&Ledger> = vec![ask.own, ask.library];
    for k in 0..args.len() as i64 {
        if !made_in_the_call(nikaia_std::index::get(&args, nikaia_std::index::at(k))) || !lends_in(contract, k, &copying) { continue; }
        let id = (walk.statement, format!("{}#{}", named, k));
        if !walk.sources.contains_key(&id) {
            let source = Source::Argument { at: walk.statement, callee: named.to_owned(), index: k, span: Span { start: u32::try_from(walk.statement).unwrap_or_else(|_| panic!("the value does not fit in an `u32`")), end: u32::try_from(walk.statement).unwrap_or_else(|_| panic!("the value does not fit in an `u32`")) } };
            walk.sources.insert(id.clone(), Sourced { source, path: walk.path.to_owned() });
        }
        out.insert(id);
    }
}

fn made_in_the_call(arg: &Expr) -> bool { !matches!(arg, Expr::Variable(_) | Expr::Field { .. } | Expr::SafeField { .. } | Expr::Index { .. } | Expr::Path(_) | Expr::LitStr { .. } | Expr::LitInt { .. } | Expr::LitFloat { .. } | Expr::LitBool(_) | Expr::LitNull) }

fn parameter_index(contract: &FnContract, position: &str) -> i64 {
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return -1 };
    let mut at: i64 = 0;
    for (name, _) in signature.params.iter() {
        if name == position { return at; }
        at += 1;
    }
    -1
}

fn tail_origins(block: &Block, ask: &BufferAsk<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, walk: &mut BufferWalk) -> collections::BTreeSet<(i64, String)> {
    let none: collections::BTreeSet<(i64, String)> = collections::BTreeSet::new();
    if block.stmts.is_empty() { return none; }
    let last = nikaia_std::index::get(&block.stmts, nikaia_std::index::at(block.stmts.len() as i64 - 1));
    match last.node {
        Stmt::Expr(ref value) => {
            let outer = walk.statement;
            walk.statement = last.span.start as i64;
            let origins = origins_of(value, ask, holes_of, unaliased, walk);
            walk.statement = outer;
            origins
        },
        _ => none,
    }
}

fn call_source(callee: &str, walk: &mut BufferWalk) -> collections::BTreeSet<(i64, String)> {
    let id = (walk.statement, callee.to_owned());
    if !walk.sources.contains_key(&id) {
        let source = Source::Call { at: walk.statement, callee: callee.to_owned(), span: Span { start: u32::try_from(walk.statement).unwrap_or_else(|_| panic!("the value does not fit in an `u32`")), end: u32::try_from(walk.statement).unwrap_or_else(|_| panic!("the value does not fit in an `u32`")) } };
        walk.sources.insert(id.clone(), Sourced { source, path: walk.path.to_owned() });
    }
    let mut one: collections::BTreeSet<(i64, String)> = collections::BTreeSet::new();
    one.insert(id);
    one
}

fn decide(key: String, body: &Block, walk: &BufferWalk, ask: &BufferAsk<'_>) -> BufferPlan {
    let mut first: i64 = -1;
    if !body.stmts.is_empty() { first = nikaia_std::index::get(&body.stmts, 0).span.start as i64; }
    let mut plan = BufferPlan { key, first, takes_keep: false, frame_keep: false, task_keep: false, local_keeps: collections::BTreeSet::new(), puts: collections::BTreeMap::new(), calls: collections::BTreeMap::new(), tethered: collections::BTreeMap::new(), element_keepers: collections::BTreeSet::new(), struct_keepers: collections::BTreeSet::new(), widths: collections::BTreeMap::new(), keeper_structs: collections::BTreeMap::new(), held_locals: collections::BTreeSet::new(), holds: collections::BTreeMap::new(), escapes: vec![], refusals: vec![], reputs: collections::BTreeMap::new() };
    for (id, found) in walk.sources.iter() { decide_source(&id.clone(), &found.source, &found.path, walk, &mut plan); }
    for (statement, bound) in walk.reassigned.iter() {
        let statement = nikaia_std::num::value(statement);let bound = nikaia_std::num::value(bound);
        let keep = match match *nikaia_std::index::get(&plan.puts, &bound) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => continue };
        plan.reputs.insert(statement.clone(), keep);
    }
    for (place, by_arg) in plan.holds.iter() {
        let mut widest: i64 = 1;
        for (_, statements) in by_arg.iter() { if (statements.len() as i64) > widest { widest = statements.len() as i64; } }
        let width = nikaia_std::index::or(*nikaia_std::index::get(&plan.widths, &place.1), || 1);
        if widest > width { plan.widths.insert(place.1.to_owned(), widest); } else { plan.widths.insert(place.1.to_owned(), width); }
    }
    for keeper in plan.element_keepers.iter() {
        let written = keeper_type(keeper, walk);
        let names_one = struct_of_views_maybe((written).as_ref(), ask);
        if names_one || walk.struct_puts.contains_key(keeper) {
            plan.struct_keepers.insert(keeper.to_owned());
            let named = keeper_struct(keeper, (written).as_ref(), walk, ask);
            if named.is_some() { plan.keeper_structs.insert(keeper.to_owned(), nikaia_std::index::or(named, || "".into())); }
        }
    }
    for (local, from) in walk.taken.iter() { if plan.struct_keepers.contains(from) { plan.held_locals.insert(local.to_owned()); } }
    element_refusals(walk, ask, &mut plan);
    plan
}

fn struct_of_views_maybe(written: Option<&Type>, ask: &BufferAsk<'_>) -> bool {
    let ty = match written { Some(__nikaia_value) => __nikaia_value, None => return false };
    names_a_struct_of_views(ask.names, ty, &ask.context.borrowing)
}

fn not_held_maybe(written: Option<&Type>, ask: &BufferAsk<'_>) -> Option<String> {
    let ty = match written { Some(__nikaia_value) => __nikaia_value, None => return None };
    let mut seen: Vec<String> = vec![];
    ask.context.not_held(ask.names, ty, &mut seen)
}

fn a_sequence_container(written: Option<&Type>, ask: &BufferAsk<'_>) -> bool {
    let ty = match written { Some(__nikaia_value) => __nikaia_value, None => return true };
    let container = ask.names.resolve(ty.name);
    container == "Vec" || container == "List" || container == "VecDeque" || container == "Deque"
}

fn keeper_type(keeper: &str, walk: &BufferWalk) -> Option<Type> {
    let local = match *nikaia_std::index::get(&walk.last_seen, keeper) { Some(__nikaia_value) => __nikaia_value, None => return None };
    match local.ty.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }
}

fn keeper_struct(keeper: &str, written: Option<&Type>, walk: &BufferWalk, ask: &BufferAsk<'_>) -> Option<String> {
    if walk.struct_puts.contains_key(keeper) {
        return match *nikaia_std::index::get(&walk.struct_puts, keeper) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        };
    }
    let ty = match written { Some(__nikaia_value) => __nikaia_value, None => return None };
    struct_in(ask.names, ty, &ask.context.borrowing)
}

fn decide_source(id: &(i64, String), source: &Source, path: &[(i64, bool)], walk: &BufferWalk, plan: &mut BufferPlan) {
    let mut ways: collections::BTreeMap<String, Escape> = collections::BTreeMap::new();
    for (known, way) in walk.escapes.iter() { if known.0 == id.0 && known.1 == id.1 { ways.insert(escape_word(way), way.clone()); } }
    let mut leaves = false;
    let mut task = false;
    let mut outer: Vec<String> = vec![];
    for (_, way) in ways.iter() {
        plan.escapes.push((source.clone(), way.clone()));
        match way {
            Escape::Returned => { leaves = true; },
            Escape::Param(_) => { leaves = true; },
            Escape::Task => { task = true; },
            Escape::Outer(name) => outer.push(name.to_owned()),
        }
    }
    let mut shedding: Vec<String> = vec![];
    for keeper in outer.iter() { if sheds_across(keeper, path, walk) { shedding.push(keeper.to_owned()); } }
    if task && leaves {
        plan.refusals.push(source_refusal(source, "is passed to a task and also returned from this function.", "The task may outlive the caller, or the caller the task, so neither can be the one that keeps the data alive.", "Give the task a copy with `.clone()`, or pass the task only what it needs and return the rest."));
        return;
    }
    let mut keep = KeepAt::Frame;
    if task {
        keep = KeepAt::Task;
        plan.task_keep = true;
    } else if leaves {
        keep = KeepAt::Param;
        plan.takes_keep = true;
    } else if !shedding.is_empty() {
        keep = KeepAt::Element(source_at(source));
        held_one_per_buffer(&id.clone(), source, &shedding, walk, plan);
    } else if !outer.is_empty() { plan.frame_keep = true; } else {
        match source {
            Source::Buffer { .. } => return,
            Source::Call { at, .. } => {
                let at = *at;
                keep = KeepAt::Local(at.clone());
                plan.local_keeps.insert(at.clone());
            },
            Source::Argument { at, .. } => {
                let at = *at;
                keep = KeepAt::Local(at.clone());
                plan.local_keeps.insert(at.clone());
            },
        }
    }
    match source {
        Source::Buffer { at, .. } => {
            let at = *at;
            plan.puts.insert(at.clone(), keep.clone());
        },
        Source::Call { at, callee, .. } => {
            let at = *at;
            plan.calls.insert((at.clone(), callee.to_owned()), keep.clone());
        },
        Source::Argument { at, callee, index, .. } => {
            let at = *at; let index = *index;
            plan.calls.insert((at.clone(), format!("{}#{}", callee, index)), keep.clone());
        },
    }
    if task { for (name, held) in walk.captured.iter() { if held.1.contains(&id) { plan.tethered.insert(name.to_owned(), held.0); } } }
}

fn sheds_across(keeper: &str, path: &[(i64, bool)], walk: &BufferWalk) -> bool {
    let sheds = match *nikaia_std::index::get(&walk.sheds, keeper) { Some(__nikaia_value) => __nikaia_value, None => return false };
    let declared: Vec<(i64, bool)> = nikaia_std::index::or(match (*nikaia_std::index::get(&walk.last_seen, keeper)).as_ref().map(|__nikaia_it| &__nikaia_it.path) {
        Some(__nikaia_it) => Some(__nikaia_it.to_owned()),
        None => None,
    }, || vec![].into());
    for around in path.iter() {
        if !around.1 || declared_in(&declared, around.0) { continue; }
        for shed in sheds.iter() { for step in shed.iter() { if step.0 == around.0 && step.1 == around.1 { return true; } } }
    }
    false
}

fn declared_in(declared: &[(i64, bool)], at: i64) -> bool {
    for step in declared.iter() { if step.0 == at && step.1 { return true; } }
    false
}

fn source_at(source: &Source) -> i64 {
    match source {
        Source::Buffer { at, .. } => { let at = *at; at.clone() },
        Source::Call { at, .. } => { let at = *at; at.clone() },
        Source::Argument { at, .. } => { let at = *at; at.clone() },
    }
}

fn held_one_per_buffer(id: &(i64, String), source: &Source, shedding: &[String], walk: &BufferWalk, plan: &mut BufferPlan) {
    for keeper in shedding.iter() { plan.element_keepers.insert(keeper.to_owned()); }
    for (place, puts) in walk.puts_into.iter() {
        if !a_name_among(&place.1, shedding) { continue; }
        for (arg, origins) in puts.by_arg.iter() {
            let arg = nikaia_std::num::value(arg);
            if origins.contains(&id) { hold(&place.clone(), arg.clone(), source_at(source), plan); }
        }
    }
}

fn hold(place: &(i64, String), arg: i64, statement: i64, plan: &mut BufferPlan) {
    let mut by_arg: collections::BTreeMap<i64, collections::BTreeSet<i64>> = nikaia_std::index::or(match *nikaia_std::index::get(&plan.holds, place) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || collections::BTreeMap::new().into());
    let mut statements: collections::BTreeSet<i64> = nikaia_std::index::or(match *nikaia_std::index::get(&by_arg, &arg) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || collections::BTreeSet::new().into());
    statements.insert(statement);
    by_arg.insert(arg, statements);
    plan.holds.insert(place.clone(), by_arg);
}

fn a_name_among(name: &str, names: &[String]) -> bool {
    for one in names.iter() { if one == name { return true; } }
    false
}

fn source_named(source: &Source) -> String {
    match source {
        Source::Buffer { name, ty, .. } => format!("`{}` (a `{}` this body reads)", name, ty),
        Source::Call { callee, .. } => format!("what `{}` returns", callee),
        Source::Argument { callee, index, .. } => { let index = *index; format!("the argument {} made in the call to `{}`", index + 1, callee) },
    }
}

fn source_refusal(source: &Source, what: &str, why: &str, help: &str) -> Finding {
    let span = match source {
        Source::Buffer { span, .. } => span.clone(),
        Source::Call { span, .. } => span.clone(),
        Source::Argument { span, .. } => span.clone(),
    };
    let named = capitalised(&source_named(source));
    refusal("NK2304", span, format!("{} {}", named, what), vec![why.to_owned()], help.to_owned())
}

fn element_refusals(walk: &BufferWalk, ask: &BufferAsk<'_>, plan: &mut BufferPlan) {
    let mut found: Vec<Finding> = vec![];
    for keeper in plan.element_keepers.iter() {
        let written = keeper_type(keeper, walk);
        let mut whys: Vec<String> = vec![];
        let held = not_held_maybe((written).as_ref(), ask);
        if held.is_some() { whys.push(nikaia_std::index::or(held, || "".into())); }
        if walk.struct_puts.contains_key(keeper) {
            let mut seen: Vec<String> = vec![];
            let named = nikaia_std::index::or(match *nikaia_std::index::get(&walk.struct_puts, keeper) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || "".into());
            let why = ask.context.struct_not_held(ask.names, &named, &mut seen);
            if why.is_some() { whys.push(nikaia_std::index::or(why, || "".into())); }
        }
        let sequence = a_sequence_container((written).as_ref(), ask);
        let not_a_list = plan.struct_keepers.contains(keeper) && !sequence;
        if !not_a_list { for why in whys.iter() { found.push(element_refusal(keeper, &format!("it holds {}, which isn't supported there yet", why), "Keep text, or structs of text views, in it, or store copies made with `.clone()`.", &plan)); } } else { found.push(element_refusal(keeper, "it isn't a list, and only a list can hold structs of views here yet", "Keep the structs in a list, or store copies made with `.clone()`.", &plan)); }
    }
    for one in found.iter() { plan.refusals.push(one.clone()); }
}

fn element_refusal(keeper: &str, why: &str, help: &str, plan: &BufferPlan) -> Finding {
    let mut span = Span::nowhere();
    for (place, _) in plan.holds.iter() {
        if place.1 == keeper {
            span = Span { start: u32::try_from(place.0).unwrap_or_else(|_| panic!("the value does not fit in an `u32`")), end: u32::try_from(place.0).unwrap_or_else(|_| panic!("the value does not fit in an `u32`")) };
            break;
        }
    }
    refusal("NK2304", span, format!("`{}` keeps views of data read inside a loop and removes entries as it goes, but {}.", keeper, why), vec![String::from("Each view keeps its own data alive here, so that data read for entries that were removed can be freed during the loop.")], help.to_owned())
}


// --- build_values.nika ---

#[derive(Debug, Clone, PartialEq)]
pub enum BuildValue {
    Int(Integer),
    Float(f64),
    Bool(bool),
    List(Vec<BuildValue>),
    Text(String),
    Variant { ty: String, variant: String, payload: Vec<BuildValue> },
    Tuple(Vec<BuildValue>),
    Struct { name: String, fields: collections::BTreeMap<String, BuildValue> },
    Constant { constructor: String, parts: Vec<BuildValue> },
}

pub fn operated(op: &BinaryOp, left: &BuildValue, right: &BuildValue) -> Option<BuildValue> {
    match left {
        BuildValue::Int(a) => match right {
            BuildValue::Int(b) => integers_operated(op, a, b),
            _ => None,
        },
        BuildValue::Float(a) => { let a = *a; match right {
            BuildValue::Float(b) => { let b = *b; floats_operated(op, a, b) },
            _ => None,
        } },
        BuildValue::Text(a) => match right {
            BuildValue::Text(b) => texts_operated(op, a, b),
            _ => None,
        },
        BuildValue::Bool(a) => { let a = *a; match right {
            BuildValue::Bool(b) => { let b = *b; truths_operated(op, a, b) },
            _ => None,
        } },
        _ => None,
    }
}

fn integers_operated(op: &BinaryOp, a: &Integer, b: &Integer) -> Option<BuildValue> {
    let order = integer_order(a, b);
    match op {
        BinaryOp::Add => an_integer(integer_sum(a, b)),
        BinaryOp::Sub => an_integer(integer_difference(a, b)),
        BinaryOp::Mul => an_integer(integer_product(a, b)),
        BinaryOp::Div => an_integer(integer_quotient(a, b, false)),
        BinaryOp::Rem => an_integer(integer_quotient(a, b, true)),
        BinaryOp::Eq => Some(BuildValue::Bool(order == 0)),
        BinaryOp::Ne => Some(BuildValue::Bool(order != 0)),
        BinaryOp::Lt => Some(BuildValue::Bool(order < 0)),
        BinaryOp::Le => Some(BuildValue::Bool(order <= 0)),
        BinaryOp::Gt => Some(BuildValue::Bool(order > 0)),
        BinaryOp::Ge => Some(BuildValue::Bool(order >= 0)),
        BinaryOp::BitAnd => an_integer(integer_bits(a, b, "&")),
        BinaryOp::BitOr => an_integer(integer_bits(a, b, "|")),
        BinaryOp::BitXor => an_integer(integer_bits(a, b, "^")),
        BinaryOp::Shl => an_integer(integer_shifted(a, b, true)),
        BinaryOp::Shr => an_integer(integer_shifted(a, b, false)),
        _ => None,
    }
}

fn an_integer(n: Option<Integer>) -> Option<BuildValue> {
    let found = match n { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(BuildValue::Int(found))
}

fn floats_operated(op: &BinaryOp, a: f64, b: f64) -> Option<BuildValue> {
    match op {
        BinaryOp::Add => Some(BuildValue::Float(a + b)),
        BinaryOp::Sub => Some(BuildValue::Float(a - b)),
        BinaryOp::Mul => Some(BuildValue::Float(a * b)),
        BinaryOp::Div => Some(BuildValue::Float(a / b)),
        BinaryOp::Rem => Some(BuildValue::Float(a % b)),
        BinaryOp::Eq => Some(BuildValue::Bool(a == b)),
        BinaryOp::Ne => Some(BuildValue::Bool(a != b)),
        BinaryOp::Lt => Some(BuildValue::Bool(a < b)),
        BinaryOp::Le => Some(BuildValue::Bool(a <= b)),
        BinaryOp::Gt => Some(BuildValue::Bool(a > b)),
        BinaryOp::Ge => Some(BuildValue::Bool(a >= b)),
        _ => None,
    }
}

fn texts_operated(op: &BinaryOp, a: &str, b: &str) -> Option<BuildValue> {
    match op {
        BinaryOp::Add => Some(BuildValue::Text(format!("{}{}", a, b))),
        BinaryOp::Eq => Some(BuildValue::Bool(a == b)),
        BinaryOp::Ne => Some(BuildValue::Bool(a != b)),
        _ => None,
    }
}

fn truths_operated(op: &BinaryOp, a: bool, b: bool) -> Option<BuildValue> {
    match op {
        BinaryOp::Eq => Some(BuildValue::Bool(a == b)),
        BinaryOp::Ne => Some(BuildValue::Bool(a != b)),
        BinaryOp::And => Some(BuildValue::Bool(a && b)),
        BinaryOp::Or => Some(BuildValue::Bool(a || b)),
        _ => None,
    }
}

#[derive(Debug, Clone, PartialEq)]
pub enum ElementRead {
    Found(BuildValue),
    OutOfBounds { at: Integer, len: i64 },
    Unreadable,
}

pub fn element_at(on: &BuildValue, at: &BuildValue) -> ElementRead {
    let items = match on {
        BuildValue::List(items) => items,
        _ => return ElementRead::Unreadable,
    };
    let index = match at {
        BuildValue::Int(index) => index.clone(),
        _ => return ElementRead::Unreadable,
    };
    let count = nikaia_std::index::or(integer_as_count(&index), || -1);
    if count < 0 || count >= items.len() as i64 { return ElementRead::OutOfBounds { at: index, len: items.len() as i64 }; }
    ElementRead::Found((*nikaia_std::index::get(&items, nikaia_std::index::at(count))).clone())
}


// --- calls.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Callee {
    Own(String),
    Library { key: String, never_pauses: bool },
    Method,
    Opaque(Option<String>),
}

pub fn callee_of(names: &winnow_grammar::InternerContext, expr: &Expr, own: &Ledger, library: &Ledger, items: &[Spanned<Item>]) -> Option<Callee> {
    let name = match expr {
        Expr::Call { func, .. } => { let func = nikaia_std::boxed::open(func); match called_name(names, func) { Some(__nikaia_value) => __nikaia_value, None => return Some(Callee::Opaque(None)) } },
        Expr::MethodCall { .. } => return Some(Callee::Method),
        Expr::SafeMethod { .. } => return Some(Callee::Method),
        Expr::Spawn { .. } => return Some(Callee::Opaque(None)),
        Expr::Dsl { .. } => return Some(Callee::Opaque(None)),
        _ => return None,
    };
    callee_named(names, name, own, library, items)
}

pub fn callee_named(names: &winnow_grammar::InternerContext, name: String, own: &Ledger, library: &Ledger, items: &[Spanned<Item>]) -> Option<Callee> {
    if own.functions.contains_key(&name) { return Some(Callee::Own(name)); }
    let constructed = format!("{}::new", name);
    if own.functions.contains_key(&constructed) { return Some(Callee::Own(constructed)); }
    for written in [name.to_owned(), constructed] {
        let contract = match *nikaia_std::index::get(&library.functions, &written) { Some(__nikaia_value) => __nikaia_value, None => continue };
        return Some(Callee::Library { key: written.to_owned(), never_pauses: contract.sync_claim.is_sync() });
    }
    if names_a_variant(names, &name, own, library, items) { return None; }
    Some(Callee::Opaque(Some(name)))
}

fn called_name(names: &winnow_grammar::InternerContext, func: &Expr) -> Option<String> {
    match func {
        Expr::Variable(symbol) => { let symbol = *symbol; Some(names.resolve(symbol).to_owned()) },
        Expr::Path(segments) => Some(written_path(names, segments)),
        _ => None,
    }
}

fn written_path(names: &winnow_grammar::InternerContext, segments: &[winnow_grammar::Symbol]) -> String {
    let mut written: String = String::from("");
    for k in 0..segments.len() as i64 {
        if k > 0 { written = format!("{}::", written); }
        let segment = names.resolve(*nikaia_std::index::get(&segments, (k) as usize));
        written = format!("{}{}", written, segment);
    }
    written
}

fn names_a_variant(names: &winnow_grammar::InternerContext, name: &str, own: &Ledger, library: &Ledger, items: &[Spanned<Item>]) -> bool {
    let mut parts: Vec<String> = vec![];
    for part in name.split("::") { parts.push(part.to_owned()); }
    if parts.len() < 2 || own.functions.contains_key(name) { return false; }
    let declared = struct_type(name);
    if library.types.contains_key(&declared) || own.types.contains_key(&declared) { return true; }
    for item in items.iter() {
        let symbol = match &item.node {
            Item::Enum { name, .. } => { let name = *name; name.to_owned() },
            Item::Struct { name, .. } => { let name = *name; name.to_owned() },
            _ => continue,
        };
        if names.resolve(symbol) == declared { return true; }
    }
    false
}


// --- check_calls.nika ---

pub fn call_arguments(signature: &Signature) -> Vec<(String, Ty)> {
    let mut out: Vec<(String, Ty)> = vec![];
    let mut first = true;
    for (name, ty) in signature.params.iter() {
        if first && name == "self" {
            first = false;
            continue;
        }
        first = false;
        out.push((name.to_owned(), ty.clone()));
    }
    out
}

pub fn expected_arguments(contract: &FnContract) -> Vec<Ty> {
    let mut out: Vec<Ty> = vec![];
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return out };
    for (_, ty) in call_arguments(signature) { out.push(ty.clone()); }
    out
}

pub fn receiver_bindings(contract: &FnContract, receiver: &Ty) -> collections::BTreeMap<String, Ty> {
    let mut bound: collections::BTreeMap<String, Ty> = collections::BTreeMap::new();
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return bound };
    if !signature.params.is_empty() && nikaia_std::index::get(&signature.params, 0).0 == "self" { bind(&nikaia_std::index::get(&signature.params, 0).1, receiver, &mut bound); }
    bound
}

pub fn argument_bindings(contract: &FnContract, found: &[Ty]) -> collections::BTreeMap<String, Ty> {
    let mut bound: collections::BTreeMap<String, Ty> = collections::BTreeMap::new();
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return bound };
    let arguments = call_arguments(signature);
    let mut at: i64 = 0;
    while ((at) as usize) < arguments.len() && ((at) as usize) < found.len() {
        bind(&nikaia_std::index::get(&arguments, (at) as usize).1, nikaia_std::index::get(&found, (at) as usize), &mut bound);
        at += 1;
    }
    bound
}

pub fn walks_by_value(contract: &FnContract) -> bool {
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return false };
    if signature.params.is_empty() { return false; }
    matches!(nikaia_std::index::get(&signature.params, 0).1, Ty::Seq { .. })
}

pub fn shape_through(contract: &FnContract, receiver: &Ty, found: &[Ty], result: Ty) -> Ty {
    let (item, is_sync, pauses, can_throw, parallel, written) = match result {
        Ty::Seq { ref item, is_sync, pauses, can_throw, parallel, shape } => { let item = nikaia_std::boxed::open(item); (item.clone(), is_sync, pauses, can_throw, parallel, shape.clone()) },
        _ => return result,
    };
    let mut ends = true;
    let mut sized = true;
    if contract.signature.is_some() {
        let signature = nikaia_std::index::or(match contract.signature.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || Signature::empty());
        if !signature.params.is_empty() && nikaia_std::index::get(&signature.params, 0).0 == "self" && a_sequence_type(&nikaia_std::index::get(&signature.params, 0).1) {
            ends = ends && shape_ends(receiver);
            sized = sized && shape_sized(receiver);
        }
        let arguments = call_arguments(&signature);
        let mut at: i64 = 0;
        while ((at) as usize) < arguments.len() && ((at) as usize) < found.len() {
            if a_sequence_type(&nikaia_std::index::get(&arguments, (at) as usize).1) {
                ends = ends && shape_ends(nikaia_std::index::get(&found, (at) as usize));
                sized = sized && shape_sized(nikaia_std::index::get(&found, (at) as usize));
            }
            at += 1;
        }
    }
    ends = ends && (!contract.ends_by_length || sized);
    Ty::Seq { item: Box::new(item), is_sync, pauses, can_throw, parallel, shape: Shape { ends: written.ends && ends, sized: written.sized && sized, replays: written.replays } }
}

fn shape_ends(ty: &Ty) -> bool {
    match ty {
        Ty::Seq { shape, .. } => shape.ends,
        _ => false,
    }
}

fn shape_sized(ty: &Ty) -> bool {
    match ty {
        Ty::Seq { shape, .. } => shape.sized,
        _ => false,
    }
}

pub fn a_paused_chain(key: &str, on: &Ty) -> bool {
    let a_step = key == "Seq::map" || key == "Seq::filter" || key == "Seq::take" || key == "Seq::skip" || key == "Seq::step_by" || key == "Seq::zip";
    a_step && match on {
        Ty::Seq { pauses, .. } => { let pauses = *pauses; pauses },
        _ => false,
    }
}

pub fn a_pausing_sequence(result: Ty, on: &Ty) -> Ty {
    let fails = match on {
        Ty::Seq { can_throw, .. } => { let can_throw = *can_throw; can_throw },
        _ => false,
    };
    match result {
        Ty::Seq { ref item, can_throw, parallel, shape, .. } => { let item = nikaia_std::boxed::open(item); Ty::Seq { item: Box::new(item.clone()), is_sync: false, pauses: true, can_throw: can_throw || fails, parallel, shape: Shape { ends: false, sized: false, replays: shape.replays } } },
        _ => result,
    }
}


// --- check_numbers.nika ---

const U64_HIGHEST: u64 = 18446744073709551615;

fn the_low_end_of(ty: &str) -> String {
    match ty {
        "i32" => String::from("-2147483648"),
        "u8" => String::from("0"),
        "u32" => String::from("0"),
        "u64" => String::from("0"),
        _ => String::from("-9223372036854775808"),
    }
}

fn the_high_end_of(ty: &str) -> String {
    match ty {
        "i32" => String::from("2147483647"),
        "u8" => String::from("255"),
        "u32" => String::from("4294967295"),
        "u64" => String::from("18446744073709551615"),
        _ => String::from("9223372036854775807"),
    }
}

pub fn a_number_that_does_not_fit(value: &Integer, beyond: bool, bare: bool, ty: &str, span: Span, why: Option<String>) -> Option<Finding> {
    if ty != "i32" && ty != "i64" && ty != "u8" && ty != "u32" && ty != "u64" { return None; }
    if !beyond && integer_fits(value, ty) { return None; }
    let article = an_or_a(ty);
    let written = integer_text(value);
    let mut comes_to = written.to_owned();
    if beyond && value.negative { comes_to = format!("less than -{}", U64_HIGHEST); } else if beyond { comes_to = format!("more than {}", U64_HIGHEST); }
    let mut message = format!("This comes to {}, which doesn't fit in {} `{}`.", comes_to, article, ty);
    if bare { message = format!("`{}` doesn't fit in {} `{}`.", written, article, ty); }
    let low = the_low_end_of(ty);
    let high = the_high_end_of(ty);
    let mut notes: Vec<String> = vec![format!("{} `{}` holds {} to {}.", article, ty, low, high)];
    if why.is_some() { notes.push(nikaia_std::index::or(why, || "".into())); }
    let help: String = match ty {
        "i32" => String::from("Use `i64` where the number needs more room."),
        "u8" => String::from("A `u8` is one byte. Use `i32` or `i64` where the number is a count rather than a byte."),
        "u32" => String::from("Use `u64` where the number needs more room."),
        "u64" => String::from("A `u64` is the widest number Nikaia has, so the computation has to stay inside it."),
        _ => if !beyond && !value.negative && value.magnitude > 0u64 { String::from("A number this big only fits a `u64`. Write the type: `let x: u64 = …`.") } else { String::from("An `i64` is the widest signed number Nikaia has, so the computation has to stay inside it.") },
    };
    Some(refusal("NK1116", span, message, notes, help))
}


// --- check_types.nika ---

pub fn a_number_name(name: &str) -> bool { name == "i8" || name == "i16" || name == "i32" || name == "i64" || name == "isize" || name == "u8" || name == "u16" || name == "u32" || name == "u64" || name == "usize" || name == "f32" || name == "f64" }

fn type_last_segment(name: &str) -> String {
    let parts: Vec<&str> = name.split("::").collect::<Vec<_>>();
    (*nikaia_std::index::get(&parts, nikaia_std::index::at(parts.len() as i64 - 1))).to_owned()
}

pub fn view_of_type(inner: &Ty) -> Ty {
    match inner {
        Ty::Named { name, args, view } => { let view = *view; if view { inner.clone() } else if args.is_empty() && name == "String" { Ty::Named { name: String::from("str"), args: vec![], view: true } } else { Ty::Named { name: name.to_owned(), args: args.to_owned(), view: true } } },
        Ty::Nullable(held) => { let held = nikaia_std::boxed::open(held); Ty::Nullable(Box::new(view_of_type(held))) },
        _ => Ty::Unknown,
    }
}

pub fn viewed_from_type(view: &Ty) -> Vec<Ty> {
    match view {
        Ty::Named { name, args, view } => { let view = *view; if !view { vec![] } else if args.is_empty() && name == "str" { vec![Ty::Named { name: String::from("String"), args: vec![], view: false }] } else { vec![Ty::Named { name: name.to_owned(), args: args.to_owned(), view: false }] } },
        _ => vec![],
    }
}

pub fn unviewed_type(ty: &Ty) -> Ty {
    match ty {
        Ty::Named { name, args, .. } => Ty::Named { name: name.to_owned(), args: args.to_owned(), view: false },
        _ => ty.clone(),
    }
}

pub fn copies_as_a_view(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; view && args.is_empty() && (a_number_name(name) || name == "bool" || name == "char") },
        _ => false,
    }
}

pub fn value_of_a_copy(ty: &Ty) -> Ty {
    if copies_as_a_view(ty) { return unviewed_type(ty); }
    ty.clone()
}

pub fn is_a_view_of_a_string(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; view && args.is_empty() && type_last_segment(name) == "String" },
        _ => false,
    }
}

pub fn a_copy_by_value(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; !view && args.is_empty() && (a_number_name(name) || name == "bool" || name == "char") },
        _ => false,
    }
}

pub fn moves_away(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; if name == ARRAY { any_moves_away(args) } else { !view && !a_number_name(name) && name != "bool" && name != "char" && name != "Shared" && name != "SharedMut" } },
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); moves_away(inner) },
        Ty::Tuple(parts) => any_moves_away(parts),
        _ => false,
    }
}

fn any_moves_away(types: &[Ty]) -> bool {
    for ty in types.iter() { if moves_away(ty) { return true; } }
    false
}

pub fn copies_plainly(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; if name == ARRAY { all_copy(args) } else { view || name == "i32" || name == "i64" || name == "u8" || name == "u32" || name == "u64" || name == "f64" || name == "bool" || name == "char" } },
        _ => false,
    }
}

fn all_copy(types: &[Ty]) -> bool {
    for ty in types.iter() { if !copies_plainly(ty) { return false; } }
    true
}

pub fn holds_an_array(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, .. } => name == ARRAY || any_holds_an_array(args),
        Ty::Tuple(parts) => any_holds_an_array(parts),
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); holds_an_array(inner) },
        _ => false,
    }
}

fn any_holds_an_array(types: &[Ty]) -> bool {
    for ty in types.iter() { if holds_an_array(ty) { return true; } }
    false
}

pub fn is_a_list_type(ty: &Ty) -> bool {
    match ty.unseen() {
        Ty::Named { ref name, .. } => name == "Vec" || name == "List" || name == "Array",
        _ => false,
    }
}

pub fn is_a_collection_type(ty: &Ty) -> bool {
    if is_a_list_type(ty) { return true; }
    match ty.unseen() {
        Ty::Named { ref name, .. } => {
            let last = type_last_segment(name);
            last == "HashMap" || last == "HashSet" || last == "BTreeMap" || last == "BTreeSet" || last == "TrustedMap" || last == "TrustedSet"
        },
        _ => false,
    }
}

pub fn is_text_type(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, .. } => args.is_empty() && (name == "String" || name == "str"),
        _ => false,
    }
}

pub fn is_a_hull(name: &str) -> bool { name == "Shared" || name == "SharedMut" || name == "Locked" }

pub fn locked_content_of(ty: &Ty) -> Option<Ty> {
    match ty {
        Ty::Named { name, args, .. } => if (name == "SharedMut" || name == "Locked") && !args.is_empty() { Some((*nikaia_std::index::get(&args, 0)).clone()) } else { None },
        _ => None,
    }
}

pub fn is_a_handle(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, view, .. } => { let view = *view; !view && (name == "Shared" || name == "SharedMut") },
        _ => false,
    }
}

pub fn locked_content(ty: &Ty) -> Ty {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; if name == "Locked" && !view && args.len() == 1 { (*nikaia_std::index::get(&args, 0)).clone() } else { ty.clone() } },
        _ => ty.clone(),
    }
}

pub fn becomes_shared(found: &Ty, want: &Ty) -> bool {
    match want {
        Ty::Named { name, args, view } => {
            let view = *view;
            if !is_a_hull(name) || view || args.len() != 1 || found.is_unknown() { false } else { found.fits(nikaia_std::index::get(&args, 0)) || found.fits(&locked_content(nikaia_std::index::get(&args, 0))) }
        },
        _ => false,
    }
}

pub fn way_out_of_a_mismatch(found: &Ty, want: &Ty) -> String {
    if becomes_shared(found, want) {
        let hull = match want {
            Ty::Named { name, .. } => name.to_owned(),
            _ => String::from(""),
        };
        return format!("Wrap it: `{}(…)`.", hull);
    }
    let element = part_of_a_list(found, want);
    if element.is_some() {
        let written = nikaia_std::index::or(element, || "?".into());
        return format!("This is part of a list. Declare the parameter `ref Array[{}]` to take a part or a whole list alike.", written);
    }
    let found_text = found.text();
    let want_text = want.text();
    if found_text == "ref String" && want_text == "String" { return String::from("Write `.clone()` to turn this view into text of its own."); }
    if found_text == "String" && want_text == "ref String" { return String::from("Write `ref` in front of it to pass a view of it."); }
    if a_number_name(&found_text) && a_number_name(&want_text) { return format!("Convert it with `as {}`. A number goes into another type on its own only where every value it can hold fits.", want_text); }
    let article = if want_text.starts_with("i") || want_text.starts_with("a") || want_text.starts_with("e") || want_text.starts_with("o") || want_text.starts_with("I") || want_text.starts_with("A") || want_text.starts_with("E") || want_text.starts_with("O") { "an" } else { "a" };
    format!("Make it {} `{}`, or change the declaration to `{}`.", article, want_text, found_text)
}

fn part_of_a_list(found: &Ty, want: &Ty) -> Option<String> {
    let run = match found {
        Ty::Named { name, args, view } => { let view = *view; view && name == ARRAY && args.len() == 1 },
        _ => false,
    };
    if !run { return None; }
    let (name, args) = match want {
        Ty::Named { name, args, .. } => (name, args),
        _ => return None,
    };
    if type_last_segment(name) != "Vec" { return None; }
    if args.is_empty() { return Some(String::from("?")); }
    Some((*nikaia_std::index::get(&args, 0)).text())
}

pub fn element_walked(over: &Ty, bindings: i64) -> Ty {
    if bindings != 1 { return Ty::Unknown; }
    match over {
        Ty::Named { name, args, view } => {
            let view = *view;
            let last = type_last_segment(name);
            if args.len() == 1 { if last == "Vec" || last == "List" || last == "BTreeSet" || last == "HashSet" { (*nikaia_std::index::get(&args, 0)).clone() } else { Ty::Unknown } } else if !args.is_empty() && !view && name == ARRAY { (*nikaia_std::index::get(&args, 0)).clone() } else { Ty::Unknown }
        },
        Ty::Pointed { item, slice, mutable } => { let item = nikaia_std::boxed::open(item); let mutable = *mutable; let slice = *slice; if slice && !mutable { item.clone() } else { Ty::Unknown } },
        Ty::Seq { item, .. } => { let item = nikaia_std::boxed::open(item); item.clone() },
        _ => Ty::Unknown,
    }
}

pub fn elements_walked(over: &Ty, bindings: i64) -> Vec<Ty> {
    if bindings == 1 { return vec![element_walked(over, 1)]; }
    let parts = parts_walked(over, bindings);
    if (parts.len() as i64) == bindings { return parts; }
    let mut unknown: Vec<Ty> = vec![];
    for _ in 0..bindings { unknown.push(Ty::Unknown); }
    unknown
}

fn parts_walked(over: &Ty, bindings: i64) -> Vec<Ty> {
    match over {
        Ty::Named { name, args, .. } => {
            let last = type_last_segment(name);
            if (last == "HashMap" || last == "Map" || last == "BTreeMap" || last == "TrustedMap") && args.len() == 2 && bindings == 2 { vec![(*nikaia_std::index::get(&args, 0)).clone(), (*nikaia_std::index::get(&args, 1)).clone()] } else if (last == "Vec" || last == "List" || last == "BTreeSet" || last == "HashSet") && args.len() == 1 || name == ARRAY && !args.is_empty() { tuple_parts(nikaia_std::index::get(&args, 0)) } else { vec![] }
        },
        Ty::Seq { item, .. } => { let item = nikaia_std::boxed::open(item); tuple_parts(item) },
        _ => vec![],
    }
}

fn tuple_parts(ty: &Ty) -> Vec<Ty> {
    match ty {
        Ty::Tuple(parts) => parts.to_owned(),
        _ => vec![],
    }
}


// --- check_words.nika ---

pub fn reserved_elsewhere(name: &str) -> Option<String> {
    if name == "loop" { return Some(String::from("Nikaia has no `loop` keyword. Write `while true { … }`. (`loop` is an ordinary name, so `let loop = 3` is fine.)")); }
    if name == "const" { return Some(String::from("A value computed while the program is built is written `comptime X = …`. (`const` is an ordinary name in Nikaia.)")); }
    if name == "macro" || name == "quote" { return Some(String::from("Nikaia has no macros. To generate code from a type's shape, use `comptime` and a bound; to turn text into a program, use a grammar. (Both words are ordinary names.)")); }
    None
}

pub fn nearest_name(name: &str, among: &[String]) -> Option<String> {
    let mut best: Option<String> = None;
    let mut best_distance: i64 = -1;
    let mut longest = name.len() as i64;
    if longest < 1 { longest = 1; }
    for candidate in among.iter() {
        let d = distance(name, candidate);
        if d * 3 > longest { continue; }
        if best_distance < 0 || d < best_distance {
            best = Some(candidate.to_owned());
            best_distance = d;
        }
    }
    best
}

pub fn with_article(what: &str) -> String {
    for c in what.chars() {
        if !c.is_alphanumeric() { continue; }
        let lower = c.to_ascii_lowercase();
        if lower == 'a' || lower == 'e' || lower == 'i' || lower == 'o' || lower == 'u' { return format!("an {}", what); }
        return format!("a {}", what);
    }
    format!("a {}", what)
}

pub fn counted(n: i64, what: &str) -> String {
    if n == 1 { return format!("1 {}", what); }
    format!("{} {}s", n, what)
}

pub fn names_listed(names: &[String]) -> String {
    if names.is_empty() { return String::from("no fields"); }
    if names.len() == 1 { return format!("`{}`", *nikaia_std::index::get(&names, 0)); }
    let mut rest: Vec<String> = vec![];
    for k in 0..names.len() as i64 - 1 { rest.push(format!("`{}`", *nikaia_std::index::get(&names, (k) as usize))); }
    format!("{} and `{}`", rest.join(", "), *nikaia_std::index::get(&names, nikaia_std::index::at(names.len() as i64 - 1)))
}

pub fn indented_text(text: &str) -> String {
    let mut lines: Vec<String> = vec![];
    for line in text.trim_end().lines() { lines.push(format!("       {}", line)); }
    lines.join("\n")
}

pub fn brace_groups(text: &str) -> Vec<String> {
    let c: Vec<char> = nikaia_std::list::chars(text.chars());
    let mut found: Vec<String> = vec![];
    let mut at: i64 = 0;
    while ((at) as usize) < c.len() {
        if *nikaia_std::index::get(&c, (at) as usize) == '\\' {
            at += 1;
            if ((at) as usize) < c.len() && *nikaia_std::index::get(&c, (at) as usize) == 'u' && ((at + 1) as usize) < c.len() && *nikaia_std::index::get(&c, (at + 1) as usize) == '{' {
                at += 1;
                while ((at) as usize) < c.len() && *nikaia_std::index::get(&c, (at) as usize) != '}' { at += 1; }
            }
            at += 1;
            continue;
        }
        if *nikaia_std::index::get(&c, (at) as usize) == '{' {
            let mut group: String = String::from("");
            at += 1;
            let mut closed = false;
            while ((at) as usize) < c.len() {
                if *nikaia_std::index::get(&c, (at) as usize) == '}' {
                    closed = true;
                    break;
                }
                group.push(*nikaia_std::index::get(&c, (at) as usize));
                at += 1;
            }
            if closed && !group.trim().is_empty() { found.push(group); }
        }
        at += 1;
    }
    found
}

pub fn not_promised_note(callee: &str) -> String {
    let parts: Vec<&str> = callee.splitn(2, "::").collect::<Vec<_>>();
    let mut package: String = String::from("its package");
    let mut function = callee.to_owned();
    if parts.len() == 2 {
        package = (*nikaia_std::index::get(&parts, 0)).to_owned();
        function = (*nikaia_std::index::get(&parts, 1)).to_owned();
    }
    format!("`{}` is `{}`'s, and its source doesn't say `sync`. That its body doesn't pause today is not a promise another package can rely on: write `sync` after the result of `{}` in `{}` to make it.", callee, package, function, package)
}

pub fn is_a_lookup(key: &str) -> bool {
    let mut bare = key.to_owned();
    if key.starts_with("collections::") {
        let parts: Vec<&str> = key.splitn(2, "::").collect::<Vec<_>>();
        bare = (*nikaia_std::index::get(&parts, 1)).to_owned();
    }
    bare == "HashMap::get" || bare == "HashMap::contains_key" || bare == "HashSet::contains" || bare == "HashSet::remove" || bare == "HashMap::remove" || bare == "BTreeMap::remove" || bare == "BTreeSet::remove" || bare == "BTreeMap::get" || bare == "BTreeMap::contains_key" || bare == "BTreeSet::contains" || bare == "Vec::contains" || bare == "Array::contains"
}

pub fn boxed_member(owner: &str, at: i64, field: &str) -> String {
    if at >= 0 { return format!("{}#{}", owner, at); }
    if !field.is_empty() { return format!("{}.{}", owner, field); }
    owner.to_owned()
}


// --- claim_names.nika ---

pub fn claim_names_in(expr: &Expr, words: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>) -> collections::BTreeSet<String> {
    let mut names: collections::BTreeSet<String> = collections::BTreeSet::new();
    collect_names(expr, words, holes_of, &mut names);
    names
}

pub fn is_a_parameter(name: &str, params: &collections::BTreeSet<String>) -> bool {
    if params.contains(name) { return true; }
    if !name.ends_with(".len()") { return false; }
    let c: Vec<char> = nikaia_std::list::chars(name.chars());
    let mut base: String = String::from("");
    for k in 0..c.len() as i64 - 6 { base.push(*nikaia_std::index::get(&c, (k) as usize)); }
    params.contains(&base)
}

fn collect_names(expr: &Expr, words: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, names: &mut collections::BTreeSet<String>) {
    match expr {
        Expr::Variable(name) => {
            let name = *name;
            names.insert(words.resolve(name).to_owned());
        },
        _ => { },
    }
    for hole in holes_of(expr) { collect_names(&hole, words, holes_of, names); }
    match expr {
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            collect_names(func, words, holes_of, names);
            each_name(args, words, holes_of, names);
            for c in config.iter() { collect_names(&c.value, words, holes_of, names); }
        },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            collect_names(receiver, words, holes_of, names);
            each_name(args, words, holes_of, names);
            for c in config.iter() { collect_names(&c.value, words, holes_of, names); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            collect_names(receiver, words, holes_of, names);
            each_name(args, words, holes_of, names);
            for c in config.iter() { collect_names(&c.value, words, holes_of, names); }
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            collect_names(lhs, words, holes_of, names);
            collect_names(rhs, words, holes_of, names);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); collect_names(expr, words, holes_of, names) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); collect_names(inner, words, holes_of, names) },
        Expr::Throw(inner) => { let inner = nikaia_std::boxed::open(inner); collect_names(inner, words, holes_of, names) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); collect_names(expr, words, holes_of, names) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); collect_names(base, words, holes_of, names) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); collect_names(base, words, holes_of, names) },
        Expr::Index { base, index } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            collect_names(base, words, holes_of, names);
            collect_names(index, words, holes_of, names);
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            collect_names(start, words, holes_of, names);
            collect_names(end, words, holes_of, names);
        },
        Expr::Tuple(parts) => each_name(parts, words, holes_of, names),
        Expr::Coalesce { value, fallback } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            collect_names(value, words, holes_of, names);
            collect_names(fallback, words, holes_of, names);
        },
        Expr::TryCatch { expr, .. } => { let expr = nikaia_std::boxed::open(expr); collect_names(expr, words, holes_of, names) },
        Expr::If { cond, .. } => { let cond = nikaia_std::boxed::open(cond); collect_names(cond, words, holes_of, names) },
        Expr::Match { value, arms } => {
            let value = nikaia_std::boxed::open(value);
            collect_names(value, words, holes_of, names);
            for arm in arms.iter() {
                collect_maybe((arm.guard).as_ref(), words, holes_of, names);
                collect_names(&arm.body, words, holes_of, names);
            }
        },
        Expr::StructLit { fields, .. } => { for field in fields.iter() { collect_maybe((field.value).as_ref(), words, holes_of, names); } },
        Expr::ListLit { items, .. } => each_name(items, words, holes_of, names),
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            collect_names(base, words, holes_of, names);
            for field in fields.iter() { collect_maybe((field.value).as_ref(), words, holes_of, names); }
        },
        Expr::Return(value) => { let value = nikaia_std::boxed::open(value); collect_maybe((value).as_ref(), words, holes_of, names) },
        Expr::Select(arms) => { for arm in arms.iter() { collect_names(&arm.value, words, holes_of, names); } },
        _ => { },
    }
}

fn collect_maybe(expr: Option<&Expr>, words: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, names: &mut collections::BTreeSet<String>) {
    let present = match expr { Some(__nikaia_value) => __nikaia_value, None => return };
    collect_names(present, words, holes_of, names);
}

fn each_name(exprs: &[Expr], words: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, names: &mut collections::BTreeSet<String>) { for e in exprs.iter() { collect_names(e, words, holes_of, names); } }


// --- contract_changes.nika ---

pub fn changed_contracts(now: &Ledger, committed: &Ledger, mine: &impl Fn(&str) -> bool, implies: &impl Fn(&[String], &[String], &collections::BTreeSet<String>) -> bool) -> String {
    let mut out: String = String::from("");
    for (key, new) in now.functions.iter() {
        let old = match committed.functions.get(key) { Some(__nikaia_value) => __nikaia_value, None => continue };
        if !new.public || !mine(key) { continue; }
        let names = condition_names(new);
        if !implies(&old.requires, &new.requires, &names) { out.push_str(&format!("warning[NK1208]: `{}` asks more of its callers than the committed ledger says.\n   = note: it required {}, and now requires {}.\n   = note: a caller that showed what it required before may now stop where it is checked.\n   = help: if that is meant, commit `nikaia.contracts`, and this is not said again.\n", key, conditions_said(&old.requires), conditions_said(&new.requires))); }
        if !implies(&new.ensures, &old.ensures, &names) { out.push_str(&format!("warning[NK1208]: `{}` promises less than the committed ledger says.\n   = note: it ensured {}, and now ensures {}.\n   = note: a caller's proof that relied on what it ensured may no longer hold.\n   = help: if that is meant, commit `nikaia.contracts`, and this is not said again.\n", key, conditions_said(&old.ensures), conditions_said(&new.ensures))); }
    }
    out
}

fn condition_names(contract: &FnContract) -> collections::BTreeSet<String> {
    let mut names: collections::BTreeSet<String> = collections::BTreeSet::new();
    names.insert(String::from("result"));
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return names };
    for (name, ty) in signature.params.iter() {
        if has_a_length(&type_name_of(ty)) { names.insert(format!("{}.len()", name)); }
        names.insert(name.to_owned());
    }
    names
}

fn type_name_of(ty: &Ty) -> String {
    match ty {
        Ty::Named { name, .. } => name.to_owned(),
        _ => String::from(""),
    }
}

fn conditions_said(list: &[String]) -> String {
    if list.is_empty() { return String::from("nothing"); }
    let mut said: Vec<String> = vec![];
    for condition in list.iter() { said.push(format!("`{}`", condition)); }
    said.join(" and ")
}


// --- crossing.nika ---

const NOT_SENDABLE: [&str; 5] = ["Rc<", "rc::Rc<", "*const ", "*mut ", "NonNull<"];

const PASSES_THROUGH: [&str; 4] = ["Vec", "Option", "Box", "VecDeque"];

const PLAIN: [&str; 18] = ["bool", "char", "str", "i8", "i16", "i32", "i64", "i128", "isize", "u8", "u16", "u32", "u64", "u128", "usize", "f32", "f64", "()"];

const THREAD_SINKS: [&str; 15] = ["std::thread::spawn", "std::thread::Builder::spawn", "std::thread::scope", "thread::spawn", "thread::scope", "tokio::spawn", "tokio::task::spawn", "tokio::task::spawn_blocking", "tokio::task::spawn_local", "task::spawn_blocking", "rayon::spawn", "rayon::scope", "rayon::join", "async_std::task::spawn", "smol::spawn"];

pub fn crosses(fields: &[String]) -> Crosses {
    if fields.is_empty() { return Crosses::Undecided; }
    for field in fields.iter() {
        for marker in NOT_SENDABLE.iter() {
            let marker = *marker;
            if field.contains(marker) { return Crosses::MayNot; }
        }
    }
    for field in fields.iter() { if !plainly_sendable(field) { return Crosses::Undecided; } }
    Crosses::May
}

pub fn plainly_sendable(written: &str) -> bool {
    let ty = written.trim();
    if ty.starts_with("&") { return false; }
    for wrapper in PASSES_THROUGH.iter() {
        let wrapper = *wrapper;
        let inner = generic_of(ty, wrapper);
        if inner.is_some() {
            for part in split_top_level(nikaia_std::index::or(inner.as_deref(), || "")) { if !plainly_sendable(&part) { return false; } }
            return true;
        }
    }
    is_plain(ty) || ty == "String"
}

pub fn is_plain(name: &str) -> bool {
    for plain in PLAIN.iter() {
        let plain = *plain;
        if name == plain { return true; }
    }
    false
}

pub fn generic_of(written: &str, name: &str) -> Option<String> {
    let text = written.trim();
    if !text.starts_with(name) { return None; }
    let c: Vec<char> = nikaia_std::list::chars(text.chars());
    let n: Vec<char> = nikaia_std::list::chars(name.chars());
    let after = slice(&c, n.len() as i64, c.len() as i64);
    let rest = after.trim_start();
    if !rest.starts_with("<") || !rest.ends_with(">") { return None; }
    let r: Vec<char> = nikaia_std::list::chars(rest.chars());
    Some(slice(&r, 1, r.len() as i64 - 1))
}

pub fn bounds_send(text: &str) -> bool {
    let c: Vec<char> = nikaia_std::list::chars(text.chars());
    let mut start: i64 = 0;
    for at in 0..c.len() as i64 + 1 {
        let ends = at == c.len() as i64 || !((*nikaia_std::index::get(&c, nikaia_std::index::at(at))).is_alphanumeric() || *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '_');
        if ends {
            if slice(&c, start, at) == "Send" { return true; }
            start = at + 1;
        }
    }
    false
}

pub fn a_list(names: &[String], one: &str, many: &str) -> String {
    if names.is_empty() { return String::from(""); }
    let mut word = many.to_owned();
    if names.len() == 1 { word = one.to_owned(); }
    let mut out = format!("{} ", word);
    for at in 0..names.len() as i64 {
        if at > 0 && at == names.len() as i64 - 1 { out.push_str(" and "); } else if at > 0 { out.push_str(", "); }
        let name = nikaia_std::index::get(&names, (at) as usize);
        let quoted = format!("`{}`", name);
        out.push_str(&quoted);
    }
    out
}

pub fn reaches_a_thread(from: &str, calls: &collections::BTreeMap<String, Vec<String>>) -> Option<Vec<String>> {
    let mut seen: collections::BTreeSet<String> = collections::BTreeSet::new();
    let mut queue: Vec<String> = vec![from.to_owned()];
    let mut ways: Vec<Vec<String>> = vec![vec![]];
    seen.insert(from.to_owned());
    let mut next: i64 = 0;
    while ((next) as usize) < queue.len() {
        let at = (*nikaia_std::index::get(&queue, (next) as usize)).to_owned();
        let how = (*nikaia_std::index::get(&ways, (next) as usize)).to_owned();
        next += 1;
        for call in nikaia_std::index::or(match *nikaia_std::index::get(&calls, &at) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || vec![].into()) {
            if is_a_sink(&call) {
                let mut path = how.to_owned();
                path.push(call.to_owned());
                return Some(path);
            }
            let inside = the_crates_own(&call, calls);
            if inside.is_none() { continue; }
            let own = nikaia_std::index::or(inside, || "".into());
            if seen.contains(&own) { continue; }
            seen.insert(own.to_owned());
            let mut way = how.to_owned();
            way.push(own.to_owned());
            queue.push(own);
            ways.push(way);
        }
    }
    None
}

pub fn the_crates_own(call: &str, calls: &collections::BTreeMap<String, Vec<String>>) -> Option<String> {
    if calls.contains_key(call) { return Some(call.to_owned()); }
    let ending = format!("::{}", call);
    let mut found: Option<String> = None;
    for (path, _) in calls.iter() {
        if path.ends_with(&ending) {
            if found.is_some() { return None; }
            found = Some(path.to_owned());
        }
    }
    found
}

fn is_a_sink(call: &str) -> bool {
    for sink in THREAD_SINKS.iter() {
        let sink = *sink;
        if call == sink { return true; }
    }
    false
}

pub fn promise_lines(promises: &[String]) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    if promises.is_empty() { return out; }
    out.push(String::from("**This crate makes promises the toolchain cannot check** (ADR-290 D10). A tool"));
    out.push(String::from("can see that the promise was made; it cannot see whether it is true - which is"));
    out.push(String::from("the line between a rule the toolchain enforces and one it inherits:"));
    for promise in promises.iter() { out.push(format!("  {}", promise)); }
    out
}

pub fn thread_lines(name: &str, bound: &[String], way: Option<Vec<String>>) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    if !bound.is_empty() {
        let listed = a_list(bound, "the parameter", "the parameters");
        out.push(format!("`{}`: {} is bound `Send`.", name, listed));
        out.push(String::from("  Seen and not claimed (ADR-290 D8): a `Send` bound says the callee **may**"));
        out.push(String::from("  send it, which is usually `spawn` and is sometimes an API keeping a door open."));
    }
    if way.is_some() {
        let steps = nikaia_std::index::or(way, || vec![].into());
        let sink = nikaia_std::index::get(&steps, nikaia_std::index::at(steps.len() as i64 - 1));
        if steps.len() == 1 { out.push(format!("`{}`: calls `{}`.", name, sink)); } else {
            let mut through: String = String::from("");
            for at in 0..steps.len() as i64 - 1 {
                if at > 0 { through.push_str(" -> "); }
                let step = nikaia_std::index::get(&steps, (at) as usize);
                let quoted = format!("`{}`", step);
                through.push_str(&quoted);
            }
            out.push(format!("`{}`: reaches `{}` through {}.", name, sink, through));
        }
        out.push(String::from("  A sink reached through a call says *this function threads something*,"));
        out.push(String::from("  never *this function threads your argument* (ADR-290 D9) - connecting"));
        out.push(String::from("  those is dataflow through a closure capture and is not built."));
    }
    if out.is_empty() { return out; }
    out.push(String::from("  Does this put it on a thread?  -> threads = true | false"));
    out
}

pub fn type_entry(fields: &[String], derives: &collections::BTreeSet<String>) -> TypeContract {
    let mut entry = TypeContract::empty();
    entry.public = true;
    entry.crosses = crosses(fields);
    entry.compares = derives.contains("PartialEq");
    entry.copies = derives.contains("Copy");
    entry
}


// --- declared.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeclaredFn {
    pub key: String,
    pub contract: FnContract,
}

pub fn written_ty(names: &winnow_grammar::InternerContext, aliases: &collections::BTreeMap<String, String>, ty: &Type) -> Ty {
    let count = nikaia_std::index::or(ty.count, || -1);
    if ty.count.is_some() { return Ty::Count(count); }
    if ty.is_view && !ty.is_slice && names.resolve(ty.name) == ARRAY && ty.generics.len() == 1 {
        let item = written_ty(names, aliases, nikaia_std::index::get(&ty.generics, 0));
        if ty.is_nullable { return Ty::Pointed { item: Box::new(Ty::Nullable(Box::new(item))), slice: true, mutable: ty.is_mut }; }
        return Ty::Pointed { item: Box::new(item), slice: true, mutable: ty.is_mut };
    }
    if ty.is_slice || ty.is_mut {
        let item = lent_item(names, aliases, ty);
        if ty.is_nullable { return Ty::Pointed { item: Box::new(Ty::Nullable(Box::new(item))), slice: ty.is_slice, mutable: ty.is_mut }; }
        return Ty::Pointed { item: Box::new(item), slice: ty.is_slice, mutable: ty.is_mut };
    }
    if ty.is_tuple { return Ty::Tuple(written_all(names, aliases, &ty.generics)); }
    if (*ty.code).is_some() {
        let code = match (*ty.code).as_ref() { Some(__nikaia_value) => __nikaia_value, None => return Ty::Unknown };
        let params = written_all(names, aliases, &ty.generics);
        let result = match (*code.result).as_ref() { Some(__nikaia_value) => __nikaia_value, None => return Ty::Fn { params, result: Box::new(None), is_sync: code.is_sync, can_throw: code.can_throw } };
        return Ty::Fn { params, result: Box::new(Some(written_ty(names, aliases, result))), is_sync: code.is_sync, can_throw: code.can_throw };
    }
    if ty.is_nullable {
        let mut inner = ty.clone();
        inner.is_nullable = false;
        return Ty::Nullable(Box::new(written_ty(names, aliases, &inner)));
    }
    let name = unaliased_in(aliases, names.resolve(ty.name));
    if ty.either { return Ty::Named { name: TEXT.to_owned(), args: vec![], view: false }; }
    if ty.is_view && name == TEXT { return Ty::Named { name: TEXT_VIEW.to_owned(), args: written_all(names, aliases, &ty.generics), view: true }; }
    Ty::Named { name, args: written_all(names, aliases, &ty.generics), view: ty.is_view }
}

fn lent_item(names: &winnow_grammar::InternerContext, aliases: &collections::BTreeMap<String, String>, ty: &Type) -> Ty {
    if !ty.generics.is_empty() { return written_ty(names, aliases, nikaia_std::index::get(&ty.generics, 0)); }
    Ty::Named { name: unaliased_in(aliases, names.resolve(ty.name)), args: vec![], view: false }
}

fn written_all(names: &winnow_grammar::InternerContext, aliases: &collections::BTreeMap<String, String>, types: &[Type]) -> Vec<Ty> {
    let mut out: Vec<Ty> = vec![];
    for ty in types.iter() { out.push(written_ty(names, aliases, ty)); }
    out
}

pub fn declared_function(names: &winnow_grammar::InternerContext, aliases: &collections::BTreeMap<String, String>, item: &Item, target: &Option<String>, outer: &collections::BTreeSet<String>) -> Option<DeclaredFn> {
    let (name, generics, receiver, args, config, ret_type, is_sync, sync_by, is_public, can_throw) = match item {
        Item::Fn { name, generics, receiver, args, config, ret_type, is_sync, sync_by, is_public, can_throw, .. } => { let can_throw = *can_throw; let is_public = *is_public; let is_sync = *is_sync; let name = *name; (name, generics, receiver, args, config, ret_type, is_sync, sync_by, is_public, can_throw) },
        _ => return None,
    };
    let mut parameters = outer.to_owned();
    for generic in generics.iter() { parameters.insert(names.resolve(generic.name).to_owned()); }
    let mut own: String = String::from("new");
    if name.is_some() {
        let symbol = match name { Some(__nikaia_value) => __nikaia_value, None => return None };
        own = names.resolve(symbol).to_owned();
    }
    let mut key = own.to_owned();
    if target.is_some() {
        let owner = nikaia_std::index::or(match target.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || "".into());
        key = format!("{}::{}", owner, own);
    }
    let mut borrows: Vec<String> = vec![];
    let returns_view = match item {
        Item::Fn { ret_type, .. } => returns_a_view((ret_type).as_ref()),
        _ => false,
    };
    if returns_view {
        if receiver.is_some() {
            let subject = match receiver { Some(__nikaia_value) => __nikaia_value, None => return None };
            if subject.is_ref { borrows.push(String::from("self")); }
        }
        for arg in args.iter() { if holds_view(&arg.ty) { borrows.push(names.resolve(arg.name).to_owned()); } }
    }
    let mut params: Vec<(String, Ty)> = vec![];
    let mut mutates = false;
    if receiver.is_some() {
        let subject = match receiver { Some(__nikaia_value) => __nikaia_value, None => return None };
        let owner = nikaia_std::index::or(match target.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || "Self".into());
        let self_name: String = String::from("self");
        params.push((self_name, Ty::Named { name: owner, args: vec![], view: subject.is_ref }));
        mutates = subject.is_mut && subject.is_ref;
    }
    let mut mutable: Vec<String> = vec![];
    for arg in args.iter() {
        let arg_name = names.resolve(arg.name).to_owned();
        params.push((arg_name.to_owned(), written_ty(names, aliases, &arg.ty).parameterise(&parameters)));
        if arg.mutable { mutable.push(arg_name); }
    }
    let mut bounds: Vec<(String, Vec<String>)> = vec![];
    for generic in generics.iter() {
        if generic.bounds.is_empty() { continue; }
        let mut written: Vec<String> = vec![];
        for bound in generic.bounds.iter() { written.push(names.resolve(*bound).to_owned()); }
        bounds.push((names.resolve(generic.name).to_owned(), written));
    }
    let mut options: Vec<ConfigContract> = vec![];
    for option in config.iter() {
        let ty = written_ty(names, aliases, &option.ty).parameterise(&parameters);
        options.push(ConfigContract { name: names.resolve(option.name).to_owned(), ty, default: default_text(&option.default) });
    }
    let mut result: Option<Ty> = None;
    if ret_type.is_some() {
        let written = match ret_type { Some(__nikaia_value) => __nikaia_value, None => return None };
        result = Some(written_ty(names, aliases, written).parameterise(&parameters));
    }
    let mut sync_claim = Sync::No;
    if is_sync { sync_claim = Sync::Asserted; } else if !sync_by.is_empty() {
        let mut lambdas: Vec<String> = vec![];
        for lambda in sync_by.iter() { lambdas.push(names.resolve(*lambda).to_owned()); }
        sync_claim = Sync::From(lambdas.join(", "));
    }
    let mut fails_with: Vec<String> = vec![];
    if can_throw { fails_with.push(String::from("?")); }
    let signature = Signature { bounds, params, mutable, config: options, result };
    let mut contract = FnContract::empty();
    contract.public = is_public;
    contract.sync_claim = sync_claim;
    contract.fails_with = fails_with;
    contract.signature = Some(signature);
    contract.borrows = borrows;
    contract.mutates = mutates;
    Some(DeclaredFn { key, contract })
}

fn returns_a_view(ret_type: Option<&Type>) -> bool {
    let written = match ret_type { Some(__nikaia_value) => __nikaia_value, None => return false };
    holds_view(written)
}

pub fn default_text(expr: &Expr) -> String {
    match expr {
        Expr::LitBool(value) => { let value = *value; if value { String::from("true") } else { String::from("false") } },
        Expr::LitNull => String::from("None"),
        Expr::LitInt { value, negative } => { let negative = *negative; let value = *value; if negative { format!("-{}", value) } else { format!("{}", value) } },
        Expr::LitFloat(written) => written.to_owned(),
        Expr::LitChar(written) => format!("'{}'", written),
        Expr::LitStr { text, .. } => format!("\"{}\"", text),
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); format!("-{}", default_text(expr)) },
        _ => String::from(""),
    }
}

pub fn declared_trait_method(names: &winnow_grammar::InternerContext, aliases: &collections::BTreeMap<String, String>, trait_name: &str, method: &TraitMethod, public: bool) -> DeclaredFn {
    let mut params: Vec<(String, Ty)> = vec![];
    if method.receiver.is_some() {
        let subject = nikaia_std::index::or(match method.receiver.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || Receiver { is_ref: false, is_mut: false });
        let owner = trait_name.to_owned();
        let self_name: String = String::from("self");
        params.push((self_name, Ty::Named { name: owner, args: vec![], view: subject.is_ref }));
    }
    let mut mutable: Vec<String> = vec![];
    for arg in method.args.iter() {
        let arg_name = names.resolve(arg.name).to_owned();
        params.push((arg_name.to_owned(), written_ty(names, aliases, &arg.ty)));
        if arg.mutable { mutable.push(arg_name); }
    }
    let mut options: Vec<ConfigContract> = vec![];
    for option in method.config.iter() { options.push(ConfigContract { name: names.resolve(option.name).to_owned(), ty: written_ty(names, aliases, &option.ty), default: default_text(&option.default) }); }
    let result = optional_ty(names, aliases, (method.ret_type).as_ref());
    let mut contract = FnContract::empty();
    contract.public = public;
    if method.is_sync { contract.sync_claim = Sync::Asserted; }
    if method.can_throw { contract.fails_with = vec![String::from("?")]; }
    contract.signature = Some(Signature { bounds: vec![], params, mutable, config: options, result });
    DeclaredFn { key: format!("{}::{}", trait_name, names.resolve(method.name)), contract }
}

fn optional_ty(names: &winnow_grammar::InternerContext, aliases: &collections::BTreeMap<String, String>, ty: Option<&Type>) -> Option<Ty> {
    let written = match ty { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(written_ty(names, aliases, written))
}


// --- describe.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Drafted {
    pub functions: collections::BTreeMap<String, FnContract>,
    pub types: collections::BTreeMap<String, TypeContract>,
    pub unanswered: Vec<String>,
    pub notes: Notes,
}

pub fn drafted(surface: &Surface, crate_word: &str, wanted: &collections::BTreeSet<String>) -> Drafted {
    let mut functions: collections::BTreeMap<String, FnContract> = collections::BTreeMap::new();
    let mut unanswered: Vec<String> = vec![];
    let mut named_types: collections::BTreeSet<String> = collections::BTreeSet::new();
    for name in wanted.iter() {
        if !answered(surface, name) {
            unanswered.push(format!("{}::{}", crate_word, name));
            continue;
        }
        let at = match *nikaia_std::index::get(&surface.reachable, name) { Some(__nikaia_value) => __nikaia_value, None => continue };
        let function = match *nikaia_std::index::get(&surface.functions, at) { Some(__nikaia_value) => __nikaia_value, None => continue };
        functions.insert(format!("{}::{}", crate_word, name), contract_of(function, crate_word, &surface.types, &mut named_types));
    }
    for name in wanted.iter() { if surface.types.contains(name) { named_types.insert(name.to_owned()); } }
    let mut types: collections::BTreeMap<String, TypeContract> = collections::BTreeMap::new();
    let no_fields: Vec<String> = vec![];
    let no_derives: collections::BTreeSet<String> = collections::BTreeSet::new();
    for name in named_types.iter() {
        let fields = nikaia_std::index::or(*nikaia_std::index::get(&surface.fields, name), || &no_fields);
        let derives = nikaia_std::index::or(*nikaia_std::index::get(&surface.derives, name), || &no_derives);
        types.insert(format!("{}::{}", crate_word, name), type_entry(fields, derives));
    }
    Drafted { functions, types, unanswered, notes: notes_on(surface, crate_word, wanted) }
}

fn notes_on(surface: &Surface, crate_word: &str, wanted: &collections::BTreeSet<String>) -> Notes {
    let mut notes = Notes::empty();
    notes.about_the_crate = promise_lines(&surface.promises);
    let mut calls: collections::BTreeMap<String, Vec<String>> = collections::BTreeMap::new();
    for (path, function) in surface.functions.iter() { calls.insert(path.to_owned(), function.calls.to_owned()); }
    for name in wanted.iter() {
        let at = match *nikaia_std::index::get(&surface.reachable, name) { Some(__nikaia_value) => __nikaia_value, None => continue };
        let function = match *nikaia_std::index::get(&surface.functions, at) { Some(__nikaia_value) => __nikaia_value, None => continue };
        let said = thread_lines(name, &bound_parameters(function), reaches_a_thread(at, &calls));
        if !said.is_empty() { notes.about_a_function.insert(format!("{}::{}", crate_word, name), said); }
    }
    notes
}

fn answered(surface: &Surface, name: &str) -> bool {
    let at = match *nikaia_std::index::get(&surface.reachable, name) { Some(__nikaia_value) => __nikaia_value, None => return false };
    surface.functions.contains_key(at)
}

fn bound_parameters(function: &Function) -> Vec<String> {
    let mut names: Vec<String> = vec![];
    let mut types: Vec<String> = vec![];
    for arg in function.args.iter() {
        names.push(arg.name.to_owned());
        types.push(arg.ty.to_owned());
    }
    sent_across(&names, &types, &function.bounds)
}

fn contract_of(function: &Function, crate_word: &str, types: &collections::BTreeSet<String>, mentioned: &mut collections::BTreeSet<String>) -> FnContract {
    let mut names: Vec<String> = vec![];
    let mut written_types: Vec<String> = vec![];
    for arg in function.args.iter() {
        names.push(arg.name.to_owned());
        written_types.push(arg.ty.to_owned());
    }
    let written = WrittenFn { names, types: written_types, result: function.result.to_owned(), pauses: function.pauses, parameters: function.parameters.to_owned() };
    contract(&written, crate_word, types, mentioned)
}


// --- diffs.nika ---

pub fn changed_lines(ledger: &str, committed: &str) -> Vec<String> {
    let mut kept: Vec<String> = vec![];
    for line in committed.lines() { kept.push(line.to_owned()); }
    let mut out: Vec<String> = vec![];
    let mut entry: String = String::from("");
    let mut named: String = String::from("");
    for line in ledger.lines() {
        if line.starts_with("[") {
            entry = line.to_owned();
            named = String::from("");
        }
        if line.is_empty() || line.starts_with("#") || nikaia_std::list::contains(&kept, &line) { continue; }
        if !entry.is_empty() && entry != line {
            if named != entry {
                out.push(format!("  {}", entry));
                named = entry.to_owned();
            }
            out.push(format!("      {}", line));
        } else {
            out.push(format!("  {}", line));
            named = entry.to_owned();
        }
    }
    out
}

pub fn differing_lines(expected: &str, produced: &str) -> String {
    let mut a: Vec<String> = vec![];
    for line in expected.lines() { a.push(line.to_owned()); }
    let mut b: Vec<String> = vec![];
    for line in produced.lines() { b.push(line.to_owned()); }
    if same_lines(&a, &b) { return String::from("  the same lines; they differ in the line break at the end\n"); }
    if (a.len() as i64 + 1) * (b.len() as i64 + 1) > 4000000 { return format!("  expected:\n{}\n  produced:\n{}\n", expected, produced); }
    let mut common: Vec<Vec<i64>> = vec![];
    for _i in 0..a.len() as i64 + 1 {
        let mut row: Vec<i64> = vec![];
        for _j in 0..b.len() as i64 + 1 { row.push(0); }
        common.push(row);
    }
    let mut i = a.len() as i64 - 1;
    while i >= 0 {
        let mut j = b.len() as i64 - 1;
        while j >= 0 {
            if *nikaia_std::index::get(&a, nikaia_std::index::at(i)) == *nikaia_std::index::get(&b, nikaia_std::index::at(j)) { { let __nikaia_stored = *nikaia_std::index::get(nikaia_std::index::get(&common, nikaia_std::index::at(i + 1)), nikaia_std::index::at(j + 1)) + 1; nikaia_std::index::set(&mut common[nikaia_std::index::at(i)], nikaia_std::index::at(j), __nikaia_stored); } } else if *nikaia_std::index::get(nikaia_std::index::get(&common, nikaia_std::index::at(i + 1)), nikaia_std::index::at(j)) >= *nikaia_std::index::get(nikaia_std::index::get(&common, nikaia_std::index::at(i)), nikaia_std::index::at(j + 1)) { { let __nikaia_stored = *nikaia_std::index::get(nikaia_std::index::get(&common, nikaia_std::index::at(i + 1)), nikaia_std::index::at(j)); nikaia_std::index::set(&mut common[nikaia_std::index::at(i)], nikaia_std::index::at(j), __nikaia_stored); } } else { { let __nikaia_stored = *nikaia_std::index::get(nikaia_std::index::get(&common, nikaia_std::index::at(i)), nikaia_std::index::at(j + 1)); nikaia_std::index::set(&mut common[nikaia_std::index::at(i)], nikaia_std::index::at(j), __nikaia_stored); } }
            j -= 1;
        }
        i -= 1;
    }
    let mut marks: Vec<char> = vec![];
    let mut lines: Vec<String> = vec![];
    let mut x: i64 = 0;
    let mut y: i64 = 0;
    while ((x) as usize) < a.len() || ((y) as usize) < b.len() {
        if ((x) as usize) < a.len() && ((y) as usize) < b.len() && *nikaia_std::index::get(&a, (x) as usize) == *nikaia_std::index::get(&b, (y) as usize) {
            marks.push(' ');
            lines.push((*nikaia_std::index::get(&a, (x) as usize)).to_owned());
            x += 1;
            y += 1;
        } else if ((y) as usize) < b.len() && (((x) as usize) == a.len() || *nikaia_std::index::get(nikaia_std::index::get(&common, (x) as usize), (y + 1) as usize) >= *nikaia_std::index::get(nikaia_std::index::get(&common, (x + 1) as usize), (y) as usize)) {
            marks.push('+');
            lines.push((*nikaia_std::index::get(&b, (y) as usize)).to_owned());
            y += 1;
        } else {
            marks.push('-');
            lines.push((*nikaia_std::index::get(&a, (x) as usize)).to_owned());
            x += 1;
        }
    }
    let mut out: String = String::from("");
    let mut skipped = false;
    for at in 0..marks.len() as i64 {
        let mut near = false;
        let from = if at >= 2 { at - 2 } else { 0 };
        let to = if ((at + 3) as usize) < marks.len() { at + 3 } else { marks.len() as i64 };
        for k in from..to { if *nikaia_std::index::get(&marks, nikaia_std::index::at(k)) != ' ' { near = true; } }
        if !near {
            skipped = true;
            continue;
        }
        if skipped {
            out.push_str("  …\n");
            skipped = false;
        }
        out.push(*nikaia_std::index::get(&marks, (at) as usize));
        out.push(' ');
        out.push_str(nikaia_std::index::get(&lines, (at) as usize));
        out.push('\n');
    }
    out
}

fn same_lines(a: &[String], b: &[String]) -> bool {
    if (a.len() as i64) != b.len() as i64 { return false; }
    for k in 0..a.len() as i64 { if *nikaia_std::index::get(&a, (k) as usize) != *nikaia_std::index::get(&b, (k) as usize) { return false; } }
    true
}


// --- dsl.nika ---

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn parameters(body: &str) -> Vec<String> {
    let c: Vec<char> = nikaia_std::list::chars(body.chars());
    let mut found: Vec<String> = Vec::new();
    let mut i: i64 = 0;
    while i < c.len() as i64 {
        if *nikaia_std::index::get(&c, nikaia_std::index::at(i)) != ':' {
            i += 1;
            continue;
        }
        let before = i > 0 && *nikaia_std::index::get(&c, nikaia_std::index::at(i - 1)) == ':';
        let after = i + 1 < c.len() as i64 && *nikaia_std::index::get(&c, nikaia_std::index::at(i + 1)) == ':';
        if before || after {
            i += 2;
            continue;
        }
        let start: i64 = i + 1;
        let mut end: i64 = start;
        while end < c.len() as i64 && a_name_goes_on(*nikaia_std::index::get(&c, nikaia_std::index::at(end))) { end += 1; }
        if end > start && a_name_begins(*nikaia_std::index::get(&c, nikaia_std::index::at(start))) {
            let mut name: String = String::new();
            for k in start..end { name.push(*nikaia_std::index::get(&c, nikaia_std::index::at(k))); }
            if !nikaia_std::list::contains(&found, &name) { found.push(name); }
            i = end;
        } else { i += 1; }
    }
    found
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn a_name_goes_on(c: char) -> bool { matches!(c, 'a'..='z' | 'A'..='Z' | '0'..='9' | '_') }

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn a_name_begins(c: char) -> bool { matches!(c, 'a'..='z' | 'A'..='Z' | '_') }

const TEMPLATE: &str = "html";

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn is_deferred(target: &str, body: &str) -> bool { target != TEMPLATE && !parameters(body).is_empty() }

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn type_name(parameters: &[String]) -> String {
    let mut names = parameters.to_owned();
    names.sort();
    let joined = joined_by(&names, "_");
    format!("NikaiaDslParams_{}", joined)
}

pub fn shadow_types(words: &winnow_grammar::InternerContext, items: &[Spanned<Item>]) -> collections::BTreeMap<String, Vec<String>> {
    let mut statements: Vec<(String, String)> = vec![];
    for item in items.iter() {
        match &item.node {
            Item::Fn { body, .. } => statements_in_block(body, words, &mut statements),
            Item::Impl { methods, .. } => {
                for method in methods.iter() {
                    match &method.node {
                        Item::Fn { body, .. } => statements_in_block(body, words, &mut statements),
                        _ => { },
                    }
                }
            },
            Item::Test { body, .. } => statements_in_block(body, words, &mut statements),
            Item::Bench { body, .. } => statements_in_block(body, words, &mut statements),
            _ => { },
        }
    }
    let mut types: collections::BTreeMap<String, Vec<String>> = collections::BTreeMap::new();
    for (target, content) in statements.iter() {
        if is_deferred(target, content) {
            let found = parameters(content);
            let named = type_name(&found);
            if types.contains_key(&named) { continue; }
            types.insert(named, found);
        }
    }
    types
}

pub fn drivers(words: &winnow_grammar::InternerContext, items: &[Spanned<Item>]) -> Vec<String> {
    let mut names: Vec<String> = vec![];
    for item in items.iter() {
        match &item.node {
            Item::Impl { methods, .. } => { for method in methods.iter() { a_driver(&method.node, words, &mut names); } },
            _ => a_driver(&item.node, words, &mut names),
        }
    }
    names
}

fn a_driver(item: &Item, words: &winnow_grammar::InternerContext, names: &mut Vec<String>) {
    match item {
        Item::Fn { name, spread, .. } => {
            let name = *name; let spread = *spread;
            if spread.is_some() {
                let named = match name { Some(__nikaia_value) => __nikaia_value, None => return };
                names.push(words.resolve(named).to_owned());
            }
        },
        _ => { },
    }
}

pub fn check(words: &winnow_grammar::InternerContext, items: &[Spanned<Item>]) -> Vec<Finding> {
    let takers = drivers(words, items);
    let mut found: Vec<Finding> = vec![];
    for item in items.iter() {
        match &item.node {
            Item::Fn { body, .. } => checked_body(body, words, &takers, &mut found),
            Item::Impl { methods, .. } => {
                for method in methods.iter() {
                    match &method.node {
                        Item::Fn { body, .. } => checked_body(body, words, &takers, &mut found),
                        _ => { },
                    }
                }
            },
            Item::Test { body, .. } => checked_body(body, words, &takers, &mut found),
            Item::Bench { body, .. } => checked_body(body, words, &takers, &mut found),
            _ => { },
        }
    }
    found
}

fn checked_body(body: &Block, words: &winnow_grammar::InternerContext, takers: &[String], found: &mut Vec<Finding>) {
    let mut bound: collections::BTreeMap<String, Vec<String>> = collections::BTreeMap::new();
    for stmt in body.stmts.iter() {
        match &stmt.node {
            Stmt::Let { names, value, .. } => {
                if names.len() != 1 { continue; }
                let text = words.resolve(*nikaia_std::index::get(&names, 0)).to_owned();
                let deferred = deferred_parameters(value, words);
                if deferred.is_some() { bound.insert(text, nikaia_std::index::or(deferred, || vec![].into())); } else { bound.remove(&text); }
            },
            _ => { },
        }
        calls_in_statement(&stmt.node, &stmt.span, words, &bound, takers, found);
    }
}

fn deferred_parameters(value: &Expr, words: &winnow_grammar::InternerContext) -> Option<Vec<String>> {
    match value {
        Expr::Dsl { target, content, .. } => { let target = *target; if is_deferred(words.resolve(target), content) { Some(parameters(content)) } else { None } },
        _ => None,
    }
}

fn calls_in_statement(stmt: &Stmt, span: &Span, words: &winnow_grammar::InternerContext, bound: &collections::BTreeMap<String, Vec<String>>, takers: &[String], found: &mut Vec<Finding>) {
    match stmt {
        Stmt::Let { value, .. } => calls_in(value, span, words, bound, takers, found),
        Stmt::Comptime { value, .. } => calls_in(value, span, words, bound, takers, found),
        Stmt::Expr(value) => calls_in(value, span, words, bound, takers, found),
        Stmt::Return(value) => calls_in(match value { Some(__nikaia_value) => __nikaia_value, None => return }, span, words, bound, takers, found),
        Stmt::Assign { target, value, .. } => {
            calls_in(target, span, words, bound, takers, found);
            calls_in(value, span, words, bound, takers, found);
        },
        Stmt::For { iter, .. } => calls_in(iter, span, words, bound, takers, found),
        Stmt::While { cond, .. } => calls_in(cond, span, words, bound, takers, found),
        _ => { },
    }
}

fn calls_in_block(block: &Block, span: &Span, words: &winnow_grammar::InternerContext, bound: &collections::BTreeMap<String, Vec<String>>, takers: &[String], found: &mut Vec<Finding>) {
    for stmt in block.stmts.iter() {
        calls_in_statement(&stmt.node, span, words, bound, takers, found);
        match &stmt.node {
            Stmt::While { body, .. } => calls_in_block(body, span, words, bound, takers, found),
            Stmt::For { body, .. } => calls_in_block(body, span, words, bound, takers, found),
            _ => { },
        }
    }
}

fn calls_in(expr: &Expr, span: &Span, words: &winnow_grammar::InternerContext, bound: &collections::BTreeMap<String, Vec<String>>, takers: &[String], found: &mut Vec<Finding>) {
    a_call(expr, span, words, bound, takers, found);
    match expr {
        Expr::MethodCall { receiver, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            calls_in(receiver, span, words, bound, takers, found);
            for arg in args.iter() { calls_in(arg, span, words, bound, takers, found); }
        },
        Expr::SafeMethod { receiver, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            calls_in(receiver, span, words, bound, takers, found);
            for arg in args.iter() { calls_in(arg, span, words, bound, takers, found); }
        },
        Expr::Call { func, args, .. } => {
            let func = nikaia_std::boxed::open(func);
            calls_in(func, span, words, bound, takers, found);
            for arg in args.iter() { calls_in(arg, span, words, bound, takers, found); }
        },
        Expr::Block(block) => calls_in_block(block, span, words, bound, takers, found),
        Expr::Overlap(block) => calls_in_block(block, span, words, bound, takers, found),
        Expr::If { cond, then_branch, else_branch } => {
            let cond = nikaia_std::boxed::open(cond);
            calls_in(cond, span, words, bound, takers, found);
            calls_in_block(then_branch, span, words, bound, takers, found);
            calls_in_block(match else_branch { Some(__nikaia_value) => __nikaia_value, None => return }, span, words, bound, takers, found);
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            calls_in(lhs, span, words, bound, takers, found);
            calls_in(rhs, span, words, bound, takers, found);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); calls_in(expr, span, words, bound, takers, found) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); calls_in(inner, span, words, bound, takers, found) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); calls_in(base, span, words, bound, takers, found) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); calls_in(base, span, words, bound, takers, found) },
        Expr::TryCatch { expr, handler } => {
            let expr = nikaia_std::boxed::open(expr);
            calls_in(expr, span, words, bound, takers, found);
            calls_in_block(handler, span, words, bound, takers, found);
        },
        _ => { },
    }
}

fn statements_in_block(block: &Block, words: &winnow_grammar::InternerContext, out: &mut Vec<(String, String)>) {
    for stmt in block.stmts.iter() {
        match &stmt.node {
            Stmt::Let { value, .. } => statements_in(value, words, out),
            Stmt::Comptime { value, .. } => statements_in(value, words, out),
            Stmt::Expr(value) => statements_in(value, words, out),
            Stmt::Return(value) => {
                let returned = match value { Some(__nikaia_value) => __nikaia_value, None => continue };
                statements_in(returned, words, out);
            },
            Stmt::Assign { target, value, .. } => {
                statements_in(target, words, out);
                statements_in(value, words, out);
            },
            Stmt::For { iter, body, .. } => {
                statements_in(iter, words, out);
                statements_in_block(body, words, out);
            },
            Stmt::While { cond, body } => {
                statements_in(cond, words, out);
                statements_in_block(body, words, out);
            },
            _ => { },
        }
    }
}

fn statements_in(expr: &Expr, words: &winnow_grammar::InternerContext, out: &mut Vec<(String, String)>) {
    match expr {
        Expr::Dsl { target, content, .. } => { let target = *target; out.push(a_statement(words.resolve(target), content)) },
        Expr::MethodCall { receiver, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            statements_in(receiver, words, out);
            for arg in args.iter() { statements_in(arg, words, out); }
        },
        Expr::SafeMethod { receiver, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            statements_in(receiver, words, out);
            for arg in args.iter() { statements_in(arg, words, out); }
        },
        Expr::Call { func, args, .. } => {
            let func = nikaia_std::boxed::open(func);
            statements_in(func, words, out);
            for arg in args.iter() { statements_in(arg, words, out); }
        },
        Expr::Block(block) => statements_in_block(block, words, out),
        Expr::Overlap(block) => statements_in_block(block, words, out),
        Expr::If { cond, then_branch, else_branch } => {
            let cond = nikaia_std::boxed::open(cond);
            statements_in(cond, words, out);
            statements_in_block(then_branch, words, out);
            statements_in_block(match else_branch { Some(__nikaia_value) => __nikaia_value, None => return }, words, out);
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            statements_in(lhs, words, out);
            statements_in(rhs, words, out);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); statements_in(expr, words, out) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); statements_in(inner, words, out) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); statements_in(base, words, out) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); statements_in(base, words, out) },
        Expr::TryCatch { expr, handler } => {
            let expr = nikaia_std::boxed::open(expr);
            statements_in(expr, words, out);
            statements_in_block(handler, words, out);
        },
        _ => { },
    }
}

fn a_statement(target: &str, content: &str) -> (String, String) { (target.to_owned(), content.to_owned()) }

fn a_call(expr: &Expr, span: &Span, words: &winnow_grammar::InternerContext, bound: &collections::BTreeMap<String, Vec<String>>, takers: &[String], found: &mut Vec<Finding>) {
    match expr {
        Expr::MethodCall { receiver, method, args, config } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            let subject = nikaia_std::index::or_maybe(bound_subject(receiver, words, bound), || bound_argument(args, words, bound));
            a_parameter_call(words.resolve(method), &option_names(config, words), subject, span, bound, takers, found);
        },
        Expr::SafeMethod { receiver, method, args, config } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            let subject = nikaia_std::index::or_maybe(bound_subject(receiver, words, bound), || bound_argument(args, words, bound));
            a_parameter_call(words.resolve(method), &option_names(config, words), subject, span, bound, takers, found);
        },
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            a_parameter_call(&callee_name(func, words), &option_names(config, words), bound_argument(args, words, bound), span, bound, takers, found);
        },
        _ => { },
    }
}

fn callee_name(func: &Expr, words: &winnow_grammar::InternerContext) -> String {
    match func {
        Expr::Variable(name) => { let name = *name; words.resolve(name).to_owned() },
        _ => String::from(""),
    }
}

fn bound_subject(subject: &Expr, words: &winnow_grammar::InternerContext, bound: &collections::BTreeMap<String, Vec<String>>) -> Option<String> {
    match subject {
        Expr::Variable(name) => { let name = *name; if bound.contains_key(words.resolve(name)) { Some(words.resolve(name).to_owned()) } else { None } },
        _ => None,
    }
}

fn bound_argument(args: &[Expr], words: &winnow_grammar::InternerContext, bound: &collections::BTreeMap<String, Vec<String>>) -> Option<String> {
    for arg in args.iter() {
        let named = bound_subject(arg, words, bound);
        if named.is_some() { return named; }
    }
    None
}

fn a_parameter_call(callee: &str, passed: &[String], subject: Option<String>, span: &Span, bound: &collections::BTreeMap<String, Vec<String>>, takers: &[String], found: &mut Vec<Finding>) {
    if passed.is_empty() { return; }
    let name = match subject { Some(__nikaia_value) => __nikaia_value, None => return };
    let declared = match *nikaia_std::index::get(&bound, &name) { Some(__nikaia_value) => __nikaia_value, None => return };
    if callee.is_empty() || !nikaia_std::list::contains(&takers, &callee) {
        let shown: String = if callee.is_empty() { String::from("this call") } else { callee.to_owned() };
        let first: String = if !passed.is_empty() { (*nikaia_std::index::get(&passed, 0)).to_owned() } else { String::from("") };
        let reached = parameter_list(&passed);
        found.push(refusal("NK1109", span.clone(), format!("`{}` has no option called `{}`.", shown, first), vec![format!("`{}` is a `dsl` statement, and its parameters go to a driver: a function declared with `...args: Self::dsl`. Nothing in this file declares `{}` that way, so {} would reach nothing.", name, shown, reached)], format!("Hand `{}` to a driver, a method declared `run(ref self, statement: ref String; ...args: Self::dsl)`, and pass the parameters there: `driver.run({}; {}: …)`.", name, name, first)));
        return;
    }
    let listed = parameter_list(declared);
    for parameter in declared.iter() { if !nikaia_std::list::contains(&passed, &parameter) { found.push(refusal("NK1112", span.clone(), format!("`{}` needs `:{}`, but this call doesn't pass it.", name, parameter), vec![format!("The statement's parameters are {}.", listed)], format!("Pass it after the `;`: `{}: …`.", parameter))); } }
    for given in passed.iter() {
        if nikaia_std::list::contains(&declared, &given) { continue; }
        let note: String = if declared.is_empty() { format!("`{}` has no parameters at all.", name) } else { format!("The statement's parameters are {}.", listed) };
        let near = nearest_parameter(given, declared);
        let help: String = if near.is_some() {
            let one = nikaia_std::index::or(near, || "".into());
            format!("Did you mean `{}`?", one)
        } else { format!("Add `:{}` to the statement, or remove it here.", given) };
        found.push(refusal("NK1113", span.clone(), format!("`{}` has no parameter called `:{}`.", name, given), vec![note], help));
    }
}

fn option_names(config: &[ConfigArg], words: &winnow_grammar::InternerContext) -> Vec<String> {
    let mut passed: Vec<String> = vec![];
    for setting in config.iter() { passed.push(words.resolve(setting.name).to_owned()); }
    passed
}

fn nearest_parameter(name: &str, declared: &[String]) -> Option<String> {
    for candidate in declared.iter() { if one_edit_apart(name, candidate) { return Some(candidate.to_owned()); } }
    None
}

fn parameter_list(names: &[String]) -> String {
    let mut out: String = String::from("");
    for k in 0..names.len() as i64 {
        if k > 0 { out.push_str(", "); }
        let one = (*nikaia_std::index::get(&names, (k) as usize)).to_owned();
        out.push_str(&format!("`:{}`", one));
    }
    out
}


// --- dump.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct VariantShape {
    pub name: String,
    pub carried: Vec<Ty>,
    pub named: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FieldShape {
    pub name: String,
    pub spelled: String,
    pub ty: Ty,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Shapes {
    pub enums: collections::BTreeMap<String, Vec<VariantShape>>,
    pub structs: collections::BTreeMap<String, Vec<FieldShape>>,
    pub constants: collections::BTreeMap<String, String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Uncrossable {
    pub ty: String,
    pub because: String,
}

const DEEPEST: i64 = 16;

pub fn dump(shapes: &Shapes, ty: &Ty, expr: &str, depth: i64, out: &mut String) -> Option<Uncrossable> {
    if depth > DEEPEST { return uncrossable(ty, "it contains itself, with no end to how deep it goes"); }
    match ty {
        Ty::Named { name, args, view } => { let view = *view; match view && name == "str" {
            true => text_view(expr, depth, out),
            false => dump_named(shapes, ty, name, args, expr, depth, out),
        } },
        Ty::Pointed { item, slice, mutable } => { let item = nikaia_std::boxed::open(item); let mutable = *mutable; let slice = *slice; match slice && !mutable {
            true => dump_run(shapes, item, expr, depth, out),
            false => uncrossable(ty, NO_FORM),
        } },
        _ => uncrossable(ty, NO_FORM),
    }
}

const NO_FORM: &str = "a `const` holds an integer, a `bool`, text, a list of those and a `struct` whose fields are those";

fn text_view(expr: &str, depth: i64, out: &mut String) -> Option<Uncrossable> {
    let pad = "    ".repeat(nikaia_std::count::of(depth));
    out.push_str(&format!("{}__nikaia_text(&mut out, {});\n", pad, expr));
    None
}

fn dump_named(shapes: &Shapes, ty: &Ty, name: &str, args: &[Ty], expr: &str, depth: i64, out: &mut String) -> Option<Uncrossable> {
    let pad = "    ".repeat(nikaia_std::count::of(depth));
    if name == "String" {
        out.push_str(&format!("{}__nikaia_text(&mut out, &{});\n", pad, expr));
        return None;
    }
    if name == "bool" {
        out.push_str(&format!("{}out.push_str(&format!(\"(b {{}})\", {}));\n", pad, expr));
        return None;
    }
    if is_whole(name) {
        out.push_str(&format!("{}out.push_str(&format!(\"(i {{}})\", {}));\n", pad, expr));
        return None;
    }
    if (name == "Vec" || name == "List" || name == ARRAY) && !args.is_empty() { return dump_run(shapes, nikaia_std::index::get(&args, 0), expr, depth, out); }
    if name == "f32" || name == "f64" {
        out.push_str(&format!("{}out.push_str(&format!(\"(f {{:?}})\", {}));\n", pad, expr));
        return None;
    }
    if shapes.constants.contains_key(name) {
        let constructor = match *nikaia_std::index::get(&shapes.constants, name) { Some(__nikaia_value) => __nikaia_value, None => return uncrossable(ty, NO_FORM) };
        out.push_str(&format!("{}out.push_str(\"(c {}\");\n", pad, constructor));
        out.push_str(&format!("{}for __nikaia_part in nikaia_std::build_time::Parts::parts(&{}) {{\n", pad, expr));
        out.push_str(&format!("{}    out.push(' ');\n", pad));
        out.push_str(&format!("{}    out.push_str(&__nikaia_part);\n", pad));
        out.push_str(&format!("{}}}\n", pad));
        out.push_str(&format!("{}out.push(')');\n", pad));
        return None;
    }
    if shapes.enums.contains_key(name) { return dump_variants(shapes, ty, name, expr, depth, out); }
    dump_fields(shapes, ty, name, expr, depth, out)
}

fn dump_run(shapes: &Shapes, item: &Ty, expr: &str, depth: i64, out: &mut String) -> Option<Uncrossable> {
    let pad = "    ".repeat(nikaia_std::count::of(depth));
    let held = format!("__nikaia_{}", depth);
    out.push_str(&format!("{}out.push_str(\"(l\");\n", pad));
    out.push_str(&format!("{}for {} in {}.iter() {{\n", pad, held, expr));
    out.push_str(&format!("{}    out.push(' ');\n", pad));
    let refused = dump(shapes, item, &held, depth + 1, out);
    if refused.is_some() { return refused; }
    out.push_str(&format!("{}}}\n", pad));
    out.push_str(&format!("{}out.push(')');\n", pad));
    None
}

fn dump_variants(shapes: &Shapes, ty: &Ty, name: &str, expr: &str, depth: i64, out: &mut String) -> Option<Uncrossable> {
    let variants = match *nikaia_std::index::get(&shapes.enums, name) { Some(__nikaia_value) => __nikaia_value, None => return uncrossable(ty, NO_FORM) };
    let pad = "    ".repeat(nikaia_std::count::of(depth));
    out.push_str(&format!("{}match {} {{\n", pad, expr));
    for variant in variants.iter() {
        if variant.named { return uncrossable(ty, &format!("`{}::{}` has named fields, and variants with named fields can't be computed at build time yet", name, variant.name)); }
        let mut bound: Vec<String> = vec![];
        let mut at: i64 = 0;
        while ((at) as usize) < variant.carried.len() {
            bound.push(format!("__nikaia_p{}", at));
            at += 1;
        }
        let mut pattern = format!("{}::{}", name, variant.name);
        if !bound.is_empty() {
            let joined = bound.join(", ");
            pattern = format!("{}::{}({})", name, variant.name, joined);
        }
        out.push_str(&format!("{}    {} => {{\n", pad, pattern));
        out.push_str(&format!("{}        out.push_str(\"(v {} {}\");\n", pad, name, variant.name));
        let mut i: i64 = 0;
        while ((i) as usize) < bound.len() {
            out.push_str(&format!("{}        out.push(' ');\n", pad));
            let refused = dump(shapes, nikaia_std::index::get(&variant.carried, (i) as usize), nikaia_std::index::get(&bound, (i) as usize), depth + 2, out);
            if refused.is_some() { return refused; }
            i += 1;
        }
        out.push_str(&format!("{}        out.push(')');\n", pad));
        out.push_str(&format!("{}    }}\n", pad));
    }
    out.push_str(&format!("{}}}\n", pad));
    None
}

fn dump_fields(shapes: &Shapes, ty: &Ty, name: &str, expr: &str, depth: i64, out: &mut String) -> Option<Uncrossable> {
    let fields = match *nikaia_std::index::get(&shapes.structs, name) { Some(__nikaia_value) => __nikaia_value, None => return uncrossable(ty, &format!("`{}` isn't declared in this program with fields, and the value is built into the program field by field", name)) };
    if fields.is_empty() { return uncrossable(ty, &format!("`{}` declares no fields", name)); }
    let pad = "    ".repeat(nikaia_std::count::of(depth));
    out.push_str(&format!("{}out.push_str(\"(t {}\");\n", pad, name));
    for field in fields.iter() {
        out.push_str(&format!("{}out.push_str(\" ({} \");\n", pad, field.name));
        let refused = dump(shapes, &field.ty, &format!("{}.{}", expr, field.spelled), depth + 1, out);
        if refused.is_some() { return refused; }
        out.push_str(&format!("{}out.push(')');\n", pad));
    }
    out.push_str(&format!("{}out.push(')');\n", pad));
    None
}

pub fn is_whole(name: &str) -> bool { name == "i8" || name == "i16" || name == "i32" || name == "i64" || name == "isize" || name == "u8" || name == "u16" || name == "u32" || name == "u64" || name == "usize" }

fn uncrossable(ty: &Ty, because: &str) -> Option<Uncrossable> { Some(Uncrossable { ty: ty.text(), because: because.to_owned() }) }


// --- escapes.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NotAnEscape {
    pub written: String,
    pub why: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum EscapeRead {
    Means { value: char, next: i64 },
    Nothing { refused: NotAnEscape },
}

const HEX: &str = "0123456789abcdef";

pub fn an_escape_nothing_names(literal: &str, char_of: &impl Fn(i64) -> Option<char>) -> Option<NotAnEscape> {
    let c: Vec<char> = nikaia_std::list::chars(literal.chars());
    let mut at: i64 = 0;
    while at < c.len() as i64 {
        if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) != '\\' {
            at += 1;
            continue;
        }
        match one_escape(&c, at + 1, char_of) {
            EscapeRead::Means { next, .. } => { at = next; },
            EscapeRead::Nothing { refused } => { return Some(refused); },
        }
    }
    None
}

pub fn decoded(literal: &str, char_of: &impl Fn(i64) -> Option<char>) -> Option<String> {
    let c: Vec<char> = nikaia_std::list::chars(literal.chars());
    let mut out: String = String::from("");
    let mut at: i64 = 0;
    while at < c.len() as i64 {
        if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) != '\\' {
            out.push(*nikaia_std::index::get(&c, nikaia_std::index::at(at)));
            at += 1;
            continue;
        }
        match one_escape(&c, at + 1, char_of) {
            EscapeRead::Means { value, next } => {
                out.push(value);
                at = next;
            },
            EscapeRead::Nothing { .. } => { return None; },
        }
    }
    Some(out)
}

pub fn as_a_literal(text: &str) -> String {
    let mut out: String = String::from("");
    for c in text.chars() {
        if c == '"' { out.push_str("\\\""); } else if c == '\\' { out.push_str("\\\\"); } else if c == '\n' { out.push_str("\\n"); } else if c == '\r' { out.push_str("\\r"); } else if c == '\t' { out.push_str("\\t"); } else if c == '\0' { out.push_str("\\0"); } else if a_control_character(c) {
            out.push_str("\\u{");
            out.push_str(&hex_of(c as i64));
            out.push('}');
        } else { out.push(c); }
    }
    out
}

fn one_escape(c: &[char], at: i64, char_of: &impl Fn(i64) -> Option<char>) -> EscapeRead {
    let mut written: String = String::from("\\");
    if at >= c.len() as i64 { return not_an_escape(&written, "a `\\` at the end of a literal escapes nothing"); }
    let first = *nikaia_std::index::get(&c, nikaia_std::index::at(at));
    written.push(first);
    if first == 'x' { return a_byte(c, at + 1, &written, char_of); }
    if first == 'u' { return a_character(c, at + 1, &written, char_of); }
    let value = match named_escape(first) { Some(__nikaia_value) => __nikaia_value, None => return not_an_escape(&written, "no escape starts with that character") };
    EscapeRead::Means { value, next: at + 1 }
}

fn a_byte(c: &[char], from: i64, so_far: &str, char_of: &impl Fn(i64) -> Option<char>) -> EscapeRead {
    let mut written = so_far.to_owned();
    let mut end = from;
    while end < from + 2 && end < c.len() as i64 {
        written.push(*nikaia_std::index::get(&c, nikaia_std::index::at(end)));
        end += 1;
    }
    if end < from + 2 { return not_an_escape(&written, "`\\x` takes exactly two hexadecimal digits"); }
    let high = nikaia_std::index::or(hex_digit(*nikaia_std::index::get(&c, nikaia_std::index::at(from))), || 128);
    let low = nikaia_std::index::or(hex_digit(*nikaia_std::index::get(&c, nikaia_std::index::at(from + 1))), || 128);
    let why = "`\\x` takes two hexadecimal digits naming a byte below `\\x80`";
    let value = high * 16 + low;
    if value >= 128 { return not_an_escape(&written, why); }
    let byte = match char_of(value) { Some(__nikaia_value) => __nikaia_value, None => return not_an_escape(&written, why) };
    EscapeRead::Means { value: byte, next: end }
}

fn a_character(c: &[char], from: i64, so_far: &str, char_of: &impl Fn(i64) -> Option<char>) -> EscapeRead {
    let mut written = so_far.to_owned();
    if from >= c.len() as i64 || *nikaia_std::index::get(&c, nikaia_std::index::at(from)) != '{' { return not_an_escape(&written, "`\\u` takes its digits in braces, as `\\u{1F600}`"); }
    written.push('{');
    let mut end = from + 1;
    let mut closed = false;
    while end < c.len() as i64 && !closed {
        written.push(*nikaia_std::index::get(&c, nikaia_std::index::at(end)));
        closed = *nikaia_std::index::get(&c, nikaia_std::index::at(end)) == '}';
        end += 1;
    }
    if !closed { return not_an_escape(&written, "`\\u{` is never closed"); }
    let why = "`\\u{…}` takes up to six hexadecimal digits naming a character";
    let value = match code_point(c, from + 1, end - 1) { Some(__nikaia_value) => __nikaia_value, None => return not_an_escape(&written, why) };
    let named = match char_of(value) { Some(__nikaia_value) => __nikaia_value, None => return not_an_escape(&written, why) };
    EscapeRead::Means { value: named, next: end }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn code_point(c: &[char], from: i64, to: i64) -> Option<i64> {
    if from >= to || *nikaia_std::index::get(&c, nikaia_std::index::at(from)) == '_' { return None; }
    let mut value: i64 = 0;
    let mut digits = 0;
    let mut at = from;
    while at < to {
        if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) != '_' {
            let digit = match hex_digit(*nikaia_std::index::get(&c, nikaia_std::index::at(at))) { Some(__nikaia_value) => __nikaia_value, None => return None };
            value = value * 16 + digit;
            digits += 1;
        }
        at += 1;
    }
    if digits > 6 { return None; }
    value.into()
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn named_escape(c: char) -> Option<char> {
    if c == 'n' { return Some('\n'); }
    if c == 'r' { return Some('\r'); }
    if c == 't' { return Some('\t'); }
    if c == '0' { return Some('\0'); }
    if c == '\\' || c == '\'' || c == '"' { return Some(c); }
    None
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn hex_digit(c: char) -> Option<i64> {
    if c >= '0' && c <= '9' { return Some(c as i64 - 48); }
    if c >= 'a' && c <= 'f' { return Some(c as i64 - 87); }
    if c >= 'A' && c <= 'F' { return Some(c as i64 - 55); }
    None
}

fn hex_of(n: i64) -> String {
    if n == 0 { return String::from("0"); }
    let digits: Vec<char> = nikaia_std::list::chars(HEX.chars());
    let mut backwards: Vec<char> = vec![];
    let mut rest = n;
    while rest > 0 {
        backwards.push(*nikaia_std::index::get(&digits, nikaia_std::index::at(rest % 16)));
        rest /= 16;
    }
    let mut out: String = String::from("");
    let mut i = backwards.len() as i64;
    while i > 0 {
        i -= 1;
        out.push(*nikaia_std::index::get(&backwards, nikaia_std::index::at(i)));
    }
    out
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn a_control_character(c: char) -> bool {
    let n = c as i64;
    n < 32 || n >= 127 && n <= 159
}

fn not_an_escape(written: &str, why: &str) -> EscapeRead { EscapeRead::Nothing { refused: NotAnEscape { written: written.to_owned(), why: why.to_owned() } } }


