// --- fixed.nika ---

pub const HASHED_FROM: i64 = 12;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Table {
    pub seed: u64,
    pub disps: Vec<(u32, u32)>,
    pub keys: Vec<String>,
    pub order: Vec<i64>,
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn fnv(key: &str, seed: u64) -> u64 {
    let mut hash: u64 = 14695981039346656037u64 ^ seed;
    for b in key.bytes() {
        hash ^= b as u64;
        hash = hash.wrapping_mul(1099511628211u64);
    }
    hash
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn displace(f1: u32, f2: u32, d1: u32, d2: u32) -> u32 { d2.wrapping_add(f1.wrapping_mul(d1)).wrapping_add(f2) }

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn build(keys: &[String]) -> Option<Table> {
    let n = keys.len() as i64;
    if n < HASHED_FROM {
        let mut written: Vec<String> = vec![];
        let mut order: Vec<i64> = vec![];
        for at in 0..n {
            written.push((*nikaia_std::index::get(&keys, nikaia_std::index::at(at))).to_owned());
            order.push(at);
        }
        return Some(Table { seed: 0, disps: vec![], keys: written, order });
    }
    let mut buckets = (n + 4) / 5;
    if buckets < 1 { buckets = 1; }
    for seed in 0..200 {
        let table = attempt(keys, seed as u64, buckets, n);
        if table.is_some() { return table; }
    }
    None
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn attempt(keys: &[String], seed: u64, buckets: i64, n: i64) -> Option<Table> {
    let mut by_bucket: Vec<Vec<(i64, u32, u32)>> = vec![];
    for _ in 0..buckets { by_bucket.push(vec![]); }
    for at in 0..n {
        let hash = fnv(nikaia_std::index::get(&keys, nikaia_std::index::at(at)), seed);
        let g = (hash >> 32) as u32;
        let f1 = hash as u32;
        let f2 = (hash >> 16) as u32;
        by_bucket[nikaia_std::index::at(g as i64 % buckets)].push((at, f1, f2));
    }
    let mut order: Vec<(i64, i64)> = vec![];
    for b in 0..buckets {
        let size = (*nikaia_std::index::get(&by_bucket, (b) as usize)).len() as i64;
        if size > 0 { order.push((0 - size, b)); }
    }
    order.sort();
    let mut disps: Vec<(u32, u32)> = vec![];
    for _ in 0..buckets { disps.push((0, 0)); }
    let mut slots: Vec<i64> = vec![];
    for _ in 0..n { slots.push(-1); }
    for (_, bucket) in order.iter() {
        let bucket = nikaia_std::num::value(bucket);
        let mut placed = false;
        let mut d1: u32 = 0u32;
        while !placed && (d1 as i64) < n {
            let mut d2: u32 = 0u32;
            while !placed && (d2 as i64) < n {
                let mut taken: Vec<(i64, i64)> = vec![];
                let mut fits = true;
                for (at, f1, f2) in (*nikaia_std::index::get(&by_bucket, nikaia_std::index::at(bucket))).iter() {
                    let at = nikaia_std::num::value(at);let f1 = nikaia_std::num::value(f1);let f2 = nikaia_std::num::value(f2);
                    let slot = displace(f1, f2, d1, d2) as i64 % n;
                    let mut clash = *nikaia_std::index::get(&slots, nikaia_std::index::at(slot)) >= 0;
                    for t in taken.iter() { if t.0 == slot { clash = true; } }
                    if clash {
                        fits = false;
                        break;
                    }
                    taken.push((slot, at));
                }
                if fits {
                    { let __nikaia_stored = (d1, d2); nikaia_std::index::set(&mut disps, nikaia_std::index::at(bucket), __nikaia_stored); }
                    for (slot, at) in taken.iter() {
                        let slot = nikaia_std::num::value(slot);let at = nikaia_std::num::value(at);
                        { let __nikaia_stored = at; nikaia_std::index::set(&mut slots, nikaia_std::index::at(slot), __nikaia_stored); }
                    }
                    placed = true;
                }
                d2 += 1;
            }
            d1 += 1;
        }
        if !placed { return None; }
    }
    let mut written: Vec<String> = vec![];
    let mut at_of: Vec<i64> = vec![];
    for slot in slots.iter() {
        let slot = nikaia_std::num::value(slot);
        if slot < 0 { return None; }
        written.push((*nikaia_std::index::get(&keys, nikaia_std::index::at(slot))).to_owned());
        at_of.push(slot);
    }
    Some(Table { seed, disps, keys: written, order: at_of })
}


// --- fold.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Constant {
    pub value: Integer,
    pub pinned: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Folded {
    Value(Constant),
    Overflows(Constant),
    TooLarge(bool),
    Nothing,
}

const I8_LOW: u64 = 128;

const I8_HIGH: u64 = 127;

const I16_LOW: u64 = 32768;

const I16_HIGH: u64 = 32767;

const U8_HIGH: u64 = 255;

const U16_HIGH: u64 = 65535;

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn fits(c: &Constant, ty: &str) -> bool { integer_fits(&c.value, ty) }

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn integer_fits(n: &Integer, ty: &str) -> bool {
    match ty {
        "i64" => integer_as_count(n).is_some(),
        "i32" => fits_an_i32(n),
        "u64" => !n.negative,
        "u32" => !n.negative && u32::try_from(n.magnitude).ok().is_some(),
        "i8" => within(n, I8_LOW, I8_HIGH),
        "i16" => within(n, I16_LOW, I16_HIGH),
        "u8" => within(n, 0u64, U8_HIGH),
        "u16" => within(n, 0u64, U16_HIGH),
        _ => true,
    }
}

fn fits_an_i32(n: &Integer) -> bool {
    let count = match integer_as_count(n) { Some(__nikaia_value) => __nikaia_value, None => return false };
    i32::try_from(count).ok().is_some()
}

fn within(n: &Integer, low: u64, high: u64) -> bool {
    if n.negative { return n.magnitude <= low; }
    n.magnitude <= high
}

fn stepped(n: Option<Integer>, heading: bool, pinned: String) -> Folded {
    let found = match n { Some(__nikaia_value) => __nikaia_value, None => return Folded::TooLarge(heading) };
    Folded::Value(Constant { value: found, pinned })
}

pub fn constant_of(expr: &Expr, name_is: &impl Fn(winnow_grammar::Symbol) -> Folded) -> Folded {
    match expr {
        Expr::LitInt { value, negative } => { let negative = *negative; let value = *value; Folded::Value(Constant { value: integer(value, negative), pinned: String::from("") }) },
        Expr::Variable(name) => { let name = *name; name_is(name) },
        Expr::Unary { op, expr } => { let expr = nikaia_std::boxed::open(expr); negated(op, expr, name_is) },
        Expr::Binary { op, lhs, rhs, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); combined(op, lhs, rhs, name_is) },
        _ => Folded::Nothing,
    }
}

fn negated(op: &UnaryOp, inner: &Expr, name_is: &impl Fn(winnow_grammar::Symbol) -> Folded) -> Folded {
    if *op != UnaryOp::Neg { return Folded::Nothing; }
    match constant_of(inner, name_is) {
        Folded::Value(c) => pinned_step(Constant { value: integer_negated(&c.value), pinned: c.pinned }),
        Folded::TooLarge(negative) => Folded::TooLarge(!negative),
        other => other,
    }
}

fn pinned_step(c: Constant) -> Folded { if fits(&c, &c.pinned) { Folded::Value(c) } else { Folded::Overflows(c) } }

fn combined(op: &BinaryOp, lhs: &Expr, rhs: &Expr, name_is: &impl Fn(winnow_grammar::Symbol) -> Folded) -> Folded {
    let a = match constant_of(lhs, name_is) {
        Folded::Value(c) => c,
        other => return other,
    };
    let b = match constant_of(rhs, name_is) {
        Folded::Value(c) => c,
        other => return other,
    };
    if !a.pinned.is_empty() && !b.pinned.is_empty() && a.pinned != b.pinned { return Folded::Nothing; }
    let pinned = if a.pinned.is_empty() { b.pinned.to_owned() } else { a.pinned.to_owned() };
    let x = a.value;
    let y = b.value;
    let folded = match op {
        BinaryOp::Add => stepped(integer_sum(&x, &y), x.negative, pinned),
        BinaryOp::Sub => stepped(integer_difference(&x, &y), x.negative, pinned),
        BinaryOp::Mul => stepped(integer_product(&x, &y), x.negative != y.negative, pinned),
        BinaryOp::Div => divided(integer_quotient(&x, &y, false), pinned),
        BinaryOp::Rem => divided(integer_quotient(&x, &y, true), pinned),
        _ => Folded::Nothing,
    };
    match folded {
        Folded::Value(c) => pinned_step(c),
        other => other,
    }
}

fn divided(n: Option<Integer>, pinned: String) -> Folded {
    let found = match n { Some(__nikaia_value) => __nikaia_value, None => return Folded::Nothing };
    Folded::Value(Constant { value: found, pinned })
}

pub fn wants_widening(folded: &Folded) -> bool {
    match folded {
        Folded::Value(c) => c.pinned.is_empty() && !fits(c, "i32") && fits(c, "i64"),
        _ => false,
    }
}


// --- foreign.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
struct Walked {
    seen: Vec<Seen>,
    with_names: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Seen {
    Path { name: String, span: Span },
    Call { name: String, wrote: Option<Wrote>, span: Span },
    Name(String),
    Spawn { span: Span },
    Opaque { span: Span },
    Joins { construct: String, span: Span },
}

pub fn written_in(program: &Program, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64) -> Vec<Seen> {
    let mut found = Walked { seen: vec![], with_names: false };
    for item in program.items.iter() { item_names(&item.node, &item.span, names, unaliased, holes_of, root_at, &mut found); }
    found.seen
}

pub fn seen_in(block: &Block, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, with_names: bool) -> Vec<Seen> {
    let mut found = Walked { seen: vec![], with_names };
    block_names(block, names, unaliased, holes_of, root_at, &mut found);
    found.seen
}

pub fn seen_in_expression(expr: &Expr, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, with_names: bool) -> Vec<Seen> {
    let mut found = Walked { seen: vec![], with_names };
    let nowhere = Span::nowhere();
    expression_paths(expr, &nowhere, names, unaliased, holes_of, root_at, &mut found);
    expression_blocks(expr, names, unaliased, holes_of, root_at, &mut found);
    found.seen
}

fn item_names(item: &Item, span: &Span, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, found: &mut Walked) {
    match item {
        Item::Fn { args, ret_type, body, .. } => {
            for arg in args.iter() { type_names(&arg.ty, span, names, unaliased, found); }
            maybe_type_names((ret_type).as_ref(), span, names, unaliased, found);
            block_names(body, names, unaliased, holes_of, root_at, found);
        },
        Item::Struct { fields, .. } => { for field in fields.iter() { type_names(&field.ty, span, names, unaliased, found); } },
        Item::Impl { methods, .. } => { for method in methods.iter() { item_names(&method.node, &method.span, names, unaliased, holes_of, root_at, found); } },
        _ => { },
    }
}

fn type_names(ty: &Type, span: &Span, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, found: &mut Walked) {
    let name = unaliased(names.resolve(ty.name));
    if name.contains("::") { found.seen.push(named_at(name, span)); }
    for argument in ty.generics.iter() { type_names(argument, span, names, unaliased, found); }
    maybe_type_names((*ty.code).as_ref().and_then(|__nikaia_it| (*__nikaia_it.result).as_ref()), span, names, unaliased, found);
}

fn maybe_type_names(ty: Option<&Type>, span: &Span, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, found: &mut Walked) { type_names(match ty { Some(__nikaia_value) => __nikaia_value, None => return }, span, names, unaliased, found); }

fn block_names(block: &Block, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, found: &mut Walked) {
    for stmt in block.stmts.iter() {
        match &stmt.node {
            Stmt::Let { ty, .. } => maybe_type_names((ty).as_ref(), &stmt.span, names, unaliased, found),
            _ => { },
        }
        statement_paths(&stmt.node, &stmt.span, names, unaliased, holes_of, root_at, found);
        statement_blocks(&stmt.node, names, unaliased, holes_of, root_at, found);
    }
}

fn statement_paths(stmt: &Stmt, span: &Span, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, found: &mut Walked) {
    match stmt {
        Stmt::Let { value, .. } => expression_paths(value, span, names, unaliased, holes_of, root_at, found),
        Stmt::Comptime { value, .. } => expression_paths(value, span, names, unaliased, holes_of, root_at, found),
        Stmt::Assign { target, value, .. } => {
            expression_paths(target, span, names, unaliased, holes_of, root_at, found);
            expression_paths(value, span, names, unaliased, holes_of, root_at, found);
        },
        Stmt::For { iter, .. } => expression_paths(iter, span, names, unaliased, holes_of, root_at, found),
        Stmt::While { cond, .. } => expression_paths(cond, span, names, unaliased, holes_of, root_at, found),
        Stmt::Return(value) => maybe_expression_paths((value).as_ref(), span, names, unaliased, holes_of, root_at, found),
        Stmt::Expr(value) => expression_paths(value, span, names, unaliased, holes_of, root_at, found),
        _ => { },
    }
}

fn maybe_expression_paths(expr: Option<&Expr>, span: &Span, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, found: &mut Walked) { expression_paths(match expr { Some(__nikaia_value) => __nikaia_value, None => return }, span, names, unaliased, holes_of, root_at, found); }

fn expression_paths(expr: &Expr, span: &Span, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, found: &mut Walked) {
    match expr {
        Expr::Spawn { .. } => found.seen.push(Seen::Spawn { span: span.clone() }),
        Expr::Dsl { .. } => found.seen.push(Seen::Opaque { span: span.clone() }),
        Expr::Overlap(_) => found.seen.push(Seen::Joins { construct: String::from("overlap"), span: span.clone() }),
        Expr::Select(_) => found.seen.push(Seen::Joins { construct: String::from("select"), span: span.clone() }),
        Expr::Call { func, args, .. } => { let func = nikaia_std::boxed::open(func); a_named_call(func, args, span, names, root_at, found) },
        _ => { },
    }
    for hole in holes_of(expr) { expression_paths(&hole, span, names, unaliased, holes_of, root_at, found); }
    match expr {
        Expr::Path(segments) => { if !segments.is_empty() { found.seen.push(named_at(path_name(segments, names, unaliased), span)); } },
        Expr::Variable(name) => {
            let name = *name;
            if found.with_names { found.seen.push(Seen::Name(names.resolve(name).to_owned())); }
        },
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            expression_paths(func, span, names, unaliased, holes_of, root_at, found);
            for arg in args.iter() { expression_paths(arg, span, names, unaliased, holes_of, root_at, found); }
            for setting in config.iter() { expression_paths(&setting.value, span, names, unaliased, holes_of, root_at, found); }
        },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            expression_paths(receiver, span, names, unaliased, holes_of, root_at, found);
            for arg in args.iter() { expression_paths(arg, span, names, unaliased, holes_of, root_at, found); }
            for setting in config.iter() { expression_paths(&setting.value, span, names, unaliased, holes_of, root_at, found); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            expression_paths(receiver, span, names, unaliased, holes_of, root_at, found);
            for arg in args.iter() { expression_paths(arg, span, names, unaliased, holes_of, root_at, found); }
            for setting in config.iter() { expression_paths(&setting.value, span, names, unaliased, holes_of, root_at, found); }
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            expression_paths(lhs, span, names, unaliased, holes_of, root_at, found);
            expression_paths(rhs, span, names, unaliased, holes_of, root_at, found);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); expression_paths(expr, span, names, unaliased, holes_of, root_at, found) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); expression_paths(inner, span, names, unaliased, holes_of, root_at, found) },
        Expr::Throw(inner) => { let inner = nikaia_std::boxed::open(inner); expression_paths(inner, span, names, unaliased, holes_of, root_at, found) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); expression_paths(expr, span, names, unaliased, holes_of, root_at, found) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); expression_paths(base, span, names, unaliased, holes_of, root_at, found) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); expression_paths(base, span, names, unaliased, holes_of, root_at, found) },
        Expr::Index { base, index } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            expression_paths(base, span, names, unaliased, holes_of, root_at, found);
            expression_paths(index, span, names, unaliased, holes_of, root_at, found);
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            expression_paths(start, span, names, unaliased, holes_of, root_at, found);
            expression_paths(end, span, names, unaliased, holes_of, root_at, found);
        },
        Expr::Tuple(parts) => { for part in parts.iter() { expression_paths(part, span, names, unaliased, holes_of, root_at, found); } },
        Expr::Coalesce { value, fallback } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            expression_paths(value, span, names, unaliased, holes_of, root_at, found);
            expression_paths(fallback, span, names, unaliased, holes_of, root_at, found);
        },
        Expr::TryCatch { expr, .. } => { let expr = nikaia_std::boxed::open(expr); expression_paths(expr, span, names, unaliased, holes_of, root_at, found) },
        Expr::If { cond, .. } => { let cond = nikaia_std::boxed::open(cond); expression_paths(cond, span, names, unaliased, holes_of, root_at, found) },
        Expr::Match { value, arms } => {
            let value = nikaia_std::boxed::open(value);
            expression_paths(value, span, names, unaliased, holes_of, root_at, found);
            for arm in arms.iter() {
                maybe_expression_paths((arm.guard).as_ref(), span, names, unaliased, holes_of, root_at, found);
                expression_paths(&arm.body, span, names, unaliased, holes_of, root_at, found);
            }
        },
        Expr::StructLit { fields, .. } => { for field in fields.iter() { maybe_expression_paths((field.value).as_ref(), span, names, unaliased, holes_of, root_at, found); } },
        Expr::ListLit { items, .. } => { for item in items.iter() { expression_paths(item, span, names, unaliased, holes_of, root_at, found); } },
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            expression_paths(base, span, names, unaliased, holes_of, root_at, found);
            for field in fields.iter() { maybe_expression_paths((field.value).as_ref(), span, names, unaliased, holes_of, root_at, found); }
        },
        Expr::Return(value) => { let value = nikaia_std::boxed::open(value); maybe_expression_paths((value).as_ref(), span, names, unaliased, holes_of, root_at, found) },
        Expr::Select(arms) => { for arm in arms.iter() { expression_paths(&arm.value, span, names, unaliased, holes_of, root_at, found); } },
        _ => { },
    }
}

fn statement_blocks(stmt: &Stmt, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, found: &mut Walked) {
    match stmt {
        Stmt::For { body, .. } => block_names(body, names, unaliased, holes_of, root_at, found),
        Stmt::While { body, .. } => block_names(body, names, unaliased, holes_of, root_at, found),
        Stmt::Let { value, .. } => expression_blocks(value, names, unaliased, holes_of, root_at, found),
        Stmt::Comptime { value, .. } => expression_blocks(value, names, unaliased, holes_of, root_at, found),
        Stmt::Expr(value) => expression_blocks(value, names, unaliased, holes_of, root_at, found),
        Stmt::Assign { target, value, .. } => {
            expression_blocks(target, names, unaliased, holes_of, root_at, found);
            expression_blocks(value, names, unaliased, holes_of, root_at, found);
        },
        Stmt::Return(value) => { expression_blocks(match value { Some(__nikaia_value) => __nikaia_value, None => return }, names, unaliased, holes_of, root_at, found); },
        _ => { },
    }
}

fn expression_blocks(expr: &Expr, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, found: &mut Walked) {
    match expr {
        Expr::Block(block) => block_names(block, names, unaliased, holes_of, root_at, found),
        Expr::Unsafe(block) => block_names(block, names, unaliased, holes_of, root_at, found),
        Expr::Overlap(block) => block_names(block, names, unaliased, holes_of, root_at, found),
        Expr::Closure { body, .. } => block_names(body, names, unaliased, holes_of, root_at, found),
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            expression_blocks(func, names, unaliased, holes_of, root_at, found);
            for arg in args.iter() { expression_blocks(arg, names, unaliased, holes_of, root_at, found); }
            for setting in config.iter() { expression_blocks(&setting.value, names, unaliased, holes_of, root_at, found); }
        },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            expression_blocks(receiver, names, unaliased, holes_of, root_at, found);
            for arg in args.iter() { expression_blocks(arg, names, unaliased, holes_of, root_at, found); }
            for setting in config.iter() { expression_blocks(&setting.value, names, unaliased, holes_of, root_at, found); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            expression_blocks(receiver, names, unaliased, holes_of, root_at, found);
            for arg in args.iter() { expression_blocks(arg, names, unaliased, holes_of, root_at, found); }
            for setting in config.iter() { expression_blocks(&setting.value, names, unaliased, holes_of, root_at, found); }
        },
        Expr::If { then_branch, else_branch, .. } => {
            block_names(then_branch, names, unaliased, holes_of, root_at, found);
            block_names(match else_branch { Some(__nikaia_value) => __nikaia_value, None => return }, names, unaliased, holes_of, root_at, found);
        },
        Expr::TryCatch { expr, handler } => {
            let expr = nikaia_std::boxed::open(expr);
            expression_blocks(expr, names, unaliased, holes_of, root_at, found);
            block_names(handler, names, unaliased, holes_of, root_at, found);
        },
        Expr::Match { arms, .. } => { for arm in arms.iter() { expression_blocks(&arm.body, names, unaliased, holes_of, root_at, found); } },
        Expr::Select(arms) => { for arm in arms.iter() { block_names(&arm.body, names, unaliased, holes_of, root_at, found); } },
        _ => { },
    }
}

fn path_name(segments: &[winnow_grammar::Symbol], names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String) -> String {
    let mut name = unaliased(names.resolve(*nikaia_std::index::get(&segments, 0)));
    for k in 1..segments.len() as i64 {
        let segment = names.resolve(*nikaia_std::index::get(&segments, (k) as usize));
        name = format!("{}::{}", name, segment);
    }
    name
}

fn named_at(name: String, span: &Span) -> Seen { Seen::Path { name, span: span.clone() } }

fn a_named_call(func: &Expr, args: &[Expr], span: &Span, names: &winnow_grammar::InternerContext, root_at: &impl Fn(&str) -> i64, found: &mut Walked) {
    let name = match func {
        Expr::Variable(name) => { let name = *name; names.resolve(name).to_owned() },
        Expr::Path(segments) => written_path(names, segments),
        _ => String::from(""),
    };
    if name.is_empty() {
        found.seen.push(Seen::Opaque { span: span.clone() });
        return;
    }
    let at = root_at(&name);
    let mut wrote: Option<Wrote> = None;
    if at >= 0 && at < args.len() as i64 { wrote = written_root(names, nikaia_std::index::get(&args, nikaia_std::index::at(at))); }
    found.seen.push(Seen::Call { name, wrote, span: span.clone() });
}


// --- http1.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Field<'a> {
    pub name: &'a str,
    pub value: &'a str,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Line<'a> {
    Field(Field<'a>),
    Skip,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Written<'a> {
    pub words: Vec<&'a str>,
    pub fields: Vec<Field<'a>>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Header<'a> {
    pub name: String,
    pub value: &'a str,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Read<'a> {
    pub refused: &'a str,
    pub method: &'a str,
    pub target: &'a str,
    pub length: i64,
    pub keep_alive: bool,
    pub headers: Vec<Header<'a>>,
}

grammar! {
    grammar Http1 {

        rule WS =
            ""
            -> { }

        pub rule head -> Written<'a> =
            words:__nikaia_list<&'a str>(item = WORD, sep = " ") "\r\n" lines:line* "\r\n" eof
            -> { Written { words, fields: fields(lines) } }

        rule WORD -> &'a str =
            w:text(WORD_PIECE*)
            -> { w }

        rule WORD_PIECE =
            not(" ") not("\r\n") any
            -> { }

        rule line -> Line<'a> =
            n:text(NAME_PIECE*) ":" v:text(REST_PIECE*) "\r\n"
            -> { Line::Field(Field { name: n, value: v }) }
          | OTHER "\r\n"
            -> { Line::Skip }

        rule NAME_PIECE =
            not(":") not("\r\n") any
            -> { }

        rule REST_PIECE =
            not("\r\n") any
            -> { }

        rule OTHER =
            REST_PIECE+
            -> { }

        rule __nikaia_list<T>(item: Rule<T>, sep) -> Vec<T> =
          first:item rest:__nikaia_list_more<T>(item = item, sep = sep)*
            -> { let mut all = vec![first]; all.extend(rest); all }
        | ""
            -> { Vec::new() }

        rule __nikaia_list_more<T>(item: Rule<T>, sep) -> T =
          sep x:item
            -> { x }
    }
}

fn fields(lines: Vec<Line<'_>>) -> Vec<Field<'_>> {
    let mut all = Vec::new();
    for line in lines.into_iter() {
        match line {
            Line::Field(f) => { all.push(f); },
            Line::Skip => { },
        }
    }
    all
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn read_head<'a>(written: &Written<'a>) -> Read<'a> {
    if written.words.len() < 3 { return refused("400 a request line that is not three words"); }
    let method = *nikaia_std::index::get(&written.words, 0);
    let target = *nikaia_std::index::get(&written.words, 1);
    if !(*nikaia_std::index::get(&written.words, 2)).starts_with("HTTP/1.") { return refused("400 a version this does not speak"); }
    if method != "GET" && method != "POST" { return refused("400 a method this does not answer"); }
    let mut length: i64 = 0;
    let mut keep_alive = false;
    let mut headers: Vec<Header<'_>> = vec![];
    for field in written.fields.iter() {
        let name = field.name.trim().to_lowercase();
        let value = field.value.trim();
        if name == "content-length" {
            let n = nikaia_std::index::or(text::parse_i64(value), || -1);
            if n < 0 { return refused("400 a content-length that is not a count"); }
            length = n;
        } else if name == "connection" { keep_alive = value.to_lowercase() == "keep-alive"; } else if name == "transfer-encoding" { return refused("400 a transfer-encoding this does not speak"); }
        headers.push(Header { name, value });
    }
    Read { refused: "", method, target, length, keep_alive, headers }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn refused(why: &str) -> Read<'_> { Read { refused: why, method: "", target: "", length: 0, keep_alive: false, headers: vec![] } }


// --- integers.nika ---

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Integer {
    pub magnitude: u64,
    pub negative: bool,
}

pub fn integer(magnitude: u64, negative: bool) -> Integer { Integer { magnitude, negative: negative && magnitude != 0u64 } }

pub fn integer_of_count(n: i64) -> Integer {
    if n < 0 { return integer(u64::try_from(0 - (n + 1)).unwrap_or_else(|_| panic!("the value does not fit in an `u64`")) + 1u64, true); }
    integer(u64::try_from(n).unwrap_or_else(|_| panic!("the value does not fit in an `u64`")), false)
}

pub fn integer_as_count(n: &Integer) -> Option<i64> {
    if !n.negative { return i64::try_from(n.magnitude).ok(); }
    let below = match i64::try_from(n.magnitude - 1u64).ok() { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(-1 - below)
}

pub fn integer_text(n: &Integer) -> String {
    if n.negative { return format!("-{}", n.magnitude); }
    format!("{}", n.magnitude)
}

pub fn integer_negated(n: &Integer) -> Integer { integer(n.magnitude, !n.negative) }

pub fn integer_sum(a: &Integer, b: &Integer) -> Option<Integer> {
    if a.negative == b.negative {
        let sum = match a.magnitude.checked_add(b.magnitude) { Some(__nikaia_value) => __nikaia_value, None => return None };
        return Some(integer(sum, a.negative));
    }
    if a.magnitude >= b.magnitude { return Some(integer(a.magnitude - b.magnitude, a.negative)); }
    Some(integer(b.magnitude - a.magnitude, b.negative))
}

pub fn integer_difference(a: &Integer, b: &Integer) -> Option<Integer> { integer_sum(a, &integer_negated(b)) }

pub fn integer_product(a: &Integer, b: &Integer) -> Option<Integer> {
    let product = match a.magnitude.checked_mul(b.magnitude) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(integer(product, a.negative != b.negative))
}

pub fn integer_quotient(a: &Integer, b: &Integer, remainder: bool) -> Option<Integer> {
    if remainder {
        let left = match a.magnitude.checked_rem(b.magnitude) { Some(__nikaia_value) => __nikaia_value, None => return None };
        return Some(integer(left, a.negative));
    }
    let quotient = match a.magnitude.checked_div(b.magnitude) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(integer(quotient, a.negative != b.negative))
}

pub fn integer_order(a: &Integer, b: &Integer) -> i64 {
    if a.negative != b.negative { return if a.negative { -1 } else { 1 }; }
    if a.magnitude == b.magnitude { return 0; }
    let larger = a.magnitude > b.magnitude;
    if larger != a.negative { return 1; }
    -1
}

pub fn integer_bits(a: &Integer, b: &Integer, op: &str) -> Option<Integer> {
    if !a.negative && !b.negative {
        let x = a.magnitude;
        let y = b.magnitude;
        if op == "&" { return Some(integer(x & y, false)); }
        if op == "|" { return Some(integer(x | y, false)); }
        return Some(integer(x ^ y, false));
    }
    let x = match integer_as_count(a) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let y = match integer_as_count(b) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if op == "&" { return Some(integer_of_count(x & y)); }
    if op == "|" { return Some(integer_of_count(x | y)); }
    Some(integer_of_count(x ^ y))
}

pub fn integer_shifted(a: &Integer, b: &Integer, left: bool) -> Option<Integer> {
    if b.negative || b.magnitude >= 64u64 { return None; }
    let count = i64::try_from(b.magnitude).unwrap_or_else(|_| panic!("the value does not fit in an `i64`"));
    if left {
        let mut magnitude = a.magnitude;
        for _ in 0..count { magnitude = match magnitude.checked_mul(2u64) { Some(__nikaia_value) => __nikaia_value, None => return None }; }
        return Some(integer(magnitude, a.negative));
    }
    if !a.negative {
        let mut magnitude = a.magnitude;
        for _ in 0..count { magnitude /= 2; }
        return Some(integer(magnitude, false));
    }
    let mut value = match integer_as_count(a) { Some(__nikaia_value) => __nikaia_value, None => return None };
    for _ in 0..count { if value % 2 != 0 { value = (value - 1) / 2; } else { value /= 2; } }
    Some(integer_of_count(value))
}


// --- keep.nika ---

#[derive(Debug, Clone, PartialEq)]
pub struct KeepContext {
    pub borrowing: collections::BTreeSet<String>,
    pub structs: collections::BTreeMap<String, DeclaredStruct>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct DeclaredStruct {
    pub generic: bool,
    pub fields: Vec<(String, Type)>,
}

impl KeepContext {
    pub fn of(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>]) -> KeepContext {
        let mut structs: collections::BTreeMap<String, DeclaredStruct> = collections::BTreeMap::new();
        for item in items.iter() {
            match &item.node {
                Item::Struct { name, generics, fields, .. } => {
                    let name = *name;
                    let mut written: Vec<(String, Type)> = vec![];
                    for field in fields.iter() { written.push((names.resolve(field.name).to_owned(), field.ty.clone())); }
                    structs.insert(names.resolve(name).to_owned(), DeclaredStruct { generic: !generics.is_empty(), fields: written });
                },
                _ => { },
            }
        }
        KeepContext { borrowing: borrowing_types(names, items), structs }
    }
    pub fn not_held(&self, names: &winnow_grammar::InternerContext, ty: &Type, seen: &mut Vec<String>) -> Option<String> {
        let name = names.resolve(ty.name);
        if ty.is_view {
            if name == "String" && ty.generics.is_empty() { return None; }
            return Some(format!("a view of `{}` rather than of text", name));
        }
        if ty.is_tuple && self.carries(names, ty) { return Some(String::from("a tuple of views")); }
        if self.structs.contains_key(name) && self.borrowing.contains(name) { return self.struct_not_held(names, name, seen); }
        if !self.carries(names, ty) { return None; }
        if name == "Vec" || name == "List" {
            for argument in ty.generics.iter() {
                let why = self.not_held(names, argument, seen);
                if why.is_some() { return why; }
            }
            return None;
        }
        Some(format!("a `{}` of views", name))
    }
    pub fn struct_not_held(&self, names: &winnow_grammar::InternerContext, name: &str, seen: &mut Vec<String>) -> Option<String> {
        let declared = match *nikaia_std::index::get(&self.structs, name) { Some(__nikaia_value) => __nikaia_value, None => return None };
        if declared.generic { return Some(format!("`{}`, a struct of views with type parameters", name)); }
        for one in seen.iter() { if one == name { return None; } }
        seen.push(name.to_owned());
        for (field, ty) in declared.fields.iter() {
            let why = self.not_held(names, ty, seen);
            if why.is_some() {
                let held = nikaia_std::index::or(why, || "".into());
                return Some(format!("`{}.{}`, which holds {}", name, field, held));
            }
        }
        None
    }
    pub fn carries(&self, names: &winnow_grammar::InternerContext, ty: &Type) -> bool {
        if ty.is_view || self.borrowing.contains(names.resolve(ty.name)) { return true; }
        for argument in ty.generics.iter() { if self.carries(names, argument) { return true; } }
        false
    }
}

pub fn struct_in(names: &winnow_grammar::InternerContext, ty: &Type, borrowing: &collections::BTreeSet<String>) -> Option<String> {
    let name = names.resolve(ty.name);
    if borrowing.contains(name) { return Some(name.to_owned()); }
    for argument in ty.generics.iter() {
        let found = struct_in(names, argument, borrowing);
        if found.is_some() { return found; }
    }
    None
}

pub fn names_a_struct_of_views(names: &winnow_grammar::InternerContext, ty: &Type, borrowing: &collections::BTreeSet<String>) -> bool {
    if borrowing.contains(names.resolve(ty.name)) { return true; }
    for argument in ty.generics.iter() { if names_a_struct_of_views(names, argument, borrowing) { return true; } }
    false
}

pub fn a_ledger_type_with_a_view(ty: &Ty) -> bool {
    match ty {
        Ty::Named { view, args, .. } => { let view = *view; view || any_with_a_view(args) },
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); a_ledger_type_with_a_view(inner) },
        Ty::Tuple(parts) => any_with_a_view(parts),
        Ty::Unknown => true,
        _ => false,
    }
}

fn any_with_a_view(types: &[Ty]) -> bool {
    for one in types.iter() { if a_ledger_type_with_a_view(one) { return true; } }
    false
}

pub fn takes_a_keep(contract: &FnContract) -> bool {
    for held in contract.views.iter() { if held.state == State::Tethered { return true; } }
    false
}

pub fn keeping_method_key(ledger: &Ledger, target: Option<&str>, on_self: bool, method: &str) -> Option<String> {
    if on_self && target.is_some() {
        let owner = nikaia_std::index::or(target, || "");
        let key = format!("{}::{}", owner, method);
        let contract = match *nikaia_std::index::get(&ledger.functions, &key) { Some(__nikaia_value) => __nikaia_value, None => return None };
        if takes_a_keep(contract) { return Some(key); }
        return None;
    }
    let suffix = format!("::{}", method);
    let mut found: Option<String> = None;
    for (key, contract) in ledger.functions.iter() {
        if key.ends_with(&suffix) && takes_a_keep(contract) {
            if found.is_some() { return None; }
            found = Some(key.to_owned());
        }
    }
    found
}

pub fn written_callee(names: &winnow_grammar::InternerContext, func: &Expr, unaliased: &impl Fn(&str) -> String) -> Option<String> {
    match func {
        Expr::Variable(name) => { let name = *name; Some(names.resolve(name).to_owned()) },
        Expr::Path(segments) => Some(unaliased(&joined_segments(segments, names))),
        _ => None,
    }
}

pub fn root_of(names: &winnow_grammar::InternerContext, expr: &Expr) -> Option<String> {
    match expr {
        Expr::Variable(name) => { let name = *name; Some(names.resolve(name).to_owned()) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); root_of(names, base) },
        Expr::Index { base, .. } => { let base = nikaia_std::boxed::open(base); root_of(names, base) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); root_of(names, base) },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); root_of(names, expr) },
        _ => None,
    }
}

pub fn taken_from(names: &winnow_grammar::InternerContext, value: &Expr) -> Option<String> {
    match value {
        Expr::MethodCall { receiver, method, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; if hands_back_what_it_removes(names.resolve(method)) { root_of(names, receiver) } else { None } },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); taken_from(names, inner) },
        Expr::TryCatch { expr, .. } => { let expr = nikaia_std::boxed::open(expr); taken_from(names, expr) },
        _ => None,
    }
}

const OWNED: [&str; 14] = ["to_owned", "clone_text", "len", "is_empty", "count", "starts_with", "ends_with", "contains", "contains_key", "parse", "to_uppercase", "to_lowercase", "join", "repeat"];

const KEEPS: [&str; 6] = ["push", "insert", "extend", "append", "push_front", "push_back"];

const SHEDS: [&str; 9] = ["clear", "remove", "drain", "pop", "truncate", "retain", "pop_front", "pop_back", "take"];

const TAKES: [&str; 6] = ["remove", "pop", "pop_front", "pop_back", "swap_remove", "take"];

pub fn hands_back_its_own(method: &str) -> bool {
    for one in OWNED.iter() {
        let one = *one;
        if one == method { return true; }
    }
    false
}

pub fn keeps_what_it_is_given(method: &str) -> bool {
    for one in KEEPS.iter() {
        let one = *one;
        if one == method { return true; }
    }
    false
}

pub fn drops_entries(method: &str) -> bool {
    for one in SHEDS.iter() {
        let one = *one;
        if one == method { return true; }
    }
    false
}

pub fn hands_back_what_it_removes(method: &str) -> bool {
    for one in TAKES.iter() {
        let one = *one;
        if one == method { return true; }
    }
    false
}

pub fn capitalised(text: &str) -> String {
    let mut out: String = String::from("");
    let mut first = true;
    for c in text.chars() {
        if first {
            let mut letter: String = String::from("");
            letter.push(c);
            out.push_str(&letter.to_uppercase());
            first = false;
        } else { out.push(c); }
    }
    out
}


// --- keeps.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct KeepsBody {
    pub parameters: collections::BTreeSet<String>,
    pub lent: collections::BTreeSet<String>,
    pub fields: collections::BTreeMap<String, collections::BTreeMap<String, Ty>>,
    pub returns_a_view: bool,
    pub hands_back_its_last: bool,
    pub unresolved: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct KeepsWalk {
    uses: Uses,
    aliases: collections::BTreeMap<String, collections::BTreeSet<String>>,
}

pub fn uses_in(body: &Block, interner: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, context: &KeepsBody, own: &Ledger, library: &Ledger) -> Uses {
    let mut walk = KeepsWalk { uses: Uses { kept: collections::BTreeSet::new(), passed: vec![] }, aliases: collections::BTreeMap::new() };
    keeps_block(body, interner, holes_of, context, own, library, &mut walk);
    if context.hands_back_its_last && !body.stmts.is_empty() {
        match &nikaia_std::index::get(&body.stmts, nikaia_std::index::at(body.stmts.len() as i64 - 1)).node {
            Stmt::Expr(value) => hand_over(value, interner, context, &mut walk),
            _ => { },
        }
    }
    walk.uses
}

fn keeps_block(block: &Block, interner: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, context: &KeepsBody, own: &Ledger, library: &Ledger, walk: &mut KeepsWalk) { for stmt in block.stmts.iter() { keeps_statement(&stmt.node, interner, holes_of, context, own, library, walk); } }

fn keeps_statement(stmt: &Stmt, interner: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, context: &KeepsBody, own: &Ledger, library: &Ledger, walk: &mut KeepsWalk) {
    match stmt {
        Stmt::Assign { value, .. } => hand_over(value, interner, context, walk),
        Stmt::Return(value) => { if !context.returns_a_view { hand_over_maybe((value).as_ref(), interner, context, walk); } },
        Stmt::Let { names, value, .. } => {
            let reached = reached_of(value, interner, context, &walk.aliases);
            if !reached.is_empty() { for bound in names.iter() { alias(interner.resolve(*bound).to_owned(), &reached, walk); } }
        },
        _ => { },
    }
    keeps_statement_parts(stmt, interner, holes_of, context, own, library, walk);
}

fn keeps_statement_parts(stmt: &Stmt, interner: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, context: &KeepsBody, own: &Ledger, library: &Ledger, walk: &mut KeepsWalk) {
    match stmt {
        Stmt::Let { value, .. } => keeps_expression(value, interner, holes_of, context, own, library, &mut walk.uses),
        Stmt::Comptime { value, .. } => keeps_expression(value, interner, holes_of, context, own, library, &mut walk.uses),
        Stmt::Assign { target, value, .. } => {
            keeps_expression(target, interner, holes_of, context, own, library, &mut walk.uses);
            keeps_expression(value, interner, holes_of, context, own, library, &mut walk.uses);
        },
        Stmt::For { iter, .. } => keeps_expression(iter, interner, holes_of, context, own, library, &mut walk.uses),
        Stmt::While { cond, .. } => keeps_expression(cond, interner, holes_of, context, own, library, &mut walk.uses),
        Stmt::Return(value) => {
            let returned = match value { Some(__nikaia_value) => __nikaia_value, None => return };
            keeps_expression(returned, interner, holes_of, context, own, library, &mut walk.uses);
        },
        Stmt::Expr(value) => keeps_expression(value, interner, holes_of, context, own, library, &mut walk.uses),
        _ => { },
    }
    match stmt {
        Stmt::For { body, .. } => keeps_block(body, interner, holes_of, context, own, library, walk),
        Stmt::While { body, .. } => keeps_block(body, interner, holes_of, context, own, library, walk),
        Stmt::Let { value, .. } => keeps_blocks_in(value, interner, holes_of, context, own, library, walk),
        Stmt::Comptime { value, .. } => keeps_blocks_in(value, interner, holes_of, context, own, library, walk),
        Stmt::Expr(value) => keeps_blocks_in(value, interner, holes_of, context, own, library, walk),
        Stmt::Assign { target, value, .. } => {
            keeps_blocks_in(target, interner, holes_of, context, own, library, walk);
            keeps_blocks_in(value, interner, holes_of, context, own, library, walk);
        },
        Stmt::Return(value) => {
            let returned = match value { Some(__nikaia_value) => __nikaia_value, None => return };
            keeps_blocks_in(returned, interner, holes_of, context, own, library, walk);
        },
        _ => { },
    }
}

fn alias(name: String, reached: &collections::BTreeSet<String>, walk: &mut KeepsWalk) {
    let mut all: collections::BTreeSet<String> = collections::BTreeSet::new();
    if walk.aliases.contains_key(&name) {
        let before = match *nikaia_std::index::get(&walk.aliases, &name) { Some(__nikaia_value) => __nikaia_value, None => return };
        for one in before.iter() { all.insert(one.to_owned()); }
    }
    for one in reached.iter() { all.insert(one.to_owned()); }
    walk.aliases.insert(name, all);
}

fn hand_over_maybe(expr: Option<&Expr>, interner: &winnow_grammar::InternerContext, context: &KeepsBody, walk: &mut KeepsWalk) { hand_over(match expr { Some(__nikaia_value) => __nikaia_value, None => return }, interner, context, walk); }

fn hand_over(expr: &Expr, interner: &winnow_grammar::InternerContext, context: &KeepsBody, walk: &mut KeepsWalk) { for name in reached_of(expr, interner, context, &walk.aliases) { walk.uses.kept.insert(name); } }

fn reached_of(expr: &Expr, interner: &winnow_grammar::InternerContext, context: &KeepsBody, aliases: &collections::BTreeMap<String, collections::BTreeSet<String>>) -> collections::BTreeSet<String> {
    let mut found: collections::BTreeSet<String> = collections::BTreeSet::new();
    match expr {
        Expr::If { then_branch, else_branch, .. } => {
            reached_by_last(then_branch, interner, context, aliases, &mut found);
            let otherwise = match else_branch { Some(__nikaia_value) => __nikaia_value, None => return found };
            reached_by_last(otherwise, interner, context, aliases, &mut found);
        },
        Expr::Match { arms, .. } => { for arm in arms.iter() { for name in reached_of(&arm.body, interner, context, aliases) { found.insert(name); } } },
        Expr::Block(block) => reached_by_last(block, interner, context, aliases, &mut found),
        Expr::Variable(ident) => {
            let ident = *ident;
            let name = interner.resolve(ident).to_owned();
            if context.parameters.contains(&name) { found.insert(name.to_owned()); }
            let aliased = match *nikaia_std::index::get(&aliases, &name) { Some(__nikaia_value) => __nikaia_value, None => return found };
            for one in aliased.iter() { found.insert(one.to_owned()); }
        },
        Expr::Field { base, name } => {
            let base = nikaia_std::boxed::open(base); let name = *name;
            let parameter = match parameter_named(base, interner, context) { Some(__nikaia_value) => __nikaia_value, None => return found };
            if parameter != "self" && !a_field_that_copies(&parameter, interner.resolve(name), context) { found.insert(parameter); }
        },
        _ => { },
    }
    found
}

fn reached_by_last(block: &Block, interner: &winnow_grammar::InternerContext, context: &KeepsBody, aliases: &collections::BTreeMap<String, collections::BTreeSet<String>>, found: &mut collections::BTreeSet<String>) {
    if block.stmts.is_empty() { return; }
    match &nikaia_std::index::get(&block.stmts, nikaia_std::index::at(block.stmts.len() as i64 - 1)).node {
        Stmt::Expr(value) => { for name in reached_of(value, interner, context, aliases) { found.insert(name); } },
        _ => { },
    }
}

fn keeps_expression(expr: &Expr, interner: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, context: &KeepsBody, own: &Ledger, library: &Ledger, uses: &mut Uses) {
    classify(expr, interner, holes_of, context, own, library, uses);
    for hole in holes_of(expr) { keeps_expression(&hole, interner, holes_of, context, own, library, uses); }
    match expr {
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            keeps_expression(func, interner, holes_of, context, own, library, uses);
            keeps_expressions(args, interner, holes_of, context, own, library, uses);
            for setting in config.iter() { keeps_expression(&setting.value, interner, holes_of, context, own, library, uses); }
        },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            keeps_expression(receiver, interner, holes_of, context, own, library, uses);
            keeps_expressions(args, interner, holes_of, context, own, library, uses);
            for setting in config.iter() { keeps_expression(&setting.value, interner, holes_of, context, own, library, uses); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            keeps_expression(receiver, interner, holes_of, context, own, library, uses);
            keeps_expressions(args, interner, holes_of, context, own, library, uses);
            for setting in config.iter() { keeps_expression(&setting.value, interner, holes_of, context, own, library, uses); }
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            keeps_expression(lhs, interner, holes_of, context, own, library, uses);
            keeps_expression(rhs, interner, holes_of, context, own, library, uses);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); keeps_expression(expr, interner, holes_of, context, own, library, uses) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); keeps_expression(inner, interner, holes_of, context, own, library, uses) },
        Expr::Throw(inner) => { let inner = nikaia_std::boxed::open(inner); keeps_expression(inner, interner, holes_of, context, own, library, uses) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); keeps_expression(expr, interner, holes_of, context, own, library, uses) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); keeps_expression(base, interner, holes_of, context, own, library, uses) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); keeps_expression(base, interner, holes_of, context, own, library, uses) },
        Expr::Index { base, index } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            keeps_expression(base, interner, holes_of, context, own, library, uses);
            keeps_expression(index, interner, holes_of, context, own, library, uses);
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            keeps_expression(start, interner, holes_of, context, own, library, uses);
            keeps_expression(end, interner, holes_of, context, own, library, uses);
        },
        Expr::Tuple(items) => keeps_expressions(items, interner, holes_of, context, own, library, uses),
        Expr::Coalesce { value, fallback } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            keeps_expression(value, interner, holes_of, context, own, library, uses);
            keeps_expression(fallback, interner, holes_of, context, own, library, uses);
        },
        Expr::TryCatch { expr, .. } => { let expr = nikaia_std::boxed::open(expr); keeps_expression(expr, interner, holes_of, context, own, library, uses) },
        Expr::If { cond, .. } => { let cond = nikaia_std::boxed::open(cond); keeps_expression(cond, interner, holes_of, context, own, library, uses) },
        Expr::Match { value, arms } => {
            let value = nikaia_std::boxed::open(value);
            keeps_expression(value, interner, holes_of, context, own, library, uses);
            for arm in arms.iter() {
                keeps_maybe((arm.guard).as_ref(), interner, holes_of, context, own, library, uses);
                keeps_expression(&arm.body, interner, holes_of, context, own, library, uses);
            }
        },
        Expr::StructLit { fields, .. } => { for field in fields.iter() { keeps_maybe((field.value).as_ref(), interner, holes_of, context, own, library, uses); } },
        Expr::ListLit { items, .. } => keeps_expressions(items, interner, holes_of, context, own, library, uses),
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            keeps_expression(base, interner, holes_of, context, own, library, uses);
            for field in fields.iter() { keeps_maybe((field.value).as_ref(), interner, holes_of, context, own, library, uses); }
        },
        Expr::Return(value) => { let value = nikaia_std::boxed::open(value); keeps_maybe((value).as_ref(), interner, holes_of, context, own, library, uses) },
        Expr::Select(arms) => { for arm in arms.iter() { keeps_expression(&arm.value, interner, holes_of, context, own, library, uses); } },
        _ => { },
    }
}

fn keeps_expressions(items: &[Expr], interner: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, context: &KeepsBody, own: &Ledger, library: &Ledger, uses: &mut Uses) { for item in items.iter() { keeps_expression(item, interner, holes_of, context, own, library, uses); } }

fn keeps_maybe(expr: Option<&Expr>, interner: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, context: &KeepsBody, own: &Ledger, library: &Ledger, uses: &mut Uses) { keeps_expression(match expr { Some(__nikaia_value) => __nikaia_value, None => return }, interner, holes_of, context, own, library, uses); }

fn keeps_blocks_in(expr: &Expr, interner: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, context: &KeepsBody, own: &Ledger, library: &Ledger, walk: &mut KeepsWalk) {
    match expr {
        Expr::Block(block) => keeps_block(block, interner, holes_of, context, own, library, walk),
        Expr::Unsafe(block) => keeps_block(block, interner, holes_of, context, own, library, walk),
        Expr::Overlap(block) => keeps_block(block, interner, holes_of, context, own, library, walk),
        Expr::Closure { body, .. } => keeps_block(body, interner, holes_of, context, own, library, walk),
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            keeps_blocks_in(func, interner, holes_of, context, own, library, walk);
            for arg in args.iter() { keeps_blocks_in(arg, interner, holes_of, context, own, library, walk); }
            for setting in config.iter() { keeps_blocks_in(&setting.value, interner, holes_of, context, own, library, walk); }
        },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            keeps_blocks_in(receiver, interner, holes_of, context, own, library, walk);
            for arg in args.iter() { keeps_blocks_in(arg, interner, holes_of, context, own, library, walk); }
            for setting in config.iter() { keeps_blocks_in(&setting.value, interner, holes_of, context, own, library, walk); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            keeps_blocks_in(receiver, interner, holes_of, context, own, library, walk);
            for arg in args.iter() { keeps_blocks_in(arg, interner, holes_of, context, own, library, walk); }
            for setting in config.iter() { keeps_blocks_in(&setting.value, interner, holes_of, context, own, library, walk); }
        },
        Expr::If { then_branch, else_branch, .. } => {
            keeps_block(then_branch, interner, holes_of, context, own, library, walk);
            keeps_block(match else_branch { Some(__nikaia_value) => __nikaia_value, None => return }, interner, holes_of, context, own, library, walk);
        },
        Expr::TryCatch { expr, handler } => {
            let expr = nikaia_std::boxed::open(expr);
            keeps_blocks_in(expr, interner, holes_of, context, own, library, walk);
            keeps_block(handler, interner, holes_of, context, own, library, walk);
        },
        Expr::Match { arms, .. } => { for arm in arms.iter() { keeps_blocks_in(&arm.body, interner, holes_of, context, own, library, walk); } },
        Expr::Select(arms) => { for arm in arms.iter() { keeps_block(&arm.body, interner, holes_of, context, own, library, walk); } },
        _ => { },
    }
}

fn classify(expr: &Expr, interner: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, context: &KeepsBody, own: &Ledger, library: &Ledger, uses: &mut Uses) {
    match expr {
        Expr::StructLit { fields, .. } => {
            for field in fields.iter() {
                if field.value.is_none() {
                    let named = interner.resolve(field.name).to_owned();
                    if context.parameters.contains(&named) { uses.kept.insert(named); }
                } else { keep_part((field.value).as_ref(), interner, context, uses); }
            }
        },
        Expr::ListLit { items, .. } => { for item in items.iter() { keep_part(Some(item), interner, context, uses); } },
        Expr::Tuple(items) => { for item in items.iter() { keep_part(Some(item), interner, context, uses); } },
        Expr::Coalesce { value, .. } => { let value = nikaia_std::boxed::open(value); keep_named(value, interner, context, uses) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); keep_named(base, interner, context, uses) },
        Expr::Try(value) => { let value = nikaia_std::boxed::open(value); keep_named(value, interner, context, uses) },
        Expr::Match { value, .. } => {
            let value = nikaia_std::boxed::open(value);
            let name = match parameter_named(value, interner, context) { Some(__nikaia_value) => __nikaia_value, None => return };
            if !context.lent.contains(&name) { uses.kept.insert(name); }
        },
        Expr::Spawn { body, .. } => { let body = nikaia_std::boxed::open(body); keep_what_a_task_names(body, interner, holes_of, context, uses) },
        Expr::Call { func, args, .. } => {
            let func = nikaia_std::boxed::open(func);
            let callee = resolved_callee(func, interner, own, library);
            for at in 0..args.len() as i64 { keep_argument(nikaia_std::index::get(&args, nikaia_std::index::at(at)), (callee).as_deref(), at, interner, context, uses); }
        },
        Expr::MethodCall { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            keep_receiver(receiver, interner.resolve(method), interner, context, own, library, uses);
            keep_method_arguments(args, interner.resolve(method), interner, context, own, library, uses);
        },
        Expr::SafeMethod { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            keep_receiver(receiver, interner.resolve(method), interner, context, own, library, uses);
            keep_method_arguments(args, interner.resolve(method), interner, context, own, library, uses);
        },
        _ => { },
    }
}

fn keep_argument(arg: &Expr, callee: Option<&str>, at: i64, interner: &winnow_grammar::InternerContext, context: &KeepsBody, uses: &mut Uses) {
    let parameter = match part_of_a_parameter(arg, interner, context) { Some(__nikaia_value) => __nikaia_value, None => return };
    if callee.is_none() {
        uses.kept.insert(parameter);
        return;
    }
    let known = match callee { Some(__nikaia_value) => __nikaia_value, None => return };
    uses.passed.push(Passed { parameter, callee: known.to_owned(), at });
}

fn keep_receiver(receiver: &Expr, method: &str, interner: &winnow_grammar::InternerContext, context: &KeepsBody, own: &Ledger, library: &Ledger, uses: &mut Uses) {
    let name = match parameter_named(receiver, interner, context) { Some(__nikaia_value) => __nikaia_value, None => return };
    let ours = receiver_taken_in(own, method);
    let theirs = receiver_taken_in(library, method);
    if context.unresolved || ours.hit || theirs.hit || !ours.any && !theirs.any { uses.kept.insert(name); }
}

fn takes_its_receiver(contract: &FnContract) -> bool {
    if contract.mutates { return true; }
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return true };
    if !signature.takes_a_receiver() { return true; }
    let subject = &nikaia_std::index::get(&signature.params, 0).1;
    if subject.is_a_view() { return false; }
    match subject {
        Ty::Named { .. } => moves(&subject),
        _ => true,
    }
}

fn keep_method_arguments(args: &[Expr], method: &str, interner: &winnow_grammar::InternerContext, context: &KeepsBody, own: &Ledger, library: &Ledger, uses: &mut Uses) {
    let ours = candidate_keys(own, method);
    for k in 0..args.len() as i64 {
        let name = match part_of_a_parameter(nikaia_std::index::get(&args, (k) as usize), interner, context) { Some(__nikaia_value) => __nikaia_value, None => continue };
        for key in ours.iter() { uses.passed.push(Passed { parameter: name.to_owned(), callee: key.to_owned(), at: k + 1 }); }
        let theirs = keeps_at_in(library, method, k + 1);
        if theirs.hit || ours.is_empty() && !theirs.any { uses.kept.insert(name); }
    }
}

fn candidate_keys(ledger: &Ledger, method: &str) -> Vec<String> {
    let suffix = format!("::{}", method);
    let mut keys: Vec<String> = vec![];
    for (key, contract) in ledger.functions.iter() { if key.ends_with(&suffix) && takes_self(contract) { keys.push(key.to_owned()); } }
    keys
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct CandidatesSay {
    any: bool,
    hit: bool,
}

fn receiver_taken_in(ledger: &Ledger, method: &str) -> CandidatesSay {
    let suffix = format!("::{}", method);
    let mut asked = CandidatesSay { any: false, hit: false };
    for (key, contract) in ledger.functions.iter() {
        if key.ends_with(&suffix) && takes_self(contract) {
            asked.any = true;
            asked.hit = asked.hit || takes_its_receiver(contract);
        }
    }
    asked
}

fn keeps_at_in(ledger: &Ledger, method: &str, at: i64) -> CandidatesSay {
    let suffix = format!("::{}", method);
    let mut asked = CandidatesSay { any: false, hit: false };
    for (key, contract) in ledger.functions.iter() {
        if key.ends_with(&suffix) && takes_self(contract) {
            asked.any = true;
            asked.hit = asked.hit || keeps_at(contract, at);
        }
    }
    asked
}

fn takes_self(contract: &FnContract) -> bool {
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return true };
    signature.takes_a_receiver()
}

fn keep_what_a_task_names(body: &Expr, interner: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, context: &KeepsBody, uses: &mut Uses) {
    let seen = match body {
        Expr::Closure { body, .. } => seen_in(body, interner, &name_as_it_is, holes_of, &no_root, true),
        Expr::Block(block) => seen_in(block, interner, &name_as_it_is, holes_of, &no_root, true),
        _ => {
            for name in context.parameters.iter() { uses.kept.insert(name.to_owned()); }
            return;
        },
    };
    for one in seen.iter() {
        match one {
            Seen::Spawn { .. } => {
                for name in context.parameters.iter() { uses.kept.insert(name.to_owned()); }
                return;
            },
            _ => { },
        }
    }
    for one in seen.iter() {
        match one {
            Seen::Name(name) => keep_if_a_parameter(name, context, uses),
            _ => { },
        }
    }
}

fn keep_if_a_parameter(name: &str, context: &KeepsBody, uses: &mut Uses) { if context.parameters.contains(name) { uses.kept.insert(name.to_owned()); } }

fn keep_named(expr: &Expr, interner: &winnow_grammar::InternerContext, context: &KeepsBody, uses: &mut Uses) { uses.kept.insert(match parameter_named(expr, interner, context) { Some(__nikaia_value) => __nikaia_value, None => return }); }

fn keep_part(expr: Option<&Expr>, interner: &winnow_grammar::InternerContext, context: &KeepsBody, uses: &mut Uses) { uses.kept.insert(match part_of_a_parameter(match expr { Some(__nikaia_value) => __nikaia_value, None => return }, interner, context) { Some(__nikaia_value) => __nikaia_value, None => return }); }

fn parameter_named(expr: &Expr, interner: &winnow_grammar::InternerContext, context: &KeepsBody) -> Option<String> {
    match expr {
        Expr::Variable(ident) => { let ident = *ident; match context.parameters.contains(interner.resolve(ident)) {
            true => Some(interner.resolve(ident).to_owned()),
            false => None,
        } },
        _ => None,
    }
}

fn part_of_a_parameter(expr: &Expr, interner: &winnow_grammar::InternerContext, context: &KeepsBody) -> Option<String> {
    match expr {
        Expr::Field { base, name } => {
            let base = nikaia_std::boxed::open(base); let name = *name;
            if parameter_named(base, interner, context).is_none() {
                let deeper = match part_of_a_parameter(base, interner, context) { Some(__nikaia_value) => __nikaia_value, None => return None };
                return not_self(deeper);
            }
            let parameter = match parameter_named(base, interner, context) { Some(__nikaia_value) => __nikaia_value, None => return None };
            if a_field_that_copies(&parameter, interner.resolve(name), context) { return None; }
            return not_self(parameter);
        },
        _ => { return parameter_named(expr, interner, context); },
    }
}

fn not_self(name: String) -> Option<String> {
    if name == "self" { return None; }
    Some(name)
}

fn a_field_that_copies(parameter: &str, field: &str, context: &KeepsBody) -> bool {
    let fields = match *nikaia_std::index::get(&context.fields, parameter) { Some(__nikaia_value) => __nikaia_value, None => return false };
    let ty = match *nikaia_std::index::get(&fields, field) { Some(__nikaia_value) => __nikaia_value, None => return false };
    !moves(ty)
}

fn resolved_callee(func: &Expr, interner: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger) -> Option<String> {
    let written = match func {
        Expr::Variable(ident) => { let ident = *ident; interner.resolve(ident).to_owned() },
        Expr::Path(segments) => written_path(interner, segments),
        _ => return None,
    };
    if own.functions.contains_key(&written) || library.functions.contains_key(&written) { return Some(written); }
    None
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn name_as_it_is(name: &str) -> String { name.to_owned() }


// --- leaves.nika ---

pub fn leaves_stmt(stmt: &Stmt, throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>, with_continue: bool) -> bool {
    match stmt {
        Stmt::Return(_) => return true,
        Stmt::Break => return true,
        Stmt::Continue if with_continue => return true,
        _ => { },
    }
    let found = match stmt {
        Stmt::Let { value, .. } => leaves_within(value, throwing, holes_of, with_continue),
        Stmt::Comptime { value, .. } => leaves_within(value, throwing, holes_of, with_continue),
        Stmt::Assign { target, value, .. } => leaves_within(target, throwing, holes_of, with_continue) || leaves_within(value, throwing, holes_of, with_continue),
        Stmt::For { iter, .. } => leaves_within(iter, throwing, holes_of, with_continue),
        Stmt::While { cond, .. } => leaves_within(cond, throwing, holes_of, with_continue),
        Stmt::Return(value) => maybe_leaves_within((value).as_ref(), throwing, holes_of, with_continue),
        Stmt::Expr(value) => leaves_within(value, throwing, holes_of, with_continue),
        _ => false,
    };
    if found { return true; }
    match stmt {
        Stmt::For { body, .. } => leaves_block(body, throwing, holes_of, with_continue),
        Stmt::While { body, .. } => leaves_block(body, throwing, holes_of, with_continue),
        Stmt::Let { value, .. } => blocks_leave(value, throwing, holes_of, with_continue),
        Stmt::Comptime { value, .. } => blocks_leave(value, throwing, holes_of, with_continue),
        Stmt::Expr(value) => blocks_leave(value, throwing, holes_of, with_continue),
        Stmt::Assign { target, value, .. } => blocks_leave(target, throwing, holes_of, with_continue) || blocks_leave(value, throwing, holes_of, with_continue),
        Stmt::Return(value) => maybe_blocks_leave((value).as_ref(), throwing, holes_of, with_continue),
        _ => false,
    }
}

pub fn leaves_block(block: &Block, throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>, with_continue: bool) -> bool {
    for stmt in block.stmts.iter() { if leaves_stmt(&stmt.node, throwing, holes_of, with_continue) { return true; } }
    false
}

pub fn leaves_expr(expr: &Expr, throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>, with_continue: bool) -> bool { leaves_within(expr, throwing, holes_of, with_continue) || blocks_leave(expr, throwing, holes_of, with_continue) }

fn leaves_here(e: &Expr, throwing: &impl Fn(&Expr) -> bool, with_continue: bool) -> bool {
    match e {
        Expr::Throw(_) => true,
        Expr::Return(_) => true,
        Expr::Break => true,
        Expr::Try(_) => true,
        Expr::Continue => with_continue,
        Expr::Call { .. } => throwing(e),
        Expr::MethodCall { .. } => throwing(e),
        Expr::SafeMethod { .. } => throwing(e),
        _ => false,
    }
}

fn leaves_within(expr: &Expr, throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>, with_continue: bool) -> bool {
    if leaves_here(expr, throwing, with_continue) { return true; }
    for hole in holes_of(expr) { if leaves_within(&hole, throwing, holes_of, with_continue) { return true; } }
    match expr {
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            if leaves_within(func, throwing, holes_of, with_continue) { return true; }
            any_leaves_within(args, throwing, holes_of, with_continue) || config_leaves_within(config, throwing, holes_of, with_continue)
        },
        Expr::MethodCall { receiver, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); leaves_within(receiver, throwing, holes_of, with_continue) || any_leaves_within(args, throwing, holes_of, with_continue) || config_leaves_within(config, throwing, holes_of, with_continue) },
        Expr::SafeMethod { receiver, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); leaves_within(receiver, throwing, holes_of, with_continue) || any_leaves_within(args, throwing, holes_of, with_continue) || config_leaves_within(config, throwing, holes_of, with_continue) },
        Expr::Binary { lhs, rhs, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); leaves_within(lhs, throwing, holes_of, with_continue) || leaves_within(rhs, throwing, holes_of, with_continue) },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); leaves_within(expr, throwing, holes_of, with_continue) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); leaves_within(inner, throwing, holes_of, with_continue) },
        Expr::Throw(inner) => { let inner = nikaia_std::boxed::open(inner); leaves_within(inner, throwing, holes_of, with_continue) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); leaves_within(expr, throwing, holes_of, with_continue) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); leaves_within(base, throwing, holes_of, with_continue) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); leaves_within(base, throwing, holes_of, with_continue) },
        Expr::Index { base, index } => { let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index); leaves_within(base, throwing, holes_of, with_continue) || leaves_within(index, throwing, holes_of, with_continue) },
        Expr::Range { start, end, .. } => { let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end); leaves_within(start, throwing, holes_of, with_continue) || leaves_within(end, throwing, holes_of, with_continue) },
        Expr::Tuple(parts) => any_leaves_within(parts, throwing, holes_of, with_continue),
        Expr::Coalesce { value, fallback } => { let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback); leaves_within(value, throwing, holes_of, with_continue) || leaves_within(fallback, throwing, holes_of, with_continue) },
        Expr::TryCatch { expr, .. } => { let expr = nikaia_std::boxed::open(expr); leaves_within(expr, throwing, holes_of, with_continue) },
        Expr::If { cond, .. } => { let cond = nikaia_std::boxed::open(cond); leaves_within(cond, throwing, holes_of, with_continue) },
        Expr::Match { value, arms } => {
            let value = nikaia_std::boxed::open(value);
            if leaves_within(value, throwing, holes_of, with_continue) { return true; }
            for arm in arms.iter() { if maybe_leaves_within((arm.guard).as_ref(), throwing, holes_of, with_continue) || leaves_within(&arm.body, throwing, holes_of, with_continue) { return true; } }
            false
        },
        Expr::StructLit { fields, .. } => fields_leave_within(fields, throwing, holes_of, with_continue),
        Expr::ListLit { items, .. } => any_leaves_within(items, throwing, holes_of, with_continue),
        Expr::With { base, fields, .. } => { let base = nikaia_std::boxed::open(base); leaves_within(base, throwing, holes_of, with_continue) || fields_leave_within(fields, throwing, holes_of, with_continue) },
        Expr::Return(value) => { let value = nikaia_std::boxed::open(value); maybe_leaves_within((value).as_ref(), throwing, holes_of, with_continue) },
        Expr::Select(arms) => {
            for arm in arms.iter() { if leaves_within(&arm.value, throwing, holes_of, with_continue) { return true; } }
            false
        },
        _ => false,
    }
}

fn maybe_leaves_within(expr: Option<&Expr>, throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>, with_continue: bool) -> bool {
    let present = match expr { Some(__nikaia_value) => __nikaia_value, None => return false };
    leaves_within(present, throwing, holes_of, with_continue)
}

fn maybe_blocks_leave(expr: Option<&Expr>, throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>, with_continue: bool) -> bool {
    let present = match expr { Some(__nikaia_value) => __nikaia_value, None => return false };
    blocks_leave(present, throwing, holes_of, with_continue)
}

fn any_leaves_within(exprs: &[Expr], throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>, with_continue: bool) -> bool {
    for e in exprs.iter() { if leaves_within(e, throwing, holes_of, with_continue) { return true; } }
    false
}

fn config_leaves_within(config: &[ConfigArg], throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>, with_continue: bool) -> bool {
    for c in config.iter() { if leaves_within(&c.value, throwing, holes_of, with_continue) { return true; } }
    false
}

fn fields_leave_within(fields: &[FieldInit], throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>, with_continue: bool) -> bool {
    for field in fields.iter() { if maybe_leaves_within((field.value).as_ref(), throwing, holes_of, with_continue) { return true; } }
    false
}

fn blocks_leave(expr: &Expr, throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>, with_continue: bool) -> bool {
    match expr {
        Expr::Block(block) => leaves_block(block, throwing, holes_of, with_continue),
        Expr::Unsafe(block) => leaves_block(block, throwing, holes_of, with_continue),
        Expr::Overlap(block) => leaves_block(block, throwing, holes_of, with_continue),
        Expr::Closure { body, .. } => leaves_block(body, throwing, holes_of, with_continue),
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            if blocks_leave(func, throwing, holes_of, with_continue) { return true; }
            any_blocks_leave(args, throwing, holes_of, with_continue) || config_blocks_leave(config, throwing, holes_of, with_continue)
        },
        Expr::MethodCall { receiver, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); blocks_leave(receiver, throwing, holes_of, with_continue) || any_blocks_leave(args, throwing, holes_of, with_continue) || config_blocks_leave(config, throwing, holes_of, with_continue) },
        Expr::SafeMethod { receiver, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); blocks_leave(receiver, throwing, holes_of, with_continue) || any_blocks_leave(args, throwing, holes_of, with_continue) || config_blocks_leave(config, throwing, holes_of, with_continue) },
        Expr::If { then_branch, else_branch, .. } => {
            if leaves_block(then_branch, throwing, holes_of, with_continue) { return true; }
            let otherwise = match else_branch { Some(__nikaia_value) => __nikaia_value, None => return false };
            leaves_block(otherwise, throwing, holes_of, with_continue)
        },
        Expr::TryCatch { expr, handler } => { let expr = nikaia_std::boxed::open(expr); blocks_leave(expr, throwing, holes_of, with_continue) || leaves_block(handler, throwing, holes_of, with_continue) },
        Expr::Match { arms, .. } => {
            for arm in arms.iter() { if blocks_leave(&arm.body, throwing, holes_of, with_continue) { return true; } }
            false
        },
        Expr::Select(arms) => {
            for arm in arms.iter() { if leaves_block(&arm.body, throwing, holes_of, with_continue) { return true; } }
            false
        },
        _ => false,
    }
}

fn any_blocks_leave(exprs: &[Expr], throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>, with_continue: bool) -> bool {
    for e in exprs.iter() { if blocks_leave(e, throwing, holes_of, with_continue) { return true; } }
    false
}

fn config_blocks_leave(config: &[ConfigArg], throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>, with_continue: bool) -> bool {
    for c in config.iter() { if blocks_leave(&c.value, throwing, holes_of, with_continue) { return true; } }
    false
}


// --- ledger.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LedgerLine<'a> {
    Table { kind: &'a str, name: &'a str },
    Sources,
    Pair { key: &'a str, value: &'a str },
    Nothing,
    Unterminated,
    Bad(&'a str),
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Refused {
    Because(String),
}

impl Refused {
    fn message(&self) -> String {
        match self {
            Refused::Because(why) => why.to_owned(),
        }
    }
}
impl std::fmt::Display for Refused {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.message())
    }
}
impl std::error::Error for Refused {}

grammar! {
    grammar LedgerText {

        rule WS =
            ""
            -> { }

        pub rule file -> Vec<LedgerLine<'a>> =
            ls:line* last:BODY eof
            -> {
                let mut all = Vec::new();
                for l in ls.into_iter() { all.push(l); }
                all.push(last);
                all
            }

        rule line -> LedgerLine<'a> =
            l:BODY line_ending
            -> { l }

        rule BODY -> LedgerLine<'a> =
            SP l:AFTER
            -> { l }

        rule AFTER -> LedgerLine<'a> =
            "#" REST
            -> { LedgerLine::Nothing }
          | "[" t:TABLE
            -> { t }
          | peek(END)
            -> { LedgerLine::Nothing }
          | k:text(KEY) "=" v:text(REST)
            -> { LedgerLine::Pair { key: k.trim(), value: v.trim() } }
          | r:text(REST)
            -> { LedgerLine::Bad(r.trim()) }

        rule TABLE -> LedgerLine<'a> =
            "sources]" SP peek(END)
            -> { LedgerLine::Sources }
          | k:KIND ".\"" n:text(NAME) CLOSE
            -> { LedgerLine::Table { kind: k, name: n } }
          | KIND ".\"" REST
            -> { LedgerLine::Unterminated }

        rule KIND -> &'a str =
            "fn"
            -> { "fn" }
          | "type"
            -> { "type" }
          | "trait"
            -> { "trait" }
          | "impl"
            -> { "impl" }

        rule SP =
            SPACE*
            -> { }

        rule SPACE =
            " "
            -> { }
          | "\t"
            -> { }

        rule END =
            line_ending
            -> { }
          | eof
            -> { }

        rule REST =
            until(line_ending | eof)
            -> { }

        rule CLOSE =
            "\"]" SP peek(END)
            -> { }

        rule NAME =
            until("\"]" | line_ending | eof)
            -> { }

        rule KEY =
            until("=" | line_ending | eof)
            -> { }
    }
}

grammar! {
    grammar LedgerValue {

        pub rule list -> Vec<&'a str> =
            "[" items:__nikaia_list<&'a str>(item = QUOTED, sep = ",") TRAILING "]" eof
            -> { items }

        rule TRAILING =
            ","
            -> { }
          | empty
            -> { }

        rule QUOTED -> &'a str =
            "\"" s:text(INSIDE) "\""
            -> { s }

        rule INSIDE =
            PIECE*
            -> { }

        rule PIECE =
            ESCAPED
            -> { }
          | not("\"") not("\\") any
            -> { }

        rule ESCAPED =
            "\\" any
            -> { }

        rule __nikaia_list<T>(item: Rule<T>, sep) -> Vec<T> =
          first:item rest:__nikaia_list_more<T>(item = item, sep = sep)*
            -> { let mut all = vec![first]; all.extend(rest); all }
        | ""
            -> { Vec::new() }

        rule __nikaia_list_more<T>(item: Rule<T>, sep) -> T =
          sep x:item
            -> { x }
    }
}

pub fn unquote(value: &str) -> Result<String, nikaia_std::error::Thrown<Refused>> {
    Ok(unquote_at(value, "")?)
}

fn unquote_at(value: &str, at: &str) -> Result<String, nikaia_std::error::Thrown<Refused>> {
    if value.len() < 2 || !value.starts_with("\"") || !value.ends_with("\"") { return Err(nikaia_std::error::throwing(Refused::Because(format!("{}expected a quoted string, found `{}`", at, value)), &"unquote_at")); }
    Ok(unescaped(nikaia_std::index::get(&value, nikaia_std::index::at(1..value.len() as i64 - 1))))
}

pub fn list(value: &str) -> Result<Vec<String>, nikaia_std::error::Thrown<Refused>> {
    Ok(list_at(value, "")?)
}

fn list_at(value: &str, at: &str) -> Result<Vec<String>, nikaia_std::error::Thrown<Refused>> {
    if value == "[]" { return Ok(vec![]); }
    let entries = match nikaia_std::grammar::parse(&*value, LedgerValue::parse_list()) {
        Ok(value) => value,
        Err(_error) => { return Err(nikaia_std::error::throwing(Refused::Because(format!("{}expected a list, found `{}`", at, value)), &"list_at")) },
    };
    let mut out: Vec<String> = vec![];
    for entry in entries.iter() {
        let entry = *entry;
        out.push(unescaped(entry));
    }
    Ok(out)
}

fn unescaped(inside: &str) -> String {
    if !inside.contains("\\") { return inside.to_owned(); }
    let mut out: String = String::from("");
    let mut escaped = false;
    for c in inside.chars() {
        if escaped {
            if c == 'n' { out.push('\n'); } else { out.push(c); }
            escaped = false;
        } else if c == '\\' { escaped = true; } else { out.push(c); }
    }
    out
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Section {
    Header,
    Function,
    Kind,
    Sources,
    Nothing,
}

pub fn read(written: &str) -> Result<Ledger, nikaia_std::error::Thrown<Refused>> {
    let mut ledger = Ledger::blank();
    let mut section = Section::Header;
    let mut current: String = String::from("");
    let mut function = FnContract::empty();
    let mut a_type = TypeContract::empty();
    let mut traits: Vec<String> = vec![];
    let mut functions: Vec<String> = vec![];
    let mut answers: Vec<(String, String)> = vec![];
    let lines = match nikaia_std::grammar::parse(&*written, LedgerText::parse_file()) {
        Ok(value) => value,
        Err(error) => { return Err(nikaia_std::error::throwing(Refused::Because(format!("{}", error)), &"read")) },
    };
    let mut n: i64 = 0;
    for one in lines.iter() {
        n += 1;
        match one {
            LedgerLine::Table { kind, name } => {
                let kind = *kind; let name = *name;
                if section == Section::Function {
                    ledger.functions.insert(current.to_owned(), function);
                    function = FnContract::empty();
                }
                if section == Section::Kind {
                    ledger.types.insert(current.to_owned(), a_type);
                    a_type = TypeContract::empty();
                }
                current = name.to_owned();
                if kind == "fn" {
                    if ledger.functions.contains_key(&current) {
                        function = nikaia_std::index::or(match *nikaia_std::index::get(&ledger.functions, &current) {
                            Some(__nikaia_it) => Some(__nikaia_it.clone()),
                            None => None,
                        }, || FnContract::empty());
                    }
                    functions.push(current.to_owned());
                    section = Section::Function;
                } else if kind == "type" {
                    if ledger.types.contains_key(&current) {
                        a_type = nikaia_std::index::or(match *nikaia_std::index::get(&ledger.types, &current) {
                            Some(__nikaia_it) => Some(__nikaia_it.clone()),
                            None => None,
                        }, || TypeContract::empty());
                    }
                    section = Section::Kind;
                } else if kind == "trait" {
                    if !ledger.traits.contains_key(&current) { ledger.traits.insert(current.to_owned(), collections::BTreeSet::new()); }
                    traits.push(current.to_owned());
                    section = Section::Nothing;
                } else {
                    answers.push(implemented(&current, n)?);
                    section = Section::Nothing;
                }
            },
            LedgerLine::Sources => {
                if section == Section::Function {
                    ledger.functions.insert(current.to_owned(), function);
                    function = FnContract::empty();
                }
                if section == Section::Kind {
                    ledger.types.insert(current.to_owned(), a_type);
                    a_type = TypeContract::empty();
                }
                section = Section::Sources;
            },
            LedgerLine::Pair { key, value } => {
                let key = *key; let value = *value;
                if section == Section::Header { header(&mut ledger, key, value, n)?; } else if section == Section::Sources { ledger.sources.insert(unquoted(key, n)?, unquoted(value, n)?); } else if section == Section::Function { function_key(&mut function, &current, key, value, n)?; } else if section == Section::Kind { type_key(&mut a_type, key, value, n)?; } else { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: a `trait` or an `impl` table has no keys, and this has `{}`", n, key)), &"read")); }
            },
            LedgerLine::Unterminated => { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: unterminated section header", n)), &"read")); },
            LedgerLine::Bad(text) => {
                let text = *text;
                return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: not a key and a value: {}", n, text)), &"read"));
            },
            LedgerLine::Nothing => { },
        }
    }
    if section == Section::Function { ledger.functions.insert(current.to_owned(), function); }
    if section == Section::Kind { ledger.types.insert(current.to_owned(), a_type); }
    for name in traits.iter() {
        let prefix = format!("{}::", name);
        let mut methods: collections::BTreeSet<String> = collections::BTreeSet::new();
        for entry in functions.iter() {
            let method = after_prefix(entry, &prefix);
            if method.is_some() {
                let rest = nikaia_std::index::or(method, || "".into());
                if !rest.contains("::") { methods.insert(rest.to_owned()); }
            }
        }
        ledger.traits.insert(name.to_owned(), methods);
    }
    let mut done: Vec<String> = vec![];
    for (trait_name, _) in answers.iter() {
        if !nikaia_std::list::contains(&done, &trait_name) {
            let mut types: collections::BTreeSet<String> = collections::BTreeSet::new();
            for (other, answering) in answers.iter() { if other == trait_name { types.insert(answering.to_owned()); } }
            ledger.implementations.insert(trait_name.to_owned(), types);
            done.push(trait_name.to_owned());
        }
    }
    Ok(ledger)
}

fn header(ledger: &mut Ledger, key: &str, value: &str, n: i64) -> Result<(), nikaia_std::error::Thrown<Refused>> {
    if key == "version" {
        let number = nikaia_std::index::or(text::parse_i64(value), || -1);
        if number < 0 { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: `version` is a whole number, not `{}`", n, value)), &"header")); }
        if number > 4294967295i64 { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: `version` is a whole number, not `{}`", n, value)), &"header")); }
        ledger.version = u32::try_from(number).unwrap_or_else(|_| panic!("the value does not fit in an `u32`"));
    } else if key == "toolchain" { ledger.toolchain = unquoted(value, n)?; } else if key == "inference" { ledger.inference = unquoted(value, n)?; } else { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: unknown header key `{}`", n, key)), &"header")); }
    Ok(())
}

fn implemented(name: &str, n: i64) -> Result<(String, String), nikaia_std::error::Thrown<Refused>> {
    let c: Vec<char> = nikaia_std::list::chars(name.chars());
    let at = find_text(&c, 0, " for ");
    if at < 0 { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: an `impl` entry is `A for T`: {}", n, name)), &"implemented")); }
    Ok((trimmed(&slice(&c, 0, at)), trimmed(&slice(&c, at + 5, c.len() as i64))))
}

fn function_key(entry: &mut FnContract, name: &str, key: &str, value: &str, n: i64) -> Result<(), nikaia_std::error::Thrown<Refused>> {
    if key == "pub" { entry.public = value == "true"; } else if key == "sync" { entry.sync_claim = sync_of(value, n)?; } else if key == "throws" { entry.fails_with = throws_of(value, n)?; } else if key == "returns" { entry.borrows = borrows_of(&unquoted(value, n)?, n)?; } else if key == "signature" {
        let spelled = spelled_signature(&unquoted(value, n)?, name)?;
        if spelled.mutates { entry.mutates = true; }
        if !spelled.borrows.is_empty() { entry.borrows = spelled.borrows.to_owned(); }
        entry.signature = Some(spelled.signature);
    } else if key == "keeps" { entry.keeps = entries(value, n)?; } else if key == "mutates" { entry.mutates = value == "true"; } else if key == "locks" {
        let said = value.trim();
        if said == "true" { entry.touches_a_lock = Lock::Holds; } else if said == "\"?\"" { entry.touches_a_lock = Lock::Undecided; } else { entry.touches_a_lock = Lock::No; }
    } else if key == "threads" {
        let said = value.trim();
        if said == "true" { entry.threads = Threads::May; } else if said == "false" { entry.threads = Threads::MayNot; } else { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: `threads` is `true` or `false`, not `{}`. (Leave it out if nobody knows.)", n, said)), &"function_key")); }
    } else if key == "touches" {
        let mut touches: Vec<Touch> = vec![];
        for one in entries(value, n)? { touches.push(touch_of(&one)?); }
        entry.touches = touches;
        entry.touches_known = true;
    } else if key == "provenance" { entry.provenance = Some(provenance_of(&unquoted(value, n)?, n)?); } else if key == "views" {
        let mut views: Vec<Held> = vec![];
        for held in entries(value, n)? {
            let read = held_of(&held);
            if read.is_none() { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: a tether state is `name: borrowed` or `name: tethered`, not `{}`", n, held)), &"function_key")); }
            views.push(nikaia_std::index::or(read, || Held { position: String::from(""), state: State::Borrowed }));
        }
        entry.views = views;
    } else if key == "sharing" {
        let mut classes: Vec<Class> = vec![];
        for class in entries(value, n)? {
            let read = class_of(&class);
            if read.is_none() { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: a sharing class is `a | b: plain` or `a | b: atomic`, not `{}`", n, class)), &"function_key")); }
            classes.push(nikaia_std::index::or(read, || Class { members: vec![], count: Count::Atomic }));
        }
        entry.sharing = classes;
    } else if key == "ends_by_length" { entry.ends_by_length = value == "true"; } else if key == "requires" { entry.requires = entries(value, n)?; } else if key == "ensures" { entry.ensures = entries(value, n)?; } else if key == "from" { entry.from = entries(value, n)?; } else { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: unknown key `{}` on a fn", n, key)), &"function_key")); }
    Ok(())
}

fn type_key(entry: &mut TypeContract, key: &str, value: &str, n: i64) -> Result<(), nikaia_std::error::Thrown<Refused>> {
    if key == "pub" { entry.public = value == "true"; } else if key == "crosses" { if value == "true" { entry.crosses = Crosses::May; } else if value == "false" { entry.crosses = Crosses::MayNot; } else { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: `crosses` is `true` or `false`, not `{}` - and leaving the line out is the third answer", n, value)), &"type_key")); } } else if key == "compares" { entry.compares = value.trim() == "true"; } else if key == "copies" { entry.copies = value.trim() == "true"; } else if key == "tethered" { entry.tethered = entries(value, n)?; } else if key == "constant" { entry.constant = unquoted(value, n)?; } else if key == "touches" { entry.touches = entries(value, n)?; } else if key == "iterates" {
        let said = unquoted(value, n)?;
        if said != "throws" { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: `iterates` is `throws` and nothing else, not `{}` - a step that cannot fail says nothing", n, said)), &"type_key")); }
        entry.iterates_fallibly = true;
    } else if key == "variants" {
        let mut variants: Vec<VariantContract> = vec![];
        for one in entries(value, n)? { variants.push(variant_of(&one)); }
        entry.variants = variants;
    } else if key == "fields" {
        let mut fields: Vec<FieldContract> = vec![];
        for one in entries(value, n)? { fields.push(field_of(&one)); }
        entry.fields = fields;
    } else { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: unknown key `{}` on a type", n, key)), &"type_key")); }
    Ok(())
}

fn unquoted(value: &str, n: i64) -> Result<String, nikaia_std::error::Thrown<Refused>> {
    Ok(unquote_at(value, &format!("line {}: ", n))?)
}

fn entries(value: &str, n: i64) -> Result<Vec<String>, nikaia_std::error::Thrown<Refused>> {
    Ok(list_at(value, &format!("line {}: ", n))?)
}

fn sync_of(value: &str, n: i64) -> Result<Sync, nikaia_std::error::Thrown<Refused>> {
    if value == "true" { return Ok(Sync::Asserted); }
    if value == "false" { return Ok(Sync::No); }
    if value == "\"inferred\"" { return Ok(Sync::Inferred); }
    let c: Vec<char> = nikaia_std::list::chars(value.chars());
    if value.ends_with(")\"") && (value.starts_with("\"sync(") || value.starts_with("\"from(")) && c.len() >= 8 {
        let inside = slice(&c, 6, c.len() as i64 - 2);
        let name = inside.trim();
        if !name.is_empty() { return Ok(Sync::From(name.to_owned())); }
    }
    return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: `sync` is `true` (the source says so), `\"inferred\"` (the body implies it) or `\"sync(f)\"` (its lambda decides), not `{}`", n, value)), &"sync_of"))
}

fn throws_of(value: &str, n: i64) -> Result<Vec<String>, nikaia_std::error::Thrown<Refused>> {
    if value == "true" {
        let unnamed: String = String::from("?");
        return Ok(vec![unnamed]);
    }
    Ok(entries(value, n)?)
}

fn borrows_of(value: &str, n: i64) -> Result<Vec<String>, nikaia_std::error::Thrown<Refused>> {
    let c: Vec<char> = nikaia_std::list::chars(value.chars());
    let mut from: i64 = -1;
    if value.ends_with(")") { if value.starts_with("ref(") { from = 4; } else if value.starts_with("borrows(") { from = 8; } }
    if from < 0 { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: expected `ref(…)`, found `{}`", n, value)), &"borrows_of")); }
    let inside = slice(&c, from, c.len() as i64 - 1);
    let mut names: Vec<String> = vec![];
    for part in inside.split("|") {
        let name = part.trim();
        if !name.is_empty() { names.push(name.to_owned()); }
    }
    Ok(names)
}

fn provenance_of(value: &str, n: i64) -> Result<Provenance, nikaia_std::error::Thrown<Refused>> {
    if value == "trusted" { return Ok(Provenance::Trusted); }
    if value == "untrusted" { return Ok(Provenance::Untrusted); }
    return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: a provenance is `trusted` or `untrusted`, not `{}`", n, value)), &"provenance_of"))
}

pub fn touch_of(written: &str) -> Result<Touch, nikaia_std::error::Thrown<Refused>> {
    let __keep_frame = nikaia_std::tether::Keep::new();
    let whole = written.trim();
    let c: Vec<char> = nikaia_std::list::chars(whole.chars());
    let space = find_last(&c, ' ');
    if space < 0 { return Err(nikaia_std::error::throwing(Refused::Because(format!("a touch is `resource read` or `resource write`, found `{}`", whole)), &"touch_of")); }
    let said = slice(&c, space + 1, c.len() as i64);
    let access = said.trim();
    let mut write = false;
    if access == "write" { write = true; } else if access != "read" { return Err(nikaia_std::error::throwing(Refused::Because(format!("a touch is `read` or `write`, not `{}` (in `{}`)", access, whole)), &"touch_of")); }
    let before = slice(&c, 0, space);
    let resource = before.trim();
    let r: Vec<char> = nikaia_std::list::chars(resource.chars());
    let open = find(&r, 0, '(');
    let mut kind: String = resource.to_owned();
    let mut parameter: Option<String> = None;
    if open >= 0 {
        if !resource.ends_with(")") { return Err(nikaia_std::error::throwing(Refused::Because(format!("a resource is `kind(parameter)`, and `{}` has no `)`", resource)), &"touch_of")); }
        let named = __keep_frame.put(slice(&r, 0, open));
        kind = named.trim().to_owned();
        let inside = __keep_frame.put(slice(&r, open + 1, r.len() as i64 - 1));
        parameter = Some(inside.trim().to_owned());
    }
    if kind.is_empty() { return Err(nikaia_std::error::throwing(Refused::Because(format!("a touch needs a resource kind, found `{}`", whole)), &"touch_of")); }
    Ok(Touch { kind, parameter, write })
}

pub fn held_of(written: &str) -> Option<Held> {
    let c: Vec<char> = nikaia_std::list::chars(written.chars());
    let colon = find_last(&c, ':');
    if colon < 0 { return None; }
    let state = State::parse(&slice(&c, colon + 1, c.len() as i64));
    if state.is_none() { return None; }
    let position = slice(&c, 0, colon);
    Some(Held { position: position.trim().to_owned(), state: nikaia_std::index::or(state, || State::Borrowed) })
}

pub fn class_of(written: &str) -> Option<Class> {
    let c: Vec<char> = nikaia_std::list::chars(written.chars());
    let colon = find_last(&c, ':');
    if colon < 0 { return None; }
    let named = slice(&c, 0, colon);
    let mut members: Vec<String> = vec![];
    for part in named.split("|") {
        let member = part.trim();
        if !member.is_empty() { members.push(member.to_owned()); }
    }
    if members.is_empty() { return None; }
    let count = Count::parse(&slice(&c, colon + 1, c.len() as i64));
    if count.is_none() { return None; }
    Some(Class { members, count: nikaia_std::index::or(count, || Count::Atomic) })
}

pub fn variant_of(written: &str) -> VariantContract {
    let __keep_frame = nikaia_std::tether::Keep::new();
    let whole = written.trim();
    let c: Vec<char> = nikaia_std::list::chars(whole.chars());
    let paren = find(&c, 0, '(');
    if paren >= 0 {
        let named = slice(&c, 0, paren);
        let rest = slice(&c, paren + 1, c.len() as i64);
        let inside = without_last(rest.trim_end(), ')');
        let mut holds: Vec<FieldContract> = vec![];
        let mut at = 0;
        for part in split_args(&inside) {
            holds.push(FieldContract { name: format!("{}", at), ty: parse(&part), public: true });
            at += 1;
        }
        return VariantContract { name: named.trim().to_owned(), holds, positional: true };
    }
    let brace = find(&c, 0, '{');
    if brace >= 0 {
        let named = slice(&c, 0, brace);
        let rest = slice(&c, brace + 1, c.len() as i64);
        let inside = without_last(rest.trim_end(), '}');
        let mut holds: Vec<FieldContract> = vec![];
        for part in split_args(&inside) {
            let p: Vec<char> = nikaia_std::list::chars(part.chars());
            let colon = find(&p, 0, ':');
            if colon >= 0 {
                let field = __keep_frame.put(slice(&p, 0, colon));
                holds.push(FieldContract { name: field.trim().to_owned(), ty: parse(&slice(&p, colon + 1, p.len() as i64)), public: true });
            }
        }
        return VariantContract { name: named.trim().to_owned(), holds, positional: false };
    }
    let nothing: Vec<FieldContract> = vec![];
    VariantContract { name: whole.to_owned(), holds: nothing, positional: false }
}

fn field_of(written: &str) -> FieldContract {
    let __keep_frame = nikaia_std::tether::Keep::new();
    let mut field: String = written.trim().to_owned();
    let mut public = false;
    if field.starts_with("pub ") {
        public = true;
        let rest = __keep_frame.put(from_char(&field, 4));
        field = rest.trim().to_owned();
    }
    let c: Vec<char> = nikaia_std::list::chars(field.chars());
    let colon = find(&c, 0, ':');
    if colon < 0 { return FieldContract { name: field.to_owned(), ty: Ty::Unknown, public }; }
    let name = slice(&c, 0, colon);
    FieldContract { name: name.trim().to_owned(), ty: parse(&slice(&c, colon + 1, c.len() as i64)), public }
}

pub fn signature_of(written: &str) -> Result<Signature, nikaia_std::error::Thrown<Refused>> {
    let spelled = spelled_signature(written, "")?;
    Ok(spelled.signature)
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Spelling {
    pub signature: Signature,
    pub borrows: Vec<String>,
    pub mutates: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum Piece<'a> {
    Owner { view: bool, mutates: bool },
    Typed { ty: &'a str, mutates: bool },
    Named { name: &'a str, ty: &'a str, mutable: bool },
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Declared<'a> {
    name: &'a str,
    traits: Vec<&'a str>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Setting<'a> {
    name: &'a str,
    ty: &'a str,
    default: &'a str,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Signed<'a> {
    declared: Vec<Declared<'a>>,
    parts: Vec<Piece<'a>>,
    settings: Vec<Setting<'a>>,
    result: Option<&'a str>,
}

grammar! {
    grammar SignatureText {

        pub rule signature -> Signed<'a> =
            d:bracket "(" ps:__nikaia_list<Piece<'a>>(item = part, sep = ",") TRAILING ss:settings ")" r:result? eof
            -> { Signed { declared: d, parts: ps, settings: ss, result: r } }

        rule bracket -> Vec<Declared<'a>> =
            "[" ds:__nikaia_list<Declared<'a>>(item = declared, sep = ",") "]"
            -> { ds }
          | empty
            -> { Vec::new() }

        rule declared -> Declared<'a> =
            n:raw_ident COLON ts:__nikaia_list<&'a str>(item = BOUND, sep = "+")
            -> { Declared { name: n, traits: ts } }
          | n:raw_ident
            -> { Declared { name: n, traits: Vec::new() } }

        rule part -> Piece<'a> =
            REF MUT SELF
            -> { Piece::Owner { view: true, mutates: true } }
          | REF SELF
            -> { Piece::Owner { view: true, mutates: false } }
          | MUT SELF COLON t:TYPE
            -> { Piece::Typed { ty: t, mutates: true } }
          | SELF COLON t:TYPE
            -> { Piece::Typed { ty: t, mutates: false } }
          | SELF
            -> { Piece::Owner { view: false, mutates: false } }
          | MUT n:raw_ident COLON t:TYPE
            -> { Piece::Named { name: n, ty: t, mutable: true } }
          | n:raw_ident COLON t:TYPE
            -> { Piece::Named { name: n, ty: t, mutable: false } }
          | t:TYPE
            -> { Piece::Typed { ty: t, mutates: false } }

        rule settings -> Vec<Setting<'a>> =
            ";" ss:__nikaia_list<Setting<'a>>(item = setting, sep = ",") TRAILING
            -> { ss }
          | empty
            -> { Vec::new() }

        rule setting -> Setting<'a> =
            n:raw_ident COLON t:SETTING_TYPE "=" d:DEFAULT
            -> { Setting { name: n, ty: t, default: d } }

        rule result -> &'a str =
            "->" t:REST
            -> { t }

        pub rule pointed -> Vec<Vec<&'a str>> =
            ps:POINTING* eof
            -> { ps }

        rule POINTING -> Vec<&'a str> =
            "ref(" ns:__nikaia_list<&'a str>(item = POINTED_NAME, sep = "|") ")"
            -> { ns }
          | WORD_CHARS
            -> { Vec::new() }
          | any
            -> { Vec::new() }

        rule POINTED_NAME -> &'a str =
            WS0 n:raw_ident WS0
            -> { n }

        rule WS0 =
            " "*
            -> { }

        rule WORD_CHARS =
            WORD_CHAR+
            -> { }

        rule WORD_CHAR =
            alpha1
            -> { }
          | digit
            -> { }
          | "_"
            -> { }
          | "$"
            -> { }

        rule REF =
            "ref" not(WORD_CHAR)
            -> { }

        rule MUT =
            "mut" not(WORD_CHAR)
            -> { }

        rule SELF =
            "self" not(WORD_CHAR)
            -> { }

        rule COLON =
            ":" not(":")
            -> { }

        rule TRAILING =
            ","
            -> { }
          | empty
            -> { }

        rule BOUND -> &'a str =
            t:text(BOUND_RUN)
            -> { t.trim() }

        rule BOUND_RUN =
            BOUND_PIECE+
            -> { }

        rule BOUND_PIECE =
            not("+") not(",") not("]") SPAN
            -> { }

        rule TYPE -> &'a str =
            t:text(TYPE_RUN)
            -> { t.trim() }

        rule TYPE_RUN =
            TYPE_PIECE+
            -> { }

        rule TYPE_PIECE =
            not(",") not(")") not(";") SPAN
            -> { }

        rule SETTING_TYPE -> &'a str =
            t:text(SETTING_RUN)
            -> { t.trim() }

        rule SETTING_RUN =
            SETTING_PIECE+
            -> { }

        rule SETTING_PIECE =
            not("=") not(",") not(")") SPAN
            -> { }

        rule DEFAULT -> &'a str =
            t:text(DEFAULT_RUN)
            -> { t.trim() }

        rule DEFAULT_RUN =
            DEFAULT_PIECE+
            -> { }

        rule DEFAULT_PIECE =
            not(",") not(")") SPAN
            -> { }

        rule REST -> &'a str =
            t:text(REST_RUN)
            -> { t.trim() }

        rule REST_RUN =
            until(eof)
            -> { }

        rule SPAN =
            PARENS
            -> { }
          | BRACKETS
            -> { }
          | BRACES
            -> { }
          | STRING
            -> { }
          | any
            -> { }

        rule PARENS =
            "(" IN_PARENS* ")"
            -> { }

        rule BRACES =
            "{" IN_BRACES* "}"
            -> { }

        rule IN_BRACES =
            not("}") SPAN
            -> { }

        rule IN_PARENS =
            not(")") SPAN
            -> { }

        rule BRACKETS =
            "[" IN_BRACKETS* "]"
            -> { }

        rule IN_BRACKETS =
            not("]") SPAN
            -> { }

        rule STRING =
            "\"" STRING_PIECE* "\""
            -> { }

        rule STRING_PIECE =
            "\\" any
            -> { }
          | not("\"") any
            -> { }

        rule __nikaia_list<T>(item: Rule<T>, sep) -> Vec<T> =
          first:item rest:__nikaia_list_more<T>(item = item, sep = sep)*
            -> { let mut all = vec![first]; all.extend(rest); all }
        | ""
            -> { Vec::new() }

        rule __nikaia_list_more<T>(item: Rule<T>, sep) -> T =
          sep x:item
            -> { x }
    }
}

pub fn spelled_signature(written: &str, key: &str) -> Result<Spelling, nikaia_std::error::Thrown<Refused>> {
    let parts = match nikaia_std::grammar::parse(&*written, SignatureText::parse_signature()) {
        Ok(value) => value,
        Err(_error) => { return Err(nikaia_std::error::throwing(Refused::Because(format!("a signature is `[T](a: A; o: O = v) -> R`, found `{}`", written)), &"spelled_signature")) },
    };
    let mut variables: collections::BTreeSet<String> = collections::BTreeSet::new();
    let mut bounds: Vec<(String, Vec<String>)> = vec![];
    for declared in parts.declared.iter() {
        variables.insert(declared.name.to_owned());
        if !declared.traits.is_empty() || key.is_empty() {
            let mut traits: Vec<String> = vec![];
            for one in declared.traits.iter() {
                let one = *one;
                traits.push(one.to_owned());
            }
            bounds.push(a_bound(declared.name, traits));
        }
    }
    let mut params: Vec<(String, Ty)> = vec![];
    let mut changed: Vec<String> = vec![];
    let mut order: Vec<String> = vec![];
    let mut receiver_changes = false;
    let mut first = true;
    for part in parts.parts.iter() {
        match part {
            Piece::Owner { view, mutates } => {
                let mutates = *mutates; let view = *view;
                let owner = nikaia_std::index::or(owner_of(key), || "?".into());
                let written_type = if view { format!("ref {}", owner) } else { owner.to_owned() };
                params.push(a_param("self", typed(&written_type, &variables)));
                if mutates { receiver_changes = true; }
                if first { order.push(a_receiver()); }
            },
            Piece::Typed { ty, mutates } => {
                let mutates = *mutates; let ty = *ty;
                params.push(a_param("self", typed(ty, &variables)));
                if mutates { receiver_changes = true; }
                if first { order.push(a_receiver()); }
            },
            Piece::Named { name, ty, mutable } => {
                let mutable = *mutable; let name = *name; let ty = *ty;
                params.push(a_param(name, typed(ty, &variables)));
                if mutable { changed.push(name.to_owned()); }
                order.push(name.to_owned());
            },
        }
        first = false;
    }
    let mut config: Vec<ConfigContract> = vec![];
    for setting in parts.settings.iter() { config.push(ConfigContract { name: setting.name.to_owned(), ty: typed(setting.ty, &variables), default: setting.default.to_owned() }); }
    let mut result: Option<Ty> = None;
    let mut borrows: Vec<String> = vec![];
    let result_text = nikaia_std::index::or(parts.result, || "");
    if parts.result.is_some() {
        result = Some(typed(result_text, &variables));
        borrows = pointed_into(result_text, &order);
    }
    Ok(Spelling { signature: Signature { bounds, params, mutable: changed, config, result }, borrows, mutates: receiver_changes })
}

fn typed(written: &str, variables: &collections::BTreeSet<String>) -> Ty {
    let ty = parse(written);
    if variables.is_empty() { return ty; }
    ty.parameterise(variables)
}

fn pointed_into(result: &str, order: &[String]) -> Vec<String> {
    if !result.contains("ref(") { return vec![]; }
    let groups = match nikaia_std::grammar::parse(&*result, SignatureText::parse_pointed()) {
        Ok(value) => value,
        Err(_error) => { return vec![]; },
    };
    let mut named: Vec<String> = vec![];
    for group in groups.iter() {
        for name in group.iter() {
            let name = *name;
            if !nikaia_std::list::contains(&named, &name) { named.push(name.to_owned()); }
        }
    }
    let mut borrows: Vec<String> = vec![];
    for name in order.iter() { if nikaia_std::list::contains(&named, &name) { borrows.push(name.to_owned()); } }
    for name in named.iter() { if !nikaia_std::list::contains(&borrows, &name) { borrows.push(name.to_owned()); } }
    borrows
}

fn a_bound(name: &str, traits: Vec<String>) -> (String, Vec<String>) { (name.to_owned(), traits) }

fn a_receiver() -> String {
    let receiver: String = String::from("self");
    receiver
}

fn owner_of(key: &str) -> Option<String> {
    let c: Vec<char> = nikaia_std::list::chars(key.chars());
    let mut last: i64 = -1;
    for at in 0..c.len() as i64 { if ((at + 1) as usize) < c.len() && *nikaia_std::index::get(&c, (at) as usize) == ':' && *nikaia_std::index::get(&c, (at + 1) as usize) == ':' { last = at; } }
    if last < 0 { return None; }
    Some(slice(&c, 0, last))
}

fn find(c: &[char], from: i64, target: char) -> i64 {
    for at in from..c.len() as i64 { if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == target { return at; } }
    -1
}

fn find_last(c: &[char], target: char) -> i64 {
    let mut found: i64 = -1;
    for at in 0..c.len() as i64 { if *nikaia_std::index::get(&c, (at) as usize) == target { found = at; } }
    found
}

fn find_text(c: &[char], from: i64, word: &str) -> i64 {
    let w: Vec<char> = nikaia_std::list::chars(word.chars());
    if w.is_empty() || (c.len() as i64) < w.len() as i64 { return -1; }
    for at in from..c.len() as i64 - w.len() as i64 + 1 {
        let mut same = true;
        for k in 0..w.len() as i64 { if same && *nikaia_std::index::get(&c, nikaia_std::index::at(at + k)) != *nikaia_std::index::get(&w, (k) as usize) { same = false; } }
        if same { return at; }
    }
    -1
}

fn slice(c: &[char], from: i64, to: i64) -> String {
    let mut out: String = String::from("");
    for k in from..to { out.push(*nikaia_std::index::get(&c, nikaia_std::index::at(k))); }
    out
}

fn from_char(written: &str, front: i64) -> String {
    let c: Vec<char> = nikaia_std::list::chars(written.chars());
    slice(&c, front, c.len() as i64)
}

fn after_prefix(written: &str, prefix: &str) -> Option<String> {
    if !written.starts_with(prefix) { return None; }
    let p: Vec<char> = nikaia_std::list::chars(prefix.chars());
    Some(from_char(written, p.len() as i64))
}

fn without_last(written: &str, last: char) -> String {
    let c: Vec<char> = nikaia_std::list::chars(written.chars());
    let mut end = c.len() as i64;
    while end > 0 && *nikaia_std::index::get(&c, nikaia_std::index::at(end - 1)) == last { end -= 1; }
    slice(&c, 0, end)
}

fn a_param(name: &str, ty: Ty) -> (String, Ty) { (name.to_owned(), ty) }

fn trimmed(written: &str) -> String { written.trim().to_owned() }

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Spelled {
    pub text: String,
    pub borrows_said: bool,
    pub mutates_said: bool,
}

pub fn spell(text: &str, key: &str, borrows: &[String], mutates: bool) -> Spelled {
    let c: Vec<char> = nikaia_std::list::chars(text.trim().chars());
    let mut declared: Vec<String> = vec![];
    let mut open: i64 = 0;
    if !c.is_empty() && *nikaia_std::index::get(&c, 0) == '[' {
        let close = matching(&c, 1, '[', ']');
        if close < 0 { return as_written(text); }
        for entry in split_args(&slice(&c, 1, close)) {
            let entry = trimmed(&entry);
            if !entry.is_empty() { declared.push(entry); }
        }
        open = close + 1;
        while open < c.len() as i64 && (*nikaia_std::index::get(&c, nikaia_std::index::at(open))).is_whitespace() { open += 1; }
    }
    if open >= c.len() as i64 || *nikaia_std::index::get(&c, nikaia_std::index::at(open)) != '(' { return as_written(text); }
    let close = matching(&c, open + 1, '(', ')');
    if close < 0 { return as_written(text); }
    let inside: Vec<char> = nikaia_std::list::chars(slice(&c, open + 1, close).chars());
    let mut result = slice(&c, close + 1, c.len() as i64);
    let semicolon = top_level_semicolon(&inside);
    let positional = if semicolon < 0 { slice(&inside, 0, inside.len() as i64) } else { slice(&inside, 0, semicolon) };
    let mut parameters: Vec<String> = vec![];
    for part in split_args(&positional) {
        let part = trimmed(&part);
        if !part.is_empty() { parameters.push(part); }
    }
    let mut mutates_said = false;
    let mut written_parameters: Vec<String> = vec![];
    for k in 0..parameters.len() as i64 {
        if k == 0 && !is_named(nikaia_std::index::get(&parameters, 0)) {
            written_parameters.push(receiver(nikaia_std::index::get(&parameters, 0), key, mutates));
            mutates_said = mutates;
        } else { written_parameters.push((*nikaia_std::index::get(&parameters, (k) as usize)).to_owned()); }
    }
    let mut borrows_said = false;
    if !borrows.is_empty() && !word_starts(&result, "ref").is_empty() {
        let pointed = joined_by(borrows, " | ");
        result = replace_ref(&result, &format!("ref({})", pointed));
        borrows_said = true;
    }
    let mut seen: Vec<String> = vec![];
    for entry in declared.iter() { seen.push(before_colon(entry)); }
    let mut body = joined_by(&written_parameters, ", ");
    if semicolon >= 0 {
        let options = trimmed(&slice(&inside, semicolon + 1, inside.len() as i64));
        body = format!("{}; {}", body, options);
    }
    for variable in variables(&format!("{}{}", body, result)) {
        if !nikaia_std::list::contains(&seen, &variable) {
            seen.push(variable.to_owned());
            declared.push(variable.to_owned());
        }
    }
    let mut before: String = String::from("");
    if !declared.is_empty() {
        let names = joined_by(&declared, ", ");
        before = format!("[{}]", names);
    }
    Spelled { text: without_dollars(&format!("{}({}){}", before, body, result)), borrows_said, mutates_said }
}

fn as_written(text: &str) -> Spelled { Spelled { text: text.to_owned(), borrows_said: false, mutates_said: false } }

fn receiver(written: &str, key: &str, mutates: bool) -> String {
    let has_owner = owner_of(key).is_some();
    let owner = nikaia_std::index::or(owner_of(key), || "".into());
    let viewed = after_prefix(written, "ref ");
    if viewed.is_some() && has_owner && nikaia_std::index::or(viewed.as_deref(), || "") == owner {
        if mutates { return String::from("ref mut self"); }
        return String::from("ref self");
    }
    if viewed.is_none() && has_owner && written == owner && !mutates { return String::from("self"); }
    if mutates { return format!("mut self: {}", written); }
    format!("self: {}", written)
}

fn is_named(part: &str) -> bool {
    let mut rest = trimmed(part);
    while rest.starts_with("mut ") { rest = from_char(&rest, 4); }
    let c: Vec<char> = nikaia_std::list::chars(rest.chars());
    let mut end: i64 = 0;
    while end < c.len() as i64 && is_word_char(*nikaia_std::index::get(&c, nikaia_std::index::at(end))) { end += 1; }
    if end == 0 || !(is_lower(*nikaia_std::index::get(&c, 0)) || *nikaia_std::index::get(&c, 0) == '_') { return false; }
    let after = trimmed_start(&slice(&c, end, c.len() as i64));
    after.starts_with(":") && !after.starts_with("::")
}

fn matching(c: &[char], from: i64, open: char, close: char) -> i64 {
    let mut depth = 0;
    for at in from..c.len() as i64 {
        if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == open { depth += 1; } else if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == close {
            if depth == 0 { return at; }
            depth -= 1;
        }
    }
    -1
}

fn top_level_semicolon(c: &[char]) -> i64 {
    let mut depth = 0;
    for at in 0..c.len() as i64 { if *nikaia_std::index::get(&c, (at) as usize) == '[' || *nikaia_std::index::get(&c, (at) as usize) == '(' { depth += 1; } else if *nikaia_std::index::get(&c, (at) as usize) == ']' || *nikaia_std::index::get(&c, (at) as usize) == ')' { if depth > 0 { depth -= 1; } } else if *nikaia_std::index::get(&c, (at) as usize) == ';' && depth == 0 { return at; } }
    -1
}

fn word_starts(text: &str, word: &str) -> Vec<i64> {
    let c: Vec<char> = nikaia_std::list::chars(text.chars());
    let w: Vec<char> = nikaia_std::list::chars(word.chars());
    let mut starts: Vec<i64> = vec![];
    let mut at = find_text(&c, 0, word);
    while at >= 0 {
        let free_before = at == 0 || !(is_word_char(*nikaia_std::index::get(&c, nikaia_std::index::at(at - 1))) || *nikaia_std::index::get(&c, nikaia_std::index::at(at - 1)) == '$');
        let blank_after = (at + w.len() as i64) < c.len() as i64 && *nikaia_std::index::get(&c, nikaia_std::index::at(at + w.len() as i64)) == ' ';
        if free_before && blank_after { starts.push(at); }
        at = find_text(&c, at + 1, word);
    }
    starts
}

fn replace_ref(text: &str, by: &str) -> String {
    let c: Vec<char> = nikaia_std::list::chars(text.chars());
    let mut out: String = String::from("");
    let mut from: i64 = 0;
    for at in word_starts(text, "ref") {
        out.push_str(&slice(&c, from, at));
        out.push_str(by);
        from = at + 3;
    }
    out.push_str(&slice(&c, from, c.len() as i64));
    out
}

fn variables(text: &str) -> Vec<String> {
    let c: Vec<char> = nikaia_std::list::chars(text.chars());
    let mut out: Vec<String> = vec![];
    for at in 0..c.len() as i64 {
        if *nikaia_std::index::get(&c, (at) as usize) == '$' {
            let mut end = at + 1;
            while end < c.len() as i64 && is_word_char(*nikaia_std::index::get(&c, nikaia_std::index::at(end))) { end += 1; }
            let name = slice(&c, at + 1, end);
            if !name.is_empty() && !nikaia_std::list::contains(&out, &name) { out.push(name); }
        }
    }
    out
}

fn joined_by(parts: &[String], between: &str) -> String {
    let mut out: String = String::from("");
    for k in 0..parts.len() as i64 {
        if k > 0 { out.push_str(between); }
        out.push_str(nikaia_std::index::get(&parts, (k) as usize));
    }
    out
}

fn without_dollars(text: &str) -> String {
    let mut out: String = String::from("");
    for c in text.chars() { if c != '$' { out.push(c); } }
    out
}

fn trimmed_start(written: &str) -> String { written.trim_start().to_owned() }

fn is_word_char(c: char) -> bool { is_lower(c) || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '_' }

fn is_lower(c: char) -> bool { c >= 'a' && c <= 'z' }


// --- ledger_ops.nika ---

pub fn published_entries(ledger: &Ledger, foreign: &collections::BTreeSet<String>) -> Ledger {
    let mut out = ledger.clone();
    out.functions = collections::BTreeMap::new();
    for (key, contract) in ledger.functions.iter() { if !of_another(key, foreign) { out.functions.insert(key.to_owned(), contract.clone()); } }
    out.types = collections::BTreeMap::new();
    for (key, contract) in ledger.types.iter() { if !of_another(key, foreign) { out.types.insert(key.to_owned(), contract.clone()); } }
    out.traits = collections::BTreeMap::new();
    for (key, methods) in ledger.traits.iter() { if !of_another(key, foreign) { out.traits.insert(key.to_owned(), methods.to_owned()); } }
    out
}

fn of_another(key: &str, foreign: &collections::BTreeSet<String>) -> bool {
    let parts: Vec<&str> = key.splitn(2, "::").collect::<Vec<_>>();
    parts.len() == 2 && foreign.contains(*nikaia_std::index::get(&parts, 0))
}

pub fn stale_units(ledger: &Ledger, sources: &collections::BTreeMap<String, String>) -> Vec<String> {
    let mut moved: collections::BTreeSet<String> = collections::BTreeSet::new();
    for (unit, hash) in sources.iter() {
        let recorded = nikaia_std::index::or(*nikaia_std::index::get(&ledger.sources, unit), || "");
        if !ledger.sources.contains_key(unit) || recorded != hash { moved.insert(unit.to_owned()); }
    }
    for (unit, _) in ledger.sources.iter() { if !sources.contains_key(unit) { moved.insert(unit.to_owned()); } }
    let mut out: Vec<String> = vec![];
    for unit in moved.iter() { out.push(unit.to_owned()); }
    out
}

pub fn absorb_into(ledger: &mut Ledger, module: Option<&str>, renames: &collections::BTreeMap<String, String>, other: &Ledger) {
    let mut declared: collections::BTreeSet<String> = collections::BTreeSet::new();
    for (name, _) in other.types.iter() { declared.insert(name.to_owned()); }
    let prefix = nikaia_std::index::or(match module {
        Some(__nikaia_it) => Some(__nikaia_it.to_owned()),
        None => None,
    }, || "".into());
    let qualified = module.is_some();
    for (field, holds) in other.code_locks.iter() {
        let parts: Vec<&str> = field.splitn(2, ".").collect::<Vec<_>>();
        if qualified && declared.contains(*nikaia_std::index::get(&parts, 0)) { ledger.code_locks.insert(format!("{}::{}", prefix, field), holds.clone()); } else { ledger.code_locks.insert(field.to_owned(), holds.clone()); }
    }
    let mut kept: collections::BTreeMap<String, String> = collections::BTreeMap::new();
    for (from, to) in renames.iter() { if !qualified || *from != prefix { kept.insert(from.to_owned(), to.to_owned()); } }
    for (name, contract) in other.functions.iter() {
        let mut entry = contract.clone();
        if entry.signature.is_some() {
            let mut signature = nikaia_std::index::or(match entry.signature.as_ref() {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || Signature::empty());
            let mut params: Vec<(String, Ty)> = vec![];
            for (param, ty) in signature.params.iter() { params.push((param.to_owned(), qualified_ty(ty, &prefix, qualified, &declared, &kept))); }
            signature.params = params;
            let mut options: Vec<ConfigContract> = vec![];
            for option in signature.config.iter() {
                let mut changed = option.clone();
                changed.ty = qualified_ty(&option.ty, &prefix, qualified, &declared, &kept);
                if qualified { changed.default = qualified_default(&option.default, &prefix, &declared); }
                options.push(changed);
            }
            signature.config = options;
            if signature.result.is_some() {
                let result = nikaia_std::index::or(match signature.result.as_ref() {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                }, || Ty::Unknown);
                signature.result = Some(qualified_ty(&result, &prefix, qualified, &declared, &kept));
            }
            entry.signature = Some(signature);
        }
        ledger.functions.insert(key_under(name, &prefix, qualified), entry);
    }
    for (name, contract) in other.types.iter() {
        let mut entry = contract.clone();
        let mut fields: Vec<FieldContract> = vec![];
        for field in contract.fields.iter() {
            let mut changed = field.clone();
            changed.ty = qualified_ty(&field.ty, &prefix, qualified, &declared, &kept);
            fields.push(changed);
        }
        entry.fields = fields;
        ledger.types.insert(key_under(name, &prefix, qualified), entry);
    }
    for (trait_name, types) in other.implementations.iter() {
        let mut widened = types.to_owned();
        if qualified { for ty in types.iter() { widened.insert(format!("{}::{}", prefix, ty)); } }
        if qualified { widen(ledger, format!("{}::{}", prefix, trait_name), &widened); }
        widen(ledger, trait_name.to_owned(), &widened);
    }
    for (name, methods) in other.traits.iter() { ledger.traits.insert(key_under(name, &prefix, qualified), methods.to_owned()); }
}

fn widen(ledger: &mut Ledger, name: String, types: &collections::BTreeSet<String>) {
    let mut all: collections::BTreeSet<String> = nikaia_std::index::or(match *nikaia_std::index::get(&ledger.implementations, &name) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || collections::BTreeSet::new().into());
    for ty in types.iter() { all.insert(ty.to_owned()); }
    ledger.implementations.insert(name, all);
}

fn qualified_default(text: &str, prefix: &str, declared: &collections::BTreeSet<String>) -> String {
    let c: Vec<char> = nikaia_std::list::chars(text.chars());
    let mut out: String = String::from("");
    let mut at: i64 = 0;
    let mut quoted = false;
    while ((at) as usize) < c.len() {
        let here = *nikaia_std::index::get(&c, (at) as usize);
        if quoted {
            out.push(here);
            if here == '\\' && ((at + 1) as usize) < c.len() {
                out.push(*nikaia_std::index::get(&c, (at + 1) as usize));
                at += 2;
                continue;
            }
            if here == '"' { quoted = false; }
            at += 1;
            continue;
        }
        if here == '"' {
            quoted = true;
            out.push(here);
            at += 1;
            continue;
        }
        if here.is_alphabetic() || here == '_' {
            let start: i64 = at;
            let mut word: String = String::from("");
            while ((at) as usize) < c.len() && ((*nikaia_std::index::get(&c, (at) as usize)).is_alphanumeric() || *nikaia_std::index::get(&c, (at) as usize) == '_') {
                word.push(*nikaia_std::index::get(&c, (at) as usize));
                at += 1;
            }
            let after_path = start >= 2 && *nikaia_std::index::get(&c, nikaia_std::index::at(start - 1)) == ':' && *nikaia_std::index::get(&c, nikaia_std::index::at(start - 2)) == ':';
            if !after_path && declared.contains(&word) {
                out.push_str(prefix);
                out.push_str("::");
            }
            out.push_str(&word);
            continue;
        }
        out.push(here);
        at += 1;
    }
    out
}

fn key_under(name: &str, prefix: &str, qualified: bool) -> String {
    if qualified { return format!("{}::{}", prefix, name); }
    name.to_owned()
}

fn qualified_ty(ty: &Ty, prefix: &str, qualified: bool, declared: &collections::BTreeSet<String>, renames: &collections::BTreeMap<String, String>) -> Ty {
    let mut out = ty.clone();
    if qualified { out = qualify(ty, prefix, declared); }
    if !renames.is_empty() { out = renamed(&out, renames); }
    out
}


// --- ledger_text.nika ---

pub fn ledger_text(ledger: &Ledger) -> String {
    let mut out: String = String::from("");
    out.push_str("# AUTO-GENERATED by `nikaia`. Commit this file like a lockfile.\n");
    out.push_str("# Do not edit by hand - it is regenerated on every build.\n");
    out.push_str("#\n");
    out.push_str("# What a caller has to know about a function it cannot see the body of:\n");
    out.push_str("# whether it may pause (`sync`), whether it may fail and with what\n");
    out.push_str("# (`throws`), and what its result may point into (`returns`). Part III, 13.5.\n");
    out.push_str("#\n");
    out.push_str("# A `\"?\"` among the errors is the absence of a claim: it fails, with\n");
    out.push_str("# something this compiler cannot name.\n");
    out.push_str(&contract_text(ledger, &no_notes()));
    out
}

pub fn derived_text(ledger: &Ledger) -> String {
    let mut out: String = String::from("");
    out.push_str("# AUTO-GENERATED by `nikaia`, beside the contract it describes.\n");
    out.push_str("# What that contract was derived from: the compiler, the inference and\n");
    out.push_str("# the sources. A consumer believes the contract while the sources hash\n");
    out.push_str("# as recorded here. Part III, 13.5.\n");
    out.push_str(&format!("version = {}\n", ledger.version));
    out.push_str(&format!("toolchain = \"{}\"\n", ledger.toolchain));
    out.push_str(&format!("inference = \"{}\"\n", ledger.inference));
    if !ledger.sources.is_empty() {
        out.push_str("\n[sources]\n");
        for (unit, hash) in ledger.sources.iter() { out.push_str(&format!("\"{}\" = \"{}\"\n", unit, hash)); }
    }
    out
}

pub fn description_text(ledger: &Ledger, crate_name: &str, version: &str, notes: &Notes) -> String {
    let mut out: String = String::from("");
    out.push_str(&format!("# The boundary of `{}`, described before it is called\n", crate_name));
    out.push_str("# ([ADR-290](../../docs/specification/adr/adr-290.md) D2).\n");
    out.push_str("#\n");
    out.push_str(&format!("# Written by `nikaia describe {}` from the crate's `pub` signatures,\n", crate_name));
    out.push_str("# translated by Part III 15.2's table. **Committed and reviewed like code**,\n");
    out.push_str("# and a hand edit is expected: what a signature cannot say is written\n");
    out.push_str("# fail-closed, and what it says wrongly is caught by the reviewer or by\n");
    out.push_str("# nobody (D5).\n");
    out.push_str("#\n");
    out.push_str("# What the signatures do not say: no `touches` on any entry, which reads as\n");
    out.push_str("# *touches everything*; no `locks`, which is that column's third answer.\n");
    out.push_str("# Neither is something a Rust signature can tell anybody, and reading\n");
    out.push_str("# silence as nothing at all is the polarity ADR-010 D1 forbids.\n");
    out.push_str("#\n");
    out.push_str(&format!("# crate: {} {}\n", crate_name, version));
    if !notes.about_the_crate.is_empty() {
        out.push_str("#\n");
        for line in notes.about_the_crate.iter() { out.push_str(&format!("# {}\n", line)); }
    }
    out.push_str(&contract_text(ledger, notes));
    out
}

fn no_notes() -> Notes { Notes { about_the_crate: vec![], about_a_function: collections::BTreeMap::new() } }

pub fn throws_text(errors: &[String]) -> String { format!("[{}]", quoted_all(errors)) }

fn quoted_all(items: &[String]) -> String {
    let mut out: String = String::from("");
    for item in items.iter() {
        if !out.is_empty() { out.push_str(", "); }
        out.push_str(&format!("\"{}\"", item));
    }
    out
}

fn ledger_escaped(value: &str) -> String { value.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n") }

pub fn contract_text(ledger: &Ledger, notes: &Notes) -> String {
    let mut out = format!("version = {}\n", ledger.version);
    for (name, contract) in ledger.functions.iter() {
        out.push('\n');
        let about: Vec<String> = nikaia_std::index::or(match *nikaia_std::index::get(&notes.about_a_function, name) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || vec![].into());
        for line in about.iter() { out.push_str(&format!("# {}\n", line)); }
        out.push_str(&format!("[fn.\"{}\"]\n", name));
        out.push_str(&function_text(name, contract));
    }
    for (name, _) in ledger.traits.iter() { out.push_str(&format!("\n[trait.\"{}\"]\n", name)); }
    for (trait_name, types) in ledger.implementations.iter() { for ty in types.iter() { out.push_str(&format!("\n[impl.\"{} for {}\"]\n", trait_name, ty)); } }
    for (name, contract) in ledger.types.iter() {
        out.push_str(&format!("\n[type.\"{}\"]\n", name));
        out.push_str(&type_text(contract));
    }
    out
}

fn function_text(name: &str, contract: &FnContract) -> String {
    let mut out: String = String::from("");
    if contract.public { out.push_str("pub = true\n"); }
    match &contract.sync_claim {
        Sync::Asserted => out.push_str("sync = true\n"),
        Sync::Inferred => out.push_str("sync = \"inferred\"\n"),
        Sync::Unpromised => out.push_str("sync = \"inferred\"\n"),
        Sync::From(lambda) => out.push_str(&format!("sync = \"sync({})\"\n", lambda)),
        Sync::No => { },
    }
    if !contract.fails_with.is_empty() { out.push_str(&format!("throws = {}\n", throws_text(&contract.fails_with))); }
    let spelled = spelled_of(name, contract);
    let mut borrows_said = false;
    let mut mutates_said = false;
    let mut signature_line: String = String::from("");
    if spelled.is_some() {
        let said = match spelled { Some(__nikaia_value) => __nikaia_value, None => return out };
        borrows_said = said.borrows_said;
        mutates_said = said.mutates_said;
        signature_line = format!("signature = \"{}\"\n", ledger_escaped(&said.text));
    }
    if !contract.borrows.is_empty() && !borrows_said { out.push_str(&format!("returns = \"ref({})\"\n", contract.borrows.join(" | "))); }
    if !contract.keeps.is_empty() { out.push_str(&format!("keeps = [{}]\n", quoted_all(&contract.keeps))); }
    if contract.mutates && !mutates_said { out.push_str("mutates = true\n"); }
    match contract.touches_a_lock {
        Lock::No => { },
        Lock::Holds => out.push_str("locks = true\n"),
        Lock::Undecided => out.push_str("locks = \"?\"\n"),
    }
    match contract.threads {
        Threads::Undecided => { },
        Threads::May => out.push_str("threads = true\n"),
        Threads::MayNot => out.push_str("threads = false\n"),
    }
    if contract.touches_known {
        let mut touched: Vec<String> = vec![];
        for touch in contract.touches.iter() { touched.push(touch.text()); }
        out.push_str(&format!("touches = [{}]\n", quoted_all(&touched)));
    }
    if contract.provenance.is_some() {
        let provenance = match match contract.provenance.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => return out };
        out.push_str(&format!("provenance = \"{}\"\n", provenance.as_str()));
    }
    if !contract.views.is_empty() {
        let mut views: Vec<String> = vec![];
        for held in contract.views.iter() { views.push(held.text()); }
        out.push_str(&format!("views = [{}]\n", quoted_all(&views)));
    }
    if !contract.sharing.is_empty() {
        let mut classes: Vec<String> = vec![];
        for class in contract.sharing.iter() { classes.push(class.text()); }
        out.push_str(&format!("sharing = [{}]\n", quoted_all(&classes)));
    }
    if contract.ends_by_length { out.push_str("ends_by_length = true\n"); }
    out.push_str(&claims_text("requires", &contract.requires));
    out.push_str(&claims_text("ensures", &contract.ensures));
    out.push_str(&claims_text("from", &contract.from));
    out.push_str(&signature_line);
    out
}

fn spelled_of(name: &str, contract: &FnContract) -> Option<Spelled> {
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(spell(&signature.text(), name, &contract.borrows, contract.mutates))
}

fn claims_text(key: &str, claims: &[String]) -> String {
    if claims.is_empty() { return String::from(""); }
    let mut escaped: Vec<String> = vec![];
    for claim in claims.iter() { escaped.push(ledger_escaped(claim)); }
    format!("{} = [{}]\n", key, quoted_all(&escaped))
}

fn type_text(contract: &TypeContract) -> String {
    let mut out: String = String::from("");
    if contract.public { out.push_str("pub = true\n"); }
    if !contract.fields.is_empty() {
        let mut fields: Vec<String> = vec![];
        for field in contract.fields.iter() {
            let word = if field.public { "pub " } else { "" };
            fields.push(format!("{}{}: {}", word, field.name, field.ty.text()));
        }
        out.push_str(&format!("fields = [{}]\n", quoted_all(&fields)));
    }
    if !contract.variants.is_empty() {
        let mut variants: Vec<String> = vec![];
        for variant in contract.variants.iter() { variants.push(variant.text()); }
        out.push_str(&format!("variants = [{}]\n", quoted_all(&variants)));
    }
    match contract.crosses {
        Crosses::May => out.push_str("crosses = true\n"),
        Crosses::MayNot => out.push_str("crosses = false\n"),
        Crosses::Undecided => { },
    }
    if contract.compares { out.push_str("compares = true\n"); }
    if contract.copies { out.push_str("copies = true\n"); }
    if contract.iterates_fallibly { out.push_str("iterates = \"throws\"\n"); }
    if !contract.touches.is_empty() { out.push_str(&format!("touches = [{}]\n", quoted_all(&contract.touches))); }
    if !contract.tethered.is_empty() { out.push_str(&format!("tethered = [{}]\n", quoted_all(&contract.tethered))); }
    if !contract.constant.is_empty() { out.push_str(&format!("constant = \"{}\"\n", contract.constant)); }
    out
}


// --- lends.nika ---

const COPIED: [&str; 18] = ["i8", "i16", "i32", "i64", "isize", "usize", "u8", "u16", "u32", "u64", "f32", "f64", "bool", "char", "Duration", "Shared", "SharedMut", "Locked"];

pub fn lends_in(contract: &FnContract, at: i64, copying: &[&Ledger]) -> bool {
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return false };
    let mut position: i64 = 0;
    for (name, ty) in signature.params.iter() {
        if position == at {
            if nikaia_std::list::contains(&signature.mutable, &name) || name == "self" { return false; }
            if ty.is_a_view() { return true; }
            return !signature.takes_a_receiver() && moves(ty) && !a_ledger_copies(ty, copying) && !nikaia_std::list::contains(&contract.keeps, &name);
        }
        position += 1;
    }
    false
}

pub fn a_ledger_copies(ty: &Ty, copying: &[&Ledger]) -> bool {
    match ty {
        Ty::Named { name, view, .. } => { let view = *view; !view && described_as_copying(name, copying) },
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); a_ledger_copies(inner, copying) },
        _ => false,
    }
}

fn described_as_copying(name: &str, copying: &[&Ledger]) -> bool {
    for ledger in copying.iter() {
        let ledger = *ledger;
        let described = match *nikaia_std::index::get(&ledger.types, name) { Some(__nikaia_value) => __nikaia_value, None => continue };
        if described.copies { return true; }
    }
    false
}

pub fn moves(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; a_name_that_moves(name, args, view) },
        Ty::Fn { .. } => true,
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); moves(inner) },
        Ty::Tuple(parts) => any_moves(parts),
        _ => false,
    }
}

fn a_name_that_moves(name: &str, args: &[Ty], view: bool) -> bool {
    let base = base_name(name);
    if base == ARRAY { return any_moves(args); }
    if view { return false; }
    for one in COPIED.iter() {
        let one = *one;
        if one == base { return false; }
    }
    true
}

fn any_moves(types: &[Ty]) -> bool {
    for one in types.iter() { if moves(one) { return true; } }
    false
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Passed {
    pub parameter: String,
    pub callee: String,
    pub at: i64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Uses {
    pub kept: collections::BTreeSet<String>,
    pub passed: Vec<Passed>,
}

pub fn kept_by(graph: &collections::BTreeMap<String, Uses>, own: &Ledger, library: &Ledger) -> collections::BTreeMap<String, collections::BTreeSet<String>> {
    let mut kept: collections::BTreeMap<String, collections::BTreeSet<String>> = collections::BTreeMap::new();
    for (name, uses) in graph.iter() { kept.insert(name.to_owned(), uses.kept.to_owned()); }
    let mut changed = true;
    while changed {
        changed = false;
        for (name, uses) in graph.iter() {
            for passed in uses.passed.iter() {
                if keeps_already(&kept, name, &passed.parameter) { continue; }
                if keeps_its(&passed.callee, passed.at, &kept, own, library) {
                    add_kept(&mut kept, name, &passed.parameter);
                    changed = true;
                }
            }
        }
    }
    kept
}

fn keeps_already(kept: &collections::BTreeMap<String, collections::BTreeSet<String>>, name: &str, parameter: &str) -> bool {
    let parameters = match *nikaia_std::index::get(&kept, name) { Some(__nikaia_value) => __nikaia_value, None => return false };
    parameters.contains(parameter)
}

fn add_kept(kept: &mut collections::BTreeMap<String, collections::BTreeSet<String>>, name: &str, parameter: &str) {
    let mut parameters: collections::BTreeSet<String> = collections::BTreeSet::new();
    if kept.contains_key(name) {
        let held = match *nikaia_std::index::get(&kept, name) { Some(__nikaia_value) => __nikaia_value, None => return };
        for one in held.iter() { parameters.insert(one.to_owned()); }
    }
    parameters.insert(parameter.to_owned());
    kept.insert(name.to_owned(), parameters);
}

fn keeps_its(callee: &str, at: i64, settling: &collections::BTreeMap<String, collections::BTreeSet<String>>, own: &Ledger, library: &Ledger) -> bool {
    if settling.contains_key(callee) {
        let contract = match *nikaia_std::index::get(&own.functions, callee) { Some(__nikaia_value) => __nikaia_value, None => return true };
        let parameter = match parameter_at(contract, at) { Some(__nikaia_value) => __nikaia_value, None => return true };
        return keeps_already(settling, callee, &parameter);
    }
    if own.functions.contains_key(callee) {
        let contract = match *nikaia_std::index::get(&own.functions, callee) { Some(__nikaia_value) => __nikaia_value, None => return true };
        return keeps_at(contract, at);
    }
    let contract = match *nikaia_std::index::get(&library.functions, callee) { Some(__nikaia_value) => __nikaia_value, None => return true };
    keeps_at(contract, at)
}

fn keeps_at(contract: &FnContract, at: i64) -> bool {
    let parameter = match parameter_at(contract, at) { Some(__nikaia_value) => __nikaia_value, None => return true };
    nikaia_std::list::contains(&contract.keeps, &parameter)
}

fn parameter_at(contract: &FnContract, at: i64) -> Option<String> {
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return None };
    let mut position: i64 = 0;
    for (name, _) in signature.params.iter() {
        if position == at { return Some(name.to_owned()); }
        position += 1;
    }
    None
}


// --- locks.nika ---

const DOORS: [&str; 10] = ["Locked::get", "Locked::set", "Locked::set(after)", "Locked::access", "Locked::update", "SharedMut::get", "SharedMut::set", "SharedMut::set(after)", "SharedMut::access", "SharedMut::update"];

const MULTI: [&str; 2] = ["access_all", "update_all"];

const FIELD: &str = "field:";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BodyCalls {
    pub resolved: collections::BTreeSet<String>,
    pub unresolved: bool,
    pub fields_called: collections::BTreeSet<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Reaches {
    pub itself: Lock,
    pub callees: collections::BTreeSet<String>,
}

pub fn stored_reaches(field: &str, resolved: &collections::BTreeSet<String>, unresolved: bool, free: &collections::BTreeSet<String>, graph: &mut collections::BTreeMap<String, Reaches>) {
    let mut reaches = Reaches { itself: Lock::No, callees: collections::BTreeSet::new() };
    if unresolved { reaches.itself = reaches.itself.or(Lock::Undecided); }
    if any_in(resolved, &DOORS) || any_in(free, &MULTI) { reaches.itself = reaches.itself.or(Lock::Holds); }
    for to in resolved.iter() { reaches.callees.insert(to.to_owned()); }
    for to in free.iter() { reaches.callees.insert(to.to_owned()); }
    graph.insert(format!("{}{}", FIELD, field), reaches);
}

pub fn unit_reaches(program: &Program, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, calls: &collections::BTreeMap<String, BodyCalls>, graph: &mut collections::BTreeMap<String, Reaches>) {
    for item in program.items.iter() {
        match &item.node {
            Item::Fn { name, body, .. } => {
                let name = *name;
                let key = key_of_function((name).as_ref(), "", names);
                graph.insert(key.to_owned(), body_reaches(body, *nikaia_std::index::get(&calls, &key), names, unaliased, holes_of));
            },
            Item::Impl { target, methods, .. } => {
                let owner = names.resolve(target.name).to_owned();
                for method in methods.iter() {
                    match &method.node {
                        Item::Fn { name, body, .. } => {
                            let name = *name;
                            let key = key_of_function((name).as_ref(), &owner, names);
                            graph.insert(key.to_owned(), body_reaches(body, *nikaia_std::index::get(&calls, &key), names, unaliased, holes_of));
                        },
                        _ => { },
                    }
                }
            },
            Item::Grammar(def) => rules_reaches(def, names, unaliased, holes_of, calls, graph),
            _ => { },
        }
    }
}

pub fn free_calls(body: &Block, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>) -> collections::BTreeSet<String> {
    let mut reaches = Reaches { itself: Lock::No, callees: collections::BTreeSet::new() };
    walk_calls(body, names, unaliased, holes_of, &mut reaches);
    reaches.callees
}

pub fn declared_types(program: &Program, names: &winnow_grammar::InternerContext, declared: &mut collections::BTreeSet<String>) {
    for item in program.items.iter() {
        match &item.node {
            Item::Enum { name, .. } => {
                let name = *name;
                declared.insert(names.resolve(name).to_owned());
            },
            Item::Struct { name, .. } => {
                let name = *name;
                declared.insert(names.resolve(name).to_owned());
            },
            _ => { },
        }
    }
}

pub fn locking_of(graph: &collections::BTreeMap<String, Reaches>, declared: &collections::BTreeSet<String>, library: &Ledger, own: &Ledger) -> Locking {
    let mut itself: collections::BTreeMap<String, Lock> = collections::BTreeMap::new();
    let mut callees: collections::BTreeMap<String, collections::BTreeSet<String>> = collections::BTreeMap::new();
    for (name, reaches) in graph.iter() {
        itself.insert(name.to_owned(), reaches.itself.clone());
        callees.insert(name.to_owned(), reaches.callees.to_owned());
    }
    locking(&itself, &callees, declared, library, own)
}

fn key_of_function(name: Option<&winnow_grammar::Symbol>, owner: &str, names: &winnow_grammar::InternerContext) -> String {
    let symbol = match name { Some(__nikaia_value) => __nikaia_value, None => return with_owner(owner, "new") };
    with_owner(owner, names.resolve(*symbol))
}

fn with_owner(owner: &str, own: &str) -> String {
    if owner.is_empty() { return own.to_owned(); }
    format!("{}::{}", owner, own)
}

fn body_reaches(body: &Block, calls: Option<&BodyCalls>, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>) -> Reaches {
    let mut reaches = Reaches { itself: Lock::No, callees: collections::BTreeSet::new() };
    resolved_into(calls, true, &mut reaches);
    walk_calls(body, names, unaliased, holes_of, &mut reaches);
    reaches
}

fn resolved_into(calls: Option<&BodyCalls>, with_fields: bool, reaches: &mut Reaches) {
    let known = match calls { Some(__nikaia_value) => __nikaia_value, None => return };
    if known.unresolved { reaches.itself = reaches.itself.or(Lock::Undecided); }
    if any_in(&known.resolved, &DOORS) { reaches.itself = reaches.itself.or(Lock::Holds); }
    for to in known.resolved.iter() { reaches.callees.insert(to.to_owned()); }
    if with_fields { for field in known.fields_called.iter() { reaches.callees.insert(format!("{}{}", FIELD, field)); } }
}

fn rules_reaches(def: &GrammarDef, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, calls: &collections::BTreeMap<String, BodyCalls>, graph: &mut collections::BTreeMap<String, Reaches>) {
    let named = names.resolve(def.name).to_owned();
    let mut whole = Reaches { itself: Lock::No, callees: collections::BTreeSet::new() };
    for rule in def.rules.iter() {
        for alt in rule.alts.iter() {
            let action = match alt.action.as_ref() { Some(__nikaia_value) => __nikaia_value, None => continue };
            walk_calls(action, names, unaliased, holes_of, &mut whole);
        }
    }
    for rule in def.rules.iter() {
        if !rule.is_entry { continue; }
        let key = format!("{}::{}", named, names.resolve(rule.name));
        let mut reaches = Reaches { itself: whole.itself.clone(), callees: whole.callees.to_owned() };
        resolved_into(*nikaia_std::index::get(&calls, &key), false, &mut reaches);
        graph.insert(key, reaches);
    }
}

fn walk_calls(block: &Block, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, reaches: &mut Reaches) {
    for seen in seen_in(block, names, unaliased, holes_of, &no_root, false) {
        match seen {
            Seen::Call { ref name, .. } => {
                let called = unaliased(name);
                if a_name_in(&called, &MULTI) { reaches.itself = reaches.itself.or(Lock::Holds); }
                reaches.callees.insert(called);
            },
            _ => { },
        }
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn no_root(_name: &str) -> i64 { -1 }

fn any_in(names: &collections::BTreeSet<String>, table: &[&str]) -> bool {
    for name in names.iter() { if a_name_in(name, table) { return true; } }
    false
}

fn a_name_in(name: &str, table: &[&str]) -> bool {
    for one in table.iter() {
        let one = *one;
        if one == name { return true; }
    }
    false
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Locking {
    pub functions: collections::BTreeMap<String, Lock>,
    pub fields: collections::BTreeMap<String, Lock>,
}

pub fn locking(itself: &collections::BTreeMap<String, Lock>, callees: &collections::BTreeMap<String, collections::BTreeSet<String>>, declared: &collections::BTreeSet<String>, library: &Ledger, own: &Ledger) -> Locking {
    let mut touches = itself.to_owned();
    let mut changed = true;
    while changed {
        changed = false;
        for (name, called) in callees.iter() {
            let before = nikaia_std::index::or(match *nikaia_std::index::get(&touches, name) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || Lock::No);
            if before.holds() { continue; }
            let mut reached = Lock::No;
            for callee in called.iter() { reached = reached.or(theirs_of(&touches, library, declared, callee)); }
            let grown = before.or(reached);
            if grown != before {
                touches.insert(name.to_owned(), grown);
                changed = true;
            }
        }
    }
    let mut answer = Locking { functions: collections::BTreeMap::new(), fields: collections::BTreeMap::new() };
    for (name, holds) in touches.iter() {
        if name.starts_with("field:") {
            let c: Vec<char> = nikaia_std::list::chars(name.chars());
            let field = slice(&c, 6, c.len() as i64);
            let settled = if published(own, &field) { holds.clone().or(Lock::Undecided) } else { holds.clone() };
            answer.fields.insert(field, settled);
        } else if own.functions.contains_key(name) { answer.functions.insert(name.to_owned(), holds.clone()); }
    }
    answer
}

fn theirs_of(touches: &collections::BTreeMap<String, Lock>, library: &Ledger, declared: &collections::BTreeSet<String>, callee: &str) -> Lock {
    let constructed = format!("{}::new", callee);
    for key in [callee.to_owned(), constructed] {
        let found = match match *nikaia_std::index::get(&touches, &key) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => match described(library, &key) { Some(__nikaia_value) => __nikaia_value, None => continue } };
        return found;
    }
    if is_a_variant(declared, callee) { Lock::No } else { Lock::Undecided }
}

fn described(library: &Ledger, key: &str) -> Option<Lock> {
    let contract = match *nikaia_std::index::get(&library.functions, key) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(contract.touches_a_lock.clone())
}

fn is_a_variant(declared: &collections::BTreeSet<String>, callee: &str) -> bool {
    let mut parts: Vec<String> = vec![];
    for part in callee.split("::") { parts.push(part.to_owned()); }
    if parts.len() < 2 || *nikaia_std::index::get(&parts, nikaia_std::index::at(parts.len() as i64 - 1)) == "new" { return false; }
    declared.contains(&struct_type(callee))
}

fn published(own: &Ledger, field: &str) -> bool {
    let c: Vec<char> = nikaia_std::list::chars(field.chars());
    let dot = find_text(&c, 0, ".");
    if dot < 0 { return false; }
    let owner = slice(&c, 0, dot);
    let name = slice(&c, dot + 1, c.len() as i64);
    let contract = match *nikaia_std::index::get(&own.types, &owner) { Some(__nikaia_value) => __nikaia_value, None => return false };
    if !contract.public { return false; }
    for one in contract.fields.iter() { if one.name == name && one.public { return true; } }
    false
}


// --- manifest.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Switch {
    Kept,
    Moved(String),
}

pub fn known() -> Vec<String> { vec![String::from("target"), String::from("user-parallelism"), String::from("reentrancy-check"), String::from("cleanup-deadline"), String::from("optimization"), String::from("refuted-claims")] }

fn withdrawn(key: &str) -> String {
    if key == "ordering" { return String::from("statements run in the order they are written, so there's nothing left for it to turn off. To run two things together, write `overlap { … }`; `--overlaps` shows which branches did"); }
    String::from("")
}

fn moved(key: &str) -> String {
    if key == "cleanup-deadline" { return String::from("the runtime configuration file `nikaia-runtime.toml`, which is read when the program starts. How long a program waits at exit is set by whoever runs it, and the compiler no longer reads this key"); }
    String::from("")
}

pub fn build_key(key: &str) -> Result<Switch, nikaia_std::error::Thrown<Refused>> {
    let gone = withdrawn(key);
    if !gone.is_empty() { return Err(nikaia_std::error::throwing(Refused::Because(format!("`{}` in `[build]` is no longer supported: {}", key, gone)), &"build_key")); }
    if !contains(&known(), key) {
        let expected = choices(&known());
        return Err(nikaia_std::error::throwing(Refused::Because(format!("`[build]` has no key called `{}`. The keys are: {}.", key, expected)), &"build_key"));
    }
    let went = moved(key);
    if !went.is_empty() { return Ok(Switch::Moved(format!("`{}` in `[build]` has moved to {}", key, went))); }
    Ok(Switch::Kept)
}

pub fn targets() -> Vec<String> { vec![String::from("x86_64-linux"), String::from("aarch64-linux"), String::from("wasm32-unknown")] }

pub fn codegen_keys() -> Vec<String> { vec![String::from("opt-level"), String::from("lto"), String::from("incremental")] }

pub fn codegen_table(target: &str) -> Result<(), nikaia_std::error::Thrown<Refused>> {
    if !contains(&targets(), target) {
        let expected = choices(&targets());
        return Err(nikaia_std::error::throwing(Refused::Because(format!("`[build.{}]` isn't a machine Nikaia builds for. The machines are: {}.", target, expected)), &"codegen_table"));
    }
    Ok(())
}

pub fn codegen_key(target: &str, key: &str) -> Result<(), nikaia_std::error::Thrown<Refused>> {
    if !contains(&codegen_keys(), key) {
        let expected = choices(&codegen_keys());
        return Err(nikaia_std::error::throwing(Refused::Because(format!("`[build.{}]` has no key called `{}`. The keys are: {}.", target, key, expected)), &"codegen_key"));
    }
    Ok(())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DependencyShape {
    Rust,
    Path,
    Nikaia,
}

pub fn dependency(name: &str, typed: bool, kind: &str, has_path: bool) -> Result<DependencyShape, nikaia_std::error::Thrown<Refused>> {
    if typed {
        if kind == "rust" { return Ok(DependencyShape::Rust); }
        return Err(nikaia_std::error::throwing(Refused::Because(format!("Dependency `{}` has `type = \"{}\"`, which isn't a kind of dependency Nikaia knows. The only one is `rust`, for a crate from crates.io.", name, kind)), &"dependency"));
    }
    if has_path { return Ok(DependencyShape::Path); }
    Ok(DependencyShape::Nikaia)
}

pub fn crate_name(key: &str) -> String {
    let mut name: String = String::from("");
    for c in key.chars() { if c == '-' { name.push('_'); } else { name.push(c); } }
    name
}

fn contains(words: &[String], word: &str) -> bool {
    for w in words.iter() { if w == word { return true; } }
    false
}

fn choices(words: &[String]) -> String {
    let mut out: String = String::from("");
    for w in words.iter() {
        if !out.is_empty() { out.push_str(", "); }
        out.push_str(w);
    }
    out
}


// --- modules.nika ---

pub fn declared_names(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>]) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    for item in items.iter() {
        let name = name_declared(names, &item.node);
        if !name.is_empty() { out.push(name); }
    }
    out
}

pub fn a_use_refused(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>], here: &str, reachable: &collections::BTreeSet<String>, alone: bool, beside: &impl Fn(&str) -> bool) -> Option<String> {
    let mut named: Vec<(String, String)> = vec![];
    for item in items.iter() {
        let segments = use_segments(names, &item.node);
        if segments.is_empty() || *nikaia_std::index::get(&segments, 0) == "std" { continue; }
        let first = (*nikaia_std::index::get(&segments, 0)).to_owned();
        if segments.len() > 1 {
            let written = segments.join("::");
            return Some(format!("`use {}` in {}: `use` takes a package name only, not a path into it. Write `use {}`, and `{}` where you need it.", written, here, first, written));
        }
        let called = alias_of(names, &item.node);
        if !called.is_empty() { named.push((first, called)); } else { named.push((first.to_owned(), first)); }
    }
    let mut once: collections::BTreeSet<String> = collections::BTreeSet::new();
    for (_, called) in named.iter() {
        if once.contains(called) { return Some(format!("`{}` is used twice in {}. Two packages can't have the same name in one file. Write `use … as …` to give one of them another name.", called, here)); }
        once.insert(called.to_owned());
    }
    for (package, _) in named.iter() {
        if reachable.contains(package) { continue; }
        if alone { return Some(format!("`use {}` in {}: a single file outside a project has no dependencies, so there's no `{}` to use.\nDependencies are declared in a project's `nikaia.toml`. Put this file in a project whose `nikaia.toml` declares it:\n    [dependencies]\n    {} = {{ path = \"../{}\" }}", package, here, package, package, package)); }
        if beside(package) { return Some(format!("`use {}` in {}: the files of a package already see each other, so there's nothing to bring in. Remove the line and use the name directly.", package, here)); }
        return Some(format!("`use {}` in {}: there's no dependency called `{}`.\nAdd it to the project's `[dependencies]` under that name:\n    [dependencies]\n    {} = {{ path = \"../{}\" }}", package, here, package, package, package));
    }
    None
}

fn use_segments(names: &winnow_grammar::InternerContext, item: &Item) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    match item {
        Item::Import { path, .. } => { for segment in path.iter() { out.push(names.resolve(*segment).to_owned()); } },
        _ => { },
    }
    out
}

fn alias_of(names: &winnow_grammar::InternerContext, item: &Item) -> String {
    match item {
        Item::Import { alias, .. } => { let alias = *alias; a_symbols_text(names, alias) },
        _ => String::from(""),
    }
}

pub fn could_promise(contracts: &Ledger, theirs: &collections::BTreeSet<String>, paused_by_code: &collections::BTreeMap<String, Vec<String>>) -> String {
    let mut never: Vec<String> = vec![];
    for (key, contract) in contracts.functions.iter() { if !of_a_dependency(key, theirs) && contract.public && inferred_sync(&contract.sync_claim) { never.push(format!("`{}`", key)); } }
    let mut through: Vec<String> = vec![];
    for (key, lambdas) in paused_by_code.iter() {
        let contract = match *nikaia_std::index::get(&contracts.functions, key) { Some(__nikaia_value) => __nikaia_value, None => continue };
        if of_a_dependency(key, theirs) || !contract.public || !no_sync(&contract.sync_claim) { continue; }
        let mut named: Vec<String> = vec![];
        for lambda in lambdas.iter() { if !nikaia_std::list::contains(&contract.keeps, &lambda) { named.push(lambda.to_owned()); } }
        if (named.len() as i64) == lambdas.len() as i64 { through.push(format!("`{}` (`sync({})`)", key, named.join(", "))); }
    }
    let mut out: String = String::from("");
    if !never.is_empty() {
        let one = never.len() == 1;
        let count = if one { String::from("") } else { format!("{} ", never.len() as i64) };
        let functions = if one { "1 pub function" } else { "pub functions" };
        let s = if one { "s" } else { "" };
        let es = if one { "es" } else { "" };
        out.push_str(&format!("note: {}{} never pause{} and do{} not promise it: {}\n  help: write `sync` after the result, and callers in other packages can rely on it\n", count, functions, s, es, never.join(", ")));
    }
    if !through.is_empty() {
        let one = through.len() == 1;
        let count = if one { String::from("") } else { format!("{} ", through.len() as i64) };
        let functions = if one { "1 pub function" } else { "pub functions" };
        let s = if one { "s" } else { "" };
        let they = if one { "it is" } else { "they are" };
        let es = if one { "es" } else { "" };
        out.push_str(&format!("note: {}{} pause{} only where the lambdas {} given do, and do{} not promise it: {}\n  help: write `sync(f)` after the result, naming those lambdas, and callers in other packages can rely on it\n", count, functions, s, they, es, through.join(", ")));
    }
    out
}

fn of_a_dependency(key: &str, theirs: &collections::BTreeSet<String>) -> bool {
    let parts: Vec<&str> = key.splitn(2, "::").collect::<Vec<_>>();
    parts.len() == 2 && theirs.contains(*nikaia_std::index::get(&parts, 0))
}

fn inferred_sync(claim: &Sync) -> bool { matches!(claim, Sync::Inferred) }

fn no_sync(claim: &Sync) -> bool { matches!(claim, Sync::No) }

pub fn pause_path(chain: &[String]) -> String {
    let mut steps: Vec<String> = vec![];
    let mut k: i64 = 0;
    while ((k + 1) as usize) < chain.len() {
        steps.push(format!("`{}` calls `{}`", *nikaia_std::index::get(&chain, (k) as usize), *nikaia_std::index::get(&chain, (k + 1) as usize)));
        k += 1;
    }
    steps.join(", which ")
}

pub fn lost_sync_unplaced(message: &str, help: &str) -> String { format!("warning[NK2211]: {}\n   = note: a method call it makes, or one of the calls it leads to, can pause.\n   = help: {}\n", message, help) }

pub fn test_function(k: i64) -> String { format!("__nikaia_test_{}", k) }

pub fn test_dispatcher(cli: &str, with_use: bool, count: i64, dispatch: &str) -> String {
    let mut text: String = String::from("");
    if with_use { text.push_str("use std::cli\n"); }
    text.push_str(&format!("fn {}() throws {{\n    let which = {}::args().nth(1) ?? \"\"\n", dispatch, cli));
    for k in 0..count { text.push_str(&format!("    if which == \"{}\" {{\n        {}()\n        return\n    }}\n", k, test_function(k))); }
    text.push_str("    panic(f\"this build has no test numbered `{which}`\")\n}\n");
    text
}


// --- names.nika ---

pub fn names_in(expr: &Expr, words: &winnow_grammar::InternerContext, out: &mut collections::BTreeSet<String>) {
    match expr {
        Expr::Variable(name) => {
            let name = *name;
            out.insert(words.resolve(name).to_owned());
        },
        Expr::Path(segments) => { if !segments.is_empty() { out.insert(words.resolve(*nikaia_std::index::get(&segments, 0)).to_owned()); } },
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            names_in(func, words, out);
            for arg in args.iter() { names_in(arg, words, out); }
            for setting in config.iter() { names_in(&setting.value, words, out); }
        },
        Expr::MethodCall { receiver, method, args, config } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            names_in(receiver, words, out);
            out.insert(words.resolve(method).to_owned());
            for arg in args.iter() { names_in(arg, words, out); }
            for setting in config.iter() { names_in(&setting.value, words, out); }
        },
        Expr::SafeMethod { receiver, method, args, config } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            names_in(receiver, words, out);
            out.insert(words.resolve(method).to_owned());
            for arg in args.iter() { names_in(arg, words, out); }
            for setting in config.iter() { names_in(&setting.value, words, out); }
        },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); names_in(base, words, out) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); names_in(base, words, out) },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            names_in(lhs, words, out);
            names_in(rhs, words, out);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); names_in(expr, words, out) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); names_in(inner, words, out) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); names_in(expr, words, out) },
        Expr::Index { base, index } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            names_in(base, words, out);
            names_in(index, words, out);
        },
        Expr::Tuple(parts) => { for part in parts.iter() { names_in(part, words, out); } },
        Expr::ListLit { items, .. } => { for item in items.iter() { names_in(item, words, out); } },
        Expr::Coalesce { value, fallback } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            names_in(value, words, out);
            names_in(fallback, words, out);
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            names_in(start, words, out);
            names_in(end, words, out);
        },
        Expr::StructLit { name, fields } => {
            let name = *name;
            out.insert(words.resolve(name).to_owned());
            for field in fields.iter() {
                out.insert(words.resolve(field.name).to_owned());
                maybe_names_in((field.value).as_ref(), words, out);
            }
        },
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            names_in(base, words, out);
            for field in fields.iter() {
                out.insert(words.resolve(field.name).to_owned());
                maybe_names_in((field.value).as_ref(), words, out);
            }
        },
        Expr::Block(block) => names_in_block(block, words, out),
        Expr::Unsafe(block) => names_in_block(block, words, out),
        Expr::Overlap(block) => names_in_block(block, words, out),
        Expr::Closure { body, .. } => names_in_block(body, words, out),
        Expr::Select(arms) => {
            for arm in arms.iter() {
                a_symbol(arm.binding, words, out);
                names_in(&arm.value, words, out);
                names_in_block(&arm.body, words, out);
            }
        },
        Expr::If { cond, then_branch, else_branch } => {
            let cond = nikaia_std::boxed::open(cond);
            names_in(cond, words, out);
            names_in_block(then_branch, words, out);
            maybe_names_in_block((else_branch).as_ref(), words, out);
        },
        Expr::Match { value, arms } => {
            let value = nikaia_std::boxed::open(value);
            names_in(value, words, out);
            for arm in arms.iter() {
                match &arm.pattern {
                    MatchPattern::Literal(pattern) => names_in(pattern, words, out),
                    _ => { },
                }
                names_in(&arm.body, words, out);
            }
        },
        Expr::Spawn { body, .. } => { let body = nikaia_std::boxed::open(body); names_in(body, words, out) },
        Expr::Throw(thrown) => { let thrown = nikaia_std::boxed::open(thrown); names_in(thrown, words, out) },
        Expr::Return(value) => { let value = nikaia_std::boxed::open(value); maybe_names_in((value).as_ref(), words, out) },
        Expr::Break => { },
        Expr::Continue => { },
        Expr::TryCatch { expr, handler } => {
            let expr = nikaia_std::boxed::open(expr);
            names_in(expr, words, out);
            names_in_block(handler, words, out);
        },
        Expr::LitInterpolated { parts } => {
            for part in parts.iter() {
                match part {
                    FPart::Hole { expr, .. } => names_in(expr, words, out),
                    FPart::Text(_) => { },
                }
            }
        },
        Expr::Dsl { target, package, context, content } => {
            let context = *context; let package = *package; let target = *target;
            out.insert(words.resolve(target).to_owned());
            a_symbol(package, words, out);
            a_symbol(context, words, out);
            words_of(content, out);
        },
        Expr::Asm { bindings, code } => {
            for binding in bindings.iter() { out.insert(words.resolve(binding.variable).to_owned()); }
            words_of(code, out);
        },
        Expr::LitInt { .. } => { },
        Expr::LitFloat(_) => { },
        Expr::LitBool(_) => { },
        Expr::LitNull => { },
        Expr::LitChar(_) => { },
        Expr::LitStr { .. } => { },
    }
}

pub fn names_in_block(block: &Block, words: &winnow_grammar::InternerContext, out: &mut collections::BTreeSet<String>) { for stmt in block.stmts.iter() { names_in_statement(&stmt.node, words, out); } }

pub fn names_in_statement(stmt: &Stmt, words: &winnow_grammar::InternerContext, out: &mut collections::BTreeSet<String>) {
    match stmt {
        Stmt::Let { value, .. } => names_in(value, words, out),
        Stmt::Comptime { value, .. } => names_in(value, words, out),
        Stmt::Expr(value) => names_in(value, words, out),
        Stmt::Assign { target, value, .. } => {
            names_in(target, words, out);
            names_in(value, words, out);
        },
        Stmt::For { iter, body, .. } => {
            names_in(iter, words, out);
            names_in_block(body, words, out);
        },
        Stmt::While { cond, body } => {
            names_in(cond, words, out);
            names_in_block(body, words, out);
        },
        Stmt::Return(value) => maybe_names_in((value).as_ref(), words, out),
        Stmt::Break => { },
        Stmt::Continue => { },
    }
}

fn maybe_names_in(expr: Option<&Expr>, words: &winnow_grammar::InternerContext, out: &mut collections::BTreeSet<String>) { names_in(match expr { Some(__nikaia_value) => __nikaia_value, None => return }, words, out); }

fn maybe_names_in_block(block: Option<&Block>, words: &winnow_grammar::InternerContext, out: &mut collections::BTreeSet<String>) { names_in_block(match block { Some(__nikaia_value) => __nikaia_value, None => return }, words, out); }

fn a_symbol(name: Option<winnow_grammar::Symbol>, words: &winnow_grammar::InternerContext, out: &mut collections::BTreeSet<String>) {
    let named = match name { Some(__nikaia_value) => __nikaia_value, None => return };
    out.insert(words.resolve(named).to_owned());
}

fn words_of(text: &str, out: &mut collections::BTreeSet<String>) {
    let mut word: String = String::from("");
    for c in text.chars() {
        if c.is_alphanumeric() || c == '_' { word.push(c); } else {
            if !word.is_empty() { out.insert(word.to_owned()); }
            word = String::from("");
        }
    }
    if !word.is_empty() { out.insert(word); }
}


// --- order.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Operation {
    pub binds: Option<String>,
    pub mentions: collections::BTreeSet<String>,
    pub reaches: Vec<Reached>,
    pub callee: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Accounted {
    Operation(Operation),
    NotAnOperation,
    Opaque(String),
    DivertingHandler,
    UncaughtFailure(String),
    NoTouches(String),
    UnknownResource { callee: String, kind: String },
    MayNotCross { callee: String, crossing: Crossing },
    NonLiteralArgument(String),
}

impl Accounted {
    pub fn why(&self) -> String {
        match self {
            Accounted::Operation(_) => String::from("it is an operation"),
            Accounted::NotAnOperation => String::from("one of them performs no operation at all"),
            Accounted::Opaque(what) => format!("one of them holds {}", what),
            Accounted::DivertingHandler => String::from("its `catch` can leave the function, so the next statement might never run. Make the handler return a value instead, and check it afterwards"),
            Accounted::UncaughtFailure(name) => format!("`{}` can fail and nothing catches it, so the next statement might never run. `catch` it into a value, and check it afterwards", name),
            Accounted::NoTouches(name) => format!("nothing says what `{}` touches, so it might touch anything", name),
            Accounted::UnknownResource { callee, kind } => unknown_resource(callee, kind),
            Accounted::MayNotCross { callee, crossing } => may_not_cross(callee, crossing),
            Accounted::NonLiteralArgument(name) => format!("`{}` isn't a literal, and only literals can be sent to another thread", name),
        }
    }
}

fn unknown_resource(callee: &str, kind: &str) -> String {
    let article = an_or_a(kind);
    format!("`{}` says it touches {} `{}`, which this version of Nikaia doesn't know, so it might touch anything", callee, article, kind)
}

fn may_not_cross(callee: &str, crossing: &Crossing) -> String {
    let note = nikaia_std::index::or(crossing.note(), || "It can't.".into());
    format!("what `{}` returns would have to move to another thread. {}", callee, note)
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Verdict {
    Overlap,
    DataDependency(String),
    Shadowed(String),
    SameResource { kind: String, named: Option<String>, unnameable: bool },
    SameDestination { one: String, other: String },
    NotAccountedFor,
}

impl Verdict {
    pub fn is_overlap(&self) -> bool { matches!(self, Verdict::Overlap) }
    pub fn why(&self) -> String {
        match self {
            Verdict::Overlap => String::from("they meet on nothing"),
            Verdict::DataDependency(name) => format!("the second uses `{}`", name),
            Verdict::Shadowed(name) => format!("both bind `{}`", name),
            Verdict::SameResource { kind, named, unnameable } => { let unnameable = *unnameable; same_resource(kind, (named).as_deref(), unnameable) },
            Verdict::SameDestination { one, other } => format!("one touches {} and the other {}, which might be the same place. Use `seq` to run them in order", one, other),
            Verdict::NotAccountedFor => String::from("the compiler can't tell what one of them does"),
        }
    }
}

fn same_resource(kind: &str, named: Option<&str>, unnameable: bool) -> String {
    if named.is_some() {
        let name = nikaia_std::index::or(named, || "");
        return format!("both reach {} `{}`, and one writes it", kind, name);
    }
    if unnameable { return format!("both touch a {} the compiler can't name, and one writes to it", kind); }
    format!("both touch {}, and one writes to it", kind)
}

pub fn verdict(earlier: &Operation, later: &Operation) -> Verdict {
    let bound = written_or_nothing((earlier.binds).as_deref());
    if earlier.binds.is_some() && later.mentions.contains(&bound) { return Verdict::DataDependency(bound.to_owned()); }
    if earlier.binds.is_some() && earlier.binds == later.binds { return Verdict::Shadowed(bound.to_owned()); }
    for a in earlier.reaches.iter() { for b in later.reaches.iter() { if a.conflicts_with(b) { return conflict(a, b); } } }
    Verdict::Overlap
}

fn conflict(a: &Reached, b: &Reached) -> Verdict {
    if a.kind != b.kind { return Verdict::SameDestination { one: a.kind.to_owned(), other: b.kind.to_owned() }; }
    let named = match readable_name(a) { Some(__nikaia_value) => __nikaia_value, None => match readable_name(b) { Some(__nikaia_value) => __nikaia_value, None => return Verdict::SameResource { kind: a.kind.to_owned(), named: None, unnameable: a.unknown || b.unknown } } };
    Verdict::SameResource { kind: a.kind.to_owned(), named: Some(named), unnameable: false }
}

fn readable_name(reached: &Reached) -> Option<String> {
    if reached.unknown { return None; }
    match reached.named.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }
}

pub fn group_verdict(run: &[Operation]) -> Verdict {
    for i in 0..run.len() as i64 {
        for j in i + 1..run.len() as i64 {
            let found = verdict(nikaia_std::index::get(&run, (i) as usize), nikaia_std::index::get(&run, nikaia_std::index::at(j)));
            if !found.is_overlap() { return found; }
        }
    }
    Verdict::Overlap
}

pub fn group_of(run: &[Operation]) -> i64 {
    let mut taken = if !run.is_empty() { 1 } else { 0 };
    while taken < run.len() as i64 {
        if !fits_with_the_front(run, taken) { break; }
        taken += 1;
    }
    if taken < 2 { return 0; }
    taken
}

fn fits_with_the_front(run: &[Operation], at: i64) -> bool {
    for i in 0..at { if !verdict(nikaia_std::index::get(&run, (i) as usize), nikaia_std::index::get(&run, nikaia_std::index::at(at))).is_overlap() { return false; } }
    true
}

const KNOWN_KINDS: [&str; 6] = ["file", "stdout", "stderr", "args", "lock", "socket"];

pub fn accounted(stmt: &Stmt, words: &winnow_grammar::InternerContext, walking: &Walking<'_>) -> Accounted {
    match stmt {
        Stmt::Let { names, value, ty, .. } => {
            if ty.is_some() { return Accounted::Opaque(String::from("a written type, which would have to be carried onto one half of a pattern")); }
            if names.len() != 1 { return Accounted::Opaque(String::from("several names bound at once")); }
            let binds: Option<String> = Some(words.resolve(*nikaia_std::index::get(&names, 0)).to_owned());
            accounted_value(binds, value, words, walking)
        },
        Stmt::Expr(value) => accounted_value(None, value, words, walking),
        _ => Accounted::NotAnOperation,
    }
}

fn accounted_value(binds: Option<String>, value: &Expr, names: &winnow_grammar::InternerContext, walking: &Walking<'_>) -> Accounted {
    match value {
        Expr::TryCatch { expr, handler } => {
            let expr = nikaia_std::boxed::open(expr);
            if diverts_within(&handler.stmts, false) { return Accounted::DivertingHandler; }
            let mut reduced = Reduced { calls: vec![], performs: false, methods: vec![], refused: None };
            reduce(expr, names, &mut reduced);
            reduce_handler(handler, names, &mut reduced);
            let mut mentions: collections::BTreeSet<String> = collections::BTreeSet::new();
            names_in(expr, names, &mut mentions);
            names_in_block(handler, names, &mut mentions);
            accounted_reduced(binds, mentions, &reduced, true, walking)
        },
        _ => {
            let mut reduced = Reduced { calls: vec![], performs: false, methods: vec![], refused: None };
            reduce(value, names, &mut reduced);
            let mut mentions: collections::BTreeSet<String> = collections::BTreeSet::new();
            names_in(value, names, &mut mentions);
            accounted_reduced(binds, mentions, &reduced, false, walking)
        },
    }
}

fn accounted_reduced(binds: Option<String>, mentions: collections::BTreeSet<String>, reduced: &Reduced, caught: bool, walking: &Walking<'_>) -> Accounted {
    if reduced.calls.is_empty() && !reduced.performs { return Accounted::NotAnOperation; }
    let mut reaches: Vec<Reached> = vec![];
    let mut named_by: Vec<String> = vec![];
    for call in reduced.calls.iter() {
        let refused = a_call_reaches(call, caught, walking, &mut reaches, &mut named_by);
        if refused.is_some() { return nikaia_std::index::or(refused, || Accounted::NotAnOperation); }
    }
    for method in reduced.methods.iter() { if !reaches_nothing(method, walking) { return Accounted::NoTouches(method.to_owned()); } }
    if reduced.refused.is_some() {
        return nikaia_std::index::or(match reduced.refused.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || Accounted::NotAnOperation);
    }
    Accounted::Operation(Operation { binds, mentions, reaches, callee: named_by.join(" + ") })
}

fn a_call_reaches(call: &OneCall, caught: bool, walking: &Walking<'_>, reaches: &mut Vec<Reached>, named_by: &mut Vec<String>) -> Option<Accounted> {
    let key = call.key.to_owned();
    let contract = match touches_described(&key, walking) { Some(__nikaia_value) => __nikaia_value, None => return Some(Accounted::NoTouches(key)) };
    if !caught && !contract.fails_with.is_empty() { return Some(Accounted::UncaughtFailure(key)); }
    for touch in contract.touches.iter() { if !known_kind(&touch.kind) { return Some(Accounted::UnknownResource { callee: key.to_owned(), kind: touch.kind.to_owned() }); } }
    let signature = match match contract.signature.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return Some(Accounted::NoTouches(key)) };
    let crossed = crossing(&signature.result_or_unit(), walking);
    if !crossed.may() { return Some(Accounted::MayNotCross { callee: key.to_owned(), crossing: crossed }); }
    let parameters = call_parameters(&signature);
    for touch in contract.touches.iter() {
        let named = argument_named((touch.parameter).as_deref(), &parameters, &call.arguments);
        reaches.push(Reached { kind: touch.kind.to_owned(), unknown: touch.parameter.is_some() && named.is_none(), named, write: touch.write });
    }
    named_by.push(key);
    None
}

fn touches_described(key: &str, walking: &Walking<'_>) -> Option<FnContract> {
    let mine: Option<FnContract> = match *nikaia_std::index::get(&walking.own.functions, key) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    };
    let found = match mine { Some(__nikaia_value) => __nikaia_value, None => match match *nikaia_std::index::get(&walking.library.functions, key) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return None } };
    if !found.touches_known { return None; }
    Some(found)
}

fn known_kind(kind: &str) -> bool {
    for known in KNOWN_KINDS.iter() {
        let known = *known;
        if known == kind { return true; }
    }
    false
}

fn call_parameters(signature: &Signature) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    for i in 0..signature.params.len() as i64 { if i > 0 || nikaia_std::index::get(&signature.params, (i) as usize).0 != "self" { out.push(nikaia_std::index::get(&signature.params, (i) as usize).0.to_owned()); } }
    out
}

fn argument_named(parameter: Option<&str>, parameters: &[String], arguments: &[Expr]) -> Option<String> {
    let wanted = match parameter { Some(__nikaia_value) => __nikaia_value, None => return None };
    for at in 0..parameters.len() as i64 {
        if *nikaia_std::index::get(&parameters, (at) as usize) == wanted {
            if ((at) as usize) >= arguments.len() { return None; }
            return literal_text(nikaia_std::index::get(&arguments, (at) as usize));
        }
    }
    None
}

fn literal_text(expr: &Expr) -> Option<String> {
    match expr {
        Expr::LitStr { text, .. } => Some(text.to_owned()),
        _ => None,
    }
}

fn reaches_nothing(method: &str, walking: &Walking<'_>) -> bool {
    let mut candidates = method_entries(method, walking.own);
    if candidates.is_empty() { candidates = method_entries(method, walking.library); }
    if candidates.is_empty() { return false; }
    for contract in candidates.iter() { if !contract.touches_known || !contract.touches.is_empty() { return false; } }
    true
}

fn method_entries(method: &str, ledger: &Ledger) -> Vec<FnContract> {
    let suffix = format!("::{}", method);
    let mut out: Vec<FnContract> = vec![];
    for (key, contract) in ledger.functions.iter() { if key.ends_with(&suffix) && takes_a_subject((contract.signature).as_ref()) { out.push(contract.clone()); } }
    out
}

fn takes_a_subject(signature: Option<&Signature>) -> bool {
    let written = match signature { Some(__nikaia_value) => __nikaia_value, None => return true };
    written.takes_a_receiver()
}

#[derive(Debug, Clone, PartialEq)]
pub struct OneCall {
    pub key: String,
    pub arguments: Vec<Expr>,
}

#[derive(Debug, Clone, PartialEq)]
struct Reduced {
    calls: Vec<OneCall>,
    performs: bool,
    methods: Vec<String>,
    refused: Option<Accounted>,
}

fn noted(reduced: &mut Reduced, why: Accounted) { if reduced.refused.is_none() { reduced.refused = Some(why); } }

fn stopped(reduced: &mut Reduced, why: Accounted) {
    reduced.performs = true;
    noted(reduced, why);
}

fn reduce_handler(block: &Block, names: &winnow_grammar::InternerContext, reduced: &mut Reduced) {
    for stmt in block.stmts.iter() {
        match &stmt.node {
            Stmt::Let { value, .. } => reduce(value, names, reduced),
            Stmt::Expr(value) => reduce(value, names, reduced),
            _ => stopped(reduced, Accounted::Opaque(String::from("a `catch` handler doing more than handing back a value"))),
        }
    }
}

fn reduce(node: &Expr, names: &winnow_grammar::InternerContext, reduced: &mut Reduced) {
    match node {
        Expr::LitInt { .. } => { },
        Expr::LitFloat(_) => { },
        Expr::LitBool(_) => { },
        Expr::LitNull => { },
        Expr::LitChar(_) => { },
        Expr::LitStr { .. } => { },
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            if !config.is_empty() {
                stopped(reduced, Accounted::Opaque(String::from("a call with options, which nothing matches against the callee's order yet")));
                return;
            }
            let key = match called_key(func, names) { Some(__nikaia_value) => __nikaia_value, None => return stopped(reduced, Accounted::Opaque(String::from("a call through something that is not a name"))) };
            for arg in args.iter() { reduce(arg, names, reduced); }
            reduced.calls.push(OneCall { key, arguments: args.to_owned() });
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); reduce(expr, names, reduced) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); reduce(expr, names, reduced) },
        Expr::Binary { op, lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            if a_short_circuit(op) {
                stopped(reduced, Accounted::Opaque(String::from("a `&&` or `||`, whose right side runs only sometimes")));
                return;
            }
            reduce(lhs, names, reduced);
            reduce(rhs, names, reduced);
        },
        Expr::Tuple(parts) => { for part in parts.iter() { reduce(part, names, reduced); } },
        Expr::ListLit { items, .. } => { for item in items.iter() { reduce(item, names, reduced); } },
        Expr::Return(_) => stopped(reduced, Accounted::Opaque(String::from("a `return`, a `break` or a `continue`"))),
        Expr::Break => stopped(reduced, Accounted::Opaque(String::from("a `return`, a `break` or a `continue`"))),
        Expr::Continue => stopped(reduced, Accounted::Opaque(String::from("a `return`, a `break` or a `continue`"))),
        Expr::Variable(name) => { let name = *name; noted(reduced, Accounted::NonLiteralArgument(names.resolve(name).to_owned())) },
        Expr::Field { base, .. } => {
            let base = nikaia_std::boxed::open(base);
            noted(reduced, Accounted::Opaque(String::from("a value read from somewhere else")));
            reduce(base, names, reduced);
        },
        Expr::SafeField { base, .. } => {
            let base = nikaia_std::boxed::open(base);
            noted(reduced, Accounted::Opaque(String::from("a value read from somewhere else")));
            reduce(base, names, reduced);
        },
        Expr::Index { base, index } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            noted(reduced, Accounted::Opaque(String::from("a value read from somewhere else")));
            reduce(base, names, reduced);
            reduce(index, names, reduced);
        },
        Expr::Path(_) => { },
        Expr::StructLit { fields, .. } => {
            noted(reduced, Accounted::Opaque(String::from("a value read from somewhere else")));
            for field in fields.iter() { reduce_maybe((field.value).as_ref(), names, reduced); }
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            noted(reduced, Accounted::Opaque(String::from("a value read from somewhere else")));
            reduce(start, names, reduced);
            reduce(end, names, reduced);
        },
        Expr::Coalesce { value, fallback } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            noted(reduced, Accounted::Opaque(String::from("a `??`, whose fallback runs only sometimes")));
            reduce(value, names, reduced);
            reduce(fallback, names, reduced);
        },
        Expr::LitInterpolated { .. } => stopped(reduced, Accounted::Opaque(String::from("text with code in it, whose holes this has not parsed"))),
        Expr::MethodCall { receiver, method, args, config } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; reduce_method(receiver, method, args, config, names, reduced) },
        Expr::SafeMethod { receiver, method, args, config } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; reduce_method(receiver, method, args, config, names, reduced) },
        Expr::Closure { .. } => stopped(reduced, Accounted::Opaque(String::from("a lambda, whose body this analysis does not read"))),
        _ => stopped(reduced, Accounted::Opaque(String::from("something with its own control flow"))),
    }
}

fn reduce_method(receiver: &Expr, method: winnow_grammar::Symbol, args: &[Expr], config: &[ConfigArg], names: &winnow_grammar::InternerContext, reduced: &mut Reduced) {
    reduce(receiver, names, reduced);
    for arg in args.iter() { reduce(arg, names, reduced); }
    for option in config.iter() { reduce(&option.value, names, reduced); }
    reduced.methods.push(names.resolve(method).to_owned());
}

fn reduce_maybe(expr: Option<&Expr>, names: &winnow_grammar::InternerContext, reduced: &mut Reduced) { reduce(match expr { Some(__nikaia_value) => __nikaia_value, None => return }, names, reduced); }

fn a_short_circuit(op: &BinaryOp) -> bool { matches!(op, BinaryOp::And | BinaryOp::Or) }

fn called_key(func: &Expr, names: &winnow_grammar::InternerContext) -> Option<String> {
    match func {
        Expr::Variable(name) => { let name = *name; Some(names.resolve(name).to_owned()) },
        Expr::Path(segments) => Some(joined_segments(segments, names)),
        _ => None,
    }
}

fn joined_segments(segments: &[winnow_grammar::Symbol], names: &winnow_grammar::InternerContext) -> String {
    let mut parts: Vec<String> = vec![];
    for segment in segments.iter() { parts.push(names.resolve(*segment).to_owned()); }
    parts.join("::")
}

pub fn diverts_within(stmts: &[Spanned<Stmt>], bound: bool) -> bool {
    for stmt in stmts.iter() {
        let leaves = match &stmt.node {
            Stmt::Return(_) => true,
            Stmt::Break => !bound,
            Stmt::Continue => !bound,
            Stmt::Expr(expr) => holds_throw(expr, bound),
            Stmt::Let { value, .. } => holds_throw(value, bound),
            Stmt::Comptime { value, .. } => holds_throw(value, bound),
            Stmt::Assign { value, .. } => holds_throw(value, bound),
            Stmt::For { body, .. } => diverts_within(&body.stmts, true),
            Stmt::While { body, .. } => diverts_within(&body.stmts, true),
        };
        if leaves { return true; }
    }
    false
}

fn holds_throw(expr: &Expr, bound: bool) -> bool {
    match expr {
        Expr::Throw(_) => true,
        Expr::Block(block) => diverts_within(&block.stmts, bound),
        Expr::Overlap(block) => diverts_within(&block.stmts, bound),
        Expr::If { then_branch, else_branch, .. } => diverts_within(&then_branch.stmts, bound) || else_diverts((else_branch).as_ref(), bound),
        Expr::Match { arms, .. } => an_arm_throws(arms, bound),
        _ => false,
    }
}

fn else_diverts(block: Option<&Block>, bound: bool) -> bool {
    let written = match block { Some(__nikaia_value) => __nikaia_value, None => return false };
    diverts_within(&written.stmts, bound)
}

fn an_arm_throws(arms: &[MatchArm], bound: bool) -> bool {
    for arm in arms.iter() { if holds_throw(&arm.body, bound) { return true; } }
    false
}

pub fn overlap_report(items: &[Spanned<Item>], names: &winnow_grammar::InternerContext, walking: &Walking<'_>, overlaps_in: &impl Fn(&Block) -> Vec<Block>, pauses: &impl Fn(&Spanned<Stmt>) -> bool) -> String {
    let mut out: String = String::from("");
    for item in items.iter() {
        match &item.node {
            Item::Fn { .. } => block_report(&item.node, None, names, walking, overlaps_in, pauses, &mut out),
            Item::Impl { target, methods, .. } => {
                let owner: Option<String> = Some(names.resolve(target.name).to_owned());
                for method in methods.iter() { block_report(&method.node, (owner).as_deref(), names, walking, overlaps_in, pauses, &mut out); }
            },
            _ => { },
        }
    }
    if out.is_empty() { out.push_str("this program writes no `overlap { … }` block.\n"); }
    out
}

fn block_report(item: &Item, target: Option<&str>, names: &winnow_grammar::InternerContext, walking: &Walking<'_>, overlaps_in: &impl Fn(&Block) -> Vec<Block>, pauses: &impl Fn(&Spanned<Stmt>) -> bool, out: &mut String) {
    match item {
        Item::Fn { name, body, .. } => {
            let name = *name;
            let own_name = function_name(names, name);
            let key = keyed(target, &own_name);
            for block in overlaps_in(body) { one_block_report(&key, &block, names, walking, pauses, out); }
        },
        _ => { },
    }
}

fn keyed(target: Option<&str>, own_name: &str) -> String {
    let owner = match target { Some(__nikaia_value) => __nikaia_value, None => return own_name.to_owned() };
    format!("{}::{}", owner, own_name)
}

fn one_block_report(key: &str, block: &Block, names: &winnow_grammar::InternerContext, walking: &Walking<'_>, pauses: &impl Fn(&Spanned<Stmt>) -> bool, out: &mut String) {
    if block.stmts.is_empty() { return; }
    let mut operations: Vec<Operation> = vec![];
    let mut present: Vec<bool> = vec![];
    let mut lines: Vec<String> = vec![];
    for stmt in block.stmts.iter() {
        let answer = accounted(&stmt.node, names, walking);
        let named = match answer {
            Accounted::Operation(ref operation) => operation.callee.to_owned(),
            _ => String::from("…"),
        };
        match answer {
            Accounted::Operation(ref operation) => {
                operations.push(operation.clone());
                present.push(true);
            },
            _ => {
                operations.push(Operation { binds: None, mentions: collections::BTreeSet::new(), reaches: vec![], callee: String::from("") });
                present.push(false);
            },
        }
        let when = if pauses(stmt) { "started first" } else { "runs while they wait" };
        lines.push(format!("    {} {}", padded_right(when, 22), named));
    }
    let count = block.stmts.len() as i64;
    let refused = first_refused(&operations, &present);
    if refused.is_empty() { out.push_str(&format!("{}: an `overlap` of {} branches, which meet on nothing\n", key, count)); } else { out.push_str(&refused_header(key, count, &operations, &refused)); }
    for line in lines.iter() {
        out.push_str(line);
        out.push('\n');
    }
}

fn first_refused(operations: &[Operation], present: &[bool]) -> Vec<i64> {
    for i in 0..operations.len() as i64 { for j in i + 1..operations.len() as i64 { if *nikaia_std::index::get(&present, (i) as usize) && *nikaia_std::index::get(&present, nikaia_std::index::at(j)) && !verdict(nikaia_std::index::get(&operations, (i) as usize), nikaia_std::index::get(&operations, nikaia_std::index::at(j))).is_overlap() { return vec![i, j]; } } }
    vec![]
}

fn refused_header(key: &str, count: i64, operations: &[Operation], pair: &[i64]) -> String {
    let first = *nikaia_std::index::get(&pair, 0) + 1;
    let second = *nikaia_std::index::get(&pair, 1) + 1;
    let why = verdict(nikaia_std::index::get(&operations, nikaia_std::index::at(*nikaia_std::index::get(&pair, 0))), nikaia_std::index::get(&operations, nikaia_std::index::at(*nikaia_std::index::get(&pair, 1)))).why();
    format!("{}: an `overlap` of {} branches, and branches {} and {} may not run together - {}\n", key, count, first, second, why)
}

fn padded_right(text: &str, width: i64) -> String {
    let mut out = text.to_owned();
    let mut have = text.chars().count() as i64;
    while have < width {
        out.push(' ');
        have += 1;
    }
    out
}


// --- parse_notes.nika ---

pub fn previous_token(source: &str, end: i64) -> String {
    let c: Vec<char> = nikaia_std::list::chars(source.chars());
    if end <= 0 { return String::from(""); }
    let last = *nikaia_std::index::get(&c, nikaia_std::index::at(end - 1));
    let mut start = end - 1;
    if a_word_char(last) { while start > 0 && a_word_char(*nikaia_std::index::get(&c, nikaia_std::index::at(start - 1))) { start -= 1; } } else if an_operator_char(last) { while start > 0 && an_operator_char(*nikaia_std::index::get(&c, nikaia_std::index::at(start - 1))) { start -= 1; } }
    slice(&c, start, end)
}

fn a_word_char(c: char) -> bool { c.is_alphanumeric() || c == '_' }

fn an_operator_char(c: char) -> bool { c == '=' || c == '+' || c == '-' || c == '*' || c == '/' || c == '%' || c == '<' || c == '>' || c == '!' || c == '&' || c == '|' }

pub fn unclosed_quote(source: &str) -> i64 {
    let c: Vec<char> = nikaia_std::list::chars(source.chars());
    let mut open: i64 = -1;
    let mut at: i64 = 0;
    while at < c.len() as i64 {
        if open >= 0 {
            if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '\\' {
                at += 2;
                continue;
            }
            if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '"' { open = -1; }
        } else if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '"' { open = at; } else if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '/' && at + 1 < c.len() as i64 && *nikaia_std::index::get(&c, nikaia_std::index::at(at + 1)) == '/' {
            at = past_the_line(&c, at);
            continue;
        }
        at += 1;
    }
    open
}

pub fn unclosed_bracket(source: &str) -> i64 {
    let c: Vec<char> = nikaia_std::list::chars(source.chars());
    let mut stack: Vec<i64> = vec![];
    let mut in_string = false;
    let mut at: i64 = 0;
    while at < c.len() as i64 {
        if in_string {
            if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '\\' {
                at += 2;
                continue;
            }
            if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '"' { in_string = false; }
        } else if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '"' { in_string = true; } else if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '/' && at + 1 < c.len() as i64 && *nikaia_std::index::get(&c, nikaia_std::index::at(at + 1)) == '/' {
            at = past_the_line(&c, at);
            continue;
        } else if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '{' || *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '(' || *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '[' { stack.push(at); } else if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '}' || *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == ')' || *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == ']' { stack.pop(); }
        at += 1;
    }
    if stack.is_empty() { return -1; }
    *nikaia_std::index::get(&stack, nikaia_std::index::at(stack.len() as i64 - 1))
}

fn past_the_line(c: &[char], at: i64) -> i64 {
    let mut k = at;
    while k < c.len() as i64 && *nikaia_std::index::get(&c, nikaia_std::index::at(k)) != '\n' { k += 1; }
    k + 1
}

pub fn opening_of_an_unclosed_comment(source: &str) -> i64 {
    let c: Vec<char> = nikaia_std::list::chars(source.chars());
    let mut open: Vec<i64> = vec![];
    let mut at: i64 = 0;
    while at < c.len() as i64 {
        if open.is_empty() {
            if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '"' {
                at += 1;
                while at < c.len() as i64 {
                    if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '\\' { at += 2; } else if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '"' {
                        at += 1;
                        break;
                    } else { at += 1; }
                }
                continue;
            }
            if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '/' && at + 1 < c.len() as i64 && *nikaia_std::index::get(&c, nikaia_std::index::at(at + 1)) == '/' {
                while at < c.len() as i64 && *nikaia_std::index::get(&c, nikaia_std::index::at(at)) != '\n' { at += 1; }
                continue;
            }
        }
        if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '/' && at + 1 < c.len() as i64 && *nikaia_std::index::get(&c, nikaia_std::index::at(at + 1)) == '*' {
            open.push(at);
            at += 2;
            continue;
        }
        if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '*' && at + 1 < c.len() as i64 && *nikaia_std::index::get(&c, nikaia_std::index::at(at + 1)) == '/' && !open.is_empty() {
            open.pop();
            at += 2;
            continue;
        }
        at += 1;
    }
    if open.is_empty() { return -1; }
    *nikaia_std::index::get(&open, 0)
}

pub fn first_sentence(text: &str) -> Vec<String> {
    let c: Vec<char> = nikaia_std::list::chars(text.chars());
    let mut quoted = false;
    for at in 0..c.len() as i64 {
        if *nikaia_std::index::get(&c, (at) as usize) == '`' { quoted = !quoted; } else if *nikaia_std::index::get(&c, (at) as usize) == '.' && !quoted && ((at + 1) as usize) < c.len() && *nikaia_std::index::get(&c, (at + 1) as usize) == ' ' {
            let rest = slice(&c, at + 1, c.len() as i64).trim().to_owned();
            if rest.is_empty() { return vec![slice(&c, 0, at + 1)]; }
            return vec![slice(&c, 0, at + 1), rest];
        }
    }
    vec![text.to_owned()]
}

pub fn the_spelling_ref_replaced_note(found: &str) -> Option<String> {
    if found != "&" { return None; }
    Some(String::from("A view is written `ref T`: `ref String` for text, `ref Array[T]` for elements something else keeps, and `ref value` to borrow a value. (`&&` still means *and*.)"))
}

pub fn an_effect_on_a_lambda_note(found: &str, before: &str) -> Option<String> {
    if found != "sync" && found != "throws" { return None; }
    let trimmed = before.trim_end();
    if !(trimmed.ends_with(")") && trimmed.contains("fn")) { return None; }
    Some(format!("`{}` isn't written on a lambda yet: a lambda's parameter list is followed by its block and nothing else.", found))
}

const AFTER_A_FALLBACK: [&str; 17] = ["==", "!=", "<=", ">=", "=", "<", ">", "&&", "|", "||", "..", "+", "-", "*", "/", "%", "as"];

pub fn coalesce_fallback_note(found: &str, before: &str) -> Vec<String> {
    if !before.contains("??") { return vec![]; }
    for operator in AFTER_A_FALLBACK.iter() {
        let operator = *operator;
        if found == operator { return vec![String::from("The fallback after `??` is a single value unless you use brackets, so `a ?? 0 > 3` would mean `a ?? (0 > 3)`."), String::from("Put brackets around the part you mean: `(a ?? 0) > 3`, or `a ?? (0 > 3)`.")]; }
    }
    vec![]
}

pub fn let_names_note(found: &str, before: &str) -> Vec<String> {
    if found != "(" || !(before.contains("let (") || before.contains("let mut (")) { return vec![]; }
    vec![String::from("A `let` binds one name, or a flat list of names like `let (tx, rx) = …`. A tuple inside a tuple can't be taken apart here."), String::from("Bind the outer parts to one name each, and read the inner parts from those names.")]
}


// --- paths.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Export {
    pub at: String,
    pub prefix: String,
    pub name: Option<Named>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Named {
    pub name: String,
    pub alias: String,
}

pub fn after(path: &str, word: &str) -> Option<String> {
    if path == word { return Some(String::from("")); }
    let lead = format!("{}::", word);
    if !path.starts_with(&lead) { return None; }
    let c: Vec<char> = nikaia_std::list::chars(path.chars());
    let w: Vec<char> = nikaia_std::list::chars(lead.chars());
    Some(slice(&c, w.len() as i64, c.len() as i64))
}

pub fn module_of(relative: &str) -> Option<String> {
    if !relative.starts_with("src/") || !relative.ends_with(".rs") { return None; }
    let c: Vec<char> = nikaia_std::list::chars(relative.chars());
    let inside = slice(&c, 4, c.len() as i64 - 3);
    if inside == "lib" { return Some(String::from("")); }
    if inside == "main" || inside.starts_with("bin/") { return None; }
    let mut path = inside.to_owned();
    if inside == "mod" { path = String::from(""); } else if inside.ends_with("/mod") {
        let i: Vec<char> = nikaia_std::list::chars(inside.chars());
        path = slice(&i, 0, i.len() as i64 - 4);
    }
    let mut out: String = String::from("");
    for part in path.split("/") { out = joined(&out, part); }
    Some(out)
}

pub fn joined(at: &str, name: &str) -> String {
    if at.is_empty() { return name.to_owned(); }
    if name.is_empty() { return at.to_owned(); }
    format!("{}::{}", at, name)
}

pub fn exported(at: &str, text: &str) -> Vec<Export> {
    let __keep_frame = nikaia_std::tether::Keep::new();
    let whole = text.trim();
    let c: Vec<char> = nikaia_std::list::chars(whole.chars());
    let mut out: Vec<Export> = vec![];
    let open = find_text(&c, 0, "::{");
    if open >= 0 && whole.ends_with("}") {
        let prefix = slice(&c, 0, open);
        let inside = slice(&c, open + 3, c.len() as i64 - 1);
        for one in split_top_level(&inside) { if !one.is_empty() { out.push(Export { at: at.to_owned(), prefix: prefix.to_owned(), name: Some(named(&one)) }); } }
        return out;
    }
    if whole.ends_with("::*") {
        out.push(Export { at: at.to_owned(), prefix: slice(&c, 0, c.len() as i64 - 3), name: None });
        return out;
    }
    let mut path = whole.to_owned();
    let mut alias: Option<String> = None;
    let space = find_text(&c, 0, " as ");
    if space >= 0 {
        let before = __keep_frame.put(slice(&c, 0, space));
        let after_it = __keep_frame.put(slice(&c, space + 4, c.len() as i64));
        path = before.trim().to_owned();
        alias = Some(after_it.trim().to_owned());
    }
    let p: Vec<char> = nikaia_std::list::chars(path.chars());
    let cut = find_last_text(&p, "::");
    let mut prefix: String = String::from("");
    let mut name = path.to_owned();
    if cut >= 0 {
        prefix = slice(&p, 0, cut);
        let rest = __keep_frame.put(slice(&p, cut + 2, p.len() as i64));
        name = rest.trim().to_owned();
    }
    let offered = nikaia_std::index::or(alias, || name.to_owned().into());
    out.push(Export { at: at.to_owned(), prefix, name: Some(Named { name, alias: offered }) });
    out
}

pub fn named(written: &str) -> Named {
    let one = written.trim();
    let c: Vec<char> = nikaia_std::list::chars(one.chars());
    let space = find_text(&c, 0, " as ");
    if space < 0 { return Named { name: one.to_owned(), alias: one.to_owned() }; }
    let before = slice(&c, 0, space);
    let after_it = slice(&c, space + 4, c.len() as i64);
    Named { name: before.trim().to_owned(), alias: after_it.trim().to_owned() }
}

pub fn bases(export: &Export) -> Vec<String> {
    let prefix = export.prefix.trim();
    let mut out: Vec<String> = vec![];
    let from_root = after(prefix, "crate");
    if from_root.is_some() {
        out.push(nikaia_std::index::or(from_root, || "".into()));
        return out;
    }
    let from_here = after(prefix, "self");
    if from_here.is_some() {
        out.push(joined(&export.at, nikaia_std::index::or(from_here.as_deref(), || "")));
        return out;
    }
    let from_up = after(prefix, "super");
    if from_up.is_some() {
        let a: Vec<char> = nikaia_std::list::chars(export.at.chars());
        let cut = find_last_text(&a, "::");
        let mut parent: String = String::from("");
        if cut >= 0 { parent = slice(&a, 0, cut); }
        out.push(joined(&parent, nikaia_std::index::or(from_up.as_deref(), || "")));
        return out;
    }
    let here = joined(&export.at, prefix);
    let root = prefix.to_owned();
    if here != root { out.push(here); }
    out.push(root);
    out
}

pub fn split_top_level(text: &str) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    let mut depth = 0;
    let mut current: String = String::from("");
    for c in text.chars() {
        if c == '<' || c == '(' || c == '[' { depth += 1; } else if c == '>' || c == ')' || c == ']' { depth -= 1; } else if c == ',' && depth == 0 {
            out.push(current.trim().to_owned());
            current = String::from("");
            continue;
        }
        current.push(c);
    }
    let last = current.trim();
    if !last.is_empty() { out.push(last.to_owned()); }
    out
}

fn find_last_text(c: &[char], word: &str) -> i64 {
    let w: Vec<char> = nikaia_std::list::chars(word.chars());
    let mut found: i64 = -1;
    if w.is_empty() || (c.len() as i64) < w.len() as i64 { return found; }
    for at in 0..c.len() as i64 - w.len() as i64 + 1 { if stands_at(c, at, &w) { found = at; } }
    found
}

fn stands_at(c: &[char], at: i64, w: &[char]) -> bool {
    for k in 0..w.len() as i64 { if *nikaia_std::index::get(&c, nikaia_std::index::at(at + k)) != *nikaia_std::index::get(&w, (k) as usize) { return false; } }
    true
}


// --- prove_terms.nika ---

pub fn lin_term(expr: &Expr, words: &winnow_grammar::InternerContext, var: &impl Fn(&str) -> bool, out: &mut Vec<SolverTerm>) -> Option<i64> {
    match expr {
        Expr::LitInt { value, negative } => {
            let negative = *negative; let value = *value;
            let n = match literal_value(value, negative) { Some(__nikaia_value) => __nikaia_value, None => return None };
            Some(built(SolverTerm::Int(n), out))
        },
        Expr::Variable(name) => {
            let name = *name;
            let text = words.resolve(name);
            if !var(text) { return None; }
            Some(built(SolverTerm::Var(text.to_owned()), out))
        },
        Expr::MethodCall { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            if !args.is_empty() || words.resolve(method) != "len" { return None; }
            let length = match receiver {
                Expr::Variable(name) => { let name = *name; format!("{}.len()", words.resolve(name)) },
                _ => return None,
            };
            if !var(&length) { return None; }
            Some(built(SolverTerm::Var(length), out))
        },
        Expr::Unary { op, expr } => {
            let expr = nikaia_std::boxed::open(expr);
            if *op != UnaryOp::Neg { return None; }
            let a = match lin_term(expr, words, var, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
            Some(built(SolverTerm::Neg(a), out))
        },
        Expr::Cast { expr, ty } => {
            let expr = nikaia_std::boxed::open(expr);
            if !ty.generics.is_empty() || !is_whole_number(words.resolve(ty.name)) { return None; }
            lin_term(expr, words, var, out)
        },
        Expr::Binary { op, lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            let l = match lin_term(lhs, words, var, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let r = match lin_term(rhs, words, var, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
            match op {
                BinaryOp::Add => Some(built(SolverTerm::Add(l, r), out)),
                BinaryOp::Sub => Some(built(SolverTerm::Sub(l, r), out)),
                BinaryOp::Mul => {
                    if constant_at(l, &out).is_none() && constant_at(r, &out).is_none() { return None; }
                    Some(built(SolverTerm::Mul(l, r), out))
                },
                _ => None,
            }
        },
        _ => None,
    }
}

pub fn claim_term(expr: &Expr, words: &winnow_grammar::InternerContext, var: &impl Fn(&str) -> bool, out: &mut Vec<SolverTerm>) -> Option<i64> {
    match expr {
        Expr::LitBool(b) => { let b = *b; Some(built(SolverTerm::Bool(b), out)) },
        Expr::Unary { op, expr } => {
            let expr = nikaia_std::boxed::open(expr);
            if *op != UnaryOp::Not { return None; }
            let a = match claim_term(expr, words, var, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
            Some(built(SolverTerm::Not(a), out))
        },
        Expr::Binary { op, lhs, rhs, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); match op {
            BinaryOp::And => {
                let l = match claim_term(lhs, words, var, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let r = match claim_term(rhs, words, var, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
                Some(built(SolverTerm::And(vec![l, r]), out))
            },
            BinaryOp::Or => {
                let l = match claim_term(lhs, words, var, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let r = match claim_term(rhs, words, var, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
                Some(built(SolverTerm::Or(vec![l, r]), out))
            },
            BinaryOp::Lt => compared(*op, lhs, rhs, words, var, out),
            BinaryOp::Le => compared(*op, lhs, rhs, words, var, out),
            BinaryOp::Gt => compared(*op, lhs, rhs, words, var, out),
            BinaryOp::Ge => compared(*op, lhs, rhs, words, var, out),
            BinaryOp::Eq => compared(*op, lhs, rhs, words, var, out),
            BinaryOp::Ne => compared(*op, lhs, rhs, words, var, out),
            _ => None,
        } },
        _ => None,
    }
}

fn compared(op: BinaryOp, lhs: &Expr, rhs: &Expr, words: &winnow_grammar::InternerContext, var: &impl Fn(&str) -> bool, out: &mut Vec<SolverTerm>) -> Option<i64> {
    let a = match lin_term(lhs, words, var, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let b = match lin_term(rhs, words, var, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(match op {
        BinaryOp::Lt => built(SolverTerm::Lt(a, b), out),
        BinaryOp::Le => built(SolverTerm::Le(a, b), out),
        BinaryOp::Gt => built(SolverTerm::Gt(a, b), out),
        BinaryOp::Ge => built(SolverTerm::Ge(a, b), out),
        BinaryOp::Eq => built(SolverTerm::Eq(a, b), out),
        _ => built(SolverTerm::Ne(a, b), out),
    })
}

fn built(node: SolverTerm, out: &mut Vec<SolverTerm>) -> i64 {
    out.push(node);
    out.len() as i64 - 1
}

fn constant_at(at: i64, out: &[SolverTerm]) -> Option<i64> {
    match nikaia_std::index::get(&out, nikaia_std::index::at(at)) {
        SolverTerm::Int(n) => { let n = *n; Some(n) },
        SolverTerm::Neg(a) => {
            let a = *a;
            let v = match constant_at(a, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
            v.checked_neg()
        },
        SolverTerm::Add(a, b) => {
            let a = *a; let b = *b;
            let x = match constant_at(a, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let y = match constant_at(b, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
            x.checked_add(y)
        },
        SolverTerm::Sub(a, b) => {
            let a = *a; let b = *b;
            let x = match constant_at(a, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let y = match constant_at(b, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
            x.checked_sub(y)
        },
        SolverTerm::Mul(a, b) => {
            let a = *a; let b = *b;
            let x = match constant_at(a, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let y = match constant_at(b, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
            x.checked_mul(y)
        },
        _ => None,
    }
}

fn literal_value(value: u64, negative: bool) -> Option<i64> {
    if value <= 9223372036854775807u64 {
        let n = i64::try_from(value).unwrap_or_else(|_| panic!("the value does not fit in an `i64`"));
        if negative { return Some(-n); }
        return Some(n);
    }
    if negative && value == 9223372036854775808u64 { return Some(-9223372036854775808i64); }
    None
}


// --- prove_text.nika ---

pub fn rust_of(id: i64, term_of: &impl Fn(i64) -> SolverTerm, escape: &impl Fn(&str) -> String) -> String {
    match term_of(id) {
        SolverTerm::Bool(b) => if b { String::from("true") } else { String::from("false") },
        SolverTerm::Int(n) => format!("({}i128)", n),
        SolverTerm::Var(ref name) => rust_of_name(name, escape),
        SolverTerm::Neg(a) => format!("(-{})", rust_of(a, term_of, escape)),
        SolverTerm::Not(a) => format!("(!{})", rust_of(a, term_of, escape)),
        SolverTerm::Add(a, b) => format!("({} + {})", rust_of(a, term_of, escape), rust_of(b, term_of, escape)),
        SolverTerm::Sub(a, b) => format!("({} - {})", rust_of(a, term_of, escape), rust_of(b, term_of, escape)),
        SolverTerm::Mul(a, b) => format!("({} * {})", rust_of(a, term_of, escape), rust_of(b, term_of, escape)),
        SolverTerm::Le(a, b) => format!("({} <= {})", rust_of(a, term_of, escape), rust_of(b, term_of, escape)),
        SolverTerm::Lt(a, b) => format!("({} < {})", rust_of(a, term_of, escape), rust_of(b, term_of, escape)),
        SolverTerm::Ge(a, b) => format!("({} >= {})", rust_of(a, term_of, escape), rust_of(b, term_of, escape)),
        SolverTerm::Gt(a, b) => format!("({} > {})", rust_of(a, term_of, escape), rust_of(b, term_of, escape)),
        SolverTerm::Eq(a, b) => format!("({} == {})", rust_of(a, term_of, escape), rust_of(b, term_of, escape)),
        SolverTerm::Ne(a, b) => format!("({} != {})", rust_of(a, term_of, escape), rust_of(b, term_of, escape)),
        SolverTerm::And(ref parts) => rust_joined(" && ", parts, "true", term_of, escape),
        SolverTerm::Or(ref parts) => rust_joined(" || ", parts, "false", term_of, escape),
        _ => String::from(""),
    }
}

fn rust_joined(op: &str, parts: &[i64], empty: &str, term_of: &impl Fn(i64) -> SolverTerm, escape: &impl Fn(&str) -> String) -> String {
    if parts.is_empty() { return empty.to_owned(); }
    let mut written: Vec<String> = vec![];
    for part in parts.iter() {
        let part = nikaia_std::num::value(part);
        written.push(rust_of(part, term_of, escape));
    }
    format!("({})", written.join(op))
}

pub fn rust_of_name(name: &str, escape: &impl Fn(&str) -> String) -> String {
    if name.ends_with(".len()") {
        let c: Vec<char> = nikaia_std::list::chars(name.chars());
        let mut base: String = String::from("");
        for k in 0..c.len() as i64 - 6 { base.push(*nikaia_std::index::get(&c, (k) as usize)); }
        return format!("({}.len() as i128)", escape(&base));
    }
    format!("({}.clone() as i128)", escape(name))
}

pub fn term_text(id: i64, term_of: &impl Fn(i64) -> SolverTerm) -> String { term_whole(id, true, term_of) }

pub fn term_ledger_text(id: i64, term_of: &impl Fn(i64) -> SolverTerm) -> String { term_whole(id, false, term_of) }

fn term_rank(term: &SolverTerm, arrow: bool) -> i64 {
    match term {
        SolverTerm::Or(parts) => if arrow && parts.len() == 2 { 0 } else { 1 },
        SolverTerm::And(_) => 2,
        SolverTerm::Le(_, _) => 3,
        SolverTerm::Lt(_, _) => 3,
        SolverTerm::Ge(_, _) => 3,
        SolverTerm::Gt(_, _) => 3,
        SolverTerm::Eq(_, _) => 3,
        SolverTerm::Ne(_, _) => 3,
        SolverTerm::Add(_, _) => 4,
        SolverTerm::Sub(_, _) => 4,
        SolverTerm::Mul(_, _) => 5,
        SolverTerm::Neg(_) => 6,
        SolverTerm::Not(_) => 6,
        _ => 7,
    }
}

fn term_inner(id: i64, at_least: i64, arrow: bool, term_of: &impl Fn(i64) -> SolverTerm) -> String {
    let text = term_whole(id, arrow, term_of);
    if term_rank(&term_of(id), arrow) < at_least { return format!("({})", text); }
    text
}

fn term_binary(op: &str, a: i64, b: i64, r: i64, arrow: bool, term_of: &impl Fn(i64) -> SolverTerm) -> String { format!("{} {} {}", term_inner(a, r, arrow, term_of), op, term_inner(b, r + 1, arrow, term_of)) }

fn term_joined(op: &str, parts: &[i64], r: i64, arrow: bool, term_of: &impl Fn(i64) -> SolverTerm) -> String {
    let mut written: Vec<String> = vec![];
    for part in parts.iter() {
        let part = nikaia_std::num::value(part);
        written.push(term_inner(part, r + 1, arrow, term_of));
    }
    written.join(op)
}

fn term_whole(id: i64, arrow: bool, term_of: &impl Fn(i64) -> SolverTerm) -> String {
    let term = term_of(id);
    let r = term_rank(&term, arrow);
    match term {
        SolverTerm::Bool(b) => if b { String::from("true") } else { String::from("false") },
        SolverTerm::Int(n) => format!("{}", n),
        SolverTerm::Var(ref name) => name.to_owned(),
        SolverTerm::Neg(a) => format!("-{}", term_inner(a, r, arrow, term_of)),
        SolverTerm::Not(a) => format!("!{}", term_inner(a, r, arrow, term_of)),
        SolverTerm::Add(a, b) => term_binary("+", a, b, r, arrow, term_of),
        SolverTerm::Sub(a, b) => term_binary("-", a, b, r, arrow, term_of),
        SolverTerm::Mul(a, b) => term_binary("*", a, b, r, arrow, term_of),
        SolverTerm::Le(a, b) => term_binary("<=", a, b, r, arrow, term_of),
        SolverTerm::Lt(a, b) => term_binary("<", a, b, r, arrow, term_of),
        SolverTerm::Ge(a, b) => term_binary(">=", a, b, r, arrow, term_of),
        SolverTerm::Gt(a, b) => term_binary(">", a, b, r, arrow, term_of),
        SolverTerm::Eq(a, b) => term_binary("==", a, b, r, arrow, term_of),
        SolverTerm::Ne(a, b) => term_binary("!=", a, b, r, arrow, term_of),
        SolverTerm::Or(ref parts) => {
            if arrow && parts.len() == 2 {
                match term_of(*nikaia_std::index::get(&parts, 0)) {
                    SolverTerm::Not(taken) => { return format!("{} → {}", term_inner(taken, 1, arrow, term_of), term_inner(*nikaia_std::index::get(&parts, 1), 1, arrow, term_of)); },
                    _ => { },
                }
            }
            term_joined(" || ", parts, r, arrow, term_of)
        },
        SolverTerm::And(ref parts) => term_joined(" && ", parts, r, arrow, term_of),
        _ => String::from(""),
    }
}

pub fn shown(values: &collections::BTreeMap<String, i64>) -> String {
    if values.is_empty() { return String::from("no value of its own; the claim is false as written"); }
    let mut said: Vec<String> = vec![];
    for (name, value) in values.iter() {
        let value = nikaia_std::num::value(value);
        said.push(format!("`{}` is {}", name, value));
    }
    said.join(", ")
}

pub fn lowered_first(text: &str) -> String {
    let c: Vec<char> = nikaia_std::list::chars(text.chars());
    if c.is_empty() { return String::from(""); }
    let mut head: String = String::from("");
    head.push(*nikaia_std::index::get(&c, 0));
    let mut out = head.to_lowercase();
    for k in 1..c.len() as i64 { out.push(*nikaia_std::index::get(&c, (k) as usize)); }
    out
}

pub fn has_a_length(ty: &str) -> bool { matches!(ty, "Vec" | "String" | "str" | "Array") }


// --- prover_arena.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TermArena {
    pub nodes: Vec<SolverTerm>,
}

impl TermArena {
    pub fn empty() -> TermArena { TermArena { nodes: vec![] } }
    fn push(&mut self, node: SolverTerm) -> i64 {
        self.nodes.push(node);
        self.nodes.len() as i64 - 1
    }
    pub fn at(&self, id: i64) -> SolverTerm { (*nikaia_std::index::get(&self.nodes, nikaia_std::index::at(id))).clone() }
    pub fn boolean(&mut self, value: bool) -> i64 { self.push(SolverTerm::Bool(value)) }
    pub fn int(&mut self, value: i64) -> i64 { self.push(SolverTerm::Int(value)) }
    pub fn var(&mut self, name: &str) -> i64 { self.push(SolverTerm::Var(name.to_owned())) }
    pub fn add(&mut self, a: i64, b: i64) -> i64 { self.push(SolverTerm::Add(a, b)) }
    pub fn sub(&mut self, a: i64, b: i64) -> i64 { self.push(SolverTerm::Sub(a, b)) }
    pub fn neg(&mut self, a: i64) -> i64 { self.push(SolverTerm::Neg(a)) }
    pub fn mul(&mut self, a: i64, b: i64) -> i64 { self.push(SolverTerm::Mul(a, b)) }
    pub fn le(&mut self, a: i64, b: i64) -> i64 { self.push(SolverTerm::Le(a, b)) }
    pub fn lt(&mut self, a: i64, b: i64) -> i64 { self.push(SolverTerm::Lt(a, b)) }
    pub fn ge(&mut self, a: i64, b: i64) -> i64 { self.push(SolverTerm::Ge(a, b)) }
    pub fn gt(&mut self, a: i64, b: i64) -> i64 { self.push(SolverTerm::Gt(a, b)) }
    pub fn equal(&mut self, a: i64, b: i64) -> i64 { self.push(SolverTerm::Eq(a, b)) }
    pub fn unequal(&mut self, a: i64, b: i64) -> i64 { self.push(SolverTerm::Ne(a, b)) }
    pub fn and(&mut self, parts: Vec<i64>) -> i64 { self.push(SolverTerm::And(parts)) }
    pub fn or(&mut self, parts: Vec<i64>) -> i64 { self.push(SolverTerm::Or(parts)) }
    pub fn not(&mut self, a: i64) -> i64 { self.push(SolverTerm::Not(a)) }
    pub fn mentions(&self, id: i64, name: &str) -> bool {
        match nikaia_std::index::get(&self.nodes, nikaia_std::index::at(id)) {
            SolverTerm::Var(n) => n == name,
            SolverTerm::Neg(a) => { let a = *a; self.mentions(a, name) },
            SolverTerm::Not(a) => { let a = *a; self.mentions(a, name) },
            SolverTerm::Add(a, b) => { let a = *a; let b = *b; self.mentions(a, name) || self.mentions(b, name) },
            SolverTerm::Sub(a, b) => { let a = *a; let b = *b; self.mentions(a, name) || self.mentions(b, name) },
            SolverTerm::Mul(a, b) => { let a = *a; let b = *b; self.mentions(a, name) || self.mentions(b, name) },
            SolverTerm::Le(a, b) => { let a = *a; let b = *b; self.mentions(a, name) || self.mentions(b, name) },
            SolverTerm::Lt(a, b) => { let a = *a; let b = *b; self.mentions(a, name) || self.mentions(b, name) },
            SolverTerm::Ge(a, b) => { let a = *a; let b = *b; self.mentions(a, name) || self.mentions(b, name) },
            SolverTerm::Gt(a, b) => { let a = *a; let b = *b; self.mentions(a, name) || self.mentions(b, name) },
            SolverTerm::Eq(a, b) => { let a = *a; let b = *b; self.mentions(a, name) || self.mentions(b, name) },
            SolverTerm::Ne(a, b) => { let a = *a; let b = *b; self.mentions(a, name) || self.mentions(b, name) },
            SolverTerm::And(parts) => self.any_mentions(parts, name),
            SolverTerm::Or(parts) => self.any_mentions(parts, name),
            _ => false,
        }
    }
    fn any_mentions(&self, parts: &[i64], name: &str) -> bool {
        for part in parts.iter() {
            let part = nikaia_std::num::value(part);
            if self.mentions(part, name) { return true; }
        }
        false
    }
    pub fn variables(&self, id: i64, names: &mut collections::BTreeSet<String>) {
        match nikaia_std::index::get(&self.nodes, nikaia_std::index::at(id)) {
            SolverTerm::Var(name) => { names.insert(name.to_owned()); },
            SolverTerm::Neg(a) => { let a = *a; self.variables(a, names) },
            SolverTerm::Not(a) => { let a = *a; self.variables(a, names) },
            SolverTerm::Add(a, b) => { let a = *a; let b = *b; self.both_variables(a, b, names) },
            SolverTerm::Sub(a, b) => { let a = *a; let b = *b; self.both_variables(a, b, names) },
            SolverTerm::Mul(a, b) => { let a = *a; let b = *b; self.both_variables(a, b, names) },
            SolverTerm::Le(a, b) => { let a = *a; let b = *b; self.both_variables(a, b, names) },
            SolverTerm::Lt(a, b) => { let a = *a; let b = *b; self.both_variables(a, b, names) },
            SolverTerm::Ge(a, b) => { let a = *a; let b = *b; self.both_variables(a, b, names) },
            SolverTerm::Gt(a, b) => { let a = *a; let b = *b; self.both_variables(a, b, names) },
            SolverTerm::Eq(a, b) => { let a = *a; let b = *b; self.both_variables(a, b, names) },
            SolverTerm::Ne(a, b) => { let a = *a; let b = *b; self.both_variables(a, b, names) },
            SolverTerm::And(parts) => {
                for part in parts.iter() {
                    let part = nikaia_std::num::value(part);
                    self.variables(part, names);
                }
            },
            SolverTerm::Or(parts) => {
                for part in parts.iter() {
                    let part = nikaia_std::num::value(part);
                    self.variables(part, names);
                }
            },
            _ => { },
        }
    }
    fn both_variables(&self, a: i64, b: i64, names: &mut collections::BTreeSet<String>) {
        self.variables(a, names);
        self.variables(b, names);
    }
    pub fn constant(&self, id: i64) -> Option<i64> {
        match nikaia_std::index::get(&self.nodes, nikaia_std::index::at(id)) {
            SolverTerm::Int(n) => { let n = *n; Some(n) },
            SolverTerm::Neg(a) => {
                let a = *a;
                let v = match self.constant(a) { Some(__nikaia_value) => __nikaia_value, None => return None };
                v.checked_neg()
            },
            SolverTerm::Add(a, b) => {
                let a = *a; let b = *b;
                let x = match self.constant(a) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let y = match self.constant(b) { Some(__nikaia_value) => __nikaia_value, None => return None };
                x.checked_add(y)
            },
            SolverTerm::Sub(a, b) => {
                let a = *a; let b = *b;
                let x = match self.constant(a) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let y = match self.constant(b) { Some(__nikaia_value) => __nikaia_value, None => return None };
                x.checked_sub(y)
            },
            SolverTerm::Mul(a, b) => {
                let a = *a; let b = *b;
                let x = match self.constant(a) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let y = match self.constant(b) { Some(__nikaia_value) => __nikaia_value, None => return None };
                x.checked_mul(y)
            },
            _ => None,
        }
    }
    pub fn int_value(&self, id: i64, values: &collections::BTreeMap<String, i64>) -> Option<i64> {
        match nikaia_std::index::get(&self.nodes, nikaia_std::index::at(id)) {
            SolverTerm::Int(n) => { let n = *n; Some(n) },
            SolverTerm::Var(name) => {
                let found = match *nikaia_std::index::get(&values, name) { Some(__nikaia_value) => nikaia_std::num::value(__nikaia_value), None => return None };
                Some(found)
            },
            SolverTerm::Neg(a) => {
                let a = *a;
                let v = match self.int_value(a, values) { Some(__nikaia_value) => __nikaia_value, None => return None };
                v.checked_neg()
            },
            SolverTerm::Add(a, b) => {
                let a = *a; let b = *b;
                let x = match self.int_value(a, values) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let y = match self.int_value(b, values) { Some(__nikaia_value) => __nikaia_value, None => return None };
                x.checked_add(y)
            },
            SolverTerm::Sub(a, b) => {
                let a = *a; let b = *b;
                let x = match self.int_value(a, values) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let y = match self.int_value(b, values) { Some(__nikaia_value) => __nikaia_value, None => return None };
                x.checked_sub(y)
            },
            SolverTerm::Mul(a, b) => {
                let a = *a; let b = *b;
                let x = match self.int_value(a, values) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let y = match self.int_value(b, values) { Some(__nikaia_value) => __nikaia_value, None => return None };
                x.checked_mul(y)
            },
            _ => None,
        }
    }
    pub fn substitute(&mut self, id: i64, given: &collections::BTreeMap<String, i64>) -> i64 {
        let node = (*nikaia_std::index::get(&self.nodes, nikaia_std::index::at(id))).clone();
        match node {
            SolverTerm::Var(ref name) => nikaia_std::index::or(given.get(name), || id.into()),
            SolverTerm::Bool(_) => id,
            SolverTerm::Int(_) => id,
            SolverTerm::Neg(a) => {
                let x = self.substitute(a, given);
                self.push(SolverTerm::Neg(x))
            },
            SolverTerm::Not(a) => {
                let x = self.substitute(a, given);
                self.push(SolverTerm::Not(x))
            },
            SolverTerm::Add(a, b) => {
                let x = self.substitute(a, given);
                let y = self.substitute(b, given);
                self.push(SolverTerm::Add(x, y))
            },
            SolverTerm::Sub(a, b) => {
                let x = self.substitute(a, given);
                let y = self.substitute(b, given);
                self.push(SolverTerm::Sub(x, y))
            },
            SolverTerm::Mul(a, b) => {
                let x = self.substitute(a, given);
                let y = self.substitute(b, given);
                self.push(SolverTerm::Mul(x, y))
            },
            SolverTerm::Le(a, b) => {
                let x = self.substitute(a, given);
                let y = self.substitute(b, given);
                self.push(SolverTerm::Le(x, y))
            },
            SolverTerm::Lt(a, b) => {
                let x = self.substitute(a, given);
                let y = self.substitute(b, given);
                self.push(SolverTerm::Lt(x, y))
            },
            SolverTerm::Ge(a, b) => {
                let x = self.substitute(a, given);
                let y = self.substitute(b, given);
                self.push(SolverTerm::Ge(x, y))
            },
            SolverTerm::Gt(a, b) => {
                let x = self.substitute(a, given);
                let y = self.substitute(b, given);
                self.push(SolverTerm::Gt(x, y))
            },
            SolverTerm::Eq(a, b) => {
                let x = self.substitute(a, given);
                let y = self.substitute(b, given);
                self.push(SolverTerm::Eq(x, y))
            },
            SolverTerm::Ne(a, b) => {
                let x = self.substitute(a, given);
                let y = self.substitute(b, given);
                self.push(SolverTerm::Ne(x, y))
            },
            SolverTerm::And(ref parts) => {
                let mut changed: Vec<i64> = vec![];
                for part in parts.iter() {
                    let part = nikaia_std::num::value(part);
                    changed.push(self.substitute(part, given));
                }
                self.push(SolverTerm::And(changed))
            },
            SolverTerm::Or(ref parts) => {
                let mut changed: Vec<i64> = vec![];
                for part in parts.iter() {
                    let part = nikaia_std::num::value(part);
                    changed.push(self.substitute(part, given));
                }
                self.push(SolverTerm::Or(changed))
            },
            _ => id,
        }
    }
    pub fn size(&self, id: i64) -> i64 {
        1 + match nikaia_std::index::get(&self.nodes, nikaia_std::index::at(id)) {
            SolverTerm::Neg(a) => { let a = *a; self.size(a) },
            SolverTerm::Not(a) => { let a = *a; self.size(a) },
            SolverTerm::Add(a, b) => { let a = *a; let b = *b; self.size(a) + self.size(b) },
            SolverTerm::Sub(a, b) => { let a = *a; let b = *b; self.size(a) + self.size(b) },
            SolverTerm::Mul(a, b) => { let a = *a; let b = *b; self.size(a) + self.size(b) },
            SolverTerm::Le(a, b) => { let a = *a; let b = *b; self.size(a) + self.size(b) },
            SolverTerm::Lt(a, b) => { let a = *a; let b = *b; self.size(a) + self.size(b) },
            SolverTerm::Ge(a, b) => { let a = *a; let b = *b; self.size(a) + self.size(b) },
            SolverTerm::Gt(a, b) => { let a = *a; let b = *b; self.size(a) + self.size(b) },
            SolverTerm::Eq(a, b) => { let a = *a; let b = *b; self.size(a) + self.size(b) },
            SolverTerm::Ne(a, b) => { let a = *a; let b = *b; self.size(a) + self.size(b) },
            SolverTerm::And(parts) => self.parts_size(parts),
            SolverTerm::Or(parts) => self.parts_size(parts),
            _ => 0,
        }
    }
    fn parts_size(&self, parts: &[i64]) -> i64 {
        let mut total: i64 = 0;
        for part in parts.iter() {
            let part = nikaia_std::num::value(part);
            total += self.size(part);
        }
        total
    }
    pub fn text(&self, id: i64) -> String { term_text(id, &|at| { self.at(at) }) }
    pub fn adopt(&mut self, nodes: &[SolverTerm]) -> i64 {
        let base = self.nodes.len() as i64;
        for node in nodes.iter() {
            let moved = match node {
                SolverTerm::Add(a, b) => { let a = *a; let b = *b; SolverTerm::Add(a + base, b + base) },
                SolverTerm::Sub(a, b) => { let a = *a; let b = *b; SolverTerm::Sub(a + base, b + base) },
                SolverTerm::Neg(a) => { let a = *a; SolverTerm::Neg(a + base) },
                SolverTerm::Mul(a, b) => { let a = *a; let b = *b; SolverTerm::Mul(a + base, b + base) },
                SolverTerm::Le(a, b) => { let a = *a; let b = *b; SolverTerm::Le(a + base, b + base) },
                SolverTerm::Lt(a, b) => { let a = *a; let b = *b; SolverTerm::Lt(a + base, b + base) },
                SolverTerm::Ge(a, b) => { let a = *a; let b = *b; SolverTerm::Ge(a + base, b + base) },
                SolverTerm::Gt(a, b) => { let a = *a; let b = *b; SolverTerm::Gt(a + base, b + base) },
                SolverTerm::Eq(a, b) => { let a = *a; let b = *b; SolverTerm::Eq(a + base, b + base) },
                SolverTerm::Ne(a, b) => { let a = *a; let b = *b; SolverTerm::Ne(a + base, b + base) },
                SolverTerm::And(parts) => SolverTerm::And(moved_by(parts, base)),
                SolverTerm::Or(parts) => SolverTerm::Or(moved_by(parts, base)),
                SolverTerm::Not(a) => { let a = *a; SolverTerm::Not(a + base) },
                _ => node.clone(),
            };
            self.nodes.push(moved);
        }
        self.nodes.len() as i64 - 1
    }
    pub fn is_the_variable(&self, id: i64, name: &str) -> bool {
        match nikaia_std::index::get(&self.nodes, nikaia_std::index::at(id)) {
            SolverTerm::Var(n) => n == name,
            _ => false,
        }
    }
}

fn moved_by(parts: &[i64], base: i64) -> Vec<i64> {
    let mut out: Vec<i64> = vec![];
    for p in parts.iter() {
        let p = nikaia_std::num::value(p);
        out.push(p + base);
    }
    out
}


// --- prover_calls.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FreeFunction {
    pub params: Vec<String>,
    pub can_throw: bool,
    pub whole_result: bool,
}

pub fn free_function(program: &Program, words: &winnow_grammar::InternerContext, wanted: &str) -> Option<FreeFunction> {
    for item in program.items.iter() {
        match &item.node {
            Item::Fn { name, receiver, args, ret_type, can_throw, .. } => {
                let can_throw = *can_throw; let name = *name;
                if receiver.is_none() && named_as((name).as_ref(), words, wanted) {
                    let mut params: Vec<String> = vec![];
                    for arg in args.iter() { params.push(words.resolve(arg.name).to_owned()); }
                    return Some(FreeFunction { params, can_throw, whole_result: whole_type((ret_type).as_ref(), words) });
                }
            },
            _ => { },
        }
    }
    None
}

fn named_as(named: Option<&winnow_grammar::Symbol>, words: &winnow_grammar::InternerContext, name: &str) -> bool {
    let symbol = match named { Some(__nikaia_value) => __nikaia_value, None => return false };
    words.resolve(*symbol) == name
}

fn whole_type(ty: Option<&Type>, words: &winnow_grammar::InternerContext) -> bool {
    let t = match ty { Some(__nikaia_value) => __nikaia_value, None => return false };
    t.generics.is_empty() && is_whole_number(words.resolve(t.name))
}

pub fn may_throw(call: &Expr, in_throwing: bool, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, unaliased: &impl Fn(&str) -> String) -> bool {
    if !in_throwing { return false; }
    let name = match thrower_named(call, words, unaliased) { Some(__nikaia_value) => __nikaia_value, None => return true };
    let function = free_function(program, words, &name);
    if function.is_some() {
        let found = match function { Some(__nikaia_value) => __nikaia_value, None => return true };
        return found.can_throw;
    }
    if own.functions.contains_key(&name) {
        let contract = match *nikaia_std::index::get(&own.functions, &name) { Some(__nikaia_value) => __nikaia_value, None => return true };
        return !contract.fails_with.is_empty();
    }
    let contract = match *nikaia_std::index::get(&library.functions, &name) { Some(__nikaia_value) => __nikaia_value, None => return true };
    !contract.fails_with.is_empty()
}

fn thrower_named(call: &Expr, words: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String) -> Option<String> {
    match call {
        Expr::Call { func, .. } => { let func = nikaia_std::boxed::open(func); match func {
            Expr::Variable(name) => { let name = *name; Some(words.resolve(name).to_owned()) },
            Expr::Path(segments) => {
                let mut joined: String = String::from("");
                for segment in segments.iter() {
                    if !joined.is_empty() { joined.push_str("::"); }
                    joined.push_str(words.resolve(*segment));
                }
                Some(unaliased(&joined))
            },
            _ => None,
        } },
        _ => None,
    }
}

pub fn from_outside(expr: &Expr, tainted: &collections::BTreeSet<String>, words: &winnow_grammar::InternerContext, library: &Ledger, holes_of: &impl Fn(&Expr) -> Vec<Expr>) -> bool {
    match expr {
        Expr::Variable(name) => {
            let name = *name;
            if tainted.contains(words.resolve(name)) { return true; }
        },
        Expr::Call { func, .. } => {
            let func = nikaia_std::boxed::open(func);
            let source = outside_source_named(func, words);
            if source.is_some() && untrusted(library, nikaia_std::index::or(source.as_deref(), || "")) { return true; }
        },
        _ => { },
    }
    for hole in holes_of(expr) { if from_outside(&hole, tainted, words, library, holes_of) { return true; } }
    match expr {
        Expr::Call { func, args, config } => { let func = nikaia_std::boxed::open(func); from_outside(func, tainted, words, library, holes_of) || any_from_outside(args, tainted, words, library, holes_of) || config_from_outside(config, tainted, words, library, holes_of) },
        Expr::MethodCall { receiver, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); from_outside(receiver, tainted, words, library, holes_of) || any_from_outside(args, tainted, words, library, holes_of) || config_from_outside(config, tainted, words, library, holes_of) },
        Expr::SafeMethod { receiver, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); from_outside(receiver, tainted, words, library, holes_of) || any_from_outside(args, tainted, words, library, holes_of) || config_from_outside(config, tainted, words, library, holes_of) },
        Expr::Binary { lhs, rhs, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); from_outside(lhs, tainted, words, library, holes_of) || from_outside(rhs, tainted, words, library, holes_of) },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); from_outside(expr, tainted, words, library, holes_of) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); from_outside(inner, tainted, words, library, holes_of) },
        Expr::Throw(inner) => { let inner = nikaia_std::boxed::open(inner); from_outside(inner, tainted, words, library, holes_of) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); from_outside(expr, tainted, words, library, holes_of) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); from_outside(base, tainted, words, library, holes_of) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); from_outside(base, tainted, words, library, holes_of) },
        Expr::Index { base, index } => { let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index); from_outside(base, tainted, words, library, holes_of) || from_outside(index, tainted, words, library, holes_of) },
        Expr::Range { start, end, .. } => { let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end); from_outside(start, tainted, words, library, holes_of) || from_outside(end, tainted, words, library, holes_of) },
        Expr::Tuple(parts) => any_from_outside(parts, tainted, words, library, holes_of),
        Expr::Coalesce { value, fallback } => { let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback); from_outside(value, tainted, words, library, holes_of) || from_outside(fallback, tainted, words, library, holes_of) },
        Expr::TryCatch { expr, .. } => { let expr = nikaia_std::boxed::open(expr); from_outside(expr, tainted, words, library, holes_of) },
        Expr::If { cond, .. } => { let cond = nikaia_std::boxed::open(cond); from_outside(cond, tainted, words, library, holes_of) },
        Expr::Match { value, arms } => {
            let value = nikaia_std::boxed::open(value);
            if from_outside(value, tainted, words, library, holes_of) { return true; }
            for arm in arms.iter() { if maybe_from_outside((arm.guard).as_ref(), tainted, words, library, holes_of) || from_outside(&arm.body, tainted, words, library, holes_of) { return true; } }
            false
        },
        Expr::StructLit { fields, .. } => {
            for field in fields.iter() { if maybe_from_outside((field.value).as_ref(), tainted, words, library, holes_of) { return true; } }
            false
        },
        Expr::ListLit { items, .. } => any_from_outside(items, tainted, words, library, holes_of),
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            if from_outside(base, tainted, words, library, holes_of) { return true; }
            for field in fields.iter() { if maybe_from_outside((field.value).as_ref(), tainted, words, library, holes_of) { return true; } }
            false
        },
        Expr::Return(value) => { let value = nikaia_std::boxed::open(value); maybe_from_outside((value).as_ref(), tainted, words, library, holes_of) },
        Expr::Select(arms) => {
            for arm in arms.iter() { if from_outside(&arm.value, tainted, words, library, holes_of) { return true; } }
            false
        },
        _ => false,
    }
}

fn maybe_from_outside(expr: Option<&Expr>, tainted: &collections::BTreeSet<String>, words: &winnow_grammar::InternerContext, library: &Ledger, holes_of: &impl Fn(&Expr) -> Vec<Expr>) -> bool {
    let present = match expr { Some(__nikaia_value) => __nikaia_value, None => return false };
    from_outside(present, tainted, words, library, holes_of)
}

fn any_from_outside(exprs: &[Expr], tainted: &collections::BTreeSet<String>, words: &winnow_grammar::InternerContext, library: &Ledger, holes_of: &impl Fn(&Expr) -> Vec<Expr>) -> bool {
    for e in exprs.iter() { if from_outside(e, tainted, words, library, holes_of) { return true; } }
    false
}

fn config_from_outside(config: &[ConfigArg], tainted: &collections::BTreeSet<String>, words: &winnow_grammar::InternerContext, library: &Ledger, holes_of: &impl Fn(&Expr) -> Vec<Expr>) -> bool {
    for c in config.iter() { if from_outside(&c.value, tainted, words, library, holes_of) { return true; } }
    false
}

fn outside_source_named(func: &Expr, words: &winnow_grammar::InternerContext) -> Option<String> {
    match func {
        Expr::Variable(name) => { let name = *name; Some(words.resolve(name).to_owned()) },
        Expr::Path(segments) => {
            let mut joined: String = String::from("");
            for segment in segments.iter() {
                if !joined.is_empty() { joined.push_str("::"); }
                joined.push_str(words.resolve(*segment));
            }
            Some(joined)
        },
        _ => None,
    }
}

fn untrusted(library: &Ledger, name: &str) -> bool {
    let contract = match *nikaia_std::index::get(&library.functions, name) { Some(__nikaia_value) => __nikaia_value, None => return false };
    let provenance = match contract.provenance { Some(__nikaia_value) => __nikaia_value, None => return false };
    provenance == Provenance::Untrusted
}


// --- prover_claims.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PreClaim {
    pub term: i64,
    pub written: String,
    pub computed: Option<String>,
    pub message: Option<String>,
    pub origin: Option<String>,
    pub site: Option<CarriedFrom>,
}

impl PreClaim {
    pub fn failure(&self, function: &str) -> String {
        let computed = match claim_text_of((self.computed).as_deref()) { Some(__nikaia_value) => __nikaia_value, None => return format!("precondition of `{}`: `{}`", function, self.written) };
        let origin = match claim_text_of((self.origin).as_deref()) { Some(__nikaia_value) => __nikaia_value, None => return format!("precondition of `{}`: `{}`, from `assert({})`", function, computed, self.written) };
        format!("precondition of `{}`: `{}`, from `assert({})` in `{}`", function, computed, self.written, origin)
    }
    pub fn carried_from(&self, site: &CarriedFrom) -> bool {
        let mine = match carried_site_of((self.site).as_ref()) { Some(__nikaia_value) => __nikaia_value, None => return false };
        mine == *site
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CarriedFrom {
    pub at: i64,
    pub callee: String,
    pub place: i64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Precondition {
    pub claims: Vec<PreClaim>,
}

impl Precondition {
    pub fn none() -> Precondition { Precondition { claims: vec![] } }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PostClaim {
    pub term: i64,
    pub written: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Foreign {
    pub params: Vec<String>,
    pub whole_result: bool,
    pub requires: Vec<PreClaim>,
    pub ensures: Vec<PostClaim>,
}

fn claim_text_of(text: Option<&str>) -> Option<String> {
    let t = match text { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(t.to_owned())
}

fn carried_site_of(site: Option<&CarriedFrom>) -> Option<CarriedFrom> {
    let s = match site { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(s.clone())
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ForeignShape {
    pub params: Vec<String>,
    pub names: collections::BTreeSet<String>,
    pub whole_result: bool,
}

pub fn foreign_shape(contract: &FnContract) -> ForeignShape {
    let mut shape = ForeignShape { params: vec![], names: collections::BTreeSet::new(), whole_result: false };
    shape.names.insert(result_name());
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return shape };
    for (param, ty) in signature.params.iter() {
        match ty {
            Ty::Named { name, args, view } => {
                let view = *view;
                if args.is_empty() && !view && is_whole_number(name) { shape.names.insert(param.to_owned()); }
                if has_a_length(name) { shape.names.insert(length_of(param)); }
            },
            _ => { },
        }
        shape.params.push(param.to_owned());
    }
    shape.whole_result = whole_result_of((signature.result).as_ref());
    shape
}

fn whole_result_of(result: Option<&Ty>) -> bool {
    let ty = match result { Some(__nikaia_value) => __nikaia_value, None => return false };
    match ty {
        Ty::Named { name, args, view } => { let view = *view; args.is_empty() && !view && is_whole_number(name) },
        _ => false,
    }
}

pub fn foreign_from(contract: &FnContract, shape: ForeignShape, requires: &[i64], ensures: &[i64]) -> Foreign {
    let mut foreign = Foreign { params: shape.params, whole_result: shape.whole_result, requires: vec![], ensures: vec![] };
    for at in 0..requires.len() as i64 {
        let term = *nikaia_std::index::get(&requires, nikaia_std::index::at(at));
        if term < 0 { continue; }
        let written = assert_of(contract, at);
        let text = nikaia_std::index::get(&contract.requires, nikaia_std::index::at(at));
        let mut computed: Option<String> = None;
        if written != *text { computed = Some(text.to_owned()); }
        foreign.requires.push(PreClaim { term, written, computed, message: None, origin: None, site: None });
    }
    for at in 0..ensures.len() as i64 {
        let term = *nikaia_std::index::get(&ensures, nikaia_std::index::at(at));
        if term < 0 { continue; }
        foreign.ensures.push(PostClaim { term, written: assert_of(contract, contract.requires.len() as i64 + at) });
    }
    foreign
}

fn assert_of(contract: &FnContract, at: i64) -> String {
    if at >= contract.from.len() as i64 { return String::from(""); }
    let from = nikaia_std::index::get(&contract.from, nikaia_std::index::at(at));
    if !from.starts_with("assert(") || !from.ends_with(")") { return String::from(""); }
    let c: Vec<char> = nikaia_std::list::chars(from.chars());
    let mut inner: String = String::from("");
    for k in 7..c.len() as i64 - 1 { inner.push(*nikaia_std::index::get(&c, (k) as usize)); }
    inner
}


// --- prover_passes.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ProverAnswers {
    pub entries: collections::BTreeMap<String, Vec<PreconditionCheck>>,
    pub published: collections::BTreeMap<String, Published>,
}

#[allow(clippy::too_many_arguments)]
pub fn prover_passes(walk: &mut ProverWalk, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String, shape_of: &impl Fn(&Expr) -> String, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) -> ProverAnswers {
    let bound = program.items.len() as i64 + 2;
    let mut preconditions: collections::BTreeMap<String, Precondition> = collections::BTreeMap::new();
    for _ in 0..bound {
        walk.state.known = preconditions;
        walk.state.preconditions = collections::BTreeMap::new();
        walk.state.candidates = collections::BTreeMap::new();
        prover_bodies(walk, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
        preconditions = walk.state.preconditions.to_owned();
        if same_preconditions(&walk.arena, &preconditions, &walk.state.known) { break; }
    }
    walk.state.known = collections::BTreeMap::new();
    walk.state.collecting = false;
    walk.state.preconditions = preconditions;
    walk.state.postconditions = walk.state.candidates.to_owned();
    walk.state.candidates = collections::BTreeMap::new();
    let mut settled = false;
    while !settled {
        walk.held = collections::BTreeMap::new();
        walk.reaches = collections::BTreeMap::new();
        walk.findings = vec![];
        walk.state.broken = collections::BTreeSet::new();
        prover_bodies(walk, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
        settled = walk.state.broken.is_empty();
        if !settled { strike_broken(&mut walk.state); }
    }
    let answers = ProverAnswers { entries: checked_entries(&walk, escape), published: published_contracts(&walk) };
    count_checked_calls(walk);
    hold_unreached(walk, program);
    answers
}

fn strike_broken(state: &mut ProverState) {
    let mut broken: Vec<(String, i64)> = vec![];
    for one in state.broken.iter() { broken.push(one.clone()); }
    let mut k = broken.len() as i64;
    while k > 0 {
        k -= 1;
        let (function, index) = nikaia_std::index::get(&broken, nikaia_std::index::at(k)); let index = nikaia_std::num::value(index);
        let mut posts = match state.postconditions.remove(function) { Some(__nikaia_value) => __nikaia_value, None => continue };
        posts.remove(nikaia_std::count::of(index));
        state.postconditions.insert(function.to_owned(), posts);
    }
    state.broken = collections::BTreeSet::new();
}

fn same_preconditions(arena: &TermArena, a: &collections::BTreeMap<String, Precondition>, b: &collections::BTreeMap<String, Precondition>) -> bool { precondition_texts(arena, a) == precondition_texts(arena, b) }

fn precondition_texts(arena: &TermArena, m: &collections::BTreeMap<String, Precondition>) -> Vec<(String, Vec<String>)> {
    let mut out: Vec<(String, Vec<String>)> = vec![];
    for (function, pre) in m.iter() {
        let mut claims: Vec<String> = vec![];
        for claim in pre.claims.iter() { claims.push(arena.text(claim.term)); }
        out.push((function.to_owned(), claims));
    }
    out
}

fn checked_entries(walk: &ProverWalk, escape: &impl Fn(&str) -> String) -> collections::BTreeMap<String, Vec<PreconditionCheck>> {
    let mut entries: collections::BTreeMap<String, Vec<PreconditionCheck>> = collections::BTreeMap::new();
    for (function, pre) in walk.state.preconditions.iter() {
        let mut checks: Vec<PreconditionCheck> = vec![];
        for claim in pre.claims.iter() {
            let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
            walk.arena.variables(claim.term, &mut read);
            let mut operands: Vec<(String, String)> = vec![];
            for name in read.iter() { operands.push((name.to_owned(), rust_of_name(name, escape))); }
            checks.push(PreconditionCheck { rust: rust_text(&walk.arena, claim.term, escape), written: claim.failure(function), message: claim_text_of((claim.message).as_deref()), operands });
        }
        entries.insert(function.to_owned(), checks);
    }
    entries
}

fn published_contracts(walk: &ProverWalk) -> collections::BTreeMap<String, Published> {
    let mut published: collections::BTreeMap<String, Published> = collections::BTreeMap::new();
    for (function, pre) in walk.state.preconditions.iter() {
        let mut entry = nikaia_std::index::or(published.remove(function), || Published::nothing());
        for claim in pre.claims.iter() {
            entry.requires.push(ledger_term_text(&walk.arena, claim.term));
            entry.from.push(format!("assert({})", claim.written));
        }
        published.insert(function.to_owned(), entry);
    }
    for (function, posts) in walk.state.postconditions.iter() {
        if posts.is_empty() { continue; }
        let mut entry = nikaia_std::index::or(published.remove(function), || Published::nothing());
        for post in posts.iter() { entry.ensures.push(ledger_term_text(&walk.arena, post.term)); }
        published.insert(function.to_owned(), entry);
    }
    let mut out: collections::BTreeMap<String, Published> = collections::BTreeMap::new();
    for (function, entry) in published.iter() {
        let mut full = entry.clone();
        let posts = nikaia_std::index::or(standing_posts(&walk.state.postconditions, function), || vec![].into());
        for post in posts.iter() { full.from.push(format!("assert({})", post.written)); }
        out.insert(function.to_owned(), full);
    }
    out
}

fn ledger_term_text(arena: &TermArena, id: i64) -> String { term_ledger_text(id, &|at| { arena.at(at) }) }

fn count_checked_calls(walk: &mut ProverWalk) {
    let mut checked: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    for (key, reach) in walk.reaches.iter() {
        match reach {
            CallReach::Checked(_) => {
                let (callee, _) = key;
                let so_far = nikaia_std::index::or(*nikaia_std::index::get(&checked, callee), || 0);
                checked.insert(callee.to_owned(), so_far + 1);
            },
            _ => { },
        }
    }
    let mut counted: collections::BTreeMap<(i64, String), ClaimHeld> = collections::BTreeMap::new();
    for (key, held) in walk.held.iter() {
        let now = match held {
            ClaimHeld::Precondition(function, _) => ClaimHeld::Precondition(function.to_owned(), nikaia_std::index::or(*nikaia_std::index::get(&checked, function), || 0)),
            _ => held.clone(),
        };
        counted.insert(key.clone(), now);
    }
    walk.held = counted;
}

fn hold_unreached(walk: &mut ProverWalk, program: &Program) {
    let mut tests: Vec<(i64, i64)> = vec![];
    for item in program.items.iter() {
        match &item.node {
            Item::Test { .. } => tests.push((item.span.start as i64, item.span.end as i64)),
            Item::Bench { .. } => tests.push((item.span.start as i64, item.span.end as i64)),
            _ => { },
        }
    }
    for (at, shape) in walk.claims.iter() {
        let at = nikaia_std::num::value(at);
        let key = (at, shape.to_owned());
        if walk.held.contains_key(&key) { continue; }
        let mut in_a_test = false;
        for (start, end) in tests.iter() {
            let start = nikaia_std::num::value(start);let end = nikaia_std::num::value(end);
            if at >= start && at < end { in_a_test = true; }
        }
        if in_a_test { walk.held.insert(key, ClaimHeld::ByTheTest); } else { walk.held.insert(key, ClaimHeld::AtRunTime(String::from("it stands somewhere the prover doesn't look yet"))); }
    }
}


// --- prover_results.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ClaimHeld {
    ByTheTest,
    Proved,
    Precondition(String, i64),
    AtRunTime(String),
    Refused,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PreconditionCheck {
    pub rust: String,
    pub written: String,
    pub message: Option<String>,
    pub operands: Vec<(String, String)>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum CallReach {
    Proved,
    Checked(Vec<PreconditionCheck>),
    Through,
}

pub fn joined_reach(a: CallReach, b: CallReach) -> CallReach {
    match a {
        CallReach::Through => CallReach::Through,
        CallReach::Proved => b,
        CallReach::Checked(first) => match b {
            CallReach::Through => CallReach::Through,
            CallReach::Proved => CallReach::Checked(first),
            CallReach::Checked(ref second) => CallReach::Checked(both_checks(first, second)),
        },
    }
}

fn both_checks(first: Vec<PreconditionCheck>, second: &[PreconditionCheck]) -> Vec<PreconditionCheck> {
    let mut all = first;
    for check in second.iter() { if !all.contains(check) { all.push(check.clone()); } }
    all
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Published {
    pub requires: Vec<String>,
    pub ensures: Vec<String>,
    pub from: Vec<String>,
}

impl Published {
    pub fn nothing() -> Published { Published { requires: vec![], ensures: vec![], from: vec![] } }
}


// --- prover_scope.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ProverScope {
    pub ints: collections::BTreeSet<String>,
    pub tainted: collections::BTreeSet<String>,
    pub locals: collections::BTreeSet<String>,
    pub facts: Vec<i64>,
    pub entry: collections::BTreeMap<String, i64>,
    pub path: Option<Vec<i64>>,
    pub exact: bool,
    pub loose: collections::BTreeSet<String>,
}

impl ProverScope {
    pub fn unknown() -> ProverScope { ProverScope { ints: collections::BTreeSet::new(), tainted: collections::BTreeSet::new(), locals: collections::BTreeSet::new(), facts: vec![], entry: collections::BTreeMap::new(), path: None, exact: false, loose: collections::BTreeSet::new() } }
    pub fn at_the_entry() -> ProverScope {
        let mut scope = ProverScope::unknown();
        scope.path = Some(vec![]);
        scope.exact = true;
        scope
    }
    pub fn rebind(&mut self, arena: &TermArena, name: &str) {
        let length = length_of(name);
        self.ints.remove(name);
        self.ints.remove(&length);
        self.tainted.remove(name);
        self.entry.remove(name);
        self.entry.remove(&length);
        self.locals.insert(name.to_owned());
        self.loose.remove(name);
        self.loose.remove(&length);
        let mut kept: Vec<i64> = vec![];
        for fact in self.facts.iter() {
            let fact = nikaia_std::num::value(fact);
            if !arena.mentions(fact, name) && !arena.mentions(fact, &length) { kept.push(fact); }
        }
        if (kept.len() as i64) != self.facts.len() as i64 { self.exact = false; }
        self.facts = kept;
    }
    pub fn has_length(&mut self, arena: &mut TermArena, name: &str, known: Option<i64>) {
        let length = length_of(name);
        self.ints.insert(length.to_owned());
        let len = arena.var(&length);
        let zero = arena.int(0);
        self.facts.push(arena.ge(len, zero));
        let n = match known { Some(__nikaia_value) => __nikaia_value, None => {
            self.loose.insert(length);
            return;
        } };
        let value = arena.int(n);
        self.facts.push(arena.equal(len, value));
        self.entry.insert(length, value);
    }
    pub fn not_negative(&mut self, arena: &mut TermArena, name: &str) {
        let n = arena.var(name);
        let zero = arena.int(0);
        self.facts.push(arena.ge(n, zero));
    }
    pub fn at_entry(&self, arena: &mut TermArena, term: i64) -> Option<i64> {
        let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
        arena.variables(term, &mut read);
        let mut values: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
        for name in read.iter() {
            let value = match *nikaia_std::index::get(&self.entry, name) { Some(__nikaia_value) => nikaia_std::num::value(__nikaia_value), None => return None };
            values.insert(name.to_owned(), value);
        }
        Some(arena.substitute(term, &values))
    }
    pub fn on_the_path(&mut self, arena: &mut TermArena, condition: Option<i64>) {
        let at = match condition { Some(__nikaia_value) => __nikaia_value, None => {
            self.path = None;
            return;
        } };
        let c = match self.at_entry(arena, at) { Some(__nikaia_value) => __nikaia_value, None => {
            self.path = None;
            return;
        } };
        self.path = pushed(copied_path((self.path).as_ref()), c);
    }
    pub fn precondition_at(&self, arena: &mut TermArena, claim: i64, params: &collections::BTreeSet<String>) -> Option<i64> {
        let path = match copied_path((self.path).as_ref()) { Some(__nikaia_value) => __nikaia_value, None => return None };
        let at_entry = match self.at_entry(arena, claim) { Some(__nikaia_value) => __nikaia_value, None => return None };
        let mut term = at_entry;
        if !path.is_empty() {
            let taken = arena.and(path);
            let not_taken = arena.not(taken);
            term = arena.or(vec![not_taken, at_entry]);
        }
        if !only_parameters(&arena, term, params) || arena.size(term) > precondition_terms() { return None; }
        Some(term)
    }
    pub fn postcondition_at(&self, arena: &mut TermArena, claim: i64, returned: &str, params: &collections::BTreeSet<String>) -> Option<i64> {
        let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
        arena.variables(claim, &mut read);
        let result = arena.var(&result_name());
        let mut values: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
        for name in read.iter() {
            if name == returned { values.insert(name.to_owned(), result); } else {
                let value = match *nikaia_std::index::get(&self.entry, name) { Some(__nikaia_value) => nikaia_std::num::value(__nikaia_value), None => return None };
                values.insert(name.to_owned(), value);
            }
        }
        let term = arena.substitute(claim, &values);
        let mut names: collections::BTreeSet<String> = collections::BTreeSet::new();
        arena.variables(term, &mut names);
        for name in names.iter() { if *name != result_name() && !is_a_parameter(name, params) { return None; } }
        Some(term)
    }
    pub fn pinned_names(&self, arena: &TermArena, claim: i64) -> Option<collections::BTreeSet<String>> {
        if !self.exact { return None; }
        let mut names: collections::BTreeSet<String> = collections::BTreeSet::new();
        arena.variables(claim, &mut names);
        let mut grown = true;
        while grown {
            let before = names.len() as i64;
            for fact in self.facts.iter() {
                let fact = nikaia_std::num::value(fact);
                let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
                arena.variables(fact, &mut read);
                if ties(&read, &names) { for n in read.iter() { names.insert(n.to_owned()); } }
            }
            grown = (names.len() as i64) != before;
        }
        for n in names.iter() { if self.loose.contains(n) || !self.ints.contains(n) { return None; } }
        Some(names)
    }
    pub fn blind(&self) -> ProverScope {
        let mut scope = ProverScope::unknown();
        scope.tainted = self.tainted.to_owned();
        scope.locals = self.locals.to_owned();
        scope
    }
}

pub fn length_of(name: &str) -> String { format!("{}.len()", name) }

pub fn result_name() -> String { String::from("result") }

pub fn precondition_terms() -> i64 { 64 }

fn pushed(path: Option<Vec<i64>>, c: i64) -> Option<Vec<i64>> {
    let mut p = match path { Some(__nikaia_value) => __nikaia_value, None => return None };
    p.push(c);
    Some(p)
}

fn copied_path(path: Option<&Vec<i64>>) -> Option<Vec<i64>> {
    let p = match path { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(p.to_owned())
}

fn only_parameters(arena: &TermArena, term: i64, params: &collections::BTreeSet<String>) -> bool {
    let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
    arena.variables(term, &mut read);
    for name in read.iter() { if !is_a_parameter(name, params) { return false; } }
    true
}

fn ties(read: &collections::BTreeSet<String>, names: &collections::BTreeSet<String>) -> bool {
    for n in read.iter() { if names.contains(n) { return true; } }
    false
}


// --- prover_solver.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SolverAnswer {
    Proved,
    Rejected(String),
    NotProved,
}

pub fn refuting_values(arena: &mut TermArena, facts: &[i64], claim: i64, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>) -> Option<collections::BTreeMap<String, i64>> {
    let negation = arena.not(claim);
    match ask(&arena, facts, negation) {
        SolverAnswer::Proved => { },
        _ => return None,
    }
    let falsum = arena.boolean(false);
    let values = match model(&arena, facts, falsum) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let mut names: collections::BTreeSet<String> = collections::BTreeSet::new();
    arena.variables(claim, &mut names);
    Some(values_of(&names, &values))
}

pub fn breaking_values(arena: &mut TermArena, scope: &ProverScope, claim: i64, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>) -> Option<collections::BTreeMap<String, i64>> {
    let names = match scope.pinned_names(&arena, claim) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let values = match model(&arena, &scope.facts, claim) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let shown = values_of(&names, &values);
    if shown.is_empty() { return None; }
    Some(shown)
}

fn values_of(names: &collections::BTreeSet<String>, values: &collections::BTreeMap<String, i64>) -> collections::BTreeMap<String, i64> {
    let mut shown: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    for name in names.iter() {
        let value = match *nikaia_std::index::get(&values, name) { Some(__nikaia_value) => nikaia_std::num::value(__nikaia_value), None => continue };
        shown.insert(name.to_owned(), value);
    }
    shown
}


// --- prover_state.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ProverState {
    pub foreign: collections::BTreeMap<String, Option<Foreign>>,
    pub preconditions: collections::BTreeMap<String, Precondition>,
    pub known: collections::BTreeMap<String, Precondition>,
    pub edges: collections::BTreeSet<(String, String)>,
    pub candidates: collections::BTreeMap<String, Vec<PostClaim>>,
    pub postconditions: collections::BTreeMap<String, Vec<PostClaim>>,
    pub broken: collections::BTreeSet<(String, i64)>,
    pub before_return: collections::BTreeMap<i64, String>,
    pub collecting: bool,
    pub in_test: bool,
}

impl ProverState {
    pub fn fresh() -> ProverState { ProverState { foreign: collections::BTreeMap::new(), preconditions: collections::BTreeMap::new(), known: collections::BTreeMap::new(), edges: collections::BTreeSet::new(), candidates: collections::BTreeMap::new(), postconditions: collections::BTreeMap::new(), broken: collections::BTreeSet::new(), before_return: collections::BTreeMap::new(), collecting: true, in_test: false } }
    pub fn reaches(&self, from: &str, to: &str) -> bool {
        let mut seen: collections::BTreeSet<String> = collections::BTreeSet::new();
        let mut next: Vec<String> = vec![from.to_owned()];
        while !next.is_empty() {
            let f = match next.pop() { Some(__nikaia_value) => __nikaia_value, None => return false };
            if f == to { return true; }
            if seen.contains(&f) { continue; }
            seen.insert(f.to_owned());
            for (caller, callee) in self.edges.iter() { if *caller == f { next.push(callee.to_owned()); } }
        }
        false
    }
    #[allow(clippy::too_many_arguments)]
    pub fn exit(&mut self, arena: &mut TermArena, value: &Expr, words: &winnow_grammar::InternerContext, scope: &ProverScope, function: Option<&str>, counts: bool, params: &collections::BTreeSet<String>, ask: impl Fn(&TermArena, &[i64], i64) -> SolverAnswer) {
        if self.collecting || !counts { return; }
        let owner = match carrying_function(function) { Some(__nikaia_value) => __nikaia_value, None => return };
        let posts = match standing_posts(&self.postconditions, &owner) { Some(__nikaia_value) => __nikaia_value, None => return };
        let returned = lin_term(value, words, &|name| { scope.ints.contains(name) }, &mut arena.nodes);
        let mut unshadowed = true;
        for p in params.iter() {
            let key = if scope.entry.contains_key(p) { p.to_owned() } else { length_of(p) };
            let at_entry = nikaia_std::index::or(*nikaia_std::index::get(&scope.entry, &key), || -1);
            if at_entry < 0 || !arena.is_the_variable(at_entry, &key) {
                unshadowed = false;
                break;
            }
        }
        for index in 0..posts.len() as i64 {
            let mut shown = false;
            if unshadowed && returned.is_some() {
                let mut given: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
                given.insert(result_name(), nikaia_std::index::or(returned, || 0));
                let goal = arena.substitute(nikaia_std::index::get(&posts, (index) as usize).term, &given);
                shown = matches!(ask(&arena, &scope.facts, goal), SolverAnswer::Proved);
            }
            if !shown { self.broken.insert((owner.to_owned(), index)); }
        }
    }
    fn carried_here(&self, function: Option<&str>, site: &CarriedFrom) -> bool {
        let owner = match carrying_function(function) { Some(__nikaia_value) => __nikaia_value, None => return false };
        let found = match *nikaia_std::index::get(&self.preconditions, &owner) { Some(__nikaia_value) => __nikaia_value, None => return false };
        for claim in found.claims.iter() { if claim.carried_from(site) { return true; } }
        false
    }
    #[allow(clippy::too_many_arguments)]
    pub fn an_assert(&mut self, arena: &mut TermArena, words: &winnow_grammar::InternerContext, cond: &Expr, written: String, names: &collections::BTreeSet<String>, message: Option<String>, span: Span, scope: &mut ProverScope, at: &ProverWhere, ask: impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>) -> AssertOutcome {
        let mut outcome = AssertOutcome { held: ClaimHeld::ByTheTest, findings: vec![] };
        if self.in_test { return outcome; }
        let claim = claim_term(cond, words, &|name| { scope.ints.contains(name) }, &mut arena.nodes);
        let at_byte = span.start as i64;
        if self.collecting && at.free && !at.lambda && claim.is_some() {
            let function = carrying_function((at.function).as_deref());
            let returned = returned_before(&self.before_return, at_byte);
            if function.is_some() && returned.is_some() {
                let term = scope.postcondition_at(arena, nikaia_std::index::or(claim, || 0), nikaia_std::index::or(returned.as_deref(), || ""), &at.params);
                if term.is_some() {
                    let owner = nikaia_std::index::or(function, || "".into());
                    let mut posts = nikaia_std::index::or(self.candidates.remove(&owner), || vec![].into());
                    posts.push(PostClaim { term: nikaia_std::index::or(term, || 0), written: written.to_owned() });
                    self.candidates.insert(owner, posts);
                }
            }
        }
        let mut rejected: Option<String> = None;
        if claim.is_some() {
            match ask(&arena, &scope.facts, nikaia_std::index::or(claim, || 0)) {
                SolverAnswer::Proved => {
                    scope.facts.push(nikaia_std::index::or(claim, || 0));
                    outcome.held = ClaimHeld::Proved;
                    return outcome;
                },
                SolverAnswer::Rejected(why) => { rejected = Some(why); },
                SolverAnswer::NotProved => { },
            }
        }
        let mut only_params = !names.is_empty();
        for n in names.iter() { if !at.params.contains(n) { only_params = false; } }
        let mut tainted_name: Option<String> = None;
        for n in names.iter() { if tainted_name.is_none() && scope.tainted.contains(n) { tainted_name = Some(n.to_owned()); } }
        let tainted_claim = tainted_name.is_some();
        let mut refuted: Option<collections::BTreeMap<String, i64>> = None;
        if claim.is_some() && !tainted_claim { refuted = refuting_values(arena, &scope.facts, nikaia_std::index::or(claim, || 0), &ask, &model); }
        let is_refuted = refuted.is_some();
        let owner = carrying_function((at.function).as_deref());
        if claim.is_some() && at.no_precondition.is_none() && owner.is_some() && !is_refuted {
            let term = scope.precondition_at(arena, nikaia_std::index::or(claim, || 0), &at.params);
            if term.is_some() {
                let function = nikaia_std::index::or(owner, || "".into());
                if self.collecting {
                    let as_written = only_params && at.top;
                    let mut computed: Option<String> = None;
                    if !as_written { computed = Some(arena.text(nikaia_std::index::or(term, || 0))); }
                    let pre = PreClaim { term: nikaia_std::index::or(term, || 0), written: written.to_owned(), computed, message, origin: None, site: None };
                    let mut found = nikaia_std::index::or(self.preconditions.remove(&function), || Precondition::none());
                    found.claims.push(pre);
                    self.preconditions.insert(function.to_owned(), found);
                }
                scope.facts.push(nikaia_std::index::or(claim, || 0));
                outcome.held = ClaimHeld::Precondition(function, 0);
                return outcome;
            }
        }
        if tainted_claim {
            outcome.held = ClaimHeld::Refused;
            if self.collecting { return outcome; }
            let first = nikaia_std::index::or(tainted_name, || "".into());
            outcome.findings.push(Finding { code: String::from("NK1202"), span, message: format!("`{}` is a claim about data from outside the program.", written), notes: vec![format!("`{}` comes from outside the program, so nothing the compiler can see says what it holds.", first), String::from("That it is wrong is a case the program has to handle, not a defect an `assert` catches.")], help: Some(format!("Check it where it arrives, with a guard the program handles: `throw BadInput({}) if !({})`, or `return … if !({})`. After that line, this `assert` is proved.", first, written, written)), warning: false });
            return outcome;
        }
        let refuted_values = nikaia_std::index::or(refuted, || collections::BTreeMap::new().into());
        if is_refuted && !self.collecting { outcome.findings.push(Finding { code: String::from("NK1207"), span, message: format!("`{}` is false every time it is reached.", written), notes: vec![format!("What is known before it rules the claim out: {}.", shown(&refuted_values))], help: Some(String::from("If the claim is right, the code before it is wrong; if the code is right, the claim is.")), warning: false }); }
        let mut sometimes: Option<collections::BTreeMap<String, i64>> = None;
        if claim.is_some() && !is_refuted && !tainted_claim { sometimes = breaking_values(arena, &scope, nikaia_std::index::or(claim, || 0), &model); }
        let is_sometimes = sometimes.is_some();
        let sometimes_values = nikaia_std::index::or(sometimes, || collections::BTreeMap::new().into());
        if is_sometimes && !self.collecting { outcome.findings.push(Finding { code: String::from("NK1207"), span, message: format!("`{}` is false when {}.", written, shown(&sometimes_values)), notes: vec![String::from("That state reaches it: what is known here pins every name the claim depends on.")], help: Some(String::from("If the claim is right, the code before it is wrong; if the code is right, the claim is.")), warning: false }); }
        let mut why = String::from("nothing before it shows it");
        if rejected.is_some() { why = nikaia_std::index::or(rejected, || "".into()); } else if is_refuted { why = format!("it is false every time it is reached ({})", shown(&refuted_values)); } else if is_sometimes { why = format!("it is false when {}", shown(&sometimes_values)); } else if claim.is_none() { why = String::from("it is not a comparison of whole numbers the prover reads"); } else if only_params && at.no_precondition.is_some() {
            let no = nikaia_std::index::or(claim_text_of((at.no_precondition).as_deref()), || "".into());
            why = format!("nothing before it shows it; {}", lowered_first(&without_full_stops(&no)));
        } else if only_params && !at.top { why = String::from("nothing before it shows it, and a claim about parameters is a precondition only at the top of the function's body"); }
        outcome.held = ClaimHeld::AtRunTime(why);
        if claim.is_some() && !is_refuted { scope.facts.push(nikaia_std::index::or(claim, || 0)); }
        outcome
    }
    #[allow(clippy::too_many_arguments)]
    pub fn precondition_call(&mut self, arena: &mut TermArena, words: &winnow_grammar::InternerContext, callee: &str, params: &[String], claims: &[PreClaim], args: &[Expr], span: Span, scope: &ProverScope, at: &ProverWhere, ask: impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: impl Fn(&str) -> String) -> CallOutcome {
        let mut outcome = CallOutcome { reach: CallReach::Proved, findings: vec![] };
        for index in 0..claims.len() as i64 {
            let pre = nikaia_std::index::get(&claims, (index) as usize);
            let mut given_by: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
            let mut k: i64 = 0;
            for arg in args.iter() {
                if ((k) as usize) >= params.len() { break; }
                let param = nikaia_std::index::get(&params, (k) as usize);
                let term = lin_term(arg, words, &|name| { scope.ints.contains(name) }, &mut arena.nodes);
                if term.is_some() { given_by.insert(param.to_owned(), nikaia_std::index::or(term, || 0)); }
                match arg {
                    Expr::Variable(name) => {
                        let name = *name;
                        let length = length_of(words.resolve(name));
                        if scope.ints.contains(&length) {
                            let known = arena.var(&length);
                            given_by.insert(length_of(&param), known);
                        }
                    },
                    _ => { },
                }
                k += 1;
            }
            let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
            arena.variables(pre.term, &mut read);
            let mut goal: Option<i64> = None;
            if every_given(&read, &given_by) { goal = Some(arena.substitute(pre.term, &given_by)); }
            if goal.is_some() && is_proved(ask(&arena, &scope.facts, nikaia_std::index::or(goal, || 0))) { continue; }
            let site = CarriedFrom { at: span.start as i64, callee: callee.to_owned(), place: index };
            if self.collecting {
                let mut carrying: Option<String> = None;
                if at.no_precondition.is_none() { carrying = carrying_function((at.function).as_deref()); }
                self.carry_back(arena, goal, &pre, callee, site, scope, (carrying).as_deref(), &at.params, &ask, &model);
                continue;
            }
            if self.carried_here((at.function).as_deref(), &site) { continue; }
            let mut always: Option<collections::BTreeMap<String, i64>> = None;
            if goal.is_some() { always = refuting_values(arena, &scope.facts, nikaia_std::index::or(goal, || 0), &ask, &model); }
            let broken_always = always.is_some();
            if broken_always {
                let values = nikaia_std::index::or(always, || collections::BTreeMap::new().into());
                let given = values_given(&arena, &given_by, &read, &values);
                let computed = claim_text_of((pre.computed).as_deref());
                let mut written = pre.written.to_owned();
                let mut notes: Vec<String> = vec![format!("Here {}.", shown(&given))];
                if computed.is_some() {
                    written = nikaia_std::index::or(computed, || "".into());
                    let origin = claim_text_of((pre.origin).as_deref());
                    if origin.is_some() { notes.push(format!("The precondition is `assert({})` in `{}`, carried back to `{}`'s entry.", pre.written, nikaia_std::index::or(origin.as_deref(), || ""), callee)); } else { notes.push(format!("The precondition is `assert({})` in `{}`, carried back to its entry.", pre.written, callee)); }
                }
                outcome.findings.push(Finding { code: String::from("NK1207"), span, message: format!("This call breaks `{}`'s precondition `{}` every time it is reached.", callee, written), notes, help: Some(format!("Pass `{}` arguments for which `{}` holds, or check them with a guard before the call.", callee, written)), warning: false });
            }
            if !broken_always && goal.is_some() {
                let breaking = breaking_values(arena, scope, nikaia_std::index::or(goal, || 0), &model);
                if breaking.is_some() {
                    let values = nikaia_std::index::or(breaking, || collections::BTreeMap::new().into());
                    let given = values_given(&arena, &given_by, &read, &values);
                    let computed = claim_text_of((pre.computed).as_deref());
                    let has_computed = computed.is_some();
                    let written = nikaia_std::index::or(computed, || pre.written.to_owned().into());
                    let mut notes: Vec<String> = vec![format!("Then {}.", shown(&given))];
                    if has_computed {
                        let origin = nikaia_std::index::or(claim_text_of((pre.origin).as_deref()), || callee.to_owned().into());
                        notes.push(format!("The precondition is `assert({})` in `{}`.", pre.written, origin));
                    }
                    outcome.findings.push(Finding { code: String::from("NK1207"), span, message: format!("This call breaks `{}`'s precondition `{}` when {}.", callee, written, shown(&values)), notes, help: Some(format!("Pass `{}` arguments for which `{}` holds, or check them with a guard before the call.", callee, written)), warning: false });
                }
            }
            let mut this_reach = CallReach::Through;
            if goal.is_some() {
                let mut operands: Vec<(String, String)> = vec![];
                for name in read.iter() {
                    let value = match *nikaia_std::index::get(&given_by, name) { Some(__nikaia_value) => nikaia_std::num::value(__nikaia_value), None => continue };
                    operands.push((name.to_owned(), rust_text(&arena, value, &escape)));
                }
                let check = PreconditionCheck { rust: rust_text(&arena, nikaia_std::index::or(goal, || 0), &escape), written: pre.failure(callee), message: claim_text_of((pre.message).as_deref()), operands };
                this_reach = CallReach::Checked(vec![check]);
            }
            outcome.reach = joined_reach(outcome.reach, this_reach);
        }
        outcome
    }
    #[allow(clippy::too_many_arguments)]
    pub fn carry_back(&mut self, arena: &mut TermArena, goal: Option<i64>, pre: &PreClaim, callee: &str, site: CarriedFrom, scope: &ProverScope, function: Option<&str>, params: &collections::BTreeSet<String>, ask: impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>) {
        let claim = match goal { Some(__nikaia_value) => __nikaia_value, None => return };
        let owner = match carrying_function(function) { Some(__nikaia_value) => __nikaia_value, None => return };
        if self.in_test || self.reaches(callee, &owner) { return; }
        if refuting_values(arena, &scope.facts, claim, &ask, &model).is_some() { return; }
        let term = match scope.precondition_at(arena, claim, params) { Some(__nikaia_value) => __nikaia_value, None => return };
        let carried = PreClaim { term, written: pre.written.to_owned(), computed: Some(arena.text(term)), message: claim_text_of((pre.message).as_deref()), origin: Some(nikaia_std::index::or(claim_text_of((pre.origin).as_deref()), || callee.to_owned().into())), site: Some(site) };
        let mut found = nikaia_std::index::or(self.preconditions.remove(&owner), || Precondition::none());
        found.claims.push(carried);
        self.preconditions.insert(owner, found);
    }
}

pub fn postconditions_for(arena: &mut TermArena, posts: &[PostClaim], params: &[String], args: &[Expr], bound: &str, scope: &ProverScope, words: &winnow_grammar::InternerContext) -> Vec<i64> {
    let mut args_given: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    let mut k: i64 = 0;
    for arg in args.iter() {
        if ((k) as usize) >= params.len() { break; }
        let param = nikaia_std::index::get(&params, (k) as usize);
        let term = lin_term(arg, words, &|name| { scope.ints.contains(name) }, &mut arena.nodes);
        if term.is_some() { args_given.insert(param.to_owned(), nikaia_std::index::or(term, || 0)); }
        match arg {
            Expr::Variable(name) => {
                let name = *name;
                let length = length_of(words.resolve(name));
                if scope.ints.contains(&length) {
                    let known = arena.var(&length);
                    args_given.insert(length_of(&param), known);
                }
            },
            _ => { },
        }
        k += 1;
    }
    let bound_length = length_of(bound);
    for (_, term) in args_given.iter() {
        let term = nikaia_std::num::value(term);
        if arena.mentions(term, bound) || arena.mentions(term, &bound_length) { return vec![]; }
    }
    let result = arena.var(bound);
    args_given.insert(result_name(), result);
    let mut out: Vec<i64> = vec![];
    for post in posts.iter() {
        let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
        arena.variables(post.term, &mut read);
        if every_given(&read, &args_given) { out.push(arena.substitute(post.term, &args_given)); }
    }
    out
}

fn every_given(names: &collections::BTreeSet<String>, args_given: &collections::BTreeMap<String, i64>) -> bool {
    for name in names.iter() { if !args_given.contains_key(name) { return false; } }
    true
}

fn standing_posts(postconditions: &collections::BTreeMap<String, Vec<PostClaim>>, function: &str) -> Option<Vec<PostClaim>> {
    let posts = match *nikaia_std::index::get(&postconditions, function) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(posts.to_owned())
}

fn carrying_function(function: Option<&str>) -> Option<String> {
    let f = match function { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(f.to_owned())
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ProverWhere {
    pub function: Option<String>,
    pub params: collections::BTreeSet<String>,
    pub no_precondition: Option<String>,
    pub top: bool,
    pub free: bool,
    pub lambda: bool,
    pub throws_out: bool,
}

impl ProverWhere {
    pub fn inside(&self, lambda: bool) -> ProverWhere {
        let mut at = self.clone();
        at.top = false;
        at.lambda = self.lambda || lambda;
        at
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CallOutcome {
    pub reach: CallReach,
    pub findings: Vec<Finding>,
}

fn is_proved(answer: SolverAnswer) -> bool { matches!(answer, SolverAnswer::Proved) }

fn values_given(arena: &TermArena, given_by: &collections::BTreeMap<String, i64>, read: &collections::BTreeSet<String>, values: &collections::BTreeMap<String, i64>) -> collections::BTreeMap<String, i64> {
    let mut out: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    for (name, term) in given_by.iter() {
        let term = nikaia_std::num::value(term);
        if !read.contains(name) { continue; }
        let value = match arena.int_value(term, values) { Some(__nikaia_value) => __nikaia_value, None => continue };
        out.insert(name.to_owned(), value);
    }
    out
}

fn rust_text(arena: &TermArena, id: i64, escape: &impl Fn(&str) -> String) -> String { rust_of(id, &|at| { arena.at(at) }, escape) }

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AssertOutcome {
    pub held: ClaimHeld,
    pub findings: Vec<Finding>,
}

fn returned_before(before_return: &collections::BTreeMap<i64, String>, at: i64) -> Option<String> {
    let name = match *nikaia_std::index::get(&before_return, &at) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(name.to_owned())
}

fn without_full_stops(text: &str) -> String {
    let c: Vec<char> = nikaia_std::list::chars(text.chars());
    let mut end = c.len() as i64;
    while end > 0 && *nikaia_std::index::get(&c, nikaia_std::index::at(end - 1)) == '.' { end -= 1; }
    let mut out: String = String::from("");
    for k in 0..end { out.push(*nikaia_std::index::get(&c, (k) as usize)); }
    out
}


// --- prover_walk.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ProverWalk {
    pub state: ProverState,
    pub arena: TermArena,
    pub held: collections::BTreeMap<(i64, String), ClaimHeld>,
    pub reaches: collections::BTreeMap<(String, String), CallReach>,
    pub findings: Vec<Finding>,
    pub claims: collections::BTreeSet<(i64, String)>,
}

#[allow(clippy::too_many_arguments)]
pub fn prover_bodies(walk: &mut ProverWalk, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String, shape_of: &impl Fn(&Expr) -> String, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) {
    for item in program.items.iter() {
        match &item.node {
            Item::Fn { .. } => prover_function(walk, item, None, false, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition),
            Item::Impl { methods, target, trait_name } => {
                let trait_name = *trait_name;
                let owner = words.resolve(target.name).to_owned();
                for method in methods.iter() { prover_function(walk, method, Some(owner.to_owned()), trait_name.is_some(), program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition); }
            },
            Item::Test { body, .. } => prover_test(walk, body, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition),
            Item::Bench { body, .. } => prover_test(walk, body, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition),
            _ => { },
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn prover_test(walk: &mut ProverWalk, body: &Block, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String, shape_of: &impl Fn(&Expr) -> String, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) {
    walk.state.in_test = true;
    let at = ProverWhere { function: None, params: collections::BTreeSet::new(), no_precondition: Some(String::from("a test has no callers")), top: true, free: false, lambda: false, throws_out: true };
    let mut scope = ProverScope::unknown();
    prover_block(walk, body, &mut scope, &at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
    walk.state.in_test = false;
}

#[allow(clippy::too_many_arguments)]
fn prover_function(walk: &mut ProverWalk, item: &Spanned<Item>, owner: Option<String>, of_a_trait: bool, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String, shape_of: &impl Fn(&Expr) -> String, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) {
    match &item.node {
        Item::Fn { name, receiver, args, body, can_throw, .. } => {
            let can_throw = *can_throw; let name = *name;
            let has_owner = owner.is_some();
            let mut key: Option<String> = None;
            let plain = prover_symbol_text((name).as_ref(), words);
            if plain.is_some() {
                let n = nikaia_std::index::or(plain, || "".into());
                if has_owner { key = Some(format!("{}::{}", nikaia_std::index::or(owner.as_deref(), || ""), n)); } else { key = Some(n); }
            }
            let was_a_test = key.is_some() && prover_a_test_function((key).as_deref());
            let mut scope = ProverScope::at_the_entry();
            let mut params: collections::BTreeSet<String> = collections::BTreeSet::new();
            if receiver.is_some() { scope.locals.insert(String::from("self")); }
            for arg in args.iter() {
                let arg_name = words.resolve(arg.name).to_owned();
                scope.locals.insert(arg_name.to_owned());
                let ty = words.resolve(arg.ty.name);
                if !arg.mutable && arg.ty.generics.is_empty() && is_whole_number(ty) {
                    scope.ints.insert(arg_name.to_owned());
                    scope.loose.insert(arg_name.to_owned());
                    params.insert(arg_name.to_owned());
                    let at_entry = walk.arena.var(&arg_name);
                    scope.entry.insert(arg_name.to_owned(), at_entry);
                    if ty.starts_with("u") { scope.not_negative(&mut walk.arena, &arg_name); }
                }
                if !arg.mutable && has_a_length(ty) {
                    scope.has_length(&mut walk.arena, &arg_name, None);
                    params.insert(arg_name.to_owned());
                    let length = length_of(&arg_name);
                    let at_entry = walk.arena.var(&length);
                    scope.entry.insert(length, at_entry);
                }
            }
            let mut no_precondition: Option<String> = None;
            if of_a_trait { no_precondition = Some(String::from("A method of a trait's implementation can't have a precondition: a call through the trait doesn't know it, and there is no second entry to check it.")); } else if prover_named_main((key).as_deref()) { no_precondition = Some(String::from("`main` has no callers.")); }
            let free = !has_owner && !was_a_test;
            let at = ProverWhere { function: claim_text_of((key).as_deref()), params, no_precondition, top: true, free, lambda: false, throws_out: can_throw };
            walk.state.in_test = was_a_test;
            let leaves = prover_block(walk, body, &mut scope, &at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
            walk.state.in_test = false;
            if !leaves && !walk.state.collecting && key.is_some() {
                let function = nikaia_std::index::or(key, || "".into());
                let posts = nikaia_std::index::or(standing_posts(&walk.state.postconditions, &function), || vec![].into());
                for index in 0..posts.len() as i64 { walk.state.broken.insert((function.to_owned(), index)); }
            }
        },
        _ => { },
    }
}

#[allow(clippy::too_many_arguments)]
fn prover_block(walk: &mut ProverWalk, block: &Block, scope: &mut ProverScope, at: &ProverWhere, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String, shape_of: &impl Fn(&Expr) -> String, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) -> bool {
    for index in 0..block.stmts.len() as i64 {
        let stmt = nikaia_std::index::get(&block.stmts, (index) as usize);
        if walk.state.collecting && ((index + 1) as usize) < block.stmts.len() {
            let returned = prover_returned_name(&nikaia_std::index::get(&block.stmts, (index + 1) as usize).node, words);
            if returned.is_some() { walk.state.before_return.insert(stmt.span.start as i64, nikaia_std::index::or(returned, || "".into())); }
        }
        if prover_stmt(walk, &stmt, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition) { return true; }
        if !prover_an_if(&stmt.node) && leaves_stmt(&stmt.node, &|e| { prover_throws(e, at, program, words, own, library, unaliased) }, holes_of, true) { scope.exact = false; }
    }
    false
}

#[allow(clippy::too_many_arguments)]
fn prover_stmt(walk: &mut ProverWalk, stmt: &Spanned<Stmt>, scope: &mut ProverScope, at: &ProverWhere, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String, shape_of: &impl Fn(&Expr) -> String, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) -> bool {
    let span = stmt.span;
    let nested = at.inside(false);
    match &stmt.node {
        Stmt::Let { names, mutable, ty, value } => {
            let mutable = *mutable;
            prover_let(walk, names, mutable, (ty).as_ref(), value, span, scope, &nested, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
            false
        },
        Stmt::Comptime { name, value, .. } => {
            let name = *name;
            prover_expr(walk, value, span, &scope, &nested, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
            scope.rebind(&walk.arena, words.resolve(name));
            false
        },
        Stmt::Assign { target, value, .. } => {
            prover_expr(walk, target, span, &scope, &nested, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
            prover_expr(walk, value, span, &scope, &nested, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
            match target {
                Expr::Variable(name) => {
                    let name = *name;
                    let n = words.resolve(name).to_owned();
                    let tainted = from_outside(value, &scope.tainted, words, library, holes_of);
                    scope.rebind(&walk.arena, &n);
                    if tainted { scope.tainted.insert(n); }
                },
                _ => { },
            }
            false
        },
        Stmt::For { bindings, iter, body } => {
            prover_for(walk, bindings, iter, body, span, scope, at, &nested, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
            false
        },
        Stmt::While { cond, body } => {
            prover_expr(walk, cond, span, &scope, &nested, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
            let mut inner = scope.clone();
            inner.path = None;
            inner.exact = false;
            scope.path = None;
            let holds = claim_term(cond, words, &|name| { inner.ints.contains(name) }, &mut walk.arena.nodes);
            if holds.is_some() { inner.facts.push(nikaia_std::index::or(holds, || 0)); }
            prover_block(walk, body, &mut inner, &nested, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
            if leaves_block(body, &|e| { prover_throws(e, at, program, words, own, library, unaliased) }, holes_of, false) { scope.exact = false; }
            false
        },
        Stmt::Return(value) => {
            prover_return(walk, (value).as_ref(), span, &scope, at, &nested, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
            true
        },
        Stmt::Break => true,
        Stmt::Continue => true,
        Stmt::Expr(expr) => prover_expr_stmt(walk, expr, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition),
    }
}

#[allow(clippy::too_many_arguments)]
fn prover_let(walk: &mut ProverWalk, names: &[winnow_grammar::Symbol], mutable: bool, ty: Option<&Type>, value: &Expr, span: Span, scope: &mut ProverScope, nested: &ProverWhere, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String, shape_of: &impl Fn(&Expr) -> String, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) {
    prover_expr(walk, value, span, &scope, nested, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
    let tainted = from_outside(value, &scope.tainted, words, library, holes_of);
    let value_lin = lin_term(value, words, &|name| { scope.ints.contains(name) }, &mut walk.arena.nodes);
    let mut value_at_entry: Option<i64> = None;
    if value_lin.is_some() { value_at_entry = scope.at_entry(&mut walk.arena, nikaia_std::index::or(value_lin, || 0)); }
    let mut called = false;
    let mut called_whole = false;
    let mut called_facts: Vec<i64> = vec![];
    if names.len() == 1 && !mutable {
        match value {
            Expr::Call { func, args, .. } => {
                let func = nikaia_std::boxed::open(func);
                let callee = prover_bound_callee(func, &scope, words, unaliased);
                if callee.is_some() {
                    let c = nikaia_std::index::or(callee, || "".into());
                    let bound = words.resolve(*nikaia_std::index::get(&names, 0)).to_owned();
                    called_facts = prover_postconditions_of(walk, &c, args, &bound, &scope, program, words, own, condition);
                    called_whole = prover_returns_whole(walk, &c, program, words, own, condition);
                    called = true;
                }
            },
            _ => { },
        }
    }
    for name in names.iter() {
        let n = words.resolve(*name).to_owned();
        scope.rebind(&walk.arena, &n);
        if tainted {
            scope.tainted.insert(n.to_owned());
            scope.loose.insert(n.to_owned());
        }
    }
    if names.len() != 1 || mutable { return; }
    let name = words.resolve(*nikaia_std::index::get(&names, 0)).to_owned();
    if value_lin.is_some() {
        let v = nikaia_std::index::or(value_lin, || 0);
        scope.ints.insert(name.to_owned());
        if !walk.arena.mentions(v, &name) {
            let named = walk.arena.var(&name);
            let fact = walk.arena.equal(named, v);
            scope.facts.push(fact);
        } else { scope.loose.insert(name.to_owned()); }
        if value_at_entry.is_some() { scope.entry.insert(name.to_owned(), nikaia_std::index::or(value_at_entry, || 0)); }
    } else if prover_typed(ty, words, 0) || called && called_whole {
        scope.ints.insert(name.to_owned());
        scope.loose.insert(name.to_owned());
    }
    if called && called_whole {
        for fact in called_facts.iter() {
            let fact = nikaia_std::num::value(fact);
            scope.facts.push(fact);
        }
    }
    if prover_typed(ty, words, 1) && scope.ints.contains(&name) { scope.not_negative(&mut walk.arena, &name); }
    match value {
        Expr::ListLit { items, .. } => {
            let known: Option<i64> = Some(items.len() as i64);
            scope.has_length(&mut walk.arena, &name, known);
        },
        Expr::LitStr { .. } => scope.has_length(&mut walk.arena, &name, None),
        _ => { if prover_typed(ty, words, 2) { scope.has_length(&mut walk.arena, &name, None); } },
    }
}

#[allow(clippy::too_many_arguments)]
fn prover_for(walk: &mut ProverWalk, bindings: &[winnow_grammar::Symbol], iter: &Expr, body: &Block, span: Span, scope: &mut ProverScope, at: &ProverWhere, nested: &ProverWhere, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String, shape_of: &impl Fn(&Expr) -> String, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) {
    prover_expr(walk, iter, span, &scope, nested, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
    let tainted = from_outside(iter, &scope.tainted, words, library, holes_of);
    let mut inner = scope.clone();
    for binding in bindings.iter() {
        let n = words.resolve(*binding).to_owned();
        inner.rebind(&walk.arena, &n);
        if tainted { inner.tainted.insert(n); }
    }
    let mut ranged = false;
    if bindings.len() == 1 {
        match iter {
            Expr::Range { start, end, inclusive } => {
                let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end); let inclusive = *inclusive;
                let low = lin_term(start, words, &|name| { scope.ints.contains(name) }, &mut walk.arena.nodes);
                let high = lin_term(end, words, &|name| { scope.ints.contains(name) }, &mut walk.arena.nodes);
                if low.is_some() && high.is_some() {
                    ranged = true;
                    let name = words.resolve(*nikaia_std::index::get(&bindings, 0)).to_owned();
                    inner.ints.insert(name.to_owned());
                    let lo = nikaia_std::index::or(low, || 0);
                    let hi = nikaia_std::index::or(high, || 0);
                    if !walk.arena.mentions(lo, &name) && !walk.arena.mentions(hi, &name) {
                        let n = walk.arena.var(&name);
                        let above = walk.arena.le(lo, n);
                        inner.facts.push(above);
                        if inclusive {
                            let below = walk.arena.le(n, hi);
                            inner.facts.push(below);
                        } else {
                            let below = walk.arena.lt(n, hi);
                            inner.facts.push(below);
                        }
                    } else { inner.loose.insert(name.to_owned()); }
                    if leaves_block(body, &|e| { prover_throws(e, at, program, words, own, library, unaliased) }, holes_of, false) { inner.loose.insert(name); }
                }
            },
            _ => { },
        }
    }
    if !ranged { for binding in bindings.iter() { inner.loose.insert(words.resolve(*binding).to_owned()); } }
    inner.path = None;
    prover_block(walk, body, &mut inner, nested, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
    scope.path = None;
    if leaves_block(body, &|e| { prover_throws(e, at, program, words, own, library, unaliased) }, holes_of, false) { scope.exact = false; }
}

#[allow(clippy::too_many_arguments)]
fn prover_return(walk: &mut ProverWalk, value: Option<&Expr>, span: Span, scope: &ProverScope, at: &ProverWhere, nested: &ProverWhere, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String, shape_of: &impl Fn(&Expr) -> String, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) {
    let returned = match value { Some(__nikaia_value) => __nikaia_value, None => return };
    prover_expr(walk, returned, span, scope, nested, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
    walk.state.exit(&mut walk.arena, returned, words, scope, (at.function).as_deref(), !at.lambda && at.free, &at.params, ask);
}

#[allow(clippy::too_many_arguments)]
fn prover_expr_stmt(walk: &mut ProverWalk, expr: &Expr, span: Span, scope: &mut ProverScope, at: &ProverWhere, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String, shape_of: &impl Fn(&Expr) -> String, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) -> bool {
    let nested = at.inside(false);
    match expr {
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            if prover_an_assert_call(func, args, &span, &walk.claims, shape_of) {
                let cond = nikaia_std::index::get(&args, 0);
                prover_expr(walk, &cond, span, &scope, &nested, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
                let message = prover_message(config, words);
                let names = claim_names_in(&cond, words, holes_of);
                let outcome = walk.state.an_assert(&mut walk.arena, words, &cond, written_of(&cond), &names, message, span, scope, at, ask, model);
                walk.held.insert((span.start as i64, shape_of(&cond)), outcome.held);
                for found in outcome.findings.iter() { walk.findings.push(found.clone()); }
                return false;
            }
        },
        Expr::If { cond, then_branch, else_branch } => {
            let cond = nikaia_std::boxed::open(cond);
            return prover_if(walk, cond, then_branch, (else_branch).as_ref(), span, scope, at, &nested, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
        },
        Expr::Throw(value) => {
            let value = nikaia_std::boxed::open(value);
            prover_expr(walk, value, span, &scope, &nested, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
            return true;
        },
        Expr::Return(value) => {
            let value = nikaia_std::boxed::open(value);
            prover_return(walk, (value).as_ref(), span, &scope, at, &nested, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
            return true;
        },
        Expr::Break => return true,
        Expr::Continue => return true,
        _ => { },
    }
    prover_expr(walk, expr, span, &scope, &nested, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
    false
}

#[allow(clippy::too_many_arguments)]
fn prover_if(walk: &mut ProverWalk, cond: &Expr, then_branch: &Block, else_branch: Option<&Block>, span: Span, scope: &mut ProverScope, at: &ProverWhere, nested: &ProverWhere, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String, shape_of: &impl Fn(&Expr) -> String, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) -> bool {
    prover_expr(walk, cond, span, &scope, nested, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
    let holds = claim_term(cond, words, &|name| { scope.ints.contains(name) }, &mut walk.arena.nodes);
    let mut fails: Option<i64> = None;
    if holds.is_some() { fails = Some(walk.arena.not(nikaia_std::index::or(holds, || 0))); }
    let mut then_scope = scope.clone();
    if holds.is_some() { then_scope.facts.push(nikaia_std::index::or(holds, || 0)); }
    then_scope.exact = then_scope.exact && holds.is_some();
    let cond_leaves = leaves_expr(cond, &|e| { prover_throws(e, at, program, words, own, library, unaliased) }, holes_of, true);
    then_scope.on_the_path(&mut walk.arena, holds);
    let then_leaves = prover_block(walk, then_branch, &mut then_scope, nested, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
    let else_leaves = prover_else(walk, else_branch, &scope, fails, nested, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
    if then_leaves && else_leaves { return true; }
    if then_leaves {
        if fails.is_some() { scope.facts.push(nikaia_std::index::or(fails, || 0)); }
        scope.on_the_path(&mut walk.arena, fails);
        scope.exact = scope.exact && fails.is_some() && !prover_else_leaves(else_branch, at, program, words, own, library, holes_of, unaliased);
    } else if else_leaves {
        if holds.is_some() { scope.facts.push(nikaia_std::index::or(holds, || 0)); }
        scope.on_the_path(&mut walk.arena, holds);
        scope.exact = scope.exact && holds.is_some() && !leaves_block(then_branch, &|e| { prover_throws(e, at, program, words, own, library, unaliased) }, holes_of, true);
    } else if leaves_block(then_branch, &|e| { prover_throws(e, at, program, words, own, library, unaliased) }, holes_of, true) || prover_else_leaves(else_branch, at, program, words, own, library, holes_of, unaliased) { scope.exact = false; }
    if cond_leaves { scope.exact = false; }
    false
}

#[allow(clippy::too_many_arguments)]
fn prover_else(walk: &mut ProverWalk, else_branch: Option<&Block>, scope: &ProverScope, fails: Option<i64>, nested: &ProverWhere, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String, shape_of: &impl Fn(&Expr) -> String, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) -> bool {
    let block = match else_branch { Some(__nikaia_value) => __nikaia_value, None => return false };
    let mut else_scope = scope.clone();
    if fails.is_some() { else_scope.facts.push(nikaia_std::index::or(fails, || 0)); }
    else_scope.exact = else_scope.exact && fails.is_some();
    else_scope.on_the_path(&mut walk.arena, fails);
    prover_block(walk, block, &mut else_scope, nested, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition)
}

#[allow(clippy::too_many_arguments)]
fn prover_else_leaves(else_branch: Option<&Block>, at: &ProverWhere, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String) -> bool {
    let block = match else_branch { Some(__nikaia_value) => __nikaia_value, None => return false };
    leaves_block(block, &|e| { prover_throws(e, at, program, words, own, library, unaliased) }, holes_of, true)
}

#[allow(clippy::too_many_arguments)]
fn prover_expr(walk: &mut ProverWalk, expr: &Expr, span: Span, scope: &ProverScope, at: &ProverWhere, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String, shape_of: &impl Fn(&Expr) -> String, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) {
    prover_calls_in(walk, expr, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
    prover_blocks_in(walk, expr, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
}

#[allow(clippy::too_many_arguments)]
fn prover_calls_in(walk: &mut ProverWalk, expr: &Expr, span: Span, scope: &ProverScope, at: &ProverWhere, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String, shape_of: &impl Fn(&Expr) -> String, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) {
    match expr {
        Expr::Call { func, args, .. } => {
            let func = nikaia_std::boxed::open(func);
            let callee = prover_called(func, words, unaliased);
            if callee.is_some() { prover_a_call(walk, nikaia_std::index::or(callee.as_deref(), || ""), args, span, scope, at, program, words, own, ask, model, escape, written_of, condition); }
        },
        _ => { },
    }
    for hole in holes_of(expr) { prover_calls_in(walk, &hole, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition); }
    match expr {
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            prover_calls_in(walk, func, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
            for arg in args.iter() { prover_calls_in(walk, arg, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition); }
            for c in config.iter() { prover_calls_in(walk, &c.value, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition); }
        },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            prover_calls_in(walk, receiver, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
            for arg in args.iter() { prover_calls_in(walk, arg, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition); }
            for c in config.iter() { prover_calls_in(walk, &c.value, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            prover_calls_in(walk, receiver, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
            for arg in args.iter() { prover_calls_in(walk, arg, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition); }
            for c in config.iter() { prover_calls_in(walk, &c.value, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition); }
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            prover_calls_in(walk, lhs, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
            prover_calls_in(walk, rhs, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); prover_calls_in(walk, expr, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); prover_calls_in(walk, inner, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition) },
        Expr::Throw(inner) => { let inner = nikaia_std::boxed::open(inner); prover_calls_in(walk, inner, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); prover_calls_in(walk, expr, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); prover_calls_in(walk, base, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); prover_calls_in(walk, base, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition) },
        Expr::Index { base, index } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            prover_calls_in(walk, base, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
            prover_calls_in(walk, index, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            prover_calls_in(walk, start, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
            prover_calls_in(walk, end, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
        },
        Expr::Tuple(parts) => { for part in parts.iter() { prover_calls_in(walk, part, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition); } },
        Expr::Coalesce { value, fallback } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            prover_calls_in(walk, value, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
            prover_calls_in(walk, fallback, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
        },
        Expr::TryCatch { expr, .. } => { let expr = nikaia_std::boxed::open(expr); prover_calls_in(walk, expr, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition) },
        Expr::If { cond, .. } => { let cond = nikaia_std::boxed::open(cond); prover_calls_in(walk, cond, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition) },
        Expr::Match { value, arms } => {
            let value = nikaia_std::boxed::open(value);
            prover_calls_in(walk, value, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
            for arm in arms.iter() {
                prover_calls_in_maybe(walk, (arm.guard).as_ref(), span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
                prover_calls_in(walk, &arm.body, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
            }
        },
        Expr::StructLit { fields, .. } => { for field in fields.iter() { prover_calls_in_maybe(walk, (field.value).as_ref(), span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition); } },
        Expr::ListLit { items, .. } => { for item in items.iter() { prover_calls_in(walk, item, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition); } },
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            prover_calls_in(walk, base, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
            for field in fields.iter() { prover_calls_in_maybe(walk, (field.value).as_ref(), span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition); }
        },
        Expr::Return(value) => { let value = nikaia_std::boxed::open(value); prover_calls_in_maybe(walk, (value).as_ref(), span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition) },
        Expr::Select(arms) => { for arm in arms.iter() { prover_calls_in(walk, &arm.value, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition); } },
        _ => { },
    }
}

#[allow(clippy::too_many_arguments)]
fn prover_calls_in_maybe(walk: &mut ProverWalk, expr: Option<&Expr>, span: Span, scope: &ProverScope, at: &ProverWhere, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String, shape_of: &impl Fn(&Expr) -> String, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) {
    let present = match expr { Some(__nikaia_value) => __nikaia_value, None => return };
    prover_calls_in(walk, present, span, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
}

#[allow(clippy::too_many_arguments)]
fn prover_blocks_in(walk: &mut ProverWalk, expr: &Expr, scope: &ProverScope, at: &ProverWhere, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String, shape_of: &impl Fn(&Expr) -> String, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) {
    match expr {
        Expr::Block(block) => prover_nested(walk, block, None, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition),
        Expr::Unsafe(block) => prover_nested(walk, block, None, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition),
        Expr::Overlap(block) => prover_nested(walk, block, None, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition),
        Expr::Closure { params, mutable, body } => {
            let mut names: Vec<String> = vec![];
            for p in params.iter() { names.push(words.resolve(*p).to_owned()); }
            for p in mutable.iter() { names.push(words.resolve(*p).to_owned()); }
            prover_nested(walk, body, Some(names), scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
        },
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            prover_blocks_in(walk, func, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
            for arg in args.iter() { prover_blocks_in(walk, arg, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition); }
            for c in config.iter() { prover_blocks_in(walk, &c.value, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition); }
        },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            prover_blocks_in(walk, receiver, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
            for arg in args.iter() { prover_blocks_in(walk, arg, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition); }
            for c in config.iter() { prover_blocks_in(walk, &c.value, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            prover_blocks_in(walk, receiver, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
            for arg in args.iter() { prover_blocks_in(walk, arg, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition); }
            for c in config.iter() { prover_blocks_in(walk, &c.value, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition); }
        },
        Expr::If { then_branch, else_branch, .. } => {
            prover_nested(walk, then_branch, None, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
            prover_nested_maybe(walk, (else_branch).as_ref(), scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
        },
        Expr::TryCatch { expr, handler } => {
            let expr = nikaia_std::boxed::open(expr);
            prover_blocks_in(walk, expr, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
            prover_nested(walk, handler, None, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
        },
        Expr::Match { arms, .. } => { for arm in arms.iter() { prover_blocks_in(walk, &arm.body, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition); } },
        Expr::Select(arms) => { for arm in arms.iter() { prover_nested(walk, &arm.body, None, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition); } },
        _ => { },
    }
}

#[allow(clippy::too_many_arguments)]
fn prover_nested_maybe(walk: &mut ProverWalk, block: Option<&Block>, scope: &ProverScope, at: &ProverWhere, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String, shape_of: &impl Fn(&Expr) -> String, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) {
    let present = match block { Some(__nikaia_value) => __nikaia_value, None => return };
    prover_nested(walk, present, None, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
}

#[allow(clippy::too_many_arguments)]
fn prover_nested(walk: &mut ProverWalk, block: &Block, lambda: Option<Vec<String>>, scope: &ProverScope, at: &ProverWhere, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String, shape_of: &impl Fn(&Expr) -> String, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) {
    let is_lambda = lambda.is_some();
    if is_lambda {
        let mut inner = scope.clone();
        for param in nikaia_std::index::or(lambda, || vec![].into()) {
            inner.rebind(&walk.arena, &param);
            inner.loose.insert(param.to_owned());
        }
        inner.path = None;
        inner.exact = false;
        prover_block(walk, block, &mut inner, &at.inside(true), program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
    } else {
        let mut inner = scope.blind();
        prover_block(walk, block, &mut inner, &at.inside(false), program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
    }
}

#[allow(clippy::too_many_arguments)]
fn prover_a_call(walk: &mut ProverWalk, callee: &str, args: &[Expr], span: Span, scope: &ProverScope, at: &ProverWhere, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) {
    if scope.locals.contains(callee) { return; }
    let caller = carrying_function((at.function).as_deref());
    if caller.is_some() { walk.state.edges.insert((nikaia_std::index::or(caller, || "".into()), callee.to_owned())); }
    let pre = if walk.state.collecting { prover_precondition_in(&walk.state.known, callee) } else { prover_precondition_in(&walk.state.preconditions, callee) };
    if pre.is_some() {
        let function = match free_function(program, words, callee) { Some(__nikaia_value) => __nikaia_value, None => return };
        let found = nikaia_std::index::or(pre, || Precondition::none());
        prover_record_call(walk, callee, &function.params, &found.claims, args, span, scope, at, words, ask, model, escape, written_of);
        return;
    }
    let foreign = match prover_foreign_contract(walk, callee, own, condition) { Some(__nikaia_value) => __nikaia_value, None => return };
    if !foreign.requires.is_empty() { prover_record_call(walk, callee, &foreign.params, &foreign.requires, args, span, scope, at, words, ask, model, escape, written_of); }
}

#[allow(clippy::too_many_arguments)]
fn prover_record_call(walk: &mut ProverWalk, callee: &str, params: &[String], claims: &[PreClaim], args: &[Expr], span: Span, scope: &ProverScope, at: &ProverWhere, words: &winnow_grammar::InternerContext, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String) {
    let outcome = walk.state.precondition_call(&mut walk.arena, words, callee, params, claims, args, span, scope, at, ask, model, escape);
    for found in outcome.findings.iter() { walk.findings.push(found.clone()); }
    let mut written: String = String::from("");
    for arg in args.iter() {
        if !written.is_empty() { written.push_str(", "); }
        written.push_str(&written_of(arg));
    }
    let key = (callee.to_owned(), written);
    let before = walk.reaches.remove(&key);
    if before.is_some() { walk.reaches.insert(key, joined_reach(nikaia_std::index::or(before, || CallReach::Proved), outcome.reach)); } else { walk.reaches.insert(key, outcome.reach); }
}

fn prover_foreign_contract(walk: &mut ProverWalk, key: &str, own: &Ledger, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) -> Option<Foreign> {
    let cached = prover_cached_foreign(&walk.state.foreign, key);
    if cached.is_some() { return cached; }
    let contract = match *nikaia_std::index::get(&own.functions, key) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let shape = foreign_shape(contract);
    let mut requires: Vec<i64> = vec![];
    for text in contract.requires.iter() { requires.push(prover_condition_term(&mut walk.arena, text, &shape.names, condition)); }
    let mut ensures: Vec<i64> = vec![];
    for text in contract.ensures.iter() { ensures.push(prover_condition_term(&mut walk.arena, text, &shape.names, condition)); }
    let foreign = foreign_from(contract, shape, &requires, &ensures);
    walk.state.foreign.insert(key.to_owned(), Some(foreign.clone()));
    Some(foreign)
}

fn prover_condition_term(arena: &mut TermArena, text: &str, names: &collections::BTreeSet<String>, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) -> i64 {
    let nodes = condition(text, names);
    if nodes.is_empty() { return -1; }
    arena.adopt(&nodes)
}

#[allow(clippy::too_many_arguments)]
fn prover_postconditions_of(walk: &mut ProverWalk, callee: &str, args: &[Expr], bound: &str, scope: &ProverScope, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) -> Vec<i64> {
    let posts = standing_posts(&walk.state.postconditions, callee);
    if posts.is_some() {
        let function = match free_function(program, words, callee) { Some(__nikaia_value) => __nikaia_value, None => return vec![] };
        return postconditions_for(&mut walk.arena, &nikaia_std::index::or(posts, || vec![].into()), &function.params, args, bound, scope, words);
    }
    let foreign = match prover_foreign_contract(walk, callee, own, condition) { Some(__nikaia_value) => __nikaia_value, None => return vec![] };
    postconditions_for(&mut walk.arena, &foreign.ensures, &foreign.params, args, bound, scope, words)
}

fn prover_returns_whole(walk: &mut ProverWalk, callee: &str, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) -> bool {
    let function = free_function(program, words, callee);
    if function.is_some() {
        let found = match function { Some(__nikaia_value) => __nikaia_value, None => return false };
        return found.whole_result;
    }
    let foreign = match prover_foreign_contract(walk, callee, own, condition) { Some(__nikaia_value) => __nikaia_value, None => return false };
    foreign.whole_result
}

fn prover_throws(call: &Expr, at: &ProverWhere, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, unaliased: &impl Fn(&str) -> String) -> bool { may_throw(call, at.throws_out, program, words, own, library, unaliased) }

fn prover_called(func: &Expr, words: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String) -> Option<String> {
    match func {
        Expr::Variable(name) => { let name = *name; Some(words.resolve(name).to_owned()) },
        Expr::Path(segments) => Some(prover_qualified(segments, words, unaliased)),
        _ => None,
    }
}

fn prover_bound_callee(func: &Expr, scope: &ProverScope, words: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String) -> Option<String> {
    match func {
        Expr::Variable(name) => {
            let name = *name;
            let text = words.resolve(name);
            if scope.locals.contains(text) { return None; }
            Some(text.to_owned())
        },
        Expr::Path(segments) => Some(prover_qualified(segments, words, unaliased)),
        _ => None,
    }
}

fn prover_qualified(segments: &[winnow_grammar::Symbol], words: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String) -> String {
    let mut joined: String = String::from("");
    for segment in segments.iter() {
        if !joined.is_empty() { joined.push_str("::"); }
        joined.push_str(words.resolve(*segment));
    }
    unaliased(&joined)
}

fn prover_an_assert_call(func: &Expr, args: &[Expr], span: &Span, claims: &collections::BTreeSet<(i64, String)>, shape_of: &impl Fn(&Expr) -> String) -> bool {
    let named = matches!(func, Expr::Variable(_));
    if !named || args.len() != 1 { return false; }
    claims.contains(&(span.start as i64, shape_of(nikaia_std::index::get(&args, 0))))
}

fn prover_message(config: &[ConfigArg], words: &winnow_grammar::InternerContext) -> Option<String> {
    for c in config.iter() {
        if words.resolve(c.name) == "message" {
            match &c.value {
                Expr::LitStr { text, .. } => return Some(text.to_owned()),
                _ => { },
            }
        }
    }
    None
}

fn prover_returned_name(stmt: &Stmt, words: &winnow_grammar::InternerContext) -> Option<String> {
    match stmt {
        Stmt::Return(value) => prover_variable_named((value).as_ref(), words),
        _ => None,
    }
}

fn prover_variable_named(value: Option<&Expr>, words: &winnow_grammar::InternerContext) -> Option<String> {
    let present = match value { Some(__nikaia_value) => __nikaia_value, None => return None };
    match present {
        Expr::Variable(name) => { let name = *name; Some(words.resolve(name).to_owned()) },
        _ => None,
    }
}

fn prover_an_if(stmt: &Stmt) -> bool {
    match stmt {
        Stmt::Expr(expr) => matches!(expr, Expr::If { .. }),
        _ => false,
    }
}

fn prover_symbol_text(symbol: Option<&winnow_grammar::Symbol>, words: &winnow_grammar::InternerContext) -> Option<String> {
    let present = match symbol { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(words.resolve(*present).to_owned())
}

fn prover_typed(ty: Option<&Type>, words: &winnow_grammar::InternerContext, asked: i64) -> bool {
    let t = match ty { Some(__nikaia_value) => __nikaia_value, None => return false };
    let name = words.resolve(t.name);
    if asked == 0 { return t.generics.is_empty() && is_whole_number(name); }
    if asked == 1 { return name.starts_with("u"); }
    has_a_length(name)
}

fn prover_a_test_function(name: Option<&str>) -> bool {
    let text = match name { Some(__nikaia_value) => __nikaia_value, None => return false };
    let prefix = "__nikaia_test_";
    if !text.starts_with(prefix) || (text.len() as i64) == prefix.len() as i64 { return false; }
    let c: Vec<char> = nikaia_std::list::chars(text.chars());
    for k in 14..c.len() as i64 { if *nikaia_std::index::get(&c, (k) as usize) < '0' || *nikaia_std::index::get(&c, (k) as usize) > '9' { return false; } }
    true
}

fn prover_precondition_in(map: &collections::BTreeMap<String, Precondition>, callee: &str) -> Option<Precondition> {
    let found = match *nikaia_std::index::get(&map, callee) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(found.clone())
}

fn prover_cached_foreign(map: &collections::BTreeMap<String, Option<Foreign>>, key: &str) -> Option<Foreign> {
    let found = match nikaia_std::index::flat(*nikaia_std::index::get(&map, key)) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(found.clone())
}

fn prover_named_main(own: Option<&str>) -> bool {
    let name = match own { Some(__nikaia_value) => __nikaia_value, None => return false };
    name == "main"
}


// --- render.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Marked {
    pub span: Span,
    pub word: String,
    pub text: String,
    pub main: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Shown {
    pub warning: bool,
    pub code: String,
    pub message: String,
    pub notes: Vec<String>,
    pub help: Option<String>,
    pub span: Span,
    pub labels: Vec<Marked>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Placed {
    line: i64,
    column: i64,
    width: i64,
    label: Marked,
}

pub fn rendered(shown: &Shown, path: &str, source: &str) -> String {
    let chars: Vec<char> = nikaia_std::list::chars(source.chars());
    let lines: Vec<&str> = source.split("\n").collect::<Vec<_>>();
    let mut labels: Vec<Marked> = shown.labels.to_owned();
    if labels.is_empty() { labels.push(Marked { span: shown.span.clone(), word: String::from(""), text: String::from(""), main: true }); }
    let mut placed: Vec<Placed> = vec![];
    for label in labels.iter() {
        let at = line_column(&chars, label.span.start);
        let text = line_of(&lines, at.0);
        let found = if label.word.is_empty() { (at.1, spanned_width(&chars, &label.span)) } else { word_in(&text, at.1, &label.word) };
        placed.push(Placed { line: at.0, column: found.0, width: found.1, label: label.clone() });
    }
    let placed = in_order(&placed);
    let mut line: i64 = -1;
    let mut column: i64 = -1;
    for one in placed.iter() {
        if line < 0 && one.label.main {
            line = one.line;
            column = one.column;
        }
    }
    if line < 0 {
        let at = line_column(&chars, shown.span.start);
        line = at.0;
        column = at.1;
    }
    let mut gutter: i64 = 1;
    for one in placed.iter() {
        let digits = format!("{}", one.line).len() as i64;
        if digits > gutter { gutter = digits; }
    }
    let mut bar = spaces(gutter + 1);
    bar.push_str(" |");
    let level = if shown.warning { "warning" } else { "error" };
    let mut out = headed(level, &shown.code);
    out.push_str(": ");
    out.push_str(&said(&shown.message));
    out.push('\n');
    out.push_str(&spaces(gutter + 1));
    out.push_str(&format!("--> {}:{}:{}", path, line, column));
    out.push('\n');
    out.push_str(&bar);
    out.push('\n');
    let mut shown_line: i64 = -1;
    for one in placed.iter() {
        if shown_line != one.line {
            if shown_line >= 0 && one.line - shown_line > 1 {
                out.push_str(&spaces(gutter + 2));
                out.push_str("...");
                out.push('\n');
            }
            out.push(' ');
            out.push_str(&right_aligned(&format!("{}", one.line), gutter));
            out.push_str(" | ");
            out.push_str(&line_of(&lines, one.line).trim_end());
            out.push('\n');
            shown_line = one.line;
        }
        let mark = if one.label.main { "^" } else { "-" };
        let mut marked = bar.to_owned();
        marked.push(' ');
        marked.push_str(&spaces(one.column - 1));
        marked.push_str(&mark.repeat(nikaia_std::count::of(one.width)));
        marked.push(' ');
        marked.push_str(&one.label.text);
        out.push_str(&marked.trim_end());
        out.push('\n');
    }
    out.push_str(&bar);
    out.push('\n');
    let indent = spaces(gutter + 2);
    for note in shown.notes.iter() {
        out.push_str(&indent);
        out.push_str("= note: ");
        out.push_str(&said(note));
        out.push('\n');
    }
    out.push_str(&helped(&indent, (shown.help).as_deref()));
    out
}

fn helped(indent: &str, help: Option<&str>) -> String {
    let given = match help { Some(__nikaia_value) => __nikaia_value, None => return String::from("") };
    format!("{}= help: {}\n", indent, said(given))
}

fn in_order(placed: &[Placed]) -> Vec<Placed> {
    let mut out: Vec<Placed> = vec![];
    for one in placed.iter() {
        let mut at = out.len() as i64;
        while at > 0 && (nikaia_std::index::get(&out, nikaia_std::index::at(at - 1)).line > one.line || nikaia_std::index::get(&out, nikaia_std::index::at(at - 1)).line == one.line && nikaia_std::index::get(&out, nikaia_std::index::at(at - 1)).column > one.column) { at -= 1; }
        out.insert(nikaia_std::count::of(at), one.clone());
    }
    out
}

fn line_of(lines: &[&str], line: i64) -> String {
    if line < 1 || line > lines.len() as i64 { return String::from(""); }
    (*nikaia_std::index::get(&lines, nikaia_std::index::at(line - 1))).to_owned()
}

fn line_column(chars: &[char], offset: u32) -> (i64, i64) {
    let wanted = offset as i64;
    let mut bytes: i64 = 0;
    let mut line = 1;
    let mut column = 1;
    for c in chars.iter() {
        let c = nikaia_std::num::value(c);
        if bytes >= wanted { break; }
        bytes += utf8_width(c);
        if c == '\n' {
            line += 1;
            column = 1;
        } else { column += 1; }
    }
    (line, column)
}

fn spanned_width(chars: &[char], span: &Span) -> i64 {
    let start = span.start as i64;
    let end = span.end as i64;
    let mut bytes: i64 = 0;
    let mut covered: String = String::from("");
    for c in chars.iter() {
        let c = nikaia_std::num::value(c);
        if bytes >= end { break; }
        if bytes >= start {
            if c == '\n' { break; }
            covered.push(c);
        }
        bytes += utf8_width(c);
    }
    let width = covered.trim_end().chars().count() as i64;
    if width < 1 { return 1; }
    width
}

fn utf8_width(c: char) -> i64 {
    let point = c as u32;
    if point < 128u32 { return 1; }
    if point < 2048u32 { return 2; }
    if point < 65536u32 { return 3; }
    4
}

fn spaces(n: i64) -> String { " ".repeat(nikaia_std::count::of(n)) }

fn right_aligned(text: &str, width: i64) -> String {
    let mut out = spaces(width - text.len() as i64);
    out.push_str(&text);
    out
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Pause {
    pub span: Span,
    pub caller: String,
    pub promise: String,
    pub callee: String,
    pub from_library: bool,
    pub unpromised: bool,
    pub construct: bool,
}

pub fn paused(pause: &Pause) -> Shown {
    let caller = pause.caller.to_owned();
    let promise = pause.promise.to_owned();
    let callee = pause.callee.to_owned();
    if pause.unpromised {
        let split = package_and_function(&callee);
        let package = &split.0;
        let function = &split.1;
        return Shown { warning: false, code: String::from("NK2202"), message: format!("`{}` is `{}`, but it calls `{}`, which doesn't promise that it never pauses.", caller, promise, callee), notes: vec![format!("`{}` is `{}`'s, and its source doesn't say `sync`. That its body doesn't pause today is not a promise another package can rely on.", callee, package)], help: Some(format!("Write `sync` after the result of `{}` in `{}`, or remove `{}` from `{}`.", function, package, promise, caller)), span: pause.span.clone(), labels: vec![Marked { span: pause.span.clone(), word: callee.to_owned(), text: String::from("doesn't promise `sync`"), main: true }] };
    }
    let ledger = if pause.from_library { "`std`" } else { "this program" };
    let article = an_or_a(&callee);
    let mut notes: Vec<String> = vec![String::from("A `sync` function promises that it never pauses and does no I/O.")];
    if pause.construct {
        let capital = said(&article);
        notes.push(format!("{} `{}` block waits for its branches to finish, which is a pause.", capital, callee));
    } else { notes.push(format!("`{}` isn't declared `sync` in {}.", callee, ledger)); }
    let message = if pause.construct { format!("`{}` is `{}`, but it contains {} `{}` block, which can pause.", caller, promise, article, callee) } else { format!("`{}` is `{}`, but it calls `{}`, which can pause.", caller, promise, callee) };
    Shown { warning: false, code: String::from("NK2202"), message, notes, help: Some(format!("Remove `{}` from `{}`, or move the call out of it.", promise, caller)), span: pause.span.clone(), labels: vec![Marked { span: pause.span.clone(), word: callee.to_owned(), text: String::from("this can pause"), main: true }] }
}

fn package_and_function(callee: &str) -> (String, String) {
    let parts: Vec<&str> = callee.splitn(2, "::").collect::<Vec<_>>();
    if parts.len() < 2 { return (String::from("its package"), callee.to_owned()); }
    ((*nikaia_std::index::get(&parts, 0)).to_owned(), (*nikaia_std::index::get(&parts, 1)).to_owned())
}

pub fn an_or_a(word: &str) -> String {
    let first: Vec<char> = nikaia_std::list::chars(word.chars());
    if !first.is_empty() && (*nikaia_std::index::get(&first, 0) == 'i' || *nikaia_std::index::get(&first, 0) == 'a' || *nikaia_std::index::get(&first, 0) == 'e' || *nikaia_std::index::get(&first, 0) == 'o' || *nikaia_std::index::get(&first, 0) == 'I' || *nikaia_std::index::get(&first, 0) == 'A' || *nikaia_std::index::get(&first, 0) == 'E' || *nikaia_std::index::get(&first, 0) == 'O') { return String::from("an"); }
    String::from("a")
}


// --- rust.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Part<'a> {
    pub name: &'a str,
    pub ty: &'a str,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Fun<'a> {
    pub name: &'a str,
    pub generics: &'a str,
    pub calls: Vec<&'a str>,
    pub wheres: &'a str,
    pub pauses: bool,
    pub parts: Vec<Part<'a>>,
    pub result: &'a str,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Rec<'a> {
    pub what: &'a str,
    pub name: &'a str,
    pub parts: Vec<Part<'a>>,
    pub derives: Vec<&'a str>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Group<'a> {
    pub what: &'a str,
    pub name: &'a str,
    pub via: &'a str,
    pub visible: bool,
    pub items: Vec<RustItem<'a>>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RustItem<'a> {
    Fun(Fun<'a>),
    Rec(Rec<'a>),
    Group(Group<'a>),
    Hidden(Fun<'a>),
    Used(&'a str),
    Export(&'a str),
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Found<'a> {
    One(RustItem<'a>),
    Skip,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Called<'a> {
    One(&'a str),
    Many(Vec<&'a str>),
    Nothing,
}

grammar! {
    grammar Rust {

        rule WSE =
            multispace1
            -> { }

        rule WS =
            (WSE | LINE | BLOCK)*
            -> { }

        rule LINE =
            "//" until(line_ending)
            -> { }

        rule BLOCK =
            "/*" until("*/") "*/"
            -> { }

        pub rule file -> Vec<RustItem<'a>> =
            items:public eof
            -> { items }

        rule public -> Vec<RustItem<'a>> =
            found:found*
            -> { kept(found) }

        rule exposed -> Vec<RustItem<'a>> =
            found:found_exposed*
            -> { kept(found) }

        rule found -> Found<'a> =
            i:item
            -> { Found::One(i) }
          | f:method
            -> { Found::One(RustItem::Hidden(f)) }
          | JUNK
            -> { Found::Skip }

        rule found_exposed -> Found<'a> =
            f:method
            -> { Found::One(RustItem::Fun(f)) }
          | i:item
            -> { Found::One(i) }
          | JUNK
            -> { Found::Skip }

        rule item -> RustItem<'a> =
            f:function
            -> { RustItem::Fun(f) }
          | r:record
            -> { RustItem::Rec(r) }
          | g:group
            -> { RustItem::Group(g) }
          | e:export
            -> { RustItem::Export(e) }
          | u:import
            -> { RustItem::Used(u) }

        rule export -> &'a str =
            PUB USE t:USE_TEXT ";"
            -> { t }

        rule import -> &'a str =
            USE t:USE_TEXT ";"
            -> { t }

        rule USE_TEXT -> &'a str =
            s:text(USE_RUN)
            -> { s.trim() }

        rule USE_RUN =
            USE_PIECE+
            -> { }

        rule USE_PIECE =
            not(";") (BRACES | LINE | BLOCK | ANY)
            -> { }

        rule function -> Fun<'a> =
            PUB f:method
            -> { f }

        rule method -> Fun<'a> =
            pauses:qualifiers FN name:IDENT g:generics parts:parameters result:result w:where_clause c:tail
            -> { Fun { name, generics: g, wheres: w, calls: c, pauses, parts, result } }

        rule qualifiers -> bool =
            qs:qualifier*
            -> {
                let mut pauses = false;
                for q in qs.into_iter() { if q { pauses = true; } }
                pauses
            }

        rule qualifier -> bool =
            ASYNC
            -> { true }
          | CONST
            -> { false }
          | UNSAFE
            -> { false }
          | EXTERN abi
            -> { false }

        rule abi =
            string
            -> { }
          | empty
            -> { }

        rule tail -> Vec<&'a str> =
            cs:inside
            -> { cs }
          | ";"
            -> { Vec::new() }

        rule inside -> Vec<&'a str> =
            "{" cs:inside_run "}"
            -> { cs }

        rule inside_run -> Vec<&'a str> =
            pieces:inside_piece*
            -> { every_call(pieces) }

        rule inside_piece -> Called<'a> =
            not("}") STRING
            -> { Called::Nothing }
          | not("}") CHAR
            -> { Called::Nothing }
          | not("}") LINE
            -> { Called::Nothing }
          | not("}") BLOCK
            -> { Called::Nothing }
          | not("}") inner:inside
            -> { Called::Many(inner) }
          | not("}") p:CALL
            -> { Called::One(p) }
          | not("}") ANY
            -> { Called::Nothing }

        rule CALL -> &'a str =
            p:text(PATH) TURBOFISH "("
            -> { p }

        rule PATH =
            raw_ident(PATH_TAIL)*
            -> { }

        rule PATH_TAIL =
            "::" raw_ident
            -> { }

        rule TURBOFISH =
            "::" ANGLES
            -> { }
          | empty
            -> { }

        rule parameters -> Vec<Part<'a>> =
            "(" ps:parameter_list ")"
            -> { ps }

        rule parameter_list -> Vec<Part<'a>> =
            head:parameter tail:parameter_tail* COMMA
            -> {
                let mut all = Vec::new();
                all.push(head);
                for p in tail.into_iter() { all.push(p); }
                all
            }
          | empty
            -> { Vec::new() }

        rule parameter_tail -> Part<'a> =
            "," p:parameter
            -> { p }

        rule parameter -> Part<'a> =
            t:text(receiver)
            -> { Part { name: "self", ty: t.trim() } }
          | MUT n:IDENT ":" t:PARAM_TYPE
            -> { Part { name: n, ty: t } }
          | n:IDENT ":" t:PARAM_TYPE
            -> { Part { name: n, ty: t } }
          | n:HOLE ":" t:PARAM_TYPE
            -> { Part { name: n, ty: t } }

        rule receiver =
            "&" LIFETIME MUT SELF
            -> { }
          | "&" LIFETIME SELF
            -> { }
          | "&" MUT SELF
            -> { }
          | "&" SELF
            -> { }
          | MUT SELF
            -> { }
          | SELF
            -> { }

        rule record -> Rec<'a> =
            ds:attributes PUB STRUCT name:IDENT generics where_clause "{" fs:field_list "}"
            -> { Rec { what: "struct", name, parts: fs, derives: ds } }
          | ds:attributes PUB STRUCT name:IDENT generics tuple_body where_clause ";"
            -> { Rec { what: "struct", name, parts: Vec::new(), derives: ds } }
          | ds:attributes PUB ENUM name:IDENT generics where_clause "{" vs:variant_list "}"
            -> { Rec { what: "enum", name, parts: vs, derives: ds } }

        rule attributes -> Vec<&'a str> =
            all:attribute*
            -> {
                let mut derives = Vec::new();
                for d in all.into_iter() { if !d.is_empty() { derives.push(d); } }
                derives
            }

        rule attribute -> &'a str =
            "#" "[" DERIVE "(" d:text(TUPLE_INNER) ")" "]"
            -> { d.trim() }
          | "#" "[" BRACKET_INNER "]"
            -> { "" }

        rule tuple_body =
            "(" TUPLE_INNER ")"
            -> { }
          | empty
            -> { }

        rule field_list -> Vec<Part<'a>> =
            head:field tail:field_tail* COMMA
            -> {
                let mut all = Vec::new();
                all.push(head);
                for f in tail.into_iter() { all.push(f); }
                all
            }
          | empty
            -> { Vec::new() }

        rule field_tail -> Part<'a> =
            "," f:field
            -> { f }

        rule field -> Part<'a> =
            PUB n:IDENT ":" t:FIELD_TYPE
            -> { Part { name: n, ty: t } }
          | n:IDENT ":" t:FIELD_TYPE
            -> { Part { name: n, ty: t } }

        rule variant_list -> Vec<Part<'a>> =
            head:variant tail:variant_tail* COMMA
            -> {
                let mut all = Vec::new();
                all.push(head);
                for v in tail.into_iter() { all.push(v); }
                all
            }
          | empty
            -> { Vec::new() }

        rule variant_tail -> Part<'a> =
            "," v:variant
            -> { v }

        rule variant -> Part<'a> =
            n:IDENT t:text(payload)
            -> { Part { name: n, ty: t.trim() } }

        rule payload =
            "(" TUPLE_INNER ")"
            -> { }
          | "{" BRACE_INNER "}"
            -> { }
          | empty
            -> { }

        rule group -> Group<'a> =
            UNSAFE IMPL generics v:IMPL_TYPE FOR t:IMPL_TYPE where_clause "{" items:exposed "}"
            -> { Group { what: "unsafe impl", name: t, via: v, visible: true, items } }
          | UNSAFE IMPL generics t:IMPL_TYPE where_clause "{" items:public "}"
            -> { Group { what: "unsafe impl", name: t, via: "", visible: true, items } }
          | IMPL generics v:IMPL_TYPE FOR t:IMPL_TYPE where_clause "{" items:exposed "}"
            -> { Group { what: "impl", name: t, via: v, visible: true, items } }
          | IMPL generics t:IMPL_TYPE where_clause "{" items:public "}"
            -> { Group { what: "impl", name: t, via: "", visible: true, items } }
          | PUB TRAIT name:IDENT generics where_clause "{" items:exposed "}"
            -> { Group { what: "trait", name, via: "", visible: true, items } }
          | PUB MOD name:IDENT "{" items:public "}"
            -> { Group { what: "mod", name, via: "", visible: true, items } }
          | PUB MOD name:IDENT ";"
            -> { Group { what: "mod", name, via: "", visible: true, items: Vec::new() } }
          | MOD name:IDENT "{" items:public "}"
            -> { Group { what: "mod", name, via: "", visible: false, items } }
          | MOD name:IDENT ";"
            -> { Group { what: "mod", name, via: "", visible: false, items: Vec::new() } }

        rule generics -> &'a str =
            "<" g:text(ANGLE_INNER) ">"
            -> { g.trim() }
          | empty
            -> { "" }

        rule where_clause -> &'a str =
            WHERE w:text(WHERE_RUN)
            -> { w.trim() }
          | empty
            -> { "" }

        rule PARAM_TYPE -> &'a str =
            s:text(PARAM_RUN)
            -> { s.trim() }

        rule PARAM_RUN =
            PARAM_PIECE+
            -> { }

        rule PARAM_PIECE =
            not(",") not(")") SPAN
            -> { }

        rule FIELD_TYPE -> &'a str =
            s:text(FIELD_RUN)
            -> { s.trim() }

        rule FIELD_RUN =
            FIELD_PIECE+
            -> { }

        rule FIELD_PIECE =
            not(",") not("}") SPAN
            -> { }

        rule result -> &'a str =
            "->" t:RESULT_TYPE
            -> { t }
          | empty
            -> { "" }

        rule RESULT_TYPE -> &'a str =
            s:text(RESULT_RUN)
            -> { s.trim() }

        rule RESULT_RUN =
            RESULT_PIECE+
            -> { }

        rule RESULT_PIECE =
            not("{") not(";") not(WHERE) SPAN
            -> { }

        rule WHERE_RUN =
            WHERE_PIECE+
            -> { }

        rule WHERE_PIECE =
            not("{") not(";") SPAN
            -> { }

        rule IMPL_TYPE -> &'a str =
            s:text(IMPL_RUN)
            -> { s.trim() }

        rule IMPL_RUN =
            IMPL_PIECE+
            -> { }

        rule IMPL_PIECE =
            not("{") not(WHERE) not(FOR) SPAN
            -> { }

        rule SPAN =
            (ANGLES | PARENS | BRACKETS | STRING | CHAR | LINE | BLOCK | ANY)
            -> { }

        rule JUNK =
            not("}") (STRING | CHAR | LINE | BLOCK | BRACES | ANY)
            -> { }

        rule BRACES =
            "{" BRACE_INNER "}"
            -> { }

        rule BRACE_INNER =
            BRACE_PIECE*
            -> { }

        rule BRACE_PIECE =
            not("}") (STRING | CHAR | LINE | BLOCK | BRACES | ANY)
            -> { }

        rule PARENS =
            "(" TUPLE_INNER ")"
            -> { }

        rule TUPLE_INNER =
            PAREN_PIECE*
            -> { }

        rule PAREN_PIECE =
            not(")") (STRING | CHAR | LINE | BLOCK | PARENS | BRACES | BRACKETS | ANGLES | ANY)
            -> { }

        rule BRACKETS =
            "[" BRACKET_INNER "]"
            -> { }

        rule BRACKET_INNER =
            BRACKET_PIECE*
            -> { }

        rule BRACKET_PIECE =
            not("]") (STRING | CHAR | LINE | BLOCK | PARENS | BRACES | BRACKETS | ANGLES | ANY)
            -> { }

        rule ANGLES =
            "<" ANGLE_INNER ">"
            -> { }

        rule ANGLE_INNER =
            ANGLE_PIECE*
            -> { }

        rule ANGLE_PIECE =
            not(">") (STRING | CHAR | LINE | BLOCK | PARENS | BRACKETS | ANGLES | ANY)
            -> { }

        rule STRING =
            "\"" (SESC | SPLAIN)* "\""
            -> { }

        rule SESC =
            "\\" any
            -> { }

        rule SPLAIN =
            not("\"") not("\\") any
            -> { }

        rule CHAR =
            "'" (CESC | CPLAIN) "'"
            -> { }

        rule CESC =
            "\\" any
            -> { }

        rule CPLAIN =
            not("'") not("\\") any
            -> { }

        rule ANY =
            any
            -> { }

        rule PUB =
            "pub" not(WORD) not("(")
            -> { }

        rule FN =
            "fn" not(WORD)
            -> { }

        rule ASYNC =
            "async" not(WORD)
            -> { }

        rule CONST =
            "const" not(WORD)
            -> { }

        rule UNSAFE =
            "unsafe" not(WORD)
            -> { }

        rule EXTERN =
            "extern" not(WORD)
            -> { }

        rule STRUCT =
            "struct" not(WORD)
            -> { }

        rule DERIVE =
            "derive" not(WORD)
            -> { }

        rule ENUM =
            "enum" not(WORD)
            -> { }

        rule TRAIT =
            "trait" not(WORD)
            -> { }

        rule IMPL =
            "impl" not(WORD)
            -> { }

        rule MOD =
            "mod" not(WORD)
            -> { }

        rule FOR =
            "for" not(WORD)
            -> { }

        rule WHERE =
            "where" not(WORD)
            -> { }

        rule MUT =
            "mut" not(WORD)
            -> { }

        rule USE =
            "use" not(WORD)
            -> { }

        rule SELF =
            "self" not(WORD)
            -> { }

        rule WORD =
            alpha1
            -> { }
          | digit
            -> { }
          | "_"
            -> { }

        rule IDENT -> &'a str =
            s:raw_ident
            -> { s }

        rule HOLE -> &'a str =
            s:text("_")
            -> { s }

        rule LIFETIME =
            "'" raw_ident
            -> { }

        rule COMMA =
            ","
            -> { }
          | empty
            -> { }
    }
}

fn every_call(pieces: Vec<Called<'_>>) -> Vec<&str> {
    let mut all = Vec::new();
    for piece in pieces.into_iter() {
        match piece {
            Called::One(one) => { all.push(one); },
            Called::Many(ref many) => {
                for one in many.iter() {
                    let one = *one;
                    all.push(one);
                }
            },
            Called::Nothing => { },
        }
    }
    all
}

fn kept(found: Vec<Found<'_>>) -> Vec<RustItem<'_>> {
    let mut all = Vec::new();
    for f in found.into_iter() {
        match f {
            Found::One(item) => { all.push(item); },
            Found::Skip => { },
        }
    }
    all
}


// --- rustc_words.nika ---

pub fn in_this_language(message: &str) -> String {
    let mut out = shared_names(message);
    out = replaced(&out, "nikaia_std::lock::Crossing", "Locked");
    out = replaced(&out, "nikaia_std::lock::Local", "Locked");
    out = replaced(&out, "lock::Crossing", "Locked");
    out = replaced(&out, "lock::Local", "Locked");
    out = replaced(&out, "Crossing<", "Locked<");
    out = replaced(&out, "Local<", "Locked<");
    out = replaced(&out, ", BuildHasherDefault<FxHasher>>", ">");
    out = replaced(&out, "nikaia_std::hash::TrustedMap", "HashMap");
    out = replaced(&out, "nikaia_std::hash::TrustedSet", "HashSet");
    out = replaced(&out, "TrustedMap", "HashMap");
    out = replaced(&out, "TrustedSet", "HashSet");
    out = replaced(&out, "`Option::<T>::map` takes ownership of the receiver `self`", "`?.` over a member that is not copied takes the value it reaches through ");
    out = replaced(&out, "`Option::<T>::and_then` takes ownership of the receiver `self`", "`?.` over a member that is not copied takes the value it reaches through ");
    out
}

pub fn is_rust_internal(note: &str) -> bool {
    for internal in ["#[deny(", "#[warn(", "#[allow(", "#[forbid(", "Cargo.toml", "cargo add", "RUST_BACKTRACE", "rustc --explain", "consider using the type `u32`", "consider using the type `u64`", "consider using the type `usize`", "consider calling `.as_ref()`", "consider calling `.as_mut()`", "you can `clone` the value and consume it"] { if note.contains(internal) { return true; } }
    false
}

pub fn both_sides_the_same(message: &str) -> Option<String> {
    let expected = match backticked_after(message, "expected ") { Some(__nikaia_value) => __nikaia_value, None => return None };
    let found = match backticked_after(message, "found ") { Some(__nikaia_value) => __nikaia_value, None => return None };
    if expected == found { return Some(expected); }
    None
}

fn backticked_after(message: &str, word: &str) -> Option<String> {
    let c: Vec<char> = nikaia_std::list::chars(message.chars());
    let w: Vec<char> = nikaia_std::list::chars(word.chars());
    let at = find_text(&c, 0, word);
    if at < 0 { return None; }
    let open = find(&c, at + w.len() as i64, '`');
    if open < 0 { return None; }
    let close = find(&c, open + 1, '`');
    if close < 0 { return None; }
    Some(slice(&c, open + 1, close))
}

fn shared_names(message: &str) -> String {
    let c: Vec<char> = nikaia_std::list::chars(message.chars());
    let mut out: String = String::from("");
    let mut last = ' ';
    let mut at: i64 = 0;
    while at < c.len() as i64 {
        let mut taken = false;
        for hull in ["std::rc::Rc<", "alloc::rc::Rc<", "std::sync::Arc<", "alloc::sync::Arc<", "Rc<", "Arc<"] {
            if !taken && begins_at(&c, at, hull) {
                let preceded_by_a_name = !hull.contains("::") && at > 0 && (last.is_alphanumeric() || last == '_' || last == ':');
                let h: Vec<char> = nikaia_std::list::chars(hull.chars());
                let close = closing_angle(&c, at + h.len() as i64);
                if !preceded_by_a_name && close >= 0 {
                    out.push_str("Shared[");
                    out.push_str(&shared_names(&slice(&c, at + h.len() as i64, close)));
                    out.push(']');
                    last = ']';
                    at = close + 1;
                    taken = true;
                }
            }
        }
        if !taken {
            out.push(*nikaia_std::index::get(&c, nikaia_std::index::at(at)));
            last = *nikaia_std::index::get(&c, nikaia_std::index::at(at));
            at += 1;
        }
    }
    out
}

fn closing_angle(c: &[char], from: i64) -> i64 {
    let mut depth = 1;
    for at in from..c.len() as i64 {
        if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '<' { depth += 1; } else if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '>' {
            depth -= 1;
            if depth == 0 { return at; }
        }
    }
    -1
}

fn begins_at(c: &[char], at: i64, word: &str) -> bool {
    let w: Vec<char> = nikaia_std::list::chars(word.chars());
    if (at + w.len() as i64) > c.len() as i64 { return false; }
    for k in 0..w.len() as i64 { if *nikaia_std::index::get(&c, nikaia_std::index::at(at + k)) != *nikaia_std::index::get(&w, (k) as usize) { return false; } }
    true
}

fn replaced(text: &str, from: &str, to: &str) -> String {
    let c: Vec<char> = nikaia_std::list::chars(text.chars());
    let f: Vec<char> = nikaia_std::list::chars(from.chars());
    let mut out: String = String::from("");
    let mut at: i64 = 0;
    let mut next = find_text(&c, 0, from);
    while next >= 0 {
        out.push_str(&slice(&c, at, next));
        out.push_str(to);
        at = next + f.len() as i64;
        next = find_text(&c, at, from);
    }
    out.push_str(&slice(&c, at, c.len() as i64));
    out
}

pub fn said(text: &str) -> String {
    let c: Vec<char> = nikaia_std::list::chars(text.trim_end().chars());
    if c.is_empty() { return String::from(""); }
    let mut first: String = String::from("");
    first.push(*nikaia_std::index::get(&c, 0));
    let mut out = first.to_uppercase();
    for k in 1..c.len() as i64 { out.push(*nikaia_std::index::get(&c, (k) as usize)); }
    let last = *nikaia_std::index::get(&c, nikaia_std::index::at(c.len() as i64 - 1));
    let mut closed = last == '.' || last == '?' || last == '!' || last == ':';
    if c.len() >= 2 && last == ')' && (*nikaia_std::index::get(&c, nikaia_std::index::at(c.len() as i64 - 2)) == '.' || *nikaia_std::index::get(&c, nikaia_std::index::at(c.len() as i64 - 2)) == '?') { closed = true; }
    let break_at = find_last(&c, '\n');
    if break_at >= 0 && break_at + 1 < c.len() as i64 && *nikaia_std::index::get(&c, nikaia_std::index::at(break_at + 1)) == ' ' { closed = true; }
    if !closed { out.push('.'); }
    out
}

pub fn headed(level: &str, code: &str) -> String {
    if code.is_empty() { return level.to_owned(); }
    format!("{}[{}]", level, code)
}

pub fn word_in(line: &str, column: i64, word: &str) -> (i64, i64) {
    let c: Vec<char> = nikaia_std::list::chars(line.chars());
    let w: Vec<char> = nikaia_std::list::chars(word.chars());
    if w.is_empty() { return (column, 1); }
    let starts_wordy = a_wordy_char(*nikaia_std::index::get(&w, 0));
    let ends_wordy = a_wordy_char(*nikaia_std::index::get(&w, nikaia_std::index::at(w.len() as i64 - 1)));
    let mut from = column - 1;
    if from < 0 { from = 0; }
    if from > c.len() as i64 { from = c.len() as i64; }
    for start in [from, 0] {
        let mut at = find_text(&c, start, word);
        while at >= 0 {
            let free_before = !starts_wordy || at == 0 || !a_wordy_char(*nikaia_std::index::get(&c, nikaia_std::index::at(at - 1)));
            let after = at + w.len() as i64;
            let free_after = !ends_wordy || after >= c.len() as i64 || !a_wordy_char(*nikaia_std::index::get(&c, nikaia_std::index::at(after)));
            if free_before && free_after { return (at + 1, w.len() as i64); }
            at = find_text(&c, at + w.len() as i64, word);
        }
    }
    (column, 1)
}

fn a_wordy_char(c: char) -> bool { c.is_alphanumeric() || c == '_' }


// --- sharing.nika ---

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Fallback {
    PublicSignature,
    PublicField,
    UnseenCall,
    UnseenMethod,
    UncoveredArgument,
    UnseenOrigin,
    ForeignFile,
}

impl Fallback {
    pub fn as_str(&self) -> String {
        match self {
            Fallback::PublicSignature => String::from("a public signature"),
            Fallback::PublicField => String::from("a public field"),
            Fallback::UnseenCall => String::from("a call nothing describes"),
            Fallback::UnseenMethod => String::from("a method nothing describes"),
            Fallback::UncoveredArgument => String::from("an argument position no contract covers"),
            Fallback::UnseenOrigin => String::from("an origin this analysis cannot see"),
            Fallback::ForeignFile => String::from("a slot another file owns"),
        }
    }
    pub fn remedy(&self) -> String {
        match self {
            Fallback::PublicSignature => String::from("nothing here - whether it crosses is decided by callers this build does not read, so an answer would be a promise about somebody else's code"),
            Fallback::PublicField => String::from("keep the field out of the published surface, or accept the atomic - code this build does not read can take the value out of it"),
            Fallback::UnseenCall => String::from("describe the callee in a ledger, so the compiler can see what it does"),
            Fallback::UnseenMethod => String::from("describe the callee in a ledger, so the compiler can see what it does"),
            Fallback::UncoveredArgument => String::from("describe the callee in a ledger, so the compiler can see what it does"),
            Fallback::UnseenOrigin => String::from("write down the call the value came out of, so this analysis can follow it to the allocation"),
            Fallback::ForeignFile => String::from("nothing here - the file that declares the field or the function decides its count, and this run reads only one of the two"),
        }
    }
}

pub fn every_fallback() -> Vec<Fallback> { vec![Fallback::PublicSignature, Fallback::PublicField, Fallback::UnseenCall, Fallback::UnseenMethod, Fallback::UncoveredArgument, Fallback::UnseenOrigin, Fallback::ForeignFile] }

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Decision {
    pub function: String,
    pub value: String,
    pub ty: String,
    pub count: Count,
    pub why: Option<String>,
    pub fallback: Option<Fallback>,
    pub duplications: Vec<String>,
    pub copied_out: Vec<String>,
    pub kept_its_lock: Option<String>,
}

impl Decision {
    pub fn undecided(&self) -> bool { self.fallback.is_some() }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Sharing {
    pub decisions: Vec<Decision>,
    pub summaries: collections::BTreeMap<String, Vec<Class>>,
    pub counts: collections::BTreeMap<String, Count>,
}

impl Sharing {
    pub fn count_of(&self, function: &str, value: &str) -> Count { nikaia_std::index::or(*nikaia_std::index::get(&self.counts, &(slot(function, value))), || Count::Atomic) }
}

pub fn every_count_plain(sharing: &mut Sharing) {
    for i in 0..sharing.decisions.len() as i64 {
        sharing.decisions[nikaia_std::index::at(i)].count = Count::Plain;
        sharing.decisions[nikaia_std::index::at(i)].why = None;
        sharing.decisions[nikaia_std::index::at(i)].fallback = None;
    }
    let mut keys: Vec<String> = vec![];
    for key in sharing.counts.keys() { keys.push(key.to_owned()); }
    for key in keys.iter() { sharing.counts.insert(key.to_owned(), Count::Plain); }
    let mut functions: Vec<String> = vec![];
    for key in sharing.summaries.keys() { functions.push(key.to_owned()); }
    for function in functions.iter() {
        let classes = nikaia_std::index::or(match *nikaia_std::index::get(&sharing.summaries, function) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || vec![].into());
        let mut plain: Vec<Class> = vec![];
        for class in classes.iter() { plain.push(Class { members: class.members.to_owned(), count: Count::Plain }); }
        sharing.summaries.insert(function.to_owned(), plain);
    }
}

pub fn sharing_report(sharing: &Sharing) -> String {
    if sharing.decisions.is_empty() { return String::from("no `Shared` value here, so there is nothing to choose.\n"); }
    let mut out: String = String::from("");
    let mut at: String = String::from("");
    let mut atomic: i64 = 0;
    let mut undecided = 0;
    let mut caught: Vec<String> = vec![];
    for decision in sharing.decisions.iter() {
        if at != decision.function {
            out.push_str(&format!("{}:\n", decision.function));
            at = decision.function.to_owned();
        }
        let count = decision.count.as_str();
        out.push_str(&format!("    {} `{}` ({})\n", padded_right(&count, 7), decision.value, decision.ty));
        out.push_str(&why_line(decision));
        out.push_str(&kept_line((decision.kept_its_lock).as_deref()));
        for site in decision.copied_out.iter() { out.push_str(&format!("             copied out: {} each time - `access` reads it in place\n", site)); }
        if decision.duplications.is_empty() { out.push_str("             one handle, so the count is never stepped\n"); }
        for site in decision.duplications.iter() { out.push_str(&format!("             duplicated: {}\n", site)); }
        if decision.count != Count::Plain { atomic += 1; }
        if decision.undecided() {
            undecided += 1;
            caught.push(fallback_text((decision.fallback).as_ref()));
        }
    }
    let all = sharing.decisions.len() as i64;
    let plain = all - atomic;
    out.push_str(&format!("\n{} `Shared` value(s): {} plain, {} atomic, of which {} because this analysis could not decide.\n", all, plain, atomic, undecided));
    out.push_str("An atomic count is the safe default. A plain count is an optimisation, and where it isn't taken the reason is one of these:\n");
    for fallback in every_fallback() {
        let said = fallback.as_str();
        let mark = if nikaia_std::list::contains(&caught, &said) { "*" } else { " " };
        let remedy = fallback.remedy();
        out.push_str(&format!("  {} {} - {}\n", mark, said, remedy));
    }
    out.push_str("The ones that need a contract get sharper as `std`'s contracts grow.\n");
    out
}

fn fallback_text(fallback: Option<&Fallback>) -> String {
    let row = match fallback { Some(__nikaia_value) => __nikaia_value, None => return String::from("") };
    row.as_str()
}

fn kept_line(kept: Option<&str>) -> String {
    let said = match kept { Some(__nikaia_value) => __nikaia_value, None => return String::from("") };
    format!("             {}\n", said)
}

fn why_line(decision: &Decision) -> String { why_said(decision, (decision.why).as_deref()) }

fn why_said(decision: &Decision, said: Option<&str>) -> String {
    let why = match said { Some(__nikaia_value) => __nikaia_value, None => return String::from("             nothing crosses a thread with it, so the count is lowered\n") };
    if decision.undecided() { return format!("             could not decide: {}\n", why); }
    if decision.count == Count::Word { return format!("             crosses: {}\n             a word, and no door over several locks takes it, so its `update` is a compare-and-swap and there is no lock\n", why); }
    format!("             crosses: {}\n", why)
}

pub fn slot(function: &str, name: &str) -> String { format!("{}::{}", function, name) }

pub fn split_slot(key: &str) -> (String, String) {
    let parts: Vec<&str> = key.split("::").collect::<Vec<_>>();
    if parts.len() < 2 { return (String::from(""), key.to_owned()); }
    let name = (*nikaia_std::index::get(&parts, nikaia_std::index::at(parts.len() as i64 - 1))).to_owned();
    let mut function: Vec<String> = vec![];
    for i in 0..parts.len() as i64 - 1 { function.push((*nikaia_std::index::get(&parts, (i) as usize)).to_owned()); }
    (function.join("::"), name)
}

pub fn holds_a_word(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; !view && name == "SharedMut" && args.len() == 1 && a_word(nikaia_std::index::get(&args, 0)) },
        _ => false,
    }
}

const WORD_TYPES: [&str; 12] = ["i8", "i16", "i32", "i64", "u8", "u16", "u32", "u64", "f32", "f64", "bool", "char"];

fn a_word(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; !view && args.is_empty() && one_of(&WORD_TYPES, name) },
        _ => false,
    }
}

pub fn held_that_does_not_copy(ty: &Ty) -> Option<String> {
    match ty {
        Ty::Named { name, args, .. } => a_held_value(ty, name, args),
        _ => None,
    }
}

fn a_held_value(ty: &Ty, name: &str, args: &[Ty]) -> Option<String> {
    if name != "SharedMut" || args.len() != 1 || holds_a_word(ty) || (*nikaia_std::index::get(&args, 0)).is_unknown() { return None; }
    Some((*nikaia_std::index::get(&args, 0)).text())
}

pub fn literal_type(expr: &Expr) -> Option<String> {
    match expr {
        Expr::LitStr { .. } => Some(String::from("String")),
        Expr::LitInterpolated { .. } => Some(String::from("String")),
        Expr::LitInt { .. } => Some(String::from("i64")),
        Expr::LitFloat(_) => Some(String::from("f64")),
        Expr::LitBool(_) => Some(String::from("bool")),
        Expr::LitChar(_) => Some(String::from("char")),
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); literal_type(expr) },
        _ => None,
    }
}

pub fn published_reason(key: &str, at: &str) -> String {
    if at == RESULT_POSITION { return format!("`{}` is public and hands a `Shared` back, so what the caller does with it is in a unit this build cannot see", key); }
    format!("`{}` is public, so its callers are in a unit this build cannot see, and one of them may cross a thread with it", key)
}

pub fn handed_on_to(key: &str, param: &str) -> String { format!("handed to `{}` as `{}`, which takes a handle of its own", key, param) }

pub fn unseen(callee: Option<&str>) -> String {
    let named = nikaia_std::index::or(callee, || "the callee");
    format!("the compiler knows nothing about `{}`, so it has to assume it might start a thread", named)
}

pub fn by_value_shared(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, view, .. } => { let view = *view; !view && (name == "Shared" || name == "SharedMut") },
        _ => false,
    }
}

pub fn is_hull(name: &str) -> bool { name == "Shared" || name == "SharedMut" || name == "Locked" }

pub fn holds_shared(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, .. } => name == "Shared" || name == "SharedMut" || any_holds_shared(args),
        Ty::Tuple(parts) => any_holds_shared(parts),
        _ => false,
    }
}

fn any_holds_shared(types: &[Ty]) -> bool {
    for ty in types.iter() { if holds_shared(ty) { return true; } }
    false
}

pub fn shared_fields(ty: &str, asked: &Asked<'_>) -> Vec<String> {
    let name = without_a_view(ty);
    let contract = match ledger_type(&name, asked.own, asked.library) { Some(__nikaia_value) => __nikaia_value, None => return vec![] };
    let mut out: Vec<String> = vec![];
    for field in contract.fields.iter() { if holds_shared(&field.ty) { out.push(format!("{}.{}", name, field.name)); } }
    out
}

pub fn declared_field_type(ty: &str, field: &str, asked: &Asked<'_>) -> Option<Ty> {
    let contract = match ledger_type(&without_a_view(ty), asked.own, asked.library) { Some(__nikaia_value) => __nikaia_value, None => return None };
    for declared in contract.fields.iter() { if declared.name == field { return Some(declared.ty.clone()); } }
    None
}

fn without_a_view(ty: &str) -> String {
    let mut out: String = String::from("");
    let mut leading = true;
    for c in ty.chars() {
        if leading && c == '&' { continue; }
        leading = false;
        out.push(c);
    }
    out
}

pub fn rust_name(count: Count) -> String {
    match count {
        Count::Plain => String::from("std::rc::Rc"),
        Count::Word => String::from("std::sync::Arc"),
        Count::Atomic => String::from("std::sync::Arc"),
    }
}

pub fn lock_name(count: Count) -> String {
    match count {
        Count::Plain => String::from("nikaia_std::lock::Local"),
        Count::Word => String::from("nikaia_std::lock::Word"),
        Count::Atomic => String::from("nikaia_std::lock::Crossing"),
    }
}

pub const FIELDS: &str = "<field>";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Handle {
    pub function: String,
    pub value: String,
    pub ty: Ty,
    pub internal: bool,
    pub position: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Forced {
    pub key: String,
    pub why: String,
    pub fallback: Option<Fallback>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Slots {
    pub declared_here: collections::BTreeSet<String>,
    pub handles: collections::BTreeMap<String, Handle>,
    pub index: collections::BTreeMap<String, i64>,
    pub parent: Vec<i64>,
    pub forced: Vec<Forced>,
    pub duplicated: Vec<(String, String)>,
    pub held_together: Vec<String>,
    pub copies: Vec<(String, String)>,
}

impl Slots {
    pub fn new(declared_here: collections::BTreeSet<String>) -> Slots { Slots { declared_here, handles: collections::BTreeMap::new(), index: collections::BTreeMap::new(), parent: vec![], forced: vec![], duplicated: vec![], held_together: vec![], copies: vec![] } }
    pub fn id(&mut self, key: &str) -> i64 {
        let found = *nikaia_std::index::get(&self.index, key);
        if found.is_some() { return nikaia_std::index::or(found, || 0); }
        let fresh = self.parent.len() as i64;
        self.parent.push(fresh);
        self.index.insert(key.to_owned(), fresh);
        fresh
    }
    pub fn root(&mut self, start: i64) -> i64 {
        let mut at = start;
        while *nikaia_std::index::get(&self.parent, nikaia_std::index::at(at)) != at {
            let up = *nikaia_std::index::get(&self.parent, nikaia_std::index::at(at));
            { let __nikaia_stored = *nikaia_std::index::get(&self.parent, nikaia_std::index::at(up)); nikaia_std::index::set(&mut self.parent, nikaia_std::index::at(at), __nikaia_stored); }
            at = *nikaia_std::index::get(&self.parent, nikaia_std::index::at(at));
        }
        at
    }
    pub fn class_of(&mut self, key: &str) -> i64 {
        let id = self.id(key);
        self.root(id)
    }
    pub fn join(&mut self, left: &str, right: &str) {
        let one = self.class_of(left);
        let other = self.class_of(right);
        if one != other { { let __nikaia_stored = other; nikaia_std::index::set(&mut self.parent, nikaia_std::index::at(one), __nikaia_stored); } }
    }
    pub fn note(&mut self, function: &str, value: &str, ty: Ty, internal: bool, position: bool) {
        let key = slot(function, value);
        self.id(&key);
        if !self.handles.contains_key(&key) { self.handles.insert(key.to_owned(), Handle { function: function.to_owned(), value: value.to_owned(), ty, internal, position }); }
    }
    pub fn force(&mut self, function: &str, value: &str, why: String, fallback: Option<Fallback>) {
        let key = slot(function, value);
        self.id(&key);
        self.forced.push(Forced { key, why, fallback });
    }
    pub fn duplicates(&mut self, function: &str, value: &str, site: String) {
        let key = slot(function, value);
        self.id(&key);
        self.duplicated.push((key, site));
    }
    fn foreign_slots_hold_the_floor(&mut self) {
        let field_prefix = format!("{}::", FIELDS);
        let mut foreign: Vec<(String, String)> = vec![];
        for key in self.index.keys() {
            if !key.contains("::") { continue; }
            let mut owner = before_last(key, "::");
            let mut named = key.to_owned();
            if key.starts_with(&field_prefix) {
                let parts: Vec<&str> = key.splitn(2, "::").collect::<Vec<_>>();
                named = (*nikaia_std::index::get(&parts, 1)).to_owned();
                owner = before_last(&named, ".");
            }
            if !self.declared_here.contains(&owner) { foreign.push((key.to_owned(), named)); }
        }
        for (key, named) in foreign.iter() {
            let why = format!("`{}` belongs to another file of this package, and that file's own pass decides its count - this one reads only one of the two", named);
            self.forced.push(Forced { key: key.to_owned(), why, fallback: Some(Fallback::ForeignFile) });
        }
    }
}

fn before_last(text: &str, separator: &str) -> String {
    let parts: Vec<&str> = text.split(separator).collect::<Vec<_>>();
    if parts.len() < 2 { return text.to_owned(); }
    let mut kept: Vec<String> = vec![];
    for i in 0..parts.len() as i64 - 1 { kept.push((*nikaia_std::index::get(&parts, (i) as usize)).to_owned()); }
    kept.join(separator)
}

pub fn decided(slots: &mut Slots) -> Sharing {
    slots.foreign_slots_hold_the_floor();
    let mut why_of: collections::BTreeMap<i64, String> = collections::BTreeMap::new();
    let mut fallback_of: collections::BTreeMap<i64, Fallback> = collections::BTreeMap::new();
    let mut floor: collections::BTreeSet<i64> = collections::BTreeSet::new();
    let forced = slots.forced.to_owned();
    for one in forced.iter() {
        let root = slots.class_of(&one.key);
        if one.fallback.is_some() { floor.insert(root); }
        if !why_of.contains_key(&root) || fallback_of.contains_key(&root) && one.fallback.is_none() {
            why_of.insert(root, one.why.to_owned());
            set_fallback(&mut fallback_of, root, one.fallback);
        }
    }
    let mut held: collections::BTreeSet<i64> = collections::BTreeSet::new();
    let together = slots.held_together.to_owned();
    for key in together.iter() { held.insert(slots.class_of(key)); }
    let keys: Vec<String> = handle_keys(&slots);
    let mut not_a_word: collections::BTreeSet<i64> = collections::BTreeSet::new();
    for key in keys.iter() {
        let root = slots.class_of(key);
        if !holds_a_word(&handle_type(&slots, key)) { not_a_word.insert(root); }
    }
    let duplicated = sites_by_slot(&slots.duplicated);
    let copied_out = sites_by_slot(&slots.copies);
    let mut decisions: Vec<Decision> = vec![];
    let mut counts: collections::BTreeMap<String, Count> = collections::BTreeMap::new();
    let mut classes: collections::BTreeMap<String, collections::BTreeMap<i64, Class>> = collections::BTreeMap::new();
    for key in keys.iter() {
        let root = slots.class_of(key);
        let handle = match match *nikaia_std::index::get(&slots.handles, key) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => continue };
        let a_word = !not_a_word.contains(&root);
        let mut count = Count::Plain;
        let mut why: Option<String> = None;
        let mut fallback: Option<Fallback> = None;
        if why_of.contains_key(&root) {
            why = match *nikaia_std::index::get(&why_of, &root) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            };
            fallback = nikaia_std::index::or_maybe(*nikaia_std::index::get(&fallback_of, &root), || None);
            count = Count::Atomic;
            if fallback.is_none() && a_word && !floor.contains(&root) && !held.contains(&root) { count = Count::Word; }
        }
        if handle.position { put_in_class(&mut classes, &handle.function, root, &handle.value, count); }
        counts.insert(key.to_owned(), count);
        if !handle.internal {
            decisions.push(Decision { function: handle.function.to_owned(), value: handle.value.to_owned(), ty: handle.ty.text(), count, why, fallback, duplications: nikaia_std::index::or(match *nikaia_std::index::get(&duplicated, key) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || vec![].into()), copied_out: nikaia_std::index::or(match *nikaia_std::index::get(&copied_out, key) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || vec![].into()), kept_its_lock: lock_kept(&count, a_word, held.contains(&root)) });
        }
    }
    let mut summaries: collections::BTreeMap<String, Vec<Class>> = collections::BTreeMap::new();
    for (function, roots) in classes.iter() {
        let mut found: Vec<Class> = vec![];
        for (_, class) in roots.iter() { found.push(Class { members: sorted_once(&class.members), count: class.count }); }
        summaries.insert(function.to_owned(), in_class_order(&found));
    }
    Sharing { decisions, summaries, counts }
}

fn set_fallback(fallback_of: &mut collections::BTreeMap<i64, Fallback>, root: i64, fallback: Option<Fallback>) {
    fallback_of.remove(&root);
    let row = match fallback { Some(__nikaia_value) => __nikaia_value, None => return };
    fallback_of.insert(root, row);
}

fn handle_keys(slots: &Slots) -> Vec<String> {
    let mut keys: Vec<String> = vec![];
    for key in slots.handles.keys() { keys.push(key.to_owned()); }
    keys
}

fn handle_type(slots: &Slots, key: &str) -> Ty {
    let handle = match *nikaia_std::index::get(&slots.handles, key) { Some(__nikaia_value) => __nikaia_value, None => return Ty::Unknown };
    handle.ty.clone()
}

fn sites_by_slot(pairs: &[(String, String)]) -> collections::BTreeMap<String, Vec<String>> {
    let mut out: collections::BTreeMap<String, Vec<String>> = collections::BTreeMap::new();
    for (key, site) in pairs.iter() {
        let mut sites = nikaia_std::index::or(match *nikaia_std::index::get(&out, key) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || vec![].into());
        if !nikaia_std::list::contains(&sites, &site) { sites.push(site.to_owned()); }
        out.insert(key.to_owned(), sites);
    }
    out
}

fn put_in_class(classes: &mut collections::BTreeMap<String, collections::BTreeMap<i64, Class>>, function: &str, root: i64, member: &str, count: Count) {
    let mut roots = nikaia_std::index::or(match *nikaia_std::index::get(&classes, function) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || collections::BTreeMap::new().into());
    let mut class = nikaia_std::index::or(match *nikaia_std::index::get(&roots, &root) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || Class { members: vec![], count });
    class.members.push(member.to_owned());
    class.count = class.count.join(count);
    roots.insert(root, class);
    classes.insert(function.to_owned(), roots);
}

fn lock_kept(count: &Count, a_word: bool, held_together: bool) -> Option<String> {
    if *count != Count::Atomic || !a_word { return None; }
    if held_together { return Some(String::from("a word, but a door over several locks takes it, and a compare-and-swap cannot be held, so it keeps its lock")); }
    Some(String::from("a word, but the floor answered for it rather than a crossing, so it keeps its lock"))
}

fn sorted_once(members: &[String]) -> Vec<String> {
    let mut sorted = members.to_owned();
    sorted.sort();
    let mut out: Vec<String> = vec![];
    for one in sorted.iter() { if out.is_empty() || *nikaia_std::index::get(&out, nikaia_std::index::at(out.len() as i64 - 1)) != *one { out.push(one.to_owned()); } }
    out
}

fn in_class_order(classes: &[Class]) -> Vec<Class> {
    let mut out: Vec<Class> = vec![];
    for class in classes.iter() {
        let mut at = out.len() as i64;
        while at > 0 && class_before(class, nikaia_std::index::get(&out, nikaia_std::index::at(at - 1))) { at -= 1; }
        out.insert(nikaia_std::count::of(at), class.clone());
    }
    out
}

fn class_before(a: &Class, b: &Class) -> bool {
    let shorter = if (a.members.len() as i64) < b.members.len() as i64 { a.members.len() as i64 } else { b.members.len() as i64 };
    for i in 0..shorter { if *nikaia_std::index::get(&a.members, (i) as usize) != *nikaia_std::index::get(&b.members, (i) as usize) { return *nikaia_std::index::get(&a.members, (i) as usize) < *nikaia_std::index::get(&b.members, (i) as usize); } }
    if (a.members.len() as i64) != b.members.len() as i64 { return (a.members.len() as i64) < b.members.len() as i64; }
    a.count.rank() < b.count.rank()
}

const PARALLEL: [&str; 3] = ["par_iter", "par_fold", "par_map"];

pub fn declared_here(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>]) -> collections::BTreeSet<String> {
    let mut out: collections::BTreeSet<String> = collections::BTreeSet::new();
    for item in items.iter() {
        match &item.node {
            Item::Struct { name, .. } => {
                let name = *name;
                out.insert(names.resolve(name).to_owned());
            },
            Item::Enum { name, .. } => {
                let name = *name;
                out.insert(names.resolve(name).to_owned());
            },
            Item::Fn { name, .. } => {
                let name = *name;
                let own = a_symbols_text(names, name);
                if !own.is_empty() { out.insert(own); }
            },
            Item::Impl { target, methods, .. } => {
                let owner = names.resolve(target.name).to_owned();
                for method in methods.iter() {
                    let own = method_name(names, &method.node);
                    if !own.is_empty() { out.insert(format!("{}::{}", owner, own)); }
                }
                out.insert(owner);
            },
            _ => { },
        }
    }
    out
}

fn method_name(names: &winnow_grammar::InternerContext, item: &Item) -> String {
    match item {
        Item::Fn { name, .. } => { let name = *name; if name.is_none() { String::from("new") } else { a_symbols_text(names, name) } },
        _ => String::from(""),
    }
}

pub fn allocates_here(expr: &Expr, asked: &Asked<'_>) -> bool {
    match expr {
        Expr::LitInt { .. } => true,
        Expr::LitFloat(_) => true,
        Expr::LitStr { .. } => true,
        Expr::LitInterpolated { .. } => true,
        Expr::LitChar(_) => true,
        Expr::LitBool(_) => true,
        Expr::LitNull => true,
        Expr::StructLit { .. } => true,
        Expr::Call { func, .. } => { let func = nikaia_std::boxed::open(func); a_call_that_allocates((call_path(func, asked.names)).as_deref(), asked) },
        Expr::MethodCall { method, .. } => { let method = *method; hands_back_a_plain_value(asked.names.resolve(method), asked) },
        Expr::SafeMethod { method, .. } => { let method = *method; hands_back_a_plain_value(asked.names.resolve(method), asked) },
        _ => false,
    }
}

fn a_call_that_allocates(path: Option<&str>, asked: &Asked<'_>) -> bool {
    let callee = match path { Some(__nikaia_value) => __nikaia_value, None => return false };
    is_hull(callee) || hands_back_a_plain_value(callee, asked)
}

pub fn hands_back_a_plain_value(callee: &str, asked: &Asked<'_>) -> bool {
    let suffix = format!("::{}", callee);
    if has_an_entry(asked.own, callee, &suffix) { return plain_in(asked.own, callee, &suffix); }
    plain_in(asked.library, callee, &suffix)
}

fn has_an_entry(ledger: &Ledger, callee: &str, suffix: &str) -> bool {
    if ledger.functions.contains_key(callee) { return true; }
    for key in ledger.functions.keys() { if key.ends_with(&suffix) { return true; } }
    false
}

fn plain_in(ledger: &Ledger, callee: &str, suffix: &str) -> bool {
    let exact = *nikaia_std::index::get(&ledger.functions, callee);
    if exact.is_some() { return a_plain_result(exact); }
    for (key, contract) in ledger.functions.iter() { if key.ends_with(&suffix) { return a_plain_result(Some(contract)); } }
    false
}

fn a_plain_result(contract: Option<&FnContract>) -> bool {
    let found = match contract { Some(__nikaia_value) => __nikaia_value, None => return false };
    let signature = match found.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return false };
    let result = match signature.result.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return false };
    !result.is_unknown() && !holds_shared(result)
}

pub fn origin_reason(expr: &Expr, names: &winnow_grammar::InternerContext) -> String {
    let from = where_it_came_from(expr, names);
    format!("{}, so this analysis did not watch the allocation being made - and the count belongs to the allocation. A call handed to another thread hands its result back across one (ADR-292)", from)
}

fn where_it_came_from(expr: &Expr, names: &winnow_grammar::InternerContext) -> String {
    match expr {
        Expr::Call { func, .. } => { let func = nikaia_std::boxed::open(func); a_call_that_hands_it_back((call_path(func, names)).as_deref()) },
        Expr::MethodCall { method, .. } => { let method = *method; format!("`{}` hands it back", names.resolve(method)) },
        Expr::SafeMethod { method, .. } => { let method = *method; format!("`{}` hands it back", names.resolve(method)) },
        Expr::Field { name, .. } => { let name = *name; format!("it is read out of `{}`", names.resolve(name)) },
        Expr::Index { .. } => String::from("it is read out of a collection"),
        _ => String::from("it comes from an expression this analysis does not follow"),
    }
}

fn a_call_that_hands_it_back(path: Option<&str>) -> String {
    let callee = match path { Some(__nikaia_value) => __nikaia_value, None => return String::from("a call hands it back") };
    format!("`{}` hands it back", callee)
}

pub fn named_handle(expr: &Expr, names: &winnow_grammar::InternerContext, scope: &collections::BTreeMap<String, Ty>) -> Option<String> {
    match expr {
        Expr::Variable(name) => { let name = *name; a_handle_in_scope(names.resolve(name), scope) },
        Expr::Block(block) => a_handle_at_the_tail(block, names, scope),
        _ => None,
    }
}

fn a_handle_in_scope(name: &str, scope: &collections::BTreeMap<String, Ty>) -> Option<String> {
    let ty = match *nikaia_std::index::get(&scope, name) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if holds_shared(ty) { return Some(name.to_owned()); }
    None
}

fn a_handle_at_the_tail(block: &Block, names: &winnow_grammar::InternerContext, scope: &collections::BTreeMap<String, Ty>) -> Option<String> {
    if block.stmts.is_empty() { return None; }
    match &nikaia_std::index::get(&block.stmts, nikaia_std::index::at(block.stmts.len() as i64 - 1)).node {
        Stmt::Expr(tail) => named_handle(tail, names, scope),
        _ => None,
    }
}

pub fn named_type(expr: &Expr, names: &winnow_grammar::InternerContext, scope: &collections::BTreeMap<String, Ty>) -> Option<String> {
    match expr {
        Expr::Variable(name) => { let name = *name; scope_type_name(names.resolve(name), scope) },
        _ => None,
    }
}

fn scope_type_name(name: &str, scope: &collections::BTreeMap<String, Ty>) -> Option<String> {
    let ty = match *nikaia_std::index::get(&scope, name) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(without_a_view(&ty.text()))
}

pub fn walks_in_parallel(receiver: &Expr, names: &winnow_grammar::InternerContext, parallel: &collections::BTreeSet<String>) -> bool {
    match receiver {
        Expr::Variable(name) => { let name = *name; parallel.contains(names.resolve(name)) },
        Expr::MethodCall { receiver, method, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; a_parallel_method(names.resolve(method)) || walks_in_parallel(receiver, names, parallel) },
        _ => false,
    }
}

pub fn a_parallel_method(method: &str) -> bool {
    for one in PARALLEL.iter() {
        let one = *one;
        if one == method { return true; }
    }
    false
}

pub fn call_path(func: &Expr, names: &winnow_grammar::InternerContext) -> Option<String> {
    match func {
        Expr::Variable(name) => { let name = *name; Some(names.resolve(name).to_owned()) },
        Expr::Path(segments) => Some(joined_segments(segments, names)),
        _ => None,
    }
}

const RESULT: &str = "<result>";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SharingWalk {
    pub slots: Slots,
    pub parallel: collections::BTreeSet<String>,
    pub function: String,
    pub scope: collections::BTreeMap<String, Ty>,
}

pub fn sharing_of(program: &Program, asked: &Asked<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, ty_of: &impl Fn(&Type) -> Ty, crossings_are_possible: bool) -> Sharing {
    let mut walk = SharingWalk { slots: Slots::new(declared_here(asked.names, &program.items)), parallel: collections::BTreeSet::new(), function: String::from(""), scope: collections::BTreeMap::new() };
    for item in program.items.iter() {
        match &item.node {
            Item::Fn { .. } => sharing_function(&item.node, "", asked, holes_of, ty_of, &mut walk),
            Item::Impl { target, methods, .. } => {
                let owner = asked.names.resolve(target.name).to_owned();
                for method in methods.iter() { sharing_function(&method.node, &owner, asked, holes_of, ty_of, &mut walk); }
            },
            Item::Struct { name, fields, is_public, .. } => {
                let is_public = *is_public; let name = *name;
                if is_public { public_fields(asked.names.resolve(name), fields, asked, ty_of, &mut walk); }
            },
            _ => { },
        }
    }
    let mut sharing = decided(&mut walk.slots);
    if !crossings_are_possible { every_count_plain(&mut sharing); }
    sharing
}

fn public_fields(owner: &str, fields: &[FieldDef], asked: &Asked<'_>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) {
    for field in fields.iter() {
        if !field.is_public { continue; }
        let ty = ty_of(&field.ty);
        if !holds_shared(&ty) { continue; }
        let key = format!("{}.{}", owner, asked.names.resolve(field.name));
        walk.slots.note(FIELDS, &key, ty, true, false);
        walk.slots.force(FIELDS, &key, format!("`{}` is a public field of a public type, so code this build cannot see may take the value out of it and cross with it", key), Some(Fallback::PublicField));
    }
}

fn sharing_function(item: &Item, owner: &str, asked: &Asked<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) {
    match item {
        Item::Fn { name, args, body, ret_type, is_public, .. } => {
            let is_public = *is_public; let name = *name;
            walk.function = key_of_function((name).as_ref(), owner, asked.names);
            walk.scope = collections::BTreeMap::new();
            for arg in args.iter() {
                let ty = ty_of(&arg.ty);
                let named = asked.names.resolve(arg.name).to_owned();
                position(&named, &ty, is_public, asked, walk);
                walk.scope.insert(named, ty);
            }
            if ret_type.is_some() {
                let result = match ret_type { Some(__nikaia_value) => __nikaia_value, None => return };
                position(RESULT, &ty_of(result), is_public, asked, walk);
            }
            sharing_block(body, asked, holes_of, ty_of, walk);
        },
        _ => { },
    }
}

fn position(named: &str, ty: &Ty, is_public: bool, asked: &Asked<'_>, walk: &mut SharingWalk) {
    let function = walk.function.to_owned();
    if holds_shared(ty) {
        walk.slots.note(&function, named, ty.clone(), named == RESULT, true);
        if is_public { walk.slots.force(&function, named, published_reason(&function, named), Some(Fallback::PublicSignature)); }
    } else if is_public { for field in shared_fields(&ty.text(), asked) { walk.slots.force(FIELDS, &field, published_reason(&function, named), Some(Fallback::PublicSignature)); } }
}

fn sharing_block(block: &Block, asked: &Asked<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) { for stmt in block.stmts.iter() { sharing_statement(&stmt.node, asked, holes_of, ty_of, walk); } }

fn sharing_statement(stmt: &Stmt, asked: &Asked<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) {
    match stmt {
        Stmt::Let { names, ty, value, .. } => {
            if names.len() != 1 { return; }
            let_binding(asked.names.resolve(*nikaia_std::index::get(&names, 0)).to_owned(), (ty).as_ref(), value, asked, ty_of, walk);
            sharing_expression(value, asked, holes_of, ty_of, walk);
        },
        Stmt::Comptime { .. } => { },
        Stmt::Assign { target, value, .. } => {
            let target_slot = slot_of(target, asked, walk);
            if target_slot.is_some() {
                let known = nikaia_std::index::or(target_slot, || "".into());
                let source = slot_of(value, asked, walk);
                if source.is_none() {
                    let (at, named) = split_slot(&known);
                    origin_unseen(&at, &named, value, asked, walk);
                } else { walk.slots.join(&known, nikaia_std::index::or(source.as_deref(), || "")); }
            }
            sharing_expression(target, asked, holes_of, ty_of, walk);
            sharing_expression(value, asked, holes_of, ty_of, walk);
        },
        Stmt::For { iter, body, .. } => {
            sharing_expression(iter, asked, holes_of, ty_of, walk);
            sharing_block(body, asked, holes_of, ty_of, walk);
        },
        Stmt::While { cond, body } => {
            sharing_expression(cond, asked, holes_of, ty_of, walk);
            sharing_block(body, asked, holes_of, ty_of, walk);
        },
        Stmt::Return(value) => {
            let returned = match value { Some(__nikaia_value) => __nikaia_value, None => return };
            hands_back(returned, asked, walk);
            sharing_expression(returned, asked, holes_of, ty_of, walk);
        },
        Stmt::Expr(value) => {
            hands_back(value, asked, walk);
            sharing_expression(value, asked, holes_of, ty_of, walk);
        },
        _ => { },
    }
}

fn let_binding(named: String, written: Option<&Type>, value: &Expr, asked: &Asked<'_>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) {
    if walks_in_parallel(value, asked.names, &walk.parallel) { walk.parallel.insert(named.to_owned()); }
    let aliased = named_handle(value, asked.names, &walk.scope);
    let ty = match binding_type(written, (aliased).as_deref(), value, asked, ty_of, &walk.scope) { Some(__nikaia_value) => __nikaia_value, None => return };
    if holds_shared(&ty) {
        let function = walk.function.to_owned();
        walk.slots.note(&function, &named, ty.clone(), false, false);
        if aliased.is_some() { walk.slots.join(&slot(&function, &named), &slot(&function, nikaia_std::index::or(aliased.as_deref(), || ""))); } else {
            let source = slot_of(value, asked, walk);
            if source.is_some() { walk.slots.join(&slot(&function, &named), nikaia_std::index::or(source.as_deref(), || "")); } else if !(by_value_shared(&ty) && allocates_here(value, asked)) { origin_unseen(&function, &named, value, asked, walk); }
        }
    }
    walk.scope.insert(named, ty);
}

fn binding_type(written: Option<&Type>, aliased: Option<&str>, value: &Expr, asked: &Asked<'_>, ty_of: &impl Fn(&Type) -> Ty, scope: &collections::BTreeMap<String, Ty>) -> Option<Ty> {
    if written.is_some() { return Some(ty_of(match written { Some(__nikaia_value) => __nikaia_value, None => return None })); }
    if aliased.is_some() {
        let handle = match aliased { Some(__nikaia_value) => __nikaia_value, None => return None };
        let ty = match *nikaia_std::index::get(&scope, handle) { Some(__nikaia_value) => __nikaia_value, None => return None };
        return Some(ty.clone());
    }
    match value {
        Expr::StructLit { name, .. } => { let name = *name; Some(plain_type(asked.names.resolve(name))) },
        Expr::Call { func, args, .. } => { let func = nikaia_std::boxed::open(func); hull_written(func, args, asked) },
        _ => None,
    }
}

fn hull_written(func: &Expr, args: &[Expr], asked: &Asked<'_>) -> Option<Ty> {
    let named = match func {
        Expr::Variable(name) => { let name = *name; asked.names.resolve(name).to_owned() },
        _ => return None,
    };
    if !is_hull(&named) { return None; }
    if args.len() == 1 {
        let held = match literal_type(nikaia_std::index::get(&args, 0)) { Some(__nikaia_value) => __nikaia_value, None => return Some(plain_type(&named)) };
        return Some(Ty::Named { name: named, args: vec![plain_type(&held)], view: false });
    }
    Some(plain_type(&named))
}

fn plain_type(name: &str) -> Ty { Ty::Named { name: name.to_owned(), args: vec![], view: false } }

fn hands_back(value: &Expr, asked: &Asked<'_>, walk: &mut SharingWalk) {
    let source = match slot_of(value, asked, walk) { Some(__nikaia_value) => __nikaia_value, None => return };
    walk.slots.join(&slot(&walk.function, RESULT), &source);
}

fn origin_unseen(function: &str, named: &str, value: &Expr, asked: &Asked<'_>, walk: &mut SharingWalk) { walk.slots.force(function, named, origin_reason(value, asked.names), Some(Fallback::UnseenOrigin)); }

fn a_crossing_reaches(named: &str, why: &str, fallback: Option<Fallback>, asked: &Asked<'_>, walk: &mut SharingWalk) {
    let ty = match match *nikaia_std::index::get(&walk.scope, named) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return };
    if holds_shared(&ty) {
        walk.slots.force(&walk.function, named, why.to_owned(), fallback);
        return;
    }
    for field in shared_fields(&ty.text(), asked) { walk.slots.force(FIELDS, &field, why.to_owned(), fallback); }
}

fn slot_of(expr: &Expr, asked: &Asked<'_>, walk: &mut SharingWalk) -> Option<String> {
    let handle = named_handle(expr, asked.names, &walk.scope);
    if handle.is_some() { return Some(slot(&walk.function, nikaia_std::index::or(handle.as_deref(), || ""))); }
    match expr {
        Expr::Field { base, name } => { let base = nikaia_std::boxed::open(base); let name = *name; field_slot(base, asked.names.resolve(name), asked, walk) },
        _ => None,
    }
}

fn field_slot(base: &Expr, field: &str, asked: &Asked<'_>, walk: &mut SharingWalk) -> Option<String> {
    let owner = match named_type(base, asked.names, &walk.scope) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let ty = match declared_field_type(&owner, field, asked) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if !holds_shared(&ty) { return None; }
    let key = format!("{}.{}", owner, field);
    walk.slots.note(FIELDS, &key, ty, true, false);
    Some(slot(FIELDS, &key))
}

fn sharing_expression(expr: &Expr, asked: &Asked<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) {
    match expr {
        Expr::Spawn { body, .. } => {
            let body = nikaia_std::boxed::open(body);
            for named in names_used_by(body, asked) {
                if a_handle_by_value(&named, &walk) { walk.slots.duplicates(&walk.function, &named, String::from("used by a `spawn` body, which takes a handle of its own")); }
                a_crossing_reaches(&named, "a `spawn` body uses it, and a task runs on a thread of its own", None, asked, walk);
            }
            sharing_expression(body, asked, holes_of, ty_of, walk);
        },
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            let callee = call_path(func, asked.names);
            let path = nikaia_std::index::or(match callee.as_ref() {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || "".into());
            if path == "access_all" || path == "update_all" {
                for arg in args.iter() {
                    let handle = match named_handle(arg, asked.names, &walk.scope) { Some(__nikaia_value) => __nikaia_value, None => continue };
                    walk.slots.held_together.push(slot(&walk.function, &handle));
                }
            }
            sharing_arguments(&SharingCall { callee, is_method: false }, args, config, asked, holes_of, ty_of, walk);
            sharing_expression(func, asked, holes_of, ty_of, walk);
        },
        Expr::MethodCall { .. } => sharing_method(expr, asked, holes_of, ty_of, walk),
        Expr::SafeMethod { .. } => sharing_method(expr, asked, holes_of, ty_of, walk),
        Expr::StructLit { name, fields } => {
            let name = *name;
            let owner = asked.names.resolve(name).to_owned();
            for field in fields.iter() { struct_field(&owner, field, asked, holes_of, ty_of, walk); }
        },
        Expr::LitInterpolated { .. } => { for hole in holes_of(expr) { sharing_expression(&hole, asked, holes_of, ty_of, walk); } },
        Expr::Closure { body, .. } => sharing_block(body, asked, holes_of, ty_of, walk),
        Expr::Block(block) => sharing_block(block, asked, holes_of, ty_of, walk),
        Expr::Overlap(block) => sharing_block(block, asked, holes_of, ty_of, walk),
        Expr::If { cond, then_branch, else_branch } => {
            let cond = nikaia_std::boxed::open(cond);
            sharing_expression(cond, asked, holes_of, ty_of, walk);
            sharing_block(then_branch, asked, holes_of, ty_of, walk);
            sharing_block(match else_branch { Some(__nikaia_value) => __nikaia_value, None => return }, asked, holes_of, ty_of, walk);
        },
        Expr::Match { value, arms } => {
            let value = nikaia_std::boxed::open(value);
            sharing_expression(value, asked, holes_of, ty_of, walk);
            for arm in arms.iter() { sharing_expression(&arm.body, asked, holes_of, ty_of, walk); }
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            sharing_expression(lhs, asked, holes_of, ty_of, walk);
            sharing_expression(rhs, asked, holes_of, ty_of, walk);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); sharing_expression(expr, asked, holes_of, ty_of, walk) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); sharing_expression(inner, asked, holes_of, ty_of, walk) },
        Expr::Throw(inner) => { let inner = nikaia_std::boxed::open(inner); sharing_expression(inner, asked, holes_of, ty_of, walk) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); sharing_expression(expr, asked, holes_of, ty_of, walk) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); sharing_expression(base, asked, holes_of, ty_of, walk) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); sharing_expression(base, asked, holes_of, ty_of, walk) },
        Expr::Index { base, index } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            sharing_expression(base, asked, holes_of, ty_of, walk);
            sharing_expression(index, asked, holes_of, ty_of, walk);
        },
        Expr::Coalesce { value, fallback } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            sharing_expression(value, asked, holes_of, ty_of, walk);
            sharing_expression(fallback, asked, holes_of, ty_of, walk);
        },
        Expr::TryCatch { expr, handler } => {
            let expr = nikaia_std::boxed::open(expr);
            sharing_expression(expr, asked, holes_of, ty_of, walk);
            sharing_block(handler, asked, holes_of, ty_of, walk);
        },
        Expr::Tuple(parts) => { for part in parts.iter() { sharing_expression(part, asked, holes_of, ty_of, walk); } },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            sharing_expression(start, asked, holes_of, ty_of, walk);
            sharing_expression(end, asked, holes_of, ty_of, walk);
        },
        _ => { },
    }
}

fn names_used_by(expr: &Expr, asked: &Asked<'_>) -> collections::BTreeSet<String> {
    let mut out: collections::BTreeSet<String> = collections::BTreeSet::new();
    names_in(expr, asked.names, &mut out);
    out
}

fn a_handle_by_value(named: &str, walk: &SharingWalk) -> bool {
    let ty = match *nikaia_std::index::get(&walk.scope, named) { Some(__nikaia_value) => __nikaia_value, None => return false };
    by_value_shared(ty)
}

fn struct_field(owner: &str, field: &FieldInit, asked: &Asked<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) {
    let field_name = asked.names.resolve(field.name).to_owned();
    let value = nikaia_std::index::or(match field.value.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || Expr::Variable(field.name));
    let key = format!("{}.{}", owner, field_name);
    let handle = named_handle(&value, asked.names, &walk.scope);
    if handle.is_some() {
        let named = nikaia_std::index::or(handle, || "".into());
        let ty = match match *nikaia_std::index::get(&walk.scope, &named) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => return };
        walk.slots.note(FIELDS, &key, ty, true, false);
        walk.slots.join(&slot(&walk.function, &named), &slot(FIELDS, &key));
    } else {
        let declared = declared_field_type(owner, &field_name, asked);
        if declared.is_some() && holds_shared(nikaia_std::index::or(declared.as_ref(), || &Ty::Unknown)) {
            walk.slots.note(FIELDS, &key, nikaia_std::index::or(declared, || Ty::Unknown), true, false);
            let source = slot_of(&value, asked, walk);
            if source.is_none() { origin_unseen(FIELDS, &key, &value, asked, walk); } else { walk.slots.join(nikaia_std::index::or(source.as_deref(), || ""), &slot(FIELDS, &key)); }
        }
    }
    sharing_expression(&value, asked, holes_of, ty_of, walk);
}

fn sharing_method(call: &Expr, asked: &Asked<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) {
    let (receiver, method, args, config) = match call {
        Expr::MethodCall { receiver, method, args, config } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; (receiver, asked.names.resolve(method).to_owned(), args, config) },
        Expr::SafeMethod { receiver, method, args, config } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; (receiver, asked.names.resolve(method).to_owned(), args, config) },
        _ => return,
    };
    if method == "get" && args.is_empty() { a_copy_out_of_the_lock(receiver, asked, walk); }
    if a_parallel_method(&method) || walks_in_parallel(receiver, asked.names, &walk.parallel) {
        let why = format!("a lambda handed to `{}` uses it, and that lambda runs on a thread the program asked for", method);
        for arg in args.iter() { for named in names_used_by(arg, asked) { a_crossing_reaches(&named, &why, None, asked, walk); } }
    }
    sharing_arguments(&SharingCall { callee: Some(method), is_method: true }, args, config, asked, holes_of, ty_of, walk);
    sharing_expression(receiver, asked, holes_of, ty_of, walk);
}

fn a_copy_out_of_the_lock(receiver: &Expr, asked: &Asked<'_>, walk: &mut SharingWalk) {
    let handle = match named_handle(receiver, asked.names, &walk.scope) { Some(__nikaia_value) => __nikaia_value, None => return };
    let ty = match *nikaia_std::index::get(&walk.scope, &handle) { Some(__nikaia_value) => __nikaia_value, None => return };
    let held = match held_that_does_not_copy(ty) { Some(__nikaia_value) => __nikaia_value, None => return };
    walk.slots.copies.push((slot(&walk.function, &handle), format!("`{}.get()` copies the whole `{}` out of the lock", handle, held)));
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct SharingCall {
    callee: Option<String>,
    is_method: bool,
}

fn sharing_arguments(called: &SharingCall, args: &[Expr], config: &[ConfigArg], asked: &Asked<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) {
    let described = parameters_of((called.callee).as_deref(), asked);
    for at in 0..args.len() as i64 {
        let arg = nikaia_std::index::get(&args, nikaia_std::index::at(at));
        let handle = named_handle(&arg, asked.names, &walk.scope);
        if handle.is_none() {
            an_argument_that_is_not_a_handle(called, (described).as_ref(), at, &arg, asked, walk);
            sharing_expression(&arg, asked, holes_of, ty_of, walk);
            continue;
        }
        a_handle_handed_on(called, (described).as_ref(), at, nikaia_std::index::or(handle.as_deref(), || ""), walk);
    }
    for setting in config.iter() {
        let why = format!("it is handed to `{}` as the option `{}`, and no contract says what happens to a `Shared` in an option", nikaia_std::index::or(match called.callee.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || "the callee".into()), asked.names.resolve(setting.name));
        for named in names_used_by(&setting.value, asked) { a_crossing_reaches(&named, &why, Some(Fallback::UncoveredArgument), asked, walk); }
        sharing_expression(&setting.value, asked, holes_of, ty_of, walk);
    }
}

fn an_argument_that_is_not_a_handle(called: &SharingCall, described: Option<&Described>, at: i64, arg: &Expr, asked: &Asked<'_>, walk: &mut SharingWalk) {
    if described.is_none() {
        let why = unseen((called.callee).as_deref());
        for named in names_used_by(arg, asked) { a_crossing_reaches(&named, &why, Some(unseen_kind(called)), asked, walk); }
        return;
    }
    let known = match described { Some(__nikaia_value) => __nikaia_value, None => return };
    if at >= known.params.len() as i64 { return; }
    let param = nikaia_std::index::get(&known.params, nikaia_std::index::at(at)).0.to_owned();
    if !by_value_shared(&nikaia_std::index::get(&known.params, nikaia_std::index::at(at)).1) { return; }
    let source = match slot_of(arg, asked, walk) { Some(__nikaia_value) => __nikaia_value, None => return };
    let (owner, named) = split_slot(&source);
    walk.slots.duplicates(&owner, &named, handed_on_to(&known.key, &param));
    walk.slots.join(&source, &slot(&known.key, &param));
}

fn a_handle_handed_on(called: &SharingCall, described: Option<&Described>, at: i64, handle: &str, walk: &mut SharingWalk) {
    let function = walk.function.to_owned();
    if described.is_none() {
        walk.slots.force(&function, handle, unseen((called.callee).as_deref()), Some(unseen_kind(called)));
        return;
    }
    let known = match described { Some(__nikaia_value) => __nikaia_value, None => return };
    if at >= known.params.len() as i64 {
        let callee = nikaia_std::index::or(match called.callee.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || "the callee".into());
        walk.slots.force(&function, handle, format!("`{}` takes it in a position no contract describes", callee), Some(Fallback::UncoveredArgument));
        return;
    }
    let param = nikaia_std::index::get(&known.params, nikaia_std::index::at(at)).0.to_owned();
    if by_value_shared(&nikaia_std::index::get(&known.params, nikaia_std::index::at(at)).1) { walk.slots.duplicates(&function, handle, handed_on_to(&known.key, &param)); }
    walk.slots.join(&slot(&function, handle), &slot(&known.key, &param));
}

fn unseen_kind(called: &SharingCall) -> Fallback {
    if called.is_method { return Fallback::UnseenMethod; }
    Fallback::UnseenCall
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Described {
    key: String,
    params: Vec<(String, Ty)>,
}

fn parameters_of(callee: Option<&str>, asked: &Asked<'_>) -> Option<Described> {
    let named = match callee { Some(__nikaia_value) => __nikaia_value, None => return None };
    let in_own = described_key(named, asked.own);
    if in_own.is_some() { return described_by(nikaia_std::index::or(in_own.as_deref(), || ""), asked.own); }
    let in_library = match described_key(named, asked.library) { Some(__nikaia_value) => __nikaia_value, None => return None };
    described_by(&in_library, asked.library)
}

fn described_key(callee: &str, ledger: &Ledger) -> Option<String> {
    if ledger.functions.contains_key(callee) { return Some(callee.to_owned()); }
    let suffix = format!("::{}", callee);
    for (one, _) in ledger.functions.iter() { if one.ends_with(&suffix) { return Some(one.to_owned()); } }
    None
}

fn described_by(key: &str, ledger: &Ledger) -> Option<Described> {
    let contract = match *nikaia_std::index::get(&ledger.functions, key) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return None };
    let mut params: Vec<(String, Ty)> = vec![];
    let mut first = true;
    for (name, ty) in signature.params.iter() {
        if !(first && name == "self") { params.push((name.to_owned(), ty.clone())); }
        first = false;
    }
    Some(Described { key: key.to_owned(), params })
}


// --- signature.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Translated {
    pub ty: Ty,
    pub kept: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Resulted {
    pub ty: Ty,
    pub fails: Option<String>,
}

pub fn translate(written: &str, crate_word: &str, parameters: &[String], types: &collections::BTreeSet<String>, mentioned: &mut collections::BTreeSet<String>) -> Translated {
    let text = written.trim();
    if text.starts_with("&mut ") { return Translated { ty: Ty::Unknown, kept: false }; }
    if text.starts_with("&") {
        let c: Vec<char> = nikaia_std::list::chars(text.chars());
        let rest = slice(&c, 1, c.len() as i64);
        let inner = translate(&rest, crate_word, parameters, types, mentioned);
        return Translated { ty: view_of(inner.ty), kept: false };
    }
    let optional = generic_of(text, "Option");
    if optional.is_some() {
        let inner = translate(nikaia_std::index::or(optional.as_deref(), || ""), crate_word, parameters, types, mentioned);
        return Translated { ty: Ty::Nullable(Box::new(inner.ty)), kept: inner.kept };
    }
    let listed = generic_of(text, "Vec");
    if listed.is_some() {
        let inner = translate(nikaia_std::index::or(listed.as_deref(), || ""), crate_word, parameters, types, mentioned);
        return Translated { ty: Ty::Named { name: String::from("Vec"), args: vec![inner.ty], view: false }, kept: true };
    }
    for parameter in parameters.iter() { if text == parameter { return Translated { ty: Ty::Var { name: text.to_owned(), view: false }, kept: true }; } }
    if is_plain(text) { return Translated { ty: Ty::Named { name: text.to_owned(), args: vec![], view: false }, kept: false }; }
    if text == "String" { return Translated { ty: Ty::Named { name: String::from("String"), args: vec![], view: false }, kept: true }; }
    if types.contains(text) {
        mentioned.insert(text.to_owned());
        return Translated { ty: Ty::Named { name: format!("{}::{}", crate_word, text), args: vec![], view: false }, kept: true };
    }
    Translated { ty: Ty::Unknown, kept: true }
}

pub fn result_of(written: &str, crate_word: &str, parameters: &[String], types: &collections::BTreeSet<String>, mentioned: &mut collections::BTreeSet<String>) -> Resulted {
    let resulted = generic_of(written, "Result");
    if resulted.is_none() {
        let plain = translate(written, crate_word, parameters, types, mentioned);
        return Resulted { ty: plain.ty, fails: None };
    }
    let parts = split_top_level(nikaia_std::index::or(resulted.as_deref(), || ""));
    let mut ok: String = String::from("");
    if !parts.is_empty() { ok = (*nikaia_std::index::get(&parts, 0)).to_owned(); }
    let fine = translate(&ok, crate_word, parameters, types, mentioned);
    let mut fails: String = String::from("?");
    if parts.len() > 1 {
        let error = (*nikaia_std::index::get(&parts, 1)).trim();
        if types.contains(error) { fails = format!("{}::{}", crate_word, error); }
    }
    Resulted { ty: fine.ty, fails: Some(fails) }
}

pub fn view_of(ty: Ty) -> Ty {
    match ty {
        Ty::Named { name, args, .. } => Ty::Named { name, args, view: true },
        Ty::Var { name, .. } => Ty::Var { name, view: true },
        _ => ty,
    }
}

pub fn sent_across(names: &[String], types: &[String], bounds: &str) -> Vec<String> {
    let sent = sends(bounds);
    let mut out: Vec<String> = vec![];
    for at in 0..names.len() as i64 {
        let ty = (*nikaia_std::index::get(&types, (at) as usize)).trim();
        let named = unreferenced(ty);
        let mut reached = bounds_send(ty);
        for one in sent.iter() { if *one == named { reached = true; } }
        if reached { out.push((*nikaia_std::index::get(&names, (at) as usize)).to_owned()); }
    }
    out
}

pub fn sends(bounds: &str) -> Vec<String> {
    let __keep_frame = nikaia_std::tether::Keep::new();
    let mut out: Vec<String> = vec![];
    for one in split_top_level(bounds) {
        let c: Vec<char> = nikaia_std::list::chars(one.chars());
        let colon = find(&c, 0, ':');
        if colon < 0 { continue; }
        let head = __keep_frame.put(slice(&c, 0, colon));
        let name = head.trim();
        let bound = slice(&c, colon + 1, c.len() as i64);
        if bounds_send(&bound) && !name.is_empty() && !name.starts_with("'") && !out.contains(&name.to_owned()) { out.push(name.to_owned()); }
    }
    out.sort();
    out
}

fn unreferenced(ty: &str) -> String {
    let c: Vec<char> = nikaia_std::list::chars(ty.chars());
    let mut from: i64 = 0;
    while from < c.len() as i64 && (*nikaia_std::index::get(&c, nikaia_std::index::at(from)) == '&' || *nikaia_std::index::get(&c, nikaia_std::index::at(from)) == ' ') { from += 1; }
    let rest = slice(&c, from, c.len() as i64);
    let trimmed = rest.trim();
    if trimmed.starts_with("mut ") {
        let t: Vec<char> = nikaia_std::list::chars(trimmed.chars());
        let after = slice(&t, 4, t.len() as i64);
        return after.to_owned();
    }
    trimmed.to_owned()
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct WrittenFn {
    pub names: Vec<String>,
    pub types: Vec<String>,
    pub result: String,
    pub pauses: bool,
    pub parameters: Vec<String>,
}

pub fn contract(written: &WrittenFn, crate_word: &str, types: &collections::BTreeSet<String>, mentioned: &mut collections::BTreeSet<String>) -> FnContract {
    let mut keeps: Vec<String> = vec![];
    let mut params: Vec<(String, Ty)> = vec![];
    for at in 0..written.names.len() as i64 {
        let translated = translate(nikaia_std::index::get(&written.types, (at) as usize), crate_word, &written.parameters, types, mentioned);
        if translated.kept { keeps.push((*nikaia_std::index::get(&written.names, (at) as usize)).to_owned()); }
        params.push(((*nikaia_std::index::get(&written.names, (at) as usize)).to_owned(), translated.ty));
    }
    let mut fails: Vec<String> = vec![];
    let mut answer: Option<Ty> = None;
    if !written.result.is_empty() {
        let resulted = result_of(&written.result, crate_word, &written.parameters, types, mentioned);
        if resulted.fails.is_some() { fails.push(nikaia_std::index::or(resulted.fails, || "?".into())); }
        answer = Some(resulted.ty);
    }
    let mut signature = Signature::empty();
    signature.params = params;
    signature.result = answer;
    let mut entry = FnContract::empty();
    entry.public = true;
    entry.sync_claim = if written.pauses { Sync::No } else { Sync::Asserted };
    entry.fails_with = fails;
    entry.keeps = keeps;
    entry.signature = Some(signature);
    entry
}


