pub const SEEN: &str = "Seen";

impl Ty {
    pub fn is_unknown(&self) -> bool { matches!(self, Ty::Unknown) }
    pub fn as_a_view(&self) -> Ty {
        match self {
            Ty::Named { name, args, view } => { let view = *view; viewed_name(name, args, view) },
            _ => self.clone(),
        }
    }
    pub fn is_seen(&self) -> bool {
        match self {
            Ty::Named { name, args, .. } => name == SEEN && args.len() == 1,
            Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); inner.is_seen() },
            _ => false,
        }
    }
    pub fn unseen(&self) -> Ty {
        match self {
            Ty::Named { name, args, .. } => { if name == SEEN && args.len() == 1 { return (*nikaia_std::index::get(&args, 0)).clone(); } },
            Ty::Nullable(inner) => {
                let inner = nikaia_std::boxed::open(inner);
                return Ty::Nullable(Box::new(inner.unseen()));
            },
            _ => { },
        }
        self.clone()
    }
    pub fn owned(&self) -> Ty {
        match self {
            Ty::Named { name, args, view } => { let view = *view; if view { Ty::Named { name: name.to_owned(), args: args.to_owned(), view: false } } else { self.clone() } },
            _ => self.clone(),
        }
    }
    pub fn is_a_view(&self) -> bool {
        match self {
            Ty::Named { view, .. } => { let view = *view; view },
            Ty::Var { view, .. } => { let view = *view; view },
            Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); inner.is_a_view() },
            Ty::Pointed { slice, mutable, .. } => { let mutable = *mutable; let slice = *slice; slice && !mutable },
            _ => false,
        }
    }
    pub fn fits(&self, expected: &Ty) -> bool {
        if self.is_unknown() || expected.is_unknown() { return true; }
        if self.is_seen() || expected.is_seen() { return self.unseen().fits(&expected.unseen()); }
        match self {
            Ty::Tuple(parts) => { if a_tuple(expected) { return tuple_fits(parts, expected); } },
            Ty::Count(n) => {
                let n = *n;
                if a_count(expected) { return count_fits(n, expected); }
            },
            Ty::Pointed { item, slice, mutable } => {
                let item = nikaia_std::boxed::open(item); let mutable = *mutable; let slice = *slice;
                if a_pointed(expected) { return pointed_fits(item, slice, mutable, expected); }
            },
            Ty::Named { name, args, view } => {
                let view = *view;
                if !view && name == ARRAY && args.len() == 2 && an_array_of_any_length(expected) { return array_fits(args, expected); }
            },
            _ => { },
        }
        match expected {
            Ty::Pointed { item, slice, .. } => {
                let item = nikaia_std::boxed::open(item); let slice = *slice;
                if slice { return lends_a_run_of(self, item); }
                return self.fits(item);
            },
            _ => { },
        }
        match self {
            Ty::Fn { params, result, is_sync, can_throw } => {
                let result = nikaia_std::boxed::open(result); let can_throw = *can_throw; let is_sync = *is_sync;
                if a_function_type(expected) { return function_fits(params, (result).as_ref(), is_sync, can_throw, expected); }
            },
            Ty::Seq { item, is_sync, pauses, can_throw, parallel, shape } => {
                let item = nikaia_std::boxed::open(item); let can_throw = *can_throw; let is_sync = *is_sync; let parallel = *parallel; let pauses = *pauses;
                if a_sequence_type(expected) { return sequence_fits(item, is_sync, pauses, can_throw, parallel, shape, expected); }
            },
            Ty::Var { .. } => { return true; },
            _ => { },
        }
        match expected {
            Ty::Var { .. } => { return true; },
            Ty::Nullable(wanted) => {
                let wanted = nikaia_std::boxed::open(wanted);
                return nullable_fits(self, wanted);
            },
            Ty::Named { name, args, view } => {
                let view = *view;
                return named_fits(self, name, args, view);
            },
            _ => { },
        }
        false
    }
    pub fn erase(&self, parameters: &collections::BTreeSet<String>) -> Ty {
        match self {
            Ty::Pointed { item, slice, mutable } => { let item = nikaia_std::boxed::open(item); let mutable = *mutable; let slice = *slice; Ty::Pointed { item: Box::new(item.erase(parameters)), slice, mutable } },
            Ty::Tuple(parts) => Ty::Tuple(erased_each(parts, parameters)),
            Ty::Fn { params, result, is_sync, can_throw } => { let result = nikaia_std::boxed::open(result); let can_throw = *can_throw; let is_sync = *is_sync; Ty::Fn { params: erased_each(params, parameters), result: Box::new(match result {
                Some(__nikaia_it) => Some(__nikaia_it.erase(parameters)),
                None => None,
            }), is_sync, can_throw } },
            Ty::Seq { item, is_sync, pauses, can_throw, parallel, shape } => { let item = nikaia_std::boxed::open(item); let can_throw = *can_throw; let is_sync = *is_sync; let parallel = *parallel; let pauses = *pauses; Ty::Seq { item: Box::new(item.erase(parameters)), is_sync, pauses, can_throw, parallel, shape: shape.clone() } },
            Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); Ty::Nullable(Box::new(inner.erase(parameters))) },
            Ty::Named { name, args, view } => { let view = *view; erased_name(name, args, view, parameters) },
            _ => self.clone(),
        }
    }
    pub fn parameterise(&self, parameters: &collections::BTreeSet<String>) -> Ty {
        match self {
            Ty::Pointed { item, slice, mutable } => { let item = nikaia_std::boxed::open(item); let mutable = *mutable; let slice = *slice; Ty::Pointed { item: Box::new(item.parameterise(parameters)), slice, mutable } },
            Ty::Tuple(parts) => Ty::Tuple(parameterised_each(parts, parameters)),
            Ty::Fn { params, result, is_sync, can_throw } => { let result = nikaia_std::boxed::open(result); let can_throw = *can_throw; let is_sync = *is_sync; Ty::Fn { params: parameterised_each(params, parameters), result: Box::new(match result {
                Some(__nikaia_it) => Some(__nikaia_it.parameterise(parameters)),
                None => None,
            }), is_sync, can_throw } },
            Ty::Seq { item, is_sync, pauses, can_throw, parallel, shape } => { let item = nikaia_std::boxed::open(item); let can_throw = *can_throw; let is_sync = *is_sync; let parallel = *parallel; let pauses = *pauses; Ty::Seq { item: Box::new(item.parameterise(parameters)), is_sync, pauses, can_throw, parallel, shape: shape.clone() } },
            Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); Ty::Nullable(Box::new(inner.parameterise(parameters))) },
            Ty::Named { name, args, view } => { let view = *view; parameterised_name(name, args, view, parameters) },
            _ => self.clone(),
        }
    }
}

impl Ty {
    fn fits_any(&self, wanted: Option<&Ty>) -> bool {
        nikaia_std::index::or(match wanted {
            Some(__nikaia_it) => Some(__nikaia_it.fitted_by(self)),
            None => None,
        }, || true)
    }
    fn fitted_by(&self, found: &Ty) -> bool { found.fits(self) }
    fn substituted_in(&self, bound: &collections::BTreeMap<String, Ty>) -> Ty { substitute(self, bound) }
    fn qualified_in(&self, module: &str, declared: &collections::BTreeSet<String>) -> Ty { qualify(self, module, declared) }
    fn renamed_by(&self, renames: &collections::BTreeMap<String, String>) -> Ty { renamed(self, renames) }
}

fn viewed_name(name: &str, args: &[Ty], view: bool) -> Ty {
    if view { return Ty::Named { name: name.to_owned(), args: args.to_owned(), view: true }; }
    if args.is_empty() && (name == TEXT || name.ends_with("::String")) { return Ty::Named { name: TEXT_VIEW.to_owned(), args: vec![], view: true }; }
    Ty::Named { name: name.to_owned(), args: args.to_owned(), view: true }
}

fn a_tuple(ty: &Ty) -> bool { matches!(ty, Ty::Tuple(_)) }

fn a_count(ty: &Ty) -> bool { matches!(ty, Ty::Count(_)) }

fn a_pointed(ty: &Ty) -> bool { matches!(ty, Ty::Pointed { .. }) }

fn a_function_type(ty: &Ty) -> bool { matches!(ty, Ty::Fn { .. }) }

fn a_sequence_type(ty: &Ty) -> bool { matches!(ty, Ty::Seq { .. }) }

fn all_fit(found: &[Ty], wanted: &[Ty]) -> bool {
    if (found.len() as i64) != wanted.len() as i64 { return false; }
    for at in 0..found.len() as i64 { if !(*nikaia_std::index::get(&found, (at) as usize)).fits(nikaia_std::index::get(&wanted, (at) as usize)) { return false; } }
    true
}

fn tuple_fits(parts: &[Ty], expected: &Ty) -> bool {
    match expected {
        Ty::Tuple(wanted) => all_fit(parts, wanted),
        _ => false,
    }
}

fn count_fits(n: i64, expected: &Ty) -> bool {
    match expected {
        Ty::Count(wanted) => { let wanted = *wanted; n == wanted },
        _ => false,
    }
}

fn pointed_fits(found: &Ty, run: bool, writes: bool, expected: &Ty) -> bool {
    match expected {
        Ty::Pointed { item, slice, mutable } => { let item = nikaia_std::boxed::open(item); let mutable = *mutable; let slice = *slice; found.fits(item) && run == slice && writes == mutable },
        _ => false,
    }
}

fn an_array_of_any_length(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; !view && name == ARRAY && args.len() == 1 },
        _ => false,
    }
}

fn array_fits(given: &[Ty], expected: &Ty) -> bool {
    match expected {
        Ty::Named { args, .. } => (*nikaia_std::index::get(&given, 0)).fits(nikaia_std::index::get(&args, 0)),
        _ => false,
    }
}

fn lends_a_run_of(found: &Ty, item: &Ty) -> bool {
    match found {
        Ty::Unknown => true,
        Ty::Named { name, args, .. } => a_run_named(name, args, item),
        _ => false,
    }
}

fn a_run_named(name: &str, args: &[Ty], item: &Ty) -> bool {
    if (name == "Vec" || name == "List") && args.len() == 1 { return (*nikaia_std::index::get(&args, 0)).fits(item); }
    if name == ARRAY && (args.len() == 1 || args.len() == 2) { return (*nikaia_std::index::get(&args, 0)).fits(item); }
    if (name == "String" || name == "str") && args.is_empty() {
        return match item {
            Ty::Named { name, .. } => name == "u8",
            _ => false,
        };
    }
    false
}

fn function_fits(found: &[Ty], found_result: Option<&Ty>, never_pauses: bool, fails: bool, expected: &Ty) -> bool {
    match expected {
        Ty::Fn { params, result, is_sync, can_throw } => { let result = nikaia_std::boxed::open(result); let can_throw = *can_throw; let is_sync = *is_sync; all_fit(found, params) && results_fit(found_result, (result).as_ref()) && (never_pauses || !is_sync) && (!fails || can_throw) },
        _ => false,
    }
}

fn results_fit(found: Option<&Ty>, wanted: Option<&Ty>) -> bool {
    if found.is_none() || wanted.is_none() { return true; }
    nikaia_std::index::or(match found {
        Some(__nikaia_it) => Some(__nikaia_it.fits_any(wanted)),
        None => None,
    }, || true)
}

fn sequence_fits(found: &Ty, never_pauses: bool, may_pause: bool, fails: bool, at_once: bool, has: &Shape, expected: &Ty) -> bool {
    match expected {
        Ty::Seq { item, is_sync, pauses, can_throw, parallel, shape } => { let item = nikaia_std::boxed::open(item); let can_throw = *can_throw; let is_sync = *is_sync; let parallel = *parallel; let pauses = *pauses; found.fits(item) && (never_pauses || !is_sync) && (!may_pause || pauses) && (!fails || can_throw) && (at_once || !parallel) && has.meets(shape) },
        _ => false,
    }
}

fn nullable_fits(found: &Ty, wanted: &Ty) -> bool {
    match found {
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); inner.fits(wanted) },
        _ => found.fits(wanted),
    }
}

fn named_fits(found: &Ty, wanted: &str, wanted_args: &[Ty], wanted_view: bool) -> bool {
    match found {
        Ty::Named { name, args, view } => { let view = *view; name == wanted && view == wanted_view && all_fit(args, wanted_args) },
        _ => false,
    }
}

fn erased_each(parts: &[Ty], parameters: &collections::BTreeSet<String>) -> Vec<Ty> {
    let mut out: Vec<Ty> = vec![];
    for part in parts.iter() { out.push(part.erase(parameters)); }
    out
}

fn erased_name(name: &str, args: &[Ty], view: bool, parameters: &collections::BTreeSet<String>) -> Ty {
    if args.is_empty() && parameters.contains(name) { return Ty::Unknown; }
    Ty::Named { name: name.to_owned(), args: erased_each(args, parameters), view }
}

fn parameterised_each(parts: &[Ty], parameters: &collections::BTreeSet<String>) -> Vec<Ty> {
    let mut out: Vec<Ty> = vec![];
    for part in parts.iter() { out.push(part.parameterise(parameters)); }
    out
}

fn parameterised_name(name: &str, args: &[Ty], view: bool, parameters: &collections::BTreeSet<String>) -> Ty {
    if args.is_empty() && parameters.contains(name) { return Ty::Var { name: name.to_owned(), view }; }
    Ty::Named { name: name.to_owned(), args: parameterised_each(args, parameters), view }
}

pub fn bind(pattern: &Ty, actual: &Ty, out: &mut collections::BTreeMap<String, Ty>) {
    match pattern {
        Ty::Var { name, .. } => { if !out.contains_key(name) { out.insert(name.to_owned(), actual.clone()); } },
        Ty::Named { name, args, .. } => { bind_named(name, args, actual, out); },
        Ty::Seq { item, .. } => {
            let item = nikaia_std::boxed::open(item);
            bind_item(item, actual, out);
        },
        Ty::Fn { params, result, .. } => {
            let result = nikaia_std::boxed::open(result);
            bind_code(params, (result).as_ref(), actual, out);
        },
        _ => { },
    }
}

fn bind_named(pattern_name: &str, pattern_args: &[Ty], actual: &Ty, out: &mut collections::BTreeMap<String, Ty>) {
    match actual {
        Ty::Named { name, args, .. } => { bind_arguments(pattern_name, pattern_args, name, args, out); },
        _ => { },
    }
}

fn bind_arguments(pattern_name: &str, pattern_args: &[Ty], name: &str, args: &[Ty], out: &mut collections::BTreeMap<String, Ty>) {
    if name != pattern_name || (args.len() as i64) != pattern_args.len() as i64 { return; }
    for at in 0..args.len() as i64 { bind(nikaia_std::index::get(&pattern_args, (at) as usize), nikaia_std::index::get(&args, (at) as usize), out); }
}

fn bind_item(pattern: &Ty, actual: &Ty, out: &mut collections::BTreeMap<String, Ty>) {
    match actual {
        Ty::Seq { item, .. } => {
            let item = nikaia_std::boxed::open(item);
            bind(pattern, item, out);
        },
        _ => { },
    }
}

fn bind_code(pattern_params: &[Ty], pattern_result: Option<&Ty>, actual: &Ty, out: &mut collections::BTreeMap<String, Ty>) {
    match actual {
        Ty::Fn { params, result, .. } => {
            let result = nikaia_std::boxed::open(result);
            let shorter = if (params.len() as i64) < pattern_params.len() as i64 { params.len() as i64 } else { pattern_params.len() as i64 };
            for at in 0..shorter { bind(nikaia_std::index::get(&pattern_params, (at) as usize), nikaia_std::index::get(&params, (at) as usize), out); }
            if pattern_result.is_some() && result.is_some() {
                let pattern = nikaia_std::index::or(match pattern_result {
                    Some(__nikaia_it) => Some(__nikaia_it.to_owned()),
                    None => None,
                }, || Ty::Unknown);
                let bound_from = nikaia_std::index::or(match result {
                    Some(__nikaia_it) => Some(__nikaia_it.to_owned()),
                    None => None,
                }, || Ty::Unknown);
                bind(&pattern, &bound_from, out);
            }
        },
        _ => { },
    }
}

pub fn substitute(ty: &Ty, bound: &collections::BTreeMap<String, Ty>) -> Ty {
    match ty {
        Ty::Var { name, view } => { let view = *view; substituted(name, view, bound) },
        Ty::Named { name, args, view } => { let view = *view; Ty::Named { name: name.to_owned(), args: substituted_each(args, bound), view } },
        Ty::Tuple(parts) => Ty::Tuple(substituted_each(parts, bound)),
        Ty::Pointed { item, slice, mutable } => { let item = nikaia_std::boxed::open(item); let mutable = *mutable; let slice = *slice; Ty::Pointed { item: Box::new(substitute(item, bound)), slice, mutable } },
        Ty::Fn { params, result, is_sync, can_throw } => { let result = nikaia_std::boxed::open(result); let can_throw = *can_throw; let is_sync = *is_sync; Ty::Fn { params: substituted_each(params, bound), result: Box::new(substituted_result((result).as_ref(), bound)), is_sync, can_throw } },
        Ty::Seq { item, is_sync, pauses, can_throw, parallel, shape } => { let item = nikaia_std::boxed::open(item); let can_throw = *can_throw; let is_sync = *is_sync; let parallel = *parallel; let pauses = *pauses; Ty::Seq { item: Box::new(substitute(item, bound)), is_sync, pauses, can_throw, parallel, shape: shape.clone() } },
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); Ty::Nullable(Box::new(substitute(inner, bound))) },
        _ => ty.clone(),
    }
}

fn substituted(name: &str, view: bool, bound: &collections::BTreeMap<String, Ty>) -> Ty {
    if !bound.contains_key(name) { return Ty::Unknown; }
    let found = nikaia_std::index::or(match *nikaia_std::index::get(&bound, name) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || Ty::Unknown);
    if view {
        match found {
            Ty::Named { ref name, ref args, .. } => { return Ty::Named { name: name.to_owned(), args: args.to_owned(), view: true }; },
            _ => { },
        }
    }
    found.clone()
}

fn substituted_each(parts: &[Ty], bound: &collections::BTreeMap<String, Ty>) -> Vec<Ty> {
    let mut out: Vec<Ty> = vec![];
    for part in parts.iter() { out.push(substitute(part, bound)); }
    out
}

fn substituted_result(result: Option<&Ty>, bound: &collections::BTreeMap<String, Ty>) -> Option<Ty> {
    match result {
        Some(__nikaia_it) => Some(__nikaia_it.substituted_in(bound)),
        None => None,
    }
}

pub fn qualify(ty: &Ty, module: &str, declared: &collections::BTreeSet<String>) -> Ty {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; Ty::Named { name: qualified_name(name, module, declared), args: qualified_each(args, module, declared), view } },
        Ty::Tuple(parts) => Ty::Tuple(qualified_each(parts, module, declared)),
        Ty::Fn { params, result, is_sync, can_throw } => { let result = nikaia_std::boxed::open(result); let can_throw = *can_throw; let is_sync = *is_sync; Ty::Fn { params: qualified_each(params, module, declared), result: Box::new(qualified_result((result).as_ref(), module, declared)), is_sync, can_throw } },
        _ => ty.clone(),
    }
}

fn qualified_name(name: &str, module: &str, declared: &collections::BTreeSet<String>) -> String {
    if declared.contains(name) { return format!("{}::{}", module, name); }
    name.to_owned()
}

fn qualified_each(parts: &[Ty], module: &str, declared: &collections::BTreeSet<String>) -> Vec<Ty> {
    let mut out: Vec<Ty> = vec![];
    for part in parts.iter() { out.push(qualify(part, module, declared)); }
    out
}

fn qualified_result(result: Option<&Ty>, module: &str, declared: &collections::BTreeSet<String>) -> Option<Ty> {
    match result {
        Some(__nikaia_it) => Some(__nikaia_it.qualified_in(module, declared)),
        None => None,
    }
}

pub fn renamed(ty: &Ty, renames: &collections::BTreeMap<String, String>) -> Ty {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; Ty::Named { name: renamed_name(name, renames), args: renamed_each(args, renames), view } },
        Ty::Tuple(parts) => Ty::Tuple(renamed_each(parts, renames)),
        Ty::Fn { params, result, is_sync, can_throw } => { let result = nikaia_std::boxed::open(result); let can_throw = *can_throw; let is_sync = *is_sync; Ty::Fn { params: renamed_each(params, renames), result: Box::new(renamed_result((result).as_ref(), renames)), is_sync, can_throw } },
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); Ty::Nullable(Box::new(renamed(inner, renames))) },
        _ => ty.clone(),
    }
}

fn renamed_name(name: &str, renames: &collections::BTreeMap<String, String>) -> String {
    if name.starts_with("&") {
        let rest = cut(name, 1, 0);
        let path = renamed_path(&rest, renames);
        return format!("&{}", path);
    }
    renamed_path(name, renames)
}

fn renamed_path(name: &str, renames: &collections::BTreeMap<String, String>) -> String {
    let c: Vec<char> = nikaia_std::list::chars(name.chars());
    for at in 0..c.len() as i64 {
        if at + 1 < c.len() as i64 && *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == ':' && *nikaia_std::index::get(&c, nikaia_std::index::at(at + 1)) == ':' {
            let package = between(&c, 0, at);
            if renames.contains_key(&package) {
                let ours = nikaia_std::index::or(*nikaia_std::index::get(&renames, &package), || "");
                let rest = between(&c, at, c.len() as i64);
                return format!("{}{}", ours, rest);
            }
            return name.to_owned();
        }
    }
    name.to_owned()
}

fn renamed_each(parts: &[Ty], renames: &collections::BTreeMap<String, String>) -> Vec<Ty> {
    let mut out: Vec<Ty> = vec![];
    for part in parts.iter() { out.push(renamed(part, renames)); }
    out
}

fn renamed_result(result: Option<&Ty>, renames: &collections::BTreeMap<String, String>) -> Option<Ty> {
    match result {
        Some(__nikaia_it) => Some(__nikaia_it.renamed_by(renames)),
        None => None,
    }
}


// --- types.nika ---

const SHAPE_BOUNDS: [&str; 2] = ["Struct", "Enum"];

const BUILT_IN: [&str; 26] = ["i8", "i16", "i32", "i64", "i128", "isize", "u8", "u16", "u32", "u64", "u128", "usize", "f32", "f64", "bool", "char", "String", "str", "Self", "Vec", "Shared", "SharedMut", "Locked", "TaskHandle", "Array", "Bytes"];

const STD_MODULES: [&str; 7] = ["cli", "collections", "channel", "foreign", "fs", "io", "time"];

pub fn types_checked(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>], own: &Ledger, library: &Ledger, declared: &collections::BTreeSet<String>, impl_parameters: &[Vec<String>]) -> Vec<Finding> {
    let mut found: Vec<Finding> = vec![];
    declared_once_in(names, items, &mut found);
    let known = known_names(own, library, declared);
    let traits = known_traits(names, items, own, library);
    for k in 0..items.len() as i64 {
        let mut here = known.to_owned();
        for parameter in generic_names(names, &nikaia_std::index::get(&items, (k) as usize).node) { here.insert(parameter); }
        for parameter in (*nikaia_std::index::get(&impl_parameters, (k) as usize)).iter() { here.insert(parameter.to_owned()); }
        bounds_of(names, &nikaia_std::index::get(&items, (k) as usize).node, &traits, &nikaia_std::index::get(&items, (k) as usize).span, &mut found);
        item_types(names, &nikaia_std::index::get(&items, (k) as usize).node, &here, &nikaia_std::index::get(&items, (k) as usize).span, &mut found);
        inherent_at_home(names, &nikaia_std::index::get(&items, (k) as usize).node, library, declared, &nikaia_std::index::get(&items, (k) as usize).span, &mut found);
    }
    found
}

fn inherent_at_home(names: &winnow_grammar::InternerContext, item: &Item, library: &Ledger, declared: &collections::BTreeSet<String>, span: &Span, out: &mut Vec<Finding>) {
    let target = match item {
        Item::Impl { trait_name, target, .. } => { let trait_name = *trait_name; if trait_name.is_none() { names.resolve(target.name).to_owned() } else { return; } },
        _ => return,
    };
    if declared.contains(&target) || target == "Self" { return; }
    let foreign = target.contains("::") || nikaia_std::list::contains(&BUILT_IN, &target) || library.types.contains_key(&target);
    if !foreign { return; }
    out.push(refusal("NK1209", span.clone(), format!("You can't add methods to `{}` with `impl {}`: your program doesn't declare it.", target, target), vec![String::from("A type's own methods belong to the code that declares the type, so an `impl` without a trait works only on your own `struct` or `enum`.")], format!("Declare a trait and implement it for the type: `trait Doubled {{ fn doubled(self) -> ... }}` and `impl Doubled for {} {{ ... }}`.", target)));
}

fn known_traits(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>], own: &Ledger, library: &Ledger) -> collections::BTreeSet<String> {
    let mut known: collections::BTreeSet<String> = collections::BTreeSet::new();
    for shape in SHAPE_BOUNDS.iter() {
        let shape = *shape;
        known.insert(shape.to_owned());
    }
    for (key, _) in own.traits.iter() { with_its_last_segment(key, &mut known); }
    for (key, _) in library.traits.iter() { with_its_last_segment(key, &mut known); }
    for item in items.iter() {
        match &item.node {
            Item::Trait { name, .. } => {
                let name = *name;
                known.insert(names.resolve(name).to_owned());
            },
            _ => { },
        }
    }
    known
}

fn with_its_last_segment(key: &str, known: &mut collections::BTreeSet<String>) {
    known.insert(key.to_owned());
    let c: Vec<char> = nikaia_std::list::chars(key.chars());
    let mut last: i64 = -1;
    for at in 0..c.len() as i64 { if ((at + 1) as usize) < c.len() && *nikaia_std::index::get(&c, (at) as usize) == ':' && *nikaia_std::index::get(&c, (at + 1) as usize) == ':' { last = at; } }
    if last >= 0 { known.insert(slice(&c, last + 2, c.len() as i64)); }
}

fn known_names(own: &Ledger, library: &Ledger, declared: &collections::BTreeSet<String>) -> collections::BTreeSet<String> {
    let mut known: collections::BTreeSet<String> = collections::BTreeSet::new();
    for name in BUILT_IN.iter() {
        let name = *name;
        known.insert(name.to_owned());
    }
    for (key, _) in library.types.iter() { known.insert(key.to_owned()); }
    for (key, _) in own.types.iter() { with_its_last_segment(key, &mut known); }
    for name in declared.iter() { known.insert(name.to_owned()); }
    known
}

fn generic_names(names: &winnow_grammar::InternerContext, item: &Item) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    match item {
        Item::Fn { generics, .. } => { for parameter in generics.iter() { out.push(names.resolve(parameter.name).to_owned()); } },
        Item::Struct { generics, .. } => { for parameter in generics.iter() { out.push(names.resolve(parameter.name).to_owned()); } },
        _ => { },
    }
    out
}

fn bounds_of(names: &winnow_grammar::InternerContext, item: &Item, traits: &collections::BTreeSet<String>, span: &Span, out: &mut Vec<Finding>) {
    match item {
        Item::Fn { generics, .. } => bounds_in(names, generics, traits, span, out),
        Item::Struct { generics, .. } => bounds_in(names, generics, traits, span, out),
        _ => { },
    }
}

fn bounds_in(names: &winnow_grammar::InternerContext, generics: &[GenericParam], traits: &collections::BTreeSet<String>, span: &Span, out: &mut Vec<Finding>) {
    for parameter in generics.iter() {
        for bound in parameter.bounds.iter() {
            let name = names.resolve(bound.to_owned()).to_owned();
            if !name.contains("::") && !traits.contains(&name) { out.push(refusal("NK1135", span.clone(), format!("There's no trait called `{}`.", name), vec![String::from("A bound names a trait the caller's type has to implement, and no trait by this name is declared.")], format!("Declare `{}` with `trait`, or remove the bound. (Without a bound, the value can only be moved and passed on.)", name))); }
        }
    }
}

fn declared_once_in(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>], out: &mut Vec<Finding>) {
    let mut seen: collections::BTreeMap<String, String> = collections::BTreeMap::new();
    for item in items.iter() {
        let kind = kind_declared(&item.node);
        if kind.is_empty() { continue; }
        let name = name_declared(names, &item.node);
        if name.is_empty() { continue; }
        let earlier: Option<String> = match *nikaia_std::index::get(&seen, &name) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        };
        if earlier.is_none() {
            seen.insert(name, kind);
            continue;
        }
        let first = match earlier { Some(__nikaia_value) => __nikaia_value, None => continue };
        let kinds = if first == kind { format!("both times as a `{}`", first) } else { format!("once as a `{}` and once as a `{}`", first, kind) };
        out.push(refusal("NK1148", item.span.clone(), format!("`{}` is declared twice in this file, {}.", name, kinds), vec![String::from("A name means one thing, so there's never a question of which declaration wins. All files of a package share their names for the same reason.")], format!("Rename one of the two. (A `struct`'s name is already its constructor, so `{}` can't also be a function.)", name)));
    }
}

fn kind_declared(item: &Item) -> String {
    match item {
        Item::Fn { name, .. } => { let name = *name; if name.is_some() { String::from("fn") } else { String::from("") } },
        Item::Struct { .. } => String::from("struct"),
        Item::Enum { .. } => String::from("enum"),
        Item::Trait { .. } => String::from("trait"),
        Item::Grammar(_) => String::from("grammar"),
        _ => String::from(""),
    }
}

fn name_declared(names: &winnow_grammar::InternerContext, item: &Item) -> String {
    match item {
        Item::Fn { name, .. } => { let name = *name; a_symbols_text(names, name) },
        Item::Struct { name, .. } => { let name = *name; names.resolve(name).to_owned() },
        Item::Enum { name, .. } => { let name = *name; names.resolve(name).to_owned() },
        Item::Trait { name, .. } => { let name = *name; names.resolve(name).to_owned() },
        Item::Grammar(def) => names.resolve(def.name).to_owned(),
        _ => String::from(""),
    }
}

fn a_symbols_text(names: &winnow_grammar::InternerContext, name: Option<winnow_grammar::Symbol>) -> String {
    let symbol = match name { Some(__nikaia_value) => __nikaia_value, None => return String::from("") };
    names.resolve(symbol).to_owned()
}

fn item_types(names: &winnow_grammar::InternerContext, item: &Item, known: &collections::BTreeSet<String>, span: &Span, out: &mut Vec<Finding>) {
    match item {
        Item::Fn { args, ret_type, body, .. } => {
            for arg in args.iter() { written_at(names, &arg.ty, known, true, span, out); }
            maybe_written(names, (ret_type).as_ref(), known, span, out);
            block_types(names, body, known, out);
        },
        Item::Struct { fields, .. } => { for field in fields.iter() { written_at(names, &field.ty, known, false, span, out); } },
        Item::Enum { variants, .. } => {
            for variant in variants.iter() {
                match &variant.fields {
                    VariantFields::Unit => { },
                    VariantFields::Tuple(parts) => { for ty in parts.iter() { written_at(names, ty, known, false, span, out); } },
                    VariantFields::Named(fields) => { for field in fields.iter() { written_at(names, &field.ty, known, false, span, out); } },
                }
            }
        },
        Item::Extern { declarations, .. } => {
            for declaration in declarations.iter() {
                for arg in declaration.node.args.iter() { written_foreign(names, &arg.ty, known, true, &declaration.span, out); }
                maybe_written_foreign(names, (declaration.node.ret_type).as_ref(), known, &declaration.span, out);
            }
        },
        Item::Trait { methods, .. } => {
            for method in methods.iter() {
                let mut here = known.to_owned();
                for parameter in method.node.generics.iter() { here.insert(names.resolve(parameter.name).to_owned()); }
                for arg in method.node.args.iter() { written_at(names, &arg.ty, &here, true, &method.span, out); }
                maybe_written(names, (method.node.ret_type).as_ref(), &here, &method.span, out);
            }
        },
        Item::Impl { methods, .. } => {
            for method in methods.iter() {
                let mut here = known.to_owned();
                for parameter in generic_names(names, &method.node) { here.insert(parameter); }
                item_types(names, &method.node, &here, &method.span, out);
            }
        },
        _ => { },
    }
}

fn maybe_written(names: &winnow_grammar::InternerContext, ty: Option<&Type>, known: &collections::BTreeSet<String>, span: &Span, out: &mut Vec<Finding>) { written_at(names, match ty { Some(__nikaia_value) => __nikaia_value, None => return }, known, false, span, out); }

fn maybe_written_foreign(names: &winnow_grammar::InternerContext, ty: Option<&Type>, known: &collections::BTreeSet<String>, span: &Span, out: &mut Vec<Finding>) { written_foreign(names, match ty { Some(__nikaia_value) => __nikaia_value, None => return }, known, false, span, out); }

fn block_types(names: &winnow_grammar::InternerContext, block: &Block, known: &collections::BTreeSet<String>, out: &mut Vec<Finding>) {
    for stmt in block.stmts.iter() {
        match &stmt.node {
            Stmt::Let { ty, value, .. } => {
                maybe_written(names, (ty).as_ref(), known, &stmt.span, out);
                blocks_types(names, value, known, out);
            },
            Stmt::Comptime { value, .. } => blocks_types(names, value, known, out),
            Stmt::Expr(value) => blocks_types(names, value, known, out),
            Stmt::Return(value) => blocks_types(names, match value { Some(__nikaia_value) => __nikaia_value, None => continue }, known, out),
            Stmt::Assign { target, value, .. } => {
                blocks_types(names, target, known, out);
                blocks_types(names, value, known, out);
            },
            Stmt::For { body, .. } => block_types(names, body, known, out),
            Stmt::While { body, .. } => block_types(names, body, known, out),
            _ => { },
        }
    }
}

fn blocks_types(names: &winnow_grammar::InternerContext, expr: &Expr, known: &collections::BTreeSet<String>, out: &mut Vec<Finding>) {
    match expr {
        Expr::Block(block) => block_types(names, block, known, out),
        Expr::Unsafe(block) => block_types(names, block, known, out),
        Expr::Overlap(block) => block_types(names, block, known, out),
        Expr::Closure { body, .. } => block_types(names, body, known, out),
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            blocks_types(names, func, known, out);
            for arg in args.iter() { blocks_types(names, arg, known, out); }
            for setting in config.iter() { blocks_types(names, &setting.value, known, out); }
        },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            blocks_types(names, receiver, known, out);
            for arg in args.iter() { blocks_types(names, arg, known, out); }
            for setting in config.iter() { blocks_types(names, &setting.value, known, out); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            blocks_types(names, receiver, known, out);
            for arg in args.iter() { blocks_types(names, arg, known, out); }
            for setting in config.iter() { blocks_types(names, &setting.value, known, out); }
        },
        Expr::If { then_branch, else_branch, .. } => {
            block_types(names, then_branch, known, out);
            block_types(names, match else_branch { Some(__nikaia_value) => __nikaia_value, None => return }, known, out);
        },
        Expr::TryCatch { expr, handler } => {
            let expr = nikaia_std::boxed::open(expr);
            blocks_types(names, expr, known, out);
            block_types(names, handler, known, out);
        },
        Expr::Match { arms, .. } => { for arm in arms.iter() { blocks_types(names, &arm.body, known, out); } },
        Expr::Select(arms) => { for arm in arms.iter() { block_types(names, &arm.body, known, out); } },
        _ => { },
    }
}

fn written_foreign(names: &winnow_grammar::InternerContext, ty: &Type, known: &collections::BTreeSet<String>, a_parameter: bool, span: &Span, out: &mut Vec<Finding>) {
    if ty.is_slice && !ty.generics.is_empty() {
        written_at(names, nikaia_std::index::get(&ty.generics, 0), known, false, span, out);
        return;
    }
    written_at_the_boundary(names, ty, known, a_parameter, true, span, out);
}

fn written_at(names: &winnow_grammar::InternerContext, ty: &Type, known: &collections::BTreeSet<String>, a_parameter: bool, span: &Span, out: &mut Vec<Finding>) { written_at_the_boundary(names, ty, known, a_parameter, false, span, out); }

fn written_at_the_boundary(names: &winnow_grammar::InternerContext, ty: &Type, known: &collections::BTreeSet<String>, a_parameter: bool, at_c: bool, span: &Span, out: &mut Vec<Finding>) {
    if ty.is_mut && !at_c {
        out.push(refusal("NK1158", span.clone(), String::from("`ref mut` can only be used when talking to C."), vec![String::from("`ref mut` is only for `extern \"C\"` declarations. Everywhere else, Nikaia has its own way to say it.")], String::from("Put `mut` in front of the name instead: `fn fill(mut out: Vec[i64])`.")));
        return;
    }
    let name = names.resolve(ty.name).to_owned();
    if !a_parameter && !ty.is_view && !ty.is_slice && ty.count.is_none() && ty.generics.len() == 1 && name == "Array" {
        let element = names.resolve(nikaia_std::index::get(&ty.generics, 0).name).to_owned();
        out.push(refusal("NK1182", span.clone(), format!("`Array[{}]` needs a length here.", element), vec![format!("`Array[{}]` without a length only works for a parameter, where each call supplies the length. A field or a result has no call to take it from.", element)], format!("Use `Vec[{}]` for a list that can grow, `ref Array[{}]` to look at elements something else keeps, or `Array[{}, N]` to write the length down.", element, element, element)));
        return;
    }
    if ty.count.is_some() { return; }
    if ty.is_slice {
        for argument in ty.generics.iter() { written_at(names, argument, known, false, span, out); }
        return;
    }
    if !ty.is_tuple && (*ty.code).is_none() && !known.contains(&name) && !name.contains("::") { out.push(nothing_declares(&name, known, span)); }
    for argument in ty.generics.iter() { written_at(names, argument, known, false, span, out); }
    maybe_written(names, (*ty.code).as_ref().and_then(|__nikaia_it| (*__nikaia_it.result).as_ref()), known, span, out);
}

fn nothing_declares(name: &str, known: &collections::BTreeSet<String>, span: &Span) -> Finding {
    let module = std_module_of(name, known);
    if !module.is_empty() { return refusal("NK1135", span.clone(), format!("`{}` needs its module in front of it.", name), vec![format!("Its full name is `{}::{}`: a type from a module is written with the module's name.", module, name)], format!("Write `use std::{}` at the top of the file, and `{}::{}` here.", module, module, name)); }
    refusal("NK1135", span.clone(), format!("There's no type called `{}`.", name), vec![String::from("A type is either built in, declared in your program with `struct` or `enum`, provided by `std`, or a type parameter.")], format!("Check the spelling, or declare `{}` with `struct` or `enum`.", name))
}

pub fn nobody_knows(name: &str, own: &Ledger, library: &Ledger) -> bool {
    if nikaia_std::list::contains(&BUILT_IN, &name) || own.types.contains_key(name) || library.types.contains_key(name) { return false; }
    let c: Vec<char> = nikaia_std::list::chars(name.chars());
    let mut last: i64 = -1;
    for at in 0..c.len() as i64 { if ((at + 1) as usize) < c.len() && *nikaia_std::index::get(&c, (at) as usize) == ':' && *nikaia_std::index::get(&c, (at + 1) as usize) == ':' { last = at; } }
    let wanted = if last < 0 { format!("::{}", name) } else { format!("{}::", slice(&c, 0, last)) };
    for ledger in [own, library] {
        for (key, _) in ledger.types.iter() { if last < 0 && key.ends_with(&wanted) || last >= 0 && key.starts_with(&wanted) { return false; } }
        for (key, _) in ledger.functions.iter() { if last >= 0 && key.starts_with(&wanted) { return false; } }
    }
    true
}

fn std_module_of(name: &str, known: &collections::BTreeSet<String>) -> String {
    let ending = format!("::{}", name);
    for key in known.iter() {
        if key.ends_with(&ending) {
            let c: Vec<char> = nikaia_std::list::chars(key.chars());
            let at = find_text(&c, 0, "::");
            let module = slice(&c, 0, at);
            for one in STD_MODULES.iter() {
                let one = *one;
                if module == one { return module; }
            }
            return String::from("");
        }
    }
    String::from("")
}


// --- views.nika ---

#[derive(Debug, Clone, PartialEq)]
pub struct Stored {
    pub span: Span,
    pub param: String,
    pub ty: String,
    pub function: String,
    pub subject: Option<String>,
    pub into: Destination,
    pub carried: bool,
    pub method: u32,
    pub symbol: winnow_grammar::Symbol,
    pub carrier: Option<winnow_grammar::Symbol>,
}

#[derive(Debug, Clone, PartialEq)]
pub enum Destination {
    Field { owner: String, field: String, ty: String },
    Subject { owner: String },
    Returned { ty: String },
    Task,
    ParamField { param: winnow_grammar::Symbol, owner: String, field: String, ty: String },
}

#[derive(Debug, Clone)]
pub struct Asked<'a> {
    pub names: &'a winnow_grammar::InternerContext,
    pub own: &'a Ledger,
    pub library: &'a Ledger,
}

#[derive(Debug, Clone, PartialEq)]
struct Unit {
    borrowing: collections::BTreeSet<String>,
    fields: collections::BTreeMap<String, Vec<(String, Type)>>,
}

#[derive(Debug, Clone, PartialEq)]
struct Here {
    subject: Option<Type>,
    subject_fields: Vec<(String, Type)>,
    declared: Vec<(winnow_grammar::Symbol, Type)>,
    result: Option<Type>,
    ours: Option<String>,
    carriers: collections::BTreeSet<String>,
    found: Vec<(Span, Destination)>,
}

#[derive(Debug, Clone, PartialEq)]
enum Root {
    Subject,
    SubjectField(String),
    Param(winnow_grammar::Symbol),
    ParamField(winnow_grammar::Symbol, String),
    Elsewhere,
}

pub fn views_stored(asked: &Asked<'_>, items: &[Spanned<Item>], own_buffer: &impl Fn(&Expr) -> bool) -> Vec<Stored> {
    let unit = Unit { borrowing: borrowing_types(asked.names, items), fields: view_fields(asked.names, items) };
    let mut found: Vec<Stored> = vec![];
    let nothing: Option<Type> = None;
    for item in items.iter() {
        match &item.node {
            Item::Fn { .. } => scan(&unit, asked, (nothing).as_ref(), item.span.start, &item.node, own_buffer, &mut found),
            Item::Impl { target, methods, .. } => {
                let subject: Option<Type> = Some(target.clone());
                for method in methods.iter() { scan(&unit, asked, (subject).as_ref(), method.span.start, &method.node, own_buffer, &mut found); }
            },
            _ => { },
        }
    }
    in_source_order(&found)
}

pub fn views_checked(asked: &Asked<'_>, items: &[Spanned<Item>], own_buffer: &impl Fn(&Expr) -> bool) -> Vec<Finding> {
    let mut out: Vec<Finding> = vec![];
    for stored in views_stored(asked, items, own_buffer) { if !stored.carried { out.push(finding(&stored)); } }
    out
}

fn in_source_order(found: &[Stored]) -> Vec<Stored> {
    let mut out: Vec<Stored> = vec![];
    for stored in found.iter() {
        let mut at = out.len() as i64;
        while at > 0 && nikaia_std::index::get(&out, nikaia_std::index::at(at - 1)).span.start > stored.span.start { at -= 1; }
        out.insert(nikaia_std::count::of(at), stored.clone());
    }
    out
}

fn finding(stored: &Stored) -> Finding {
    let param = stored.param.to_owned();
    let written = stored.ty.to_owned();
    let function = stored.function.to_owned();
    let where_it_goes = match &stored.into {
        Destination::Field { owner, field, .. } => format!("`{}.{}`", owner, field),
        Destination::ParamField { owner, field, .. } => format!("`{}.{}`", owner, field),
        Destination::Subject { owner } => format!("`{}`, through a call on it", owner),
        Destination::Returned { .. } => String::from("the value this function returns"),
        Destination::Task => String::from("a task, which goes on running after the call"),
    };
    let why = match &stored.into {
        Destination::ParamField { owner, field, .. } => format!("`{}.{}` belongs to a struct that was passed in, and this function stores into more than one such struct, so it's unclear whose data `{}` points into.", owner, field, param),
        Destination::Field { owner, field, ty } => format!("`{}.{}` is a `{}`, so it points into some data, but `{}: {}` doesn't say whose.", owner, field, ty, param, written),
        Destination::Subject { owner } => format!("A call on `{}` might keep what it's given, and nothing says it doesn't, so `{}` counts as kept.", owner, param),
        Destination::Returned { ty } => format!("The result is a `{}`, which holds a view, and this function takes views of other data besides `{}`, so it's unclear which one the result points into.", ty, param),
        Destination::Task => String::from("A task keeps running after the call that started it, so anything it looks at has to live longer than the call."),
    };
    let of = of_what((stored.subject).as_deref(), &function);
    let mut help: String = String::from("Put the view in a struct and pass the struct, so its declaration says whose data it is (like `Reading` in `examples/1brc.nika`):\n           struct Held { ");
    help.push_str(&format!("{}: {}", param, written));
    help.push_str(" }\n           …\n           fn ");
    help.push_str(&format!("{}(…, held: Held)", function));
    help.push_str(" { … held.");
    help.push_str(&param);
    help.push_str(" … }\n       Or keep a copy of the text with `.clone()`, which costs one allocation.");
    refusal("NK2302", stored.span.clone(), format!("{} keeps `{}` after this call, but `{}: {}` doesn't say whose data it points into.", of, param, param, written), vec![format!("It's stored in {}.", where_it_goes), why], help)
}

fn of_what(subject: Option<&str>, function: &str) -> String {
    let owner = match subject { Some(__nikaia_value) => __nikaia_value, None => return format!("`{}`", function) };
    format!("`{}.{}`", owner, function)
}

fn borrowing_types(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>]) -> collections::BTreeSet<String> {
    let mut types_of: Vec<(String, Vec<Type>)> = vec![];
    let mut borrowing: collections::BTreeSet<String> = collections::BTreeSet::new();
    for item in items.iter() {
        match &item.node {
            Item::Enum { name, variants, .. } => {
                let name = *name;
                let mut types: Vec<Type> = vec![];
                for variant in variants.iter() {
                    match &variant.fields {
                        VariantFields::Unit => { },
                        VariantFields::Tuple(written) => { for ty in written.iter() { types.push(ty.clone()); } },
                        VariantFields::Named(declared) => { for field in declared.iter() { types.push(field.ty.clone()); } },
                    }
                }
                a_shape(names.resolve(name).to_owned(), types, &mut borrowing, &mut types_of);
            },
            Item::Struct { name, fields, .. } => {
                let name = *name;
                let mut types: Vec<Type> = vec![];
                for field in fields.iter() { types.push(field.ty.clone()); }
                a_shape(names.resolve(name).to_owned(), types, &mut borrowing, &mut types_of);
            },
            _ => { },
        }
    }
    let mut changed = true;
    while changed {
        changed = false;
        for (name, types) in types_of.iter() {
            if !borrowing.contains(name) && any_names_borrowing(names, types, &borrowing) {
                borrowing.insert(name.to_owned());
                changed = true;
            }
        }
    }
    borrowing
}

fn a_shape(name: String, types: Vec<Type>, borrowing: &mut collections::BTreeSet<String>, types_of: &mut Vec<(String, Vec<Type>)>) {
    for ty in types.iter() { if holds_view(ty) { borrowing.insert(name.to_owned()); } }
    types_of.push((name, types));
}

fn any_names_borrowing(names: &winnow_grammar::InternerContext, types: &[Type], borrowing: &collections::BTreeSet<String>) -> bool {
    for ty in types.iter() { if names_borrowing(names, ty, borrowing) { return true; } }
    false
}

pub fn holds_view(ty: &Type) -> bool {
    let code = match (*ty.code).as_ref() { Some(__nikaia_value) => __nikaia_value, None => return holds_view_written(ty) };
    let result = match (*code.result).as_ref() { Some(__nikaia_value) => __nikaia_value, None => return false };
    holds_view(result)
}

fn holds_view_written(ty: &Type) -> bool {
    if ty.is_view { return true; }
    for inner in ty.generics.iter() { if holds_view(inner) { return true; } }
    false
}

fn names_borrowing(names: &winnow_grammar::InternerContext, ty: &Type, borrowing: &collections::BTreeSet<String>) -> bool {
    if (*ty.code).is_some() {
        let code = match (*ty.code).as_ref() { Some(__nikaia_value) => __nikaia_value, None => return false };
        let result = match (*code.result).as_ref() { Some(__nikaia_value) => __nikaia_value, None => return false };
        return names_borrowing(names, result, borrowing);
    }
    if borrowing.contains(names.resolve(ty.name)) { return true; }
    for inner in ty.generics.iter() { if names_borrowing(names, inner, borrowing) { return true; } }
    false
}

fn brings_buffer(unit: &Unit, asked: &Asked<'_>, ty: &Type) -> bool { holds_view(ty) || names_borrowing(asked.names, ty, &unit.borrowing) }

fn view_fields(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>]) -> collections::BTreeMap<String, Vec<(String, Type)>> {
    let mut out: collections::BTreeMap<String, Vec<(String, Type)>> = collections::BTreeMap::new();
    for item in items.iter() {
        match &item.node {
            Item::Struct { name, fields, .. } => {
                let name = *name;
                let mut declared: Vec<(String, Type)> = vec![];
                for field in fields.iter() { declared.push((names.resolve(field.name).to_owned(), field.ty.clone())); }
                out.insert(names.resolve(name).to_owned(), declared);
            },
            Item::Enum { name, variants, .. } => {
                let name = *name;
                let mut carried: Vec<(String, Type)> = vec![];
                for variant in variants.iter() {
                    match &variant.fields {
                        VariantFields::Unit => { },
                        VariantFields::Tuple(written) => { for i in 0..written.len() as i64 { carried.push((format!("{}", i), (*nikaia_std::index::get(&written, (i) as usize)).clone())); } },
                        VariantFields::Named(declared) => { for field in declared.iter() { carried.push((names.resolve(field.name).to_owned(), field.ty.clone())); } },
                    }
                }
                out.insert(names.resolve(name).to_owned(), carried);
            },
            _ => { },
        }
    }
    out
}

pub fn written_type(names: &winnow_grammar::InternerContext, ty: &Type) -> String {
    let mut out: String = String::from("");
    if ty.is_view {
        out.push_str("ref ");
        if ty.is_mut { out.push_str("mut "); }
    }
    let mut parts: Vec<String> = vec![];
    for inner in ty.generics.iter() { parts.push(written_type(names, inner)); }
    let joined = parts.join(", ");
    if ty.is_tuple {
        out.push_str(&format!("({})", joined));
        return out;
    }
    let name = names.resolve(ty.name);
    if ty.is_view && name == "str" { out.push_str(TEXT); } else { out.push_str(name); }
    if !parts.is_empty() { out.push_str(&format!("[{}]", joined)); }
    out
}

fn scan(unit: &Unit, asked: &Asked<'_>, target: Option<&Type>, method: u32, item: &Item, own_buffer: &impl Fn(&Expr) -> bool, out: &mut Vec<Stored>) {
    match item {
        Item::Fn { name, receiver, args, config, ret_type, body, .. } => {
            let name = *name;
            let mut declared: Vec<(winnow_grammar::Symbol, Type)> = vec![];
            for arg in args.iter() { declared.push((arg.name, arg.ty.clone())); }
            for option in config.iter() { declared.push((option.name, option.ty.clone())); }
            let mut any_view = false;
            for (_, ty) in declared.iter() { if ty.is_view { any_view = true; } }
            if !any_view { return; }
            let mut sources: Vec<String> = vec![];
            for (param, ty) in declared.iter() { if brings_buffer(unit, asked, ty) { sources.push(asked.names.resolve(*param).to_owned()); } }
            let subject_is_a_source = takes_a_view_of_itself((receiver).as_ref());
            let result_holds_view = buffered(unit, asked, (ret_type).as_ref());
            let subject_names_a_buffer = named_in(asked, target, &unit.borrowing);
            let subject_name = text_of(asked, target);
            let function = function_name(asked.names, name);
            let subject_fields = fields_of_type(unit, asked, target);
            for (param, ty) in declared.iter() {
                if !ty.is_view { continue; }
                let param_name = asked.names.resolve(*param).to_owned();
                let result_is_ours = !subject_is_a_source && sources.len() == 1 && *nikaia_std::index::get(&sources, 0) == param_name;
                let hands_back = result_holds_view && !result_is_ours;
                let mut carriers: collections::BTreeSet<String> = collections::BTreeSet::new();
                carriers.insert(param_name.to_owned());
                let mut here = Here { subject: match target {
                    Some(__nikaia_it) => Some(__nikaia_it.to_owned()),
                    None => None,
                }, subject_fields: subject_fields.to_owned(), declared: declared.to_owned(), result: if hands_back {
                    match ret_type {
                        Some(__nikaia_it) => Some(__nikaia_it.to_owned()),
                        None => None,
                    }
                } else { None }, ours: if result_holds_view && result_is_ours { text_of(asked, (ret_type).as_ref()) } else { None }, carriers, found: vec![] };
                walk_block(unit, asked, body, true, own_buffer, &mut here);
                one_answer(asked, &here, *param, Scanned { param: param_name, ty: written_type(asked.names, ty), function: function.to_owned(), subject: match subject_name.as_ref() {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                }, method, names_a_buffer: subject_names_a_buffer }, out);
            }
        },
        _ => { },
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Scanned {
    param: String,
    ty: String,
    function: String,
    subject: Option<String>,
    method: u32,
    names_a_buffer: bool,
}

fn one_answer(asked: &Asked<'_>, here: &Here, symbol: winnow_grammar::Symbol, signed: Scanned, out: &mut Vec<Stored>) {
    let mut carriers: collections::BTreeSet<String> = collections::BTreeSet::new();
    let mut carrier: Option<winnow_grammar::Symbol> = None;
    for (_, into) in here.found.iter() {
        match into {
            Destination::ParamField { param, .. } => {
                let param = *param;
                if carriers.insert(asked.names.resolve(param).to_owned()) && carrier.is_none() { carrier = Some(param); }
            },
            _ => { },
        }
    }
    let one_carrier = carriers.len() == 1 && !signed.names_a_buffer;
    let mut unreached: Vec<(Span, Destination)> = vec![];
    let mut reached: Vec<(Span, Destination)> = vec![];
    for (span, into) in here.found.iter() { if covered_by_the_subject(signed.names_a_buffer, into) || one_carrier && a_param_field(into) { reached.push((span.clone(), into.clone())); } else { unreached.push((span.clone(), into.clone())); } }
    let carried = unreached.is_empty();
    let candidates = if carried { reached } else { unreached };
    if candidates.is_empty() { return; }
    let mut best: i64 = 0;
    for i in 1..candidates.len() as i64 {
        let rank_i = rank(&nikaia_std::index::get(&candidates, (i) as usize).1);
        let rank_best = rank(&nikaia_std::index::get(&candidates, nikaia_std::index::at(best)).1);
        if rank_i < rank_best || rank_i == rank_best && nikaia_std::index::get(&candidates, (i) as usize).0.start < nikaia_std::index::get(&candidates, nikaia_std::index::at(best)).0.start { best = i; }
    }
    out.push(Stored { span: nikaia_std::index::get(&candidates, nikaia_std::index::at(best)).0.clone(), param: signed.param, ty: signed.ty, function: signed.function, subject: signed.subject, into: nikaia_std::index::get(&candidates, nikaia_std::index::at(best)).1.clone(), carried, method: signed.method, symbol, carrier: if one_carrier && carried { carrier } else { None } });
}

fn a_param_field(into: &Destination) -> bool { matches!(into, Destination::ParamField { .. }) }

fn covered_by_the_subject(subject_names_a_buffer: bool, into: &Destination) -> bool { subject_names_a_buffer && matches!(into, Destination::Field { .. } | Destination::Subject { .. }) }

fn rank(into: &Destination) -> i64 {
    match into {
        Destination::Field { .. } => 0,
        Destination::Subject { .. } => 1,
        Destination::Task => 2,
        Destination::Returned { .. } => 3,
        Destination::ParamField { .. } => 0,
    }
}

fn takes_a_view_of_itself(receiver: Option<&Receiver>) -> bool {
    let taken = match receiver { Some(__nikaia_value) => __nikaia_value, None => return false };
    taken.is_ref
}

fn buffered(unit: &Unit, asked: &Asked<'_>, ty: Option<&Type>) -> bool { brings_buffer(unit, asked, match ty { Some(__nikaia_value) => __nikaia_value, None => return false }) }

fn named_in(asked: &Asked<'_>, ty: Option<&Type>, borrowing: &collections::BTreeSet<String>) -> bool {
    let named = match ty { Some(__nikaia_value) => __nikaia_value, None => return false };
    borrowing.contains(asked.names.resolve(named.name))
}

fn text_of(asked: &Asked<'_>, ty: Option<&Type>) -> Option<String> {
    let named = match ty { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(asked.names.resolve(named.name).to_owned())
}

fn function_name(names: &winnow_grammar::InternerContext, name: Option<winnow_grammar::Symbol>) -> String {
    let named = match name { Some(__nikaia_value) => __nikaia_value, None => return String::from("new") };
    names.resolve(named).to_owned()
}

fn fields_of_type(unit: &Unit, asked: &Asked<'_>, ty: Option<&Type>) -> Vec<(String, Type)> {
    let named = match ty { Some(__nikaia_value) => __nikaia_value, None => return vec![] };
    nikaia_std::index::or(match *nikaia_std::index::get(&unit.fields, asked.names.resolve(named.name)) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || vec![].into())
}

fn walk_block(unit: &Unit, asked: &Asked<'_>, block: &Block, tail: bool, own_buffer: &impl Fn(&Expr) -> bool, here: &mut Here) {
    let count = block.stmts.len() as i64;
    for i in 0..count {
        let returning = tail && i + 1 == count;
        let span = nikaia_std::index::get(&block.stmts, (i) as usize).span.clone();
        match &nikaia_std::index::get(&block.stmts, (i) as usize).node {
            Stmt::Let { names, value, .. } => {
                if mentions(unit, asked, &here, value) && !own_buffer(value) { for name in names.iter() { here.carriers.insert(asked.names.resolve(*name).to_owned()); } }
                stores(unit, asked, value, &span, own_buffer, here);
            },
            Stmt::Comptime { name, value, .. } => {
                let name = *name;
                if mentions(unit, asked, &here, value) { here.carriers.insert(asked.names.resolve(name).to_owned()); }
                stores(unit, asked, value, &span, own_buffer, here);
            },
            Stmt::Assign { target, value, .. } => {
                if mentions(unit, asked, &here, value) {
                    match target {
                        Expr::Variable(name) => {
                            let name = *name;
                            here.carriers.insert(asked.names.resolve(name).to_owned());
                        },
                        _ => assigned(unit, asked, target, &span, here),
                    }
                }
                stores(unit, asked, target, &span, own_buffer, here);
                stores(unit, asked, value, &span, own_buffer, here);
            },
            Stmt::Return(value) => returned_maybe(unit, asked, (value).as_ref(), &span, own_buffer, here),
            Stmt::Expr(expr) => {
                if returning {
                    returned(unit, asked, expr, &span, here);
                    handed_back(unit, asked, expr, &span, own_buffer, here);
                } else { stores(unit, asked, expr, &span, own_buffer, here); }
            },
            Stmt::For { bindings, iter, body } => {
                if mentions(unit, asked, &here, iter) { for binding in bindings.iter() { here.carriers.insert(asked.names.resolve(*binding).to_owned()); } }
                stores(unit, asked, iter, &span, own_buffer, here);
                walk_block(unit, asked, body, false, own_buffer, here);
            },
            Stmt::While { cond, body } => {
                stores(unit, asked, cond, &span, own_buffer, here);
                walk_block(unit, asked, body, false, own_buffer, here);
            },
            Stmt::Break => { },
            Stmt::Continue => { },
        }
    }
}

fn returned_maybe(unit: &Unit, asked: &Asked<'_>, value: Option<&Expr>, span: &Span, own_buffer: &impl Fn(&Expr) -> bool, here: &mut Here) {
    let handed = match value { Some(__nikaia_value) => __nikaia_value, None => return };
    returned(unit, asked, handed, span, here);
    handed_back(unit, asked, handed, span, own_buffer, here);
}

fn handed_back(unit: &Unit, asked: &Asked<'_>, value: &Expr, span: &Span, own_buffer: &impl Fn(&Expr) -> bool, here: &mut Here) {
    match value {
        Expr::StructLit { name, .. } => {
            let name = *name;
            if ours_is(asked, (here.ours).as_deref(), name) { descend(unit, asked, value, span, own_buffer, here); } else { stores(unit, asked, value, span, own_buffer, here); }
        },
        _ => stores(unit, asked, value, span, own_buffer, here),
    }
}

fn ours_is(asked: &Asked<'_>, ours: Option<&str>, name: winnow_grammar::Symbol) -> bool {
    let named = match ours { Some(__nikaia_value) => __nikaia_value, None => return false };
    named == asked.names.resolve(name)
}

fn assigned(unit: &Unit, asked: &Asked<'_>, target: &Expr, span: &Span, here: &mut Here) {
    match root(unit, asked, &here, target) {
        Root::SubjectField(ref field) => field_of_subject(unit, asked, field, span, here),
        Root::Subject => subject_destination(unit, asked, span, here),
        Root::ParamField(param, ref field) => field_of_param(unit, asked, param, field, span, here),
        Root::Param(_) => { },
        Root::Elsewhere => { },
    }
}

fn a_struct_parameter(unit: &Unit, asked: &Asked<'_>, here: &Here, name: winnow_grammar::Symbol) -> Option<String> {
    let wanted = asked.names.resolve(name);
    for (declared, ty) in here.declared.iter() {
        if asked.names.resolve(*declared) == wanted {
            let owner = asked.names.resolve(ty.name);
            if !ty.is_view && unit.borrowing.contains(owner) { return Some(owner.to_owned()); }
            return None;
        }
    }
    None
}

fn field_of_param(unit: &Unit, asked: &Asked<'_>, param: winnow_grammar::Symbol, field: &str, span: &Span, here: &mut Here) {
    let owner = match a_struct_parameter(unit, asked, &here, param) { Some(__nikaia_value) => __nikaia_value, None => return };
    let declared = nikaia_std::index::or(match *nikaia_std::index::get(&unit.fields, &owner) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || vec![].into());
    for (name, ty) in declared.iter() {
        if name == field {
            if brings_buffer(unit, asked, ty) { here.found.push((span.clone(), Destination::ParamField { param, owner, field: field.to_owned(), ty: written_type(asked.names, ty) })); }
            return;
        }
    }
}

fn returned(unit: &Unit, asked: &Asked<'_>, value: &Expr, span: &Span, here: &mut Here) {
    let result = match match here.result.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return };
    if !mentions(unit, asked, &here, value) { return; }
    if hands_back_another_buffer(unit, asked, &here, value) { return; }
    here.found.push((span.clone(), Destination::Returned { ty: written_type(asked.names, &result) }));
}

fn hands_back_another_buffer(unit: &Unit, asked: &Asked<'_>, here: &Here, value: &Expr) -> bool {
    match value {
        Expr::MethodCall { receiver, method, args, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; a_method_borrows_elsewhere(unit, asked, here, receiver, method, args) },
        Expr::SafeMethod { receiver, method, args, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; a_method_borrows_elsewhere(unit, asked, here, receiver, method, args) },
        Expr::Call { func, args, .. } => { let func = nikaia_std::boxed::open(func); match func {
            Expr::Variable(name) => { let name = *name; borrows_elsewhere(unit, asked, here, asked.names.resolve(name), None, args) },
            Expr::Path(parts) => borrows_elsewhere(unit, asked, here, &joined_path(asked, parts), None, args),
            _ => false,
        } },
        _ => false,
    }
}

fn a_method_borrows_elsewhere(unit: &Unit, asked: &Asked<'_>, here: &Here, receiver: &Expr, method: winnow_grammar::Symbol, args: &[Expr]) -> bool {
    let ty = match type_of(unit, asked, here, receiver) { Some(__nikaia_value) => __nikaia_value, None => return false };
    let subject = asked.names.resolve(ty.name);
    let name = asked.names.resolve(method);
    let on: Option<Expr> = Some(receiver.clone());
    borrows_elsewhere(unit, asked, here, &format!("{}::{}", subject, name), (on).as_ref(), args)
}

fn joined_path(asked: &Asked<'_>, parts: &[winnow_grammar::Symbol]) -> String {
    let mut written: Vec<String> = vec![];
    for part in parts.iter() { written.push(asked.names.resolve(*part).to_owned()); }
    written.join("::")
}

fn borrows_elsewhere(unit: &Unit, asked: &Asked<'_>, here: &Here, key: &str, receiver: Option<&Expr>, args: &[Expr]) -> bool {
    let contract = match match *nikaia_std::index::get(&asked.own.functions, key) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => match match *nikaia_std::index::get(&asked.library.functions, key) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return false } };
    let signature = match match contract.signature.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return false };
    if contract.borrows.is_empty() { return false; }
    let takes_a_receiver = signature.takes_a_receiver();
    for borrowed in contract.borrows.iter() {
        if borrowed == "self" {
            if !receiver_clear(unit, asked, here, receiver) { return false; }
            continue;
        }
        let mut at: i64 = -1;
        for i in 0..signature.params.len() as i64 { if at < 0 && nikaia_std::index::get(&signature.params, (i) as usize).0 == *borrowed { at = i; } }
        if at < 0 { return false; }
        if takes_a_receiver { at -= 1; }
        if at < 0 || at >= args.len() as i64 { return false; }
        if mentions(unit, asked, here, nikaia_std::index::get(&args, nikaia_std::index::at(at))) { return false; }
    }
    true
}

fn receiver_clear(unit: &Unit, asked: &Asked<'_>, here: &Here, receiver: Option<&Expr>) -> bool {
    let on = match receiver { Some(__nikaia_value) => __nikaia_value, None => return false };
    !mentions(unit, asked, here, on)
}

fn type_of(unit: &Unit, asked: &Asked<'_>, here: &Here, receiver: &Expr) -> Option<Type> {
    match receiver {
        Expr::Variable(name) => { let name = *name; variable_type(asked, here, asked.names.resolve(name)) },
        Expr::Field { base, name } => { let base = nikaia_std::boxed::open(base); let name = *name; field_type(unit, asked, here, base, asked.names.resolve(name)) },
        _ => None,
    }
}

fn variable_type(asked: &Asked<'_>, here: &Here, name: &str) -> Option<Type> {
    if name == "self" {
        return match here.subject.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        };
    }
    for (param, ty) in here.declared.iter() { if asked.names.resolve(*param) == name { return Some(ty.clone()); } }
    None
}

fn field_type(unit: &Unit, asked: &Asked<'_>, here: &Here, base: &Expr, name: &str) -> Option<Type> {
    let fields = match fields_reached(unit, asked, here, base) { Some(__nikaia_value) => __nikaia_value, None => return None };
    for (field, ty) in fields.iter() { if field == name { return Some(ty.clone()); } }
    None
}

fn fields_reached(unit: &Unit, asked: &Asked<'_>, here: &Here, base: &Expr) -> Option<Vec<(String, Type)>> {
    if is_self(asked, base) { return Some(here.subject_fields.to_owned()); }
    let ty = match type_of(unit, asked, here, base) { Some(__nikaia_value) => __nikaia_value, None => return None };
    match *nikaia_std::index::get(&unit.fields, asked.names.resolve(ty.name)) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }
}

fn is_self(asked: &Asked<'_>, expr: &Expr) -> bool {
    match expr {
        Expr::Variable(name) => { let name = *name; asked.names.resolve(name) == "self" },
        _ => false,
    }
}

fn stores(unit: &Unit, asked: &Asked<'_>, expr: &Expr, span: &Span, own_buffer: &impl Fn(&Expr) -> bool, here: &mut Here) {
    match expr {
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            handed_to(unit, asked, receiver, args, config, span, here);
            descend(unit, asked, expr, span, own_buffer, here);
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            handed_to(unit, asked, receiver, args, config, span, here);
            descend(unit, asked, expr, span, own_buffer, here);
        },
        Expr::StructLit { name, fields } => {
            let name = *name;
            let owner = asked.names.resolve(name).to_owned();
            if unit.borrowing.contains(&owner) {
                let declared = nikaia_std::index::or(match *nikaia_std::index::get(&unit.fields, &owner) {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                }, || vec![].into());
                for init in fields.iter() { a_field_built(unit, asked, &owner, &declared, init, span, here); }
            }
            descend(unit, asked, expr, span, own_buffer, here);
        },
        Expr::Spawn { body, .. } => {
            let body = nikaia_std::boxed::open(body);
            if mentions(unit, asked, &here, body) { here.found.push((span.clone(), Destination::Task)); }
            descend(unit, asked, expr, span, own_buffer, here);
        },
        _ => descend(unit, asked, expr, span, own_buffer, here),
    }
}

fn handed_to(unit: &Unit, asked: &Asked<'_>, receiver: &Expr, args: &[Expr], config: &[ConfigArg], span: &Span, here: &mut Here) {
    let mut handed_over = false;
    for arg in args.iter() { if mentions(unit, asked, &here, arg) { handed_over = true; } }
    for setting in config.iter() { if mentions(unit, asked, &here, &setting.value) { handed_over = true; } }
    if !handed_over { return; }
    match root(unit, asked, &here, receiver) {
        Root::SubjectField(ref field) => field_of_subject(unit, asked, field, span, here),
        Root::Subject => subject_destination(unit, asked, span, here),
        _ => { },
    }
}

fn a_field_built(unit: &Unit, asked: &Asked<'_>, owner: &str, declared: &[(String, Type)], init: &FieldInit, span: &Span, here: &mut Here) {
    let field = asked.names.resolve(init.name).to_owned();
    let mentioned = value_mentions(unit, asked, &here, (init.value).as_ref(), &field);
    if !mentioned { return; }
    for (name, ty) in declared.iter() {
        if *name == field {
            if brings_buffer(unit, asked, ty) { here.found.push((span.clone(), Destination::Field { owner: owner.to_owned(), field, ty: written_type(asked.names, ty) })); }
            return;
        }
    }
}

fn value_mentions(unit: &Unit, asked: &Asked<'_>, here: &Here, value: Option<&Expr>, field: &str) -> bool {
    let written = match value { Some(__nikaia_value) => __nikaia_value, None => return here.carriers.contains(field) };
    mentions(unit, asked, here, written)
}

fn subject_destination(unit: &Unit, asked: &Asked<'_>, span: &Span, here: &mut Here) {
    let owner = match text_of(asked, (here.subject).as_ref()) { Some(__nikaia_value) => __nikaia_value, None => return };
    let known = unit.fields.contains_key(&owner);
    let mut can_hold = false;
    for (_, ty) in here.subject_fields.iter() { if brings_buffer(unit, asked, ty) { can_hold = true; } }
    if known && !can_hold { return; }
    here.found.push((span.clone(), Destination::Subject { owner }));
}

fn field_of_subject(unit: &Unit, asked: &Asked<'_>, field: &str, span: &Span, here: &mut Here) {
    let mut written: Option<String> = None;
    for (name, ty) in here.subject_fields.iter() {
        if written.is_none() && name == field && brings_buffer(unit, asked, ty) { written = Some(written_type(asked.names, ty)); }
        if name == field { break; }
    }
    let ty = match written { Some(__nikaia_value) => __nikaia_value, None => return };
    let owner = match text_of(asked, (here.subject).as_ref()) { Some(__nikaia_value) => __nikaia_value, None => return };
    here.found.push((span.clone(), Destination::Field { owner, field: field.to_owned(), ty }));
}

fn root(unit: &Unit, asked: &Asked<'_>, here: &Here, expr: &Expr) -> Root {
    match expr {
        Expr::Variable(name) => { let name = *name; a_variable_root(unit, asked, here, name) },
        Expr::Field { base, name } => { let base = nikaia_std::boxed::open(base); let name = *name; match root(unit, asked, here, base) {
            Root::Subject => Root::SubjectField(asked.names.resolve(name).to_owned()),
            Root::Param(param) => Root::ParamField(param, asked.names.resolve(name).to_owned()),
            Root::SubjectField(field) => Root::SubjectField(field),
            Root::ParamField(param, field) => Root::ParamField(param, field),
            Root::Elsewhere => Root::Elsewhere,
        } },
        Expr::MethodCall { receiver, .. } => { let receiver = nikaia_std::boxed::open(receiver); root(unit, asked, here, receiver) },
        Expr::SafeMethod { receiver, .. } => { let receiver = nikaia_std::boxed::open(receiver); root(unit, asked, here, receiver) },
        Expr::Index { base, .. } => { let base = nikaia_std::boxed::open(base); root(unit, asked, here, base) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); root(unit, asked, here, inner) },
        _ => Root::Elsewhere,
    }
}

fn a_variable_root(unit: &Unit, asked: &Asked<'_>, here: &Here, name: winnow_grammar::Symbol) -> Root {
    if asked.names.resolve(name) == "self" { return Root::Subject; }
    if a_struct_parameter(unit, asked, here, name).is_some() { return Root::Param(name); }
    Root::Elsewhere
}

fn mentions(unit: &Unit, asked: &Asked<'_>, here: &Here, node: &Expr) -> bool {
    match node {
        Expr::Variable(name) => { let name = *name; here.carriers.contains(asked.names.resolve(name)) },
        Expr::MethodCall { receiver, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); mentions(unit, asked, here, receiver) || any_mentions(unit, asked, here, args) || config_mentions(unit, asked, here, config) },
        Expr::SafeMethod { receiver, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); mentions(unit, asked, here, receiver) || any_mentions(unit, asked, here, args) || config_mentions(unit, asked, here, config) },
        Expr::Call { func, args, config } => { let func = nikaia_std::boxed::open(func); mentions(unit, asked, here, func) || any_mentions(unit, asked, here, args) || config_mentions(unit, asked, here, config) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); mentions(unit, asked, here, base) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); mentions(unit, asked, here, base) },
        Expr::Index { base, index } => { let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index); mentions(unit, asked, here, base) || mentions(unit, asked, here, index) },
        Expr::Binary { lhs, rhs, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); mentions(unit, asked, here, lhs) || mentions(unit, asked, here, rhs) },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); mentions(unit, asked, here, expr) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); mentions(unit, asked, here, inner) },
        Expr::Throw(inner) => { let inner = nikaia_std::boxed::open(inner); mentions(unit, asked, here, inner) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); mentions(unit, asked, here, expr) },
        Expr::Spawn { body, .. } => { let body = nikaia_std::boxed::open(body); mentions(unit, asked, here, body) },
        Expr::Coalesce { value, fallback } => { let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback); mentions(unit, asked, here, value) || mentions(unit, asked, here, fallback) },
        Expr::Range { start, end, .. } => { let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end); mentions(unit, asked, here, start) || mentions(unit, asked, here, end) },
        Expr::Tuple(parts) => any_mentions(unit, asked, here, parts),
        Expr::ListLit { items, .. } => any_mentions(unit, asked, here, items),
        Expr::Return(value) => { let value = nikaia_std::boxed::open(value); maybe_mentions(unit, asked, here, (value).as_ref()) },
        Expr::StructLit { fields, .. } => fields_mention(unit, asked, here, fields),
        Expr::With { base, fields, .. } => { let base = nikaia_std::boxed::open(base); mentions(unit, asked, here, base) || fields_mention(unit, asked, here, fields) },
        Expr::Match { value, arms } => { let value = nikaia_std::boxed::open(value); mentions(unit, asked, here, value) || arms_mention(unit, asked, here, arms) },
        Expr::If { cond, then_branch, else_branch } => { let cond = nikaia_std::boxed::open(cond); mentions(unit, asked, here, cond) || block_mentions(unit, asked, here, then_branch) || maybe_block_mentions(unit, asked, here, (else_branch).as_ref()) },
        Expr::Block(block) => block_mentions(unit, asked, here, block),
        Expr::Unsafe(block) => block_mentions(unit, asked, here, block),
        Expr::Overlap(block) => block_mentions(unit, asked, here, block),
        Expr::Closure { body, .. } => block_mentions(unit, asked, here, body),
        Expr::Select(arms) => select_mentions(unit, asked, here, arms),
        Expr::TryCatch { expr, handler } => { let expr = nikaia_std::boxed::open(expr); mentions(unit, asked, here, expr) || block_mentions(unit, asked, here, handler) },
        Expr::Break => false,
        Expr::Continue => false,
        Expr::Asm { .. } => false,
        Expr::Dsl { .. } => false,
        Expr::Path(_) => false,
        Expr::LitInt { .. } => false,
        Expr::LitFloat(_) => false,
        Expr::LitStr { .. } => false,
        Expr::LitInterpolated { .. } => false,
        Expr::LitChar(_) => false,
        Expr::LitBool(_) => false,
        Expr::LitNull => false,
    }
}

fn any_mentions(unit: &Unit, asked: &Asked<'_>, here: &Here, exprs: &[Expr]) -> bool {
    for expr in exprs.iter() { if mentions(unit, asked, here, expr) { return true; } }
    false
}

fn config_mentions(unit: &Unit, asked: &Asked<'_>, here: &Here, config: &[ConfigArg]) -> bool {
    for setting in config.iter() { if mentions(unit, asked, here, &setting.value) { return true; } }
    false
}

fn fields_mention(unit: &Unit, asked: &Asked<'_>, here: &Here, fields: &[FieldInit]) -> bool {
    for field in fields.iter() { if maybe_mentions(unit, asked, here, (field.value).as_ref()) { return true; } }
    false
}

fn arms_mention(unit: &Unit, asked: &Asked<'_>, here: &Here, arms: &[MatchArm]) -> bool {
    for arm in arms.iter() { if mentions(unit, asked, here, &arm.body) { return true; } }
    false
}

fn select_mentions(unit: &Unit, asked: &Asked<'_>, here: &Here, arms: &[SelectArm]) -> bool {
    for arm in arms.iter() { if mentions(unit, asked, here, &arm.value) || block_mentions(unit, asked, here, &arm.body) { return true; } }
    false
}

fn maybe_mentions(unit: &Unit, asked: &Asked<'_>, here: &Here, expr: Option<&Expr>) -> bool { mentions(unit, asked, here, match expr { Some(__nikaia_value) => __nikaia_value, None => return false }) }

fn maybe_block_mentions(unit: &Unit, asked: &Asked<'_>, here: &Here, block: Option<&Block>) -> bool { block_mentions(unit, asked, here, match block { Some(__nikaia_value) => __nikaia_value, None => return false }) }

fn block_mentions(unit: &Unit, asked: &Asked<'_>, here: &Here, block: &Block) -> bool {
    for stmt in block.stmts.iter() { if statement_mentions(unit, asked, here, &stmt.node) { return true; } }
    false
}

fn statement_mentions(unit: &Unit, asked: &Asked<'_>, here: &Here, stmt: &Stmt) -> bool {
    match stmt {
        Stmt::Let { value, .. } => mentions(unit, asked, here, value),
        Stmt::Comptime { value, .. } => mentions(unit, asked, here, value),
        Stmt::Expr(expr) => mentions(unit, asked, here, expr),
        Stmt::Return(value) => maybe_mentions(unit, asked, here, (value).as_ref()),
        Stmt::Assign { target, value, .. } => mentions(unit, asked, here, target) || mentions(unit, asked, here, value),
        Stmt::For { iter, body, .. } => mentions(unit, asked, here, iter) || block_mentions(unit, asked, here, body),
        Stmt::While { cond, body } => mentions(unit, asked, here, cond) || block_mentions(unit, asked, here, body),
        Stmt::Break => false,
        Stmt::Continue => false,
    }
}

fn descend(unit: &Unit, asked: &Asked<'_>, node: &Expr, span: &Span, own_buffer: &impl Fn(&Expr) -> bool, here: &mut Here) {
    match node {
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            stores(unit, asked, receiver, span, own_buffer, here);
            stores_all(unit, asked, args, span, own_buffer, here);
            stores_config(unit, asked, config, span, own_buffer, here);
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            stores(unit, asked, receiver, span, own_buffer, here);
            stores_all(unit, asked, args, span, own_buffer, here);
            stores_config(unit, asked, config, span, own_buffer, here);
        },
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            stores(unit, asked, func, span, own_buffer, here);
            stores_all(unit, asked, args, span, own_buffer, here);
            stores_config(unit, asked, config, span, own_buffer, here);
        },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); stores(unit, asked, base, span, own_buffer, here) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); stores(unit, asked, base, span, own_buffer, here) },
        Expr::Index { base, index } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            stores(unit, asked, base, span, own_buffer, here);
            stores(unit, asked, index, span, own_buffer, here);
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            stores(unit, asked, lhs, span, own_buffer, here);
            stores(unit, asked, rhs, span, own_buffer, here);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); stores(unit, asked, expr, span, own_buffer, here) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); stores(unit, asked, inner, span, own_buffer, here) },
        Expr::Throw(inner) => { let inner = nikaia_std::boxed::open(inner); stores(unit, asked, inner, span, own_buffer, here) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); stores(unit, asked, expr, span, own_buffer, here) },
        Expr::Spawn { body, .. } => { let body = nikaia_std::boxed::open(body); stores(unit, asked, body, span, own_buffer, here) },
        Expr::Coalesce { value, fallback } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            stores(unit, asked, value, span, own_buffer, here);
            stores(unit, asked, fallback, span, own_buffer, here);
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            stores(unit, asked, start, span, own_buffer, here);
            stores(unit, asked, end, span, own_buffer, here);
        },
        Expr::Tuple(parts) => stores_all(unit, asked, parts, span, own_buffer, here),
        Expr::ListLit { items, .. } => stores_all(unit, asked, items, span, own_buffer, here),
        Expr::Return(value) => { let value = nikaia_std::boxed::open(value); stores_maybe(unit, asked, (value).as_ref(), span, own_buffer, here) },
        Expr::StructLit { fields, .. } => stores_fields(unit, asked, fields, span, own_buffer, here),
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            stores(unit, asked, base, span, own_buffer, here);
            stores_fields(unit, asked, fields, span, own_buffer, here);
        },
        Expr::Match { value, arms } => {
            let value = nikaia_std::boxed::open(value);
            stores(unit, asked, value, span, own_buffer, here);
            for arm in arms.iter() { stores(unit, asked, &arm.body, span, own_buffer, here); }
        },
        Expr::If { cond, then_branch, else_branch } => {
            let cond = nikaia_std::boxed::open(cond);
            stores(unit, asked, cond, span, own_buffer, here);
            walk_block(unit, asked, then_branch, false, own_buffer, here);
            walk_maybe_block(unit, asked, (else_branch).as_ref(), own_buffer, here);
        },
        Expr::Block(block) => walk_block(unit, asked, block, false, own_buffer, here),
        Expr::Unsafe(block) => walk_block(unit, asked, block, false, own_buffer, here),
        Expr::Overlap(block) => walk_block(unit, asked, block, false, own_buffer, here),
        Expr::Closure { body, .. } => walk_block(unit, asked, body, false, own_buffer, here),
        Expr::Select(arms) => {
            for arm in arms.iter() { stores(unit, asked, &arm.value, span, own_buffer, here); }
            for arm in arms.iter() { walk_block(unit, asked, &arm.body, false, own_buffer, here); }
        },
        Expr::TryCatch { expr, handler } => {
            let expr = nikaia_std::boxed::open(expr);
            stores(unit, asked, expr, span, own_buffer, here);
            walk_block(unit, asked, handler, false, own_buffer, here);
        },
        Expr::Break => { },
        Expr::Continue => { },
        Expr::Asm { .. } => { },
        Expr::Dsl { .. } => { },
        Expr::Path(_) => { },
        Expr::Variable(_) => { },
        Expr::LitInt { .. } => { },
        Expr::LitFloat(_) => { },
        Expr::LitStr { .. } => { },
        Expr::LitInterpolated { .. } => { },
        Expr::LitChar(_) => { },
        Expr::LitBool(_) => { },
        Expr::LitNull => { },
    }
}

fn stores_all(unit: &Unit, asked: &Asked<'_>, exprs: &[Expr], span: &Span, own_buffer: &impl Fn(&Expr) -> bool, here: &mut Here) { for expr in exprs.iter() { stores(unit, asked, expr, span, own_buffer, here); } }

fn stores_config(unit: &Unit, asked: &Asked<'_>, config: &[ConfigArg], span: &Span, own_buffer: &impl Fn(&Expr) -> bool, here: &mut Here) { for setting in config.iter() { stores(unit, asked, &setting.value, span, own_buffer, here); } }

fn stores_fields(unit: &Unit, asked: &Asked<'_>, fields: &[FieldInit], span: &Span, own_buffer: &impl Fn(&Expr) -> bool, here: &mut Here) { for field in fields.iter() { stores_maybe(unit, asked, (field.value).as_ref(), span, own_buffer, here); } }

fn stores_maybe(unit: &Unit, asked: &Asked<'_>, expr: Option<&Expr>, span: &Span, own_buffer: &impl Fn(&Expr) -> bool, here: &mut Here) { stores(unit, asked, match expr { Some(__nikaia_value) => __nikaia_value, None => return }, span, own_buffer, here); }

fn walk_maybe_block(unit: &Unit, asked: &Asked<'_>, block: Option<&Block>, own_buffer: &impl Fn(&Expr) -> bool, here: &mut Here) { walk_block(unit, asked, match block { Some(__nikaia_value) => __nikaia_value, None => return }, false, own_buffer, here); }


// --- written.nika ---

pub fn written_expression(names: &winnow_grammar::InternerContext, expr: &Expr) -> String {
    match expr {
        Expr::LitInt { value, negative } => { let negative = *negative; let value = *value; if negative && value > 0u64 { format!("-{}", value) } else { format!("{}", value) } },
        Expr::LitFloat(text) => text.to_owned(),
        Expr::LitBool(value) => { let value = *value; if value { String::from("true") } else { String::from("false") } },
        Expr::LitChar(text) => format!("'{}'", text),
        Expr::LitStr { text, .. } => format!("\"{}\"", text),
        Expr::LitInterpolated { parts } => {
            let mut body: String = String::from("");
            for part in parts.iter() {
                match part {
                    FPart::Text(text) => body.push_str(text),
                    FPart::Hole { expr, spec, .. } => body.push_str(&hole_written(names, expr, (spec).as_deref())),
                }
            }
            format!("f\"{}\"", body)
        },
        Expr::LitNull => String::from("null"),
        Expr::Variable(name) => { let name = *name; names.resolve(name).to_owned() },
        Expr::Path(segments) => path_written(names, segments),
        Expr::Field { base, name } => { let base = nikaia_std::boxed::open(base); let name = *name; format!("{}.{}", operand(names, base), names.resolve(name)) },
        Expr::SafeField { base, name } => { let base = nikaia_std::boxed::open(base); let name = *name; format!("{}?.{}", operand(names, base), names.resolve(name)) },
        Expr::Index { base, index } => { let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index); format!("{}[{}]", operand(names, base), written_expression(names, index)) },
        Expr::Call { func, args, config } => { let func = nikaia_std::boxed::open(func); format!("{}{}", written_expression(names, func), call_written(names, args, config)) },
        Expr::MethodCall { receiver, method, args, config } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; format!("{}.{}{}", operand(names, receiver), names.resolve(method), call_written(names, args, config)) },
        Expr::SafeMethod { receiver, method, args, config } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; format!("{}?.{}{}", operand(names, receiver), names.resolve(method), call_written(names, args, config)) },
        Expr::Unary { op, expr } => { let expr = nikaia_std::boxed::open(expr); format!("{}{}", unary_word(op), operand(names, expr)) },
        Expr::Binary { op, lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            let here = binds(op);
            format!("{} {} {}", side(names, lhs, here, false), binary_word(op), side(names, rhs, here, true))
        },
        Expr::Coalesce { value, fallback } => { let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback); format!("{} ?? {}", operand(names, value), operand(names, fallback)) },
        Expr::Tuple(items) => format!("({})", all_written(names, items)),
        Expr::ListLit { items, .. } => format!("[{}]", all_written(names, items)),
        Expr::Range { start, end, inclusive } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end); let inclusive = *inclusive;
            let dots = if inclusive { ".." } else { "..<" };
            format!("{}{}{}", operand(names, start), dots, operand(names, end))
        },
        _ => String::from("…"),
    }
}

fn hole_written(names: &winnow_grammar::InternerContext, expr: &Expr, spec: Option<&str>) -> String {
    let format = match spec { Some(__nikaia_value) => __nikaia_value, None => return format!("{{{}}}", written_expression(names, expr)) };
    format!("{{{}:{}}}", written_expression(names, expr), format)
}

fn path_written(names: &winnow_grammar::InternerContext, segments: &[winnow_grammar::Symbol]) -> String {
    let mut parts: Vec<String> = vec![];
    for segment in segments.iter() { parts.push(names.resolve(*segment).to_owned()); }
    parts.join("::")
}

fn all_written(names: &winnow_grammar::InternerContext, items: &[Expr]) -> String {
    let mut parts: Vec<String> = vec![];
    for item in items.iter() { parts.push(written_expression(names, item)); }
    parts.join(", ")
}

fn call_written(names: &winnow_grammar::InternerContext, args: &[Expr], config: &[ConfigArg]) -> String {
    if config.is_empty() { return format!("({})", all_written(names, args)); }
    let mut options: Vec<String> = vec![];
    for option in config.iter() { options.push(format!("{}: {}", names.resolve(option.name), written_expression(names, &option.value))); }
    if args.is_empty() { return format!("(; {})", options.join(", ")); }
    format!("({}; {})", all_written(names, args), options.join(", "))
}

fn operand(names: &winnow_grammar::InternerContext, expr: &Expr) -> String {
    match expr {
        Expr::Binary { .. } => format!("({})", written_expression(names, expr)),
        Expr::Coalesce { .. } => format!("({})", written_expression(names, expr)),
        Expr::Cast { .. } => format!("({})", written_expression(names, expr)),
        _ => written_expression(names, expr),
    }
}

fn side(names: &winnow_grammar::InternerContext, expr: &Expr, here: i64, right: bool) -> String {
    match expr {
        Expr::Binary { op, .. } => {
            let inner = binds(op);
            if inner < here || right && inner == here { format!("({})", written_expression(names, expr)) } else { written_expression(names, expr) }
        },
        _ => operand(names, expr),
    }
}

fn binds(op: &BinaryOp) -> i64 {
    match op {
        BinaryOp::Or => 1,
        BinaryOp::And => 2,
        BinaryOp::Eq => 3,
        BinaryOp::Ne => 3,
        BinaryOp::Lt => 3,
        BinaryOp::Le => 3,
        BinaryOp::Gt => 3,
        BinaryOp::Ge => 3,
        BinaryOp::BitOr => 4,
        BinaryOp::BitXor => 5,
        BinaryOp::BitAnd => 6,
        BinaryOp::Shl => 7,
        BinaryOp::Shr => 7,
        BinaryOp::Add => 8,
        BinaryOp::Sub => 8,
        BinaryOp::Mul => 9,
        BinaryOp::Div => 9,
        BinaryOp::Rem => 9,
    }
}

fn binary_word(op: &BinaryOp) -> String {
    match op {
        BinaryOp::Add => String::from("+"),
        BinaryOp::Sub => String::from("-"),
        BinaryOp::Mul => String::from("*"),
        BinaryOp::Div => String::from("/"),
        BinaryOp::Rem => String::from("%"),
        BinaryOp::Eq => String::from("=="),
        BinaryOp::Ne => String::from("!="),
        BinaryOp::Lt => String::from("<"),
        BinaryOp::Le => String::from("<="),
        BinaryOp::Gt => String::from(">"),
        BinaryOp::Ge => String::from(">="),
        BinaryOp::And => String::from("&&"),
        BinaryOp::Or => String::from("||"),
        BinaryOp::BitAnd => String::from("&"),
        BinaryOp::BitOr => String::from("|"),
        BinaryOp::BitXor => String::from("^"),
        BinaryOp::Shl => String::from("<<"),
        BinaryOp::Shr => String::from(">>"),
    }
}

fn unary_word(op: &UnaryOp) -> String {
    match op {
        UnaryOp::Neg => String::from("-"),
        UnaryOp::Not => String::from("!"),
        UnaryOp::Ref => String::from("&"),
    }
}

pub fn written_pattern(names: &winnow_grammar::InternerContext, pattern: &MatchPattern) -> String {
    match pattern {
        MatchPattern::Path(path) => path_written(names, path),
        MatchPattern::Tuple { path, .. } => format!("{}(…)", path_written(names, path)),
        MatchPattern::Named { path, .. } => format!("{} {{ … }}", path_written(names, path)),
        _ => String::from("this pattern"),
    }
}


